window.CHAPTER_DATA["ch29"]={"id": "ch29", "num": 29, "part": "רשויות", "title": "בגדרי רשויות", "paras": [{"s": "h2", "h": "\u003csup class=\"cb\" data-c=\"1082\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">1\u003c/sup>\u003cspan class=\"ca\" data-c=\"1082\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">בגדרי רשויות\u003c/span>"}, {"s": "h3", "h": "\u003csup class=\"cb\" data-c=\"1083\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">2\u003c/sup>\u003cspan class=\"ca\" data-c=\"1083\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">א. הצ\"ב במח' ר\"י וחכ' ושייכותה במבוי\u003c/span>"}, {"s": "h7", "h": "מחלוקת ר\"י וחכמים אי רה\"ר מיערבא - מחלוקת בשם הרשות ולא רק בצורת התיקון"}, {"s": "p", "h": "והנה לבאר יותר גדר מבוי עצמו ובמה דחשיב להיות מותר בלחי וקורה, היינו, מה שמצאנו שדין לחי וקורה אינו מועיל אלא במבוי שיש לו תנאים מסוימים."}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"487\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">3\u003c/sup>\u003cspan class=\"ca\" data-c=\"487\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">ובהקדם לזה ביסוד מח' ר\"י וחכ' אי רה\"ר מיערבא. ומצאנוה בשתי סוגיות בגמ' ובתרוויהו משמע דר\"י וחכ' חלקו בעצם המושג אי רה\"ר מיערבא, ובלי שייכות לצורת התיקון, דבגמ' דעיר של יחיד ורבים נאמרה דעת ר\"י כדין כללי דלדעתו רה\"ר מיערבא, ולדעת חכ' אין רה\"ר מיערבא, וכן הוא בגמ' פ\"ק דמשמע דעיקר מחלוקתם הוא באי רה\"ר מיערבא או לא, וביותר, דאיתא שם בגמ' להוכיח דאין רה\"ר מיערבא אפילו בדלתות מהא דבעינן לדלתות ננעלות בירושלים ובמחוזא בכדי שלא יתחייבו עליה משום רה\"ר, והיינו, דפשיטא ליה לגמ' דמה דרה\"ר מיערבא ע\"י דלתות ננעלות אין זה בגדר דרה\"ר מיערבא, אלא הוא ביטול רה\"ר ועירובא ברה\"י הוא. ופשיטא ליה דדלתות שאינן ננעלות הוא רק אי רה\"ר מיערבא, ומזה הכריחה הגמ' דהאי דרך רה\"ר הוא במקום אחר מרה\"ר, והיינו, דהוקשה לגמ' לשון דעירוב בדרך רה\"ר דהא אין רה\"ר מיערבא, ופשיטא ליה דאין לחי או קורה או צורת הפתח או דלת שאין ננעלת מועילים להחשיב המקום כאינו רה\"ר. וע\"כ שאלו היאך מערבים רה\"ר הרי דעת חכ' דאין רה\"ר מיערבא כדתני בברייתא דיתר על כן.\u003c/span>"}, {"s": "h7", "h": "הצריך ביאור במחלוקת עירוב רה\"ר - היאך מועיל לו\"ק להפוך רה\"ר לרה\"י"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"488\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">4\u003c/sup>\u003cspan class=\"ca\" data-c=\"488\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">והנה זה צ\"ב דהלא מצאנו דמח' זו תלויה בדין אתי רבים בשני מחיצות מעלייתא, ובדין מחיצות דאורייתא, ובדין לחי וקורה אי הוו משום מחיצה, וא\"כ היכי משמע לגמ' דהוא מח' נפרדת אי רה\"ר מיערבא. ועוד צ\"ב דהרי דין עירוב הוא לכאורה דין ברה\"י, שתקנו חכ' דאף במקום דהוא רה\"י דאורייתא בעינן להכשרו משום דאתי לאחלופי, אבל מה שיהיה המקום הנ\"ל רה\"י ולא רה\"ר אינו מדין הכשר מבוי, וא\"כ הרי ודאי דלא שייך תיקוני מבוי ברה\"ר, דבזה איכא לדין דאורייתא דהעברה ברה\"ר. וכל דין הכשר מבוי הוא אחר שיש לנו רה\"י דאורייתא רק דאיכא לחשש דאתי לאחלופי האי מקום ברה\"ר. וע\"כ תקנו חכ' דינא דלחי וקורה דלהוי היכרא. וא\"כ בהכרח דמה דדהתיר ר\"י בלחי וקורה מכאן ומכאן, או דדעתו דהאי מקום חשיב רה\"י, או דדעתו דלחי וקורה עבדי לתרוויהו, היינו, דמלבד דמהני להכשר מבוי, מהני גם להפוך רה\"ר לרה\"י.\u003c/span>"}, {"s": "h3", "h": "\u003csup class=\"cb\" data-c=\"1085\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">6\u003c/sup>\u003csup class=\"cb\" data-c=\"1084\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">5\u003c/sup>\u003cspan class=\"ca\" data-c=\"1084 1085\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">ב. במשמעות תיקוני מבוי להגדיר הרשות\u003c/span>"}, {"s": "h7", "h": "תיקון מבוי לעומת תיקון רה\"י - הכשר הקורה מועיל בכרמלית ואינו הופכה לרה\"י"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"489\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">7\u003c/sup>\u003cspan class=\"ca\" data-c=\"489\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">ואחר העיון נראה דזה אינו מוכרח, דהא עיקר הסוגיא אי לחי וקורה משום היכר או מחיצה נאמרה לגבי מבוי שאינו רה\"י, ופליגי אם יש בלחי וקורה לעשותו רה\"י ולענין הוצאה מרה\"ר לרה\"י. וא\"כ הרי שמצאנו אף בכרמלית שהותרה לטלטול ע\"י הכשר מבוי. ומוכרחים אנו לומר בדעת מאן דס\"ל דלחי או קורה משום היכר (ולא מצאנו אמורא דאמר מפורש דשניהם משום מחיצה, ואף אי הוה הרי בעצם המח' משמע שאין זה עיקר בגדר השכר לו\"ק), דאין דין הכשר מבוי שייך לדיני מקום דרה\"י. ולפ\"ז צ\"ל דמה דתקנו חכ' הכשר קורה אין זה דווקא ברה\"י דאתי לאחלופי ברה\"ר, אלא הוא בכל מקום דאתי לאחלופי ברה\"ר (ואין תקנתם ז\"ל להבחנת הבדל שבין רה\"י ורה\"ר, אלא להגדרת רה\"ר). \u003c/span>"}, {"s": "h7", "h": "דקדוק לישנא דרש\"י בריש מסכתין - מבוי מפולש שאינו רה\"י בדין קורה"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"1086\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">8\u003c/sup>\u003csup class=\"cb\" data-c=\"490\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">9\u003c/sup>\u003cspan class=\"ca\" data-c=\"1086 490\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">וכן משמע בהקדמת רש\"י לדין המשנה בריש מסכתין, דכתב דהאי מבוי איירי במקום שאינו חשיב רה\"ר, וכמו דמבוי שאינו רחב ט\"ז או אינו מפולש. והנה מבוי מפולש לכאורה יש להקדים ולסותמו מצד אחד ע\"י צורת הפתח וכו' (עכ\"פ להילכתא), ולא היה לרש\"י להביא מקרה כזה שאינו דוגמא לדין הכשר קורה ולחי. וגם מזה נראה להוכיח דאין הכשר דמבוי בגדר שם רה\"י שלו כחיזוק מחיצותיו וכו', ועיקר תקנת מבוי נאמרה בכלל המקומות דאתו לאחלופי ברה\"ר, דאם יתכן להכשיר מבוי בלחי וקורה (ומשמע דהוא נעשה כדין) ולקיים התקנה הנ\"ל, ואף שאין נעשה המקום רה\"י, ודאי שאין לומר דדין הכשר מבוי הוא לחיזוק גדר רה\"י שיש לו, לחזק דבר שאינו קיים. ומיניה דחשיבי הכשיר ובעינן להו, דהואילו האי לחי וקורה להוציאו מחשש דאתי לאחלופי. \u003c/span>"}, {"s": "h7", "h": "מבוי שאינו ראוי לשיתוף - הכשר קורה משום היכר ויחשב כרמלית לענין הכנסה"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"491\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">10\u003c/sup>\u003cspan class=\"ca\" data-c=\"491\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">וזהו דאמר רב יהודה מבוי שאינו ראוי לשיתוף, היינו, מפולש דהכשירוהו בקורה, ועדיין חשיב כרמלית לעניין הכנסה, והיינו, דהאי הכשר אמנם הועיל משום היכר, אך לא הועיל להופכו לרה\"י. ומוכרח דאין הכשר מבוי נוגע להגדרת המקום כרה\"י, ואין צריך שיהיה המקום רה\"י ע\"מ שיועיל בו האי הכשר (וזה לכאורה גדר מפולש דמבוי, דמצאנו שיחשב המבוי מפולש אף שהפילוש הוא דרך חצר דאינה נאסרת ע\"י האי פילוש. ואם היה פילוש נושא הנוגע לרה\"י איך יתכן שיהיה הפילוש דרך רה\"י, הרי ודאי אין רה\"י חסרה בפילוש לעצמה).\u003c/span>"}, {"s": "h7", "h": "איסור טלטול במבוי שאינו משותף - הכשר קורה אינו נוגע להיתר טלטול דשיתוף"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"1087\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">11\u003c/sup>\u003csup class=\"cb\" data-c=\"492\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">12\u003c/sup>\u003cspan class=\"ca\" data-c=\"1087 492\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">וכן נראה מדין טלטול במבוי שאינו משותף דס\"ל לרב דאסור (לדעת מי שאינו סובר כרש\"י דהוא בכלי בית), דקשה א\"כ מה הועלנו בהכשר לחי וקורה אם אין בהם להתיר טלטול דמבוי, ואף דמבואר שם דאיסור הנ\"ל הוא משום תקנת שיתוף ואיסורי דיורין, איכא למשמע מיניה דאין הכשר ענין להיתר טלטול, דאי אכן הוה כגזירה לגזירה. וצ\"ל דגדריהם חלוקים דתקנת שיתוף נאמרה ביחס לרה\"י, והכשר מבוי במקום סתם, ואין זה נוגע להגדרת המקום כרה\"ר או רה\"י. \u003c/span>"}, {"s": "h3", "h": "\u003csup class=\"cb\" data-c=\"1088\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">13\u003c/sup>\u003cspan class=\"ca\" data-c=\"1088\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">ג. ביאור גדר עירוב רה\"ר\u003c/span>"}, {"s": "h7", "h": "משמעות לישנא דעירוב רשות הרבים – מדיני רה\"ר כרשות הילוך ולא מגדרי מקום דרה\"י"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"493\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">14\u003c/sup>\u003cspan class=\"ca\" data-c=\"493\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">ובזה יבואר דין עירוב רה\"ר, ואמנם ודאי אין משמעות בהכשר הנ\"ל דעבדינן ברה\"ר אם היא עדיין נחשבת רה\"ר, ובהכרח דעכ\"פ עשה ההכשר שלא יהיה מקום זה נחשב רה\"ר, וכדכתב ברש\"י דזה ההכשר לא מהני אלא במקומות שאינם רה\"ר. אבל יהיה משמעות עירוב רה\"ר ביחס לגדרה כרשות הילוך לרבים, והיינו, דכאמור אין שייך ההכשר הנ\"ל במקום רה\"ר דאי מהני הרי אין זה רה\"ר, ואי לא מהני לאו כלום הוא. והם כשני הפכים ואין שייך לומר בזה לשון עירוב רה\"ר (וכמו שלא נאמר שמי שגידר מקום רה\"ר בארבע מחיצות שהוא התיר ע\"י זה לטלטל ברה\"ר), אבל הוא שייך ביחס לגדרה כרשות להילוך הרבים. וזה ימצא במקומות שאין בהם תנאי מקום דרה\"ר וחשובים כרה\"ר מחמת היותם מחוברים לה או מאיזה סיבה שהיא, שבהכשרם בלו\"ק יהיה כדי לבטל שייכותם לרה\"ר. \u003c/span>"}, {"s": "h7", "h": "יסוד מחלוקת ר\"י וחכמים בלו\"ק - חילוק בין הגדרת מקום בצורתו להגדרת שימוש הרבים"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"1089\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">15\u003c/sup>\u003csup class=\"cb\" data-c=\"494\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">16\u003c/sup>\u003cspan class=\"ca\" data-c=\"1089 494\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">ובזה נחלקו ר\"י וחכ' ברה\"ר אי מיערבא או לא. דר\"י סבר דכיון דיש בלחי וקורה להגדיר מקום בצורתו יש לו להגדיר גם משמעות דשימוש בו, ואין בהילוך הרבים שהוא רק משמעות בשימוש המקום לבטל גדר הכשר הנ\"ל שהוא בצורת המקום עצמה. וחכ' סברי דהכשר לחי וקורה אף שהוא בצורת המקום אין הוא כמחיצות ולא מהני להגדיר שימוש דמקום אלא בשימוש סתם, ולא כזה שיש בו סיבה עצמית להגדרתו כשימוש הרבים (היינו, שהרי הוא המשך שימוש הרבים). וביאורו בהקדם משנ\"ת במק\"א באריכות דנמצא מדיני רה\"ר (היינו, במה חשוב מקום כרה\"ר), דינים שהם במקום עצמו, ודינים שהם בשימושו. במקום עצמו, כמו שיעור רוחב רה\"ר וכו'. ובשימושו, מעבר ס' ריבוא, והיותו סרטיא או פלטיא או פתוח להם וכו'.\u003c/span>"}, {"s": "h7", "h": "שני גדרים במקום להכשרו בלו\"ק - במקום עצמו לרוחבו ובשימוש המקום המחובר לרה\"ר"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"495\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">17\u003c/sup>\u003cspan class=\"ca\" data-c=\"495\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">וא\"כ נמצאנו שני גדרים במקום לענין הכשרו בתיקון דלחי וקורה. האחד, במקום עצמו, וזה שייך לרוחבו עד ט\"ז, ומפולש משער לשער וכו'. דאף ר\"י מודה בזה ברוחבו בי' או ביג' ושליש או עד ט\"ז וכו'. והשני, בשימוש המקום, וזה שייך במקום המחובר לרה\"ר וכו'. וזה ביאור שאמר ר\"י דינו בשני בתים בצידי רה\"ר, והיינו, דאף איהו דס\"ל דשתי מחיצות דאורייתא מודה דהוי רה\"ר מחמת היות מחובר לרה\"ר, וכמו מה דאמר לגבי פסי ביראות, אבל סבר דיועיל הכשר דלו\"ק להגדיר רשותו.\u003c/span>"}, {"s": "h7", "h": "שייכות לשון עירוב לתיקון לו\"ק - הכשר מועיל בכרמלית אף שאינו עושה רה\"י"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"496\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">18\u003c/sup>\u003cspan class=\"ca\" data-c=\"496\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">ובזה יבואר מה דנקטו בברייתא ובגמ' לישנא דעירוב רה\"ר, דלכאורה אין לומר בהכשר דלו\"ק לשון עירוב (ולא נקטו כן במבוי אלא ביחס לשיתוף הדיורין וכמו בכל מערבין, דשיתוף למבוי כעירוב לחצר, ואין שייכות בין זה להכשר דלחי וקורה). וכן יש לבאר בזה מה דמהני הכשר דלחי וקורה בכרמלית, ואף שלא יועיל ההכשר דלא יהא חשיב כרמלית. \u003c/span>"}, {"s": "h3", "h": "\u003csup class=\"cb\" data-c=\"1090\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">19\u003c/sup>\u003cspan class=\"ca\" data-c=\"1090\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">ד. ביאור גדר גזירת אתי לאחלופי\u003c/span>"}, {"s": "h7", "h": "ביאור גזירת אתי לאחלופי בכרמלית - איסור העברה דין ברשות המחייב הגדרת חלל המבוי"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"497\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">20\u003c/sup>\u003cspan class=\"ca\" data-c=\"497\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">והביאור בזה שהרי איסור העברה ד\"א ברה\"ר הוא דין ברה\"ר דחשיב העברה כזאת להוצאה' דיש במקום רה\"ר גדר דהעברה ד\"א בו חשובה כהוצאה, והא דליתא ברה\"י הוא בחסרון גדר זה. וא\"כ מה שגזרו חכ' טלטול ד\"א בכרמלית הוא ברשות שתיחשב כרה\"ר. וכן משמע דדין טלטול והוצאה מכרמלית ולכרמלית הוא בגדר אחד, וזה כי הוא גדר ברשות ביחס לאתי לאחלופי. וכן משמע מהא דדין רה\"י שאינה ככרמלית כיון דכולה כד\"א, וא\"כ הרי שיש לומר דגדר עירוב הוא נושא כללי הנוגע לחיבור רשויות. וגזירת חכ' במבוי דהוי ככרמלית נוגע לגדר זה, וגם הכשר מבוי הוא ביחס לזה. וכיון דמדאורייתא גדר זה נוגע לתנאי השימוש, דהרי אין כרמלית חסרת תנאי מקום דרה\"ר, הרי שמה שתקנו חכמים לתקן גדר כרמלית דמבוי, הוא נוגע לגדר זה., והיינו, דשימוש דמבוי דומה לשימוש דרה\"ר, ואתי לאחלופי. ויועיל היכר דלחי וקורה דלא אתי לאחלופי. וכיון שכן הרי שזה יועיל אף לכרמלית, דהכשר זה יש בו להחשיב כלל המקום כמקום אחד שאינו מחולק. וזה גדר שם עירוב דאיכא בהכשר מבוי. ונחלקו חכ' ור\"י אם אפשר להכשיר מקום שיש עליו שם רה\"ר מחמת שימושו, שדעת חכ' דאין אפשרות לערב רה\"ר היא מחמת שימוש דרה\"ר. שנחלקו אם שייך בכלל להגדיר שימוש של רבים, ע\"י הגדרת מקום שאין לה משמעות לגבי השימוש בפועל.\u003c/span>"}, {"s": "h7", "h": "\u003csup class=\"cb\" data-c=\"1094\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">24\u003c/sup>\u003csup class=\"cb\" data-c=\"1093\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">23\u003c/sup>\u003csup class=\"cb\" data-c=\"1092\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">22\u003c/sup>\u003csup class=\"cb\" data-c=\"1091\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">21\u003c/sup>\u003cspan class=\"ca\" data-c=\"1091 1092 1093 1094\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">גדר דלתות ננעלות - הגדרת שימוש המקום שלא כחלק משימוש רה\"ר\u003c/span>"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"1095\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">25\u003c/sup>\u003csup class=\"cb\" data-c=\"498\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">26\u003c/sup>\u003cspan class=\"ca\" data-c=\"1095 498\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">ובזה יבואר מה שפשוט לגמרא שגדר דלתות ננעלות שונה מגדר דלתות שאינם ננעלות, כי אין זה דין בדלת משום נעילה עצמה דביום אין נעולות, אלא הכוונה ביחס להגדרת השימוש במקום, שדלתות ננעלות בלילה חשיבי להגדיר את גדר השימוש במקום עצמו. וזה ביאור מה שהביאו מדר' יוחנן ושהיה להקשות הא איהו פליג עלה ולא ס\"ל כחכ' לגבי אתי רבים, והוכיחו זה מהאי מימרא, וא\"כ הרי שיש לומר דס\"ל דליכא למחיצה, ועל כן צריך לדלתות ננעלות. ומוכח מזה דגדר דלתות ננעלות יותר משאינן אינו משום מחיצה. ויש בהאי מימרא שני נושאים. האחד, אם שימוש רה\"ר במקום מבטל המחיצות, ובזה ס\"ל לר' יוחנן כר\"י, ועל כן חשיבא רה\"ר וחייבין עליה. והשני, וממנו הוכחת הגמ', הוא ממה שאמר ר' יוחנן דדלתות ננעלות מועיל למקום כזה, והרי אין גדר ננעלות חלק ממשמעות מחיצה לגבי אתי רבים, וכמו שם ד' מחיצות לרבנן, ושתי מחיצות מעלייתא לר\"י. ובהכרח דזה ביחס לשימוש הרבים ברשות, ושלא יחשב שימוש זה חלק משימוש רה\"ר ע\"י הגדרת המקום, וממילא ליכא לבקעי בה רבים, דאין שימוש הפנימי אחד עם שימוש שבחוץ. וכיון דס\"ל דרה\"ר לא מיערבא, והיינו, דאין שייך לערב מקום שיש בו שימוש הרבים ע\"י הגדרת המקום, אלא רק ע\"י הגדרת השימוש עצמו, הרי זה באותה משמעות דאתי רבים, ומוכח דאין זה ניתר אלא בדלתות ננעלות, וכן הוא גם לעירוב הנ\"ל, אך אין זה חלק מדין אתי רבים. \u003c/span>"}, {"s": "h3", "h": "\u003csup class=\"cb\" data-c=\"1097\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">28\u003c/sup>\u003csup class=\"cb\" data-c=\"1096\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">27\u003c/sup>\u003cspan class=\"ca\" data-c=\"1096 1097\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">ה. ביסוד חילוק תיקון דלו\"ק מדין מחיצה\u003c/span>"}, {"s": "h7", "h": "חילוק לחי וקורה משאר מחיצה - שתי מחיצות דר\"י אינן מועילות בלא לחי וקורה"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"1098\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">29\u003c/sup>\u003csup class=\"cb\" data-c=\"499\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">30\u003c/sup>\u003cspan class=\"ca\" data-c=\"1098 499\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">ואחר העיון נראה שזה סיבת שינוי בין הכשר מבוי למחיצות, דהרי אנן ס\"ל כאביי דלחי משום מחיצה, וא\"כ אמאי לא מודו חכ' עכ\"פ בלחי. וביאורו כי אין גדר מחיצה דלחי והכשר מבוי שווה למחיצות או לגדר רה\"י. וזהו לכ\"ע, דהא חזינן דאין שם לחי שייך לשם קורה, דאיכא למ\"ד דזה משום היכר, וזה משום מחיצה. וזה מוכח מעצם דחיית הגמ' ההוכחה מדעת ר\"י דהוא ס\"ל דשתי מחיצות דאורייתא, וזה קשה דעכ\"פ בלא האי לחי או קורה אף הוא ס\"ל דהוי רה\"ר, וא\"כ אין מועיל שני מחיצות אלו, ועדיין יש להוכיח דלחי וקורה משום מחיצה, אלא בהכרח דאף דמאן דס\"ל דלחי משום מחיצה, אין זה שייך לגדרי מחיצה דרה\"י. \u003c/span>"}, {"s": "h7", "h": "שתי משמעויות שימוש בהגדרת מקום - מחיצות המגדירות מקום נפרד מול תיקון המגדיר שימוש"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"500\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">31\u003c/sup>\u003cspan class=\"ca\" data-c=\"500\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">והביאור בזה הוא דמחיצות רה\"י מגדירות את המקום כראוי להיחשב נפרד, ובלי משמעות ביחס לשימוש עצמו, אלא בהיפך ששימוש במקום נפרד יוגדר כשימוש היחיד. אך גדר הכשר מבוי כאמור נוגע למשמעות השימוש עצמו, היינו, שע\"י הכשר דלחי וקורה יחשה המקום כראוי לשימוש מסויים. וזה גדר שאינו ברשויות דאורייתא לא ברה\"י ולא ברה\"ר, דאף גדר תנאי דשימוש הרבים ברה\"ר הוא בהגדרת המקום, היינו, שע\"י שימוש הרבים המקום מוגדר אחרת, ויש בזה תוספת ביאור במח' דכיון דהכשר מבוי בא להגדיר את המקום כשימוש מסויים, וזה אף במקום ששימושו בפועל הוא בגדר זה(דשימוש מבוי אינו שימוש רשות הרבים), אלא שאנו רוצים שיהיה שימוש הנ\"ל מוגדר בצורת המקום, וסבר ר\"י שיש לומר שהכשר זה מועיל אף כשהשימוש בפועל אינו באותו מובן של ההכשר, וכמו בשימוש הרבים. ודעת חכ' דאמנם ודאי הכשר מבוי הוא בהגדרת המקום, אך זה מועיל רק כשאין למקום הגדרה סותרת מחמת שימושו. \u003c/span>"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"501\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">32\u003c/sup>\u003cspan class=\"ca\" data-c=\"501\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">וזה ביאור מה שדייקו מילת בכך, דלכאורה קשה דאם אכן יש לדייק, הרי זה הוכחה דלא כר' יוחנן, וביאורו להוציא שלא תאמר דבכך מתייחס ללחי וקורה ומשום דלאו מחיצות מעלייתא נינהו, אלא כוונת חכ' דבכך, היינו, ע\"י הגדרת המקום ולא בשימושו, ואפילו דלתות אין הם אלא בגדר זה.\u003c/span>"}, {"s": "h7", "h": "חילוק עירוב רה\"ר מאתי רבים - אין הכשר מבוי מעניין ביטול מחיצה"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"502\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">33\u003c/sup>\u003cspan class=\"ca\" data-c=\"502\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">ומעתה יבואר מה שאמרנו לחלק נושא מחלוקת ר\"י וחכ' בעירוב רשות הרבים ממחלוקתם אי אתי רבים ומבטלי מחיצתא, דהנה הרי מחלוקתם הוא בדיני רשויות דאורייתא, דפסים רה\"י דאורייתא נינהו, וזה צ\"ב שהרי גדר רה\"י הוא מקום נפרד, וזה נובע ממחיצותיה ולא ע\"י השימוש, ובהכרח שאין חסרון אם יהיה בה שימוש שהוא שאינו בגדר זה (היינו שימוש נפרד), כי יהיה מקומה מגדיר את השימוש ולא בהיפך, וא\"כ אין בבקיעת הרבים לאסור הרשות ובודאי שאינה מגדירתה כרה\"ר, וכמו דאמרינן לר\"א וכי משום דנפרצה לרה\"ר הוויא ליה רה\"ר. שעצם שימוש הרבים בתוכה אינו נוגע להגדרתה, שהרי הגדרתה בנפרדותה ולא בסוג השימוש, וע\"כ שגדר אתי רבים פוגע בעצם נפרדותה, היינו, שהוא מגדיר את המקום כחלק ממקום אחר, אלא דאחר שנפרדותה נובעת ממחיצותיה, י\"ל דכל עוד מחיצותיה קיימות הרי שהיא נפרדת, וא\"כ לכאורה לא ניתן לפגוע בנפרדות רה\"י, ואם המקום חשוב רה\"י בהכרח שהוא נפרד, דהרי אין רה\"י בלא מחיצות. \u003c/span>"}, {"s": "h3", "h": "\u003csup class=\"cb\" data-c=\"1100\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">35\u003c/sup>\u003csup class=\"cb\" data-c=\"1099\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">34\u003c/sup>\u003cspan class=\"ca\" data-c=\"1099 1100\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">ו. במשמעות מחיצות להיות גדר במקום\u003c/span>"}, {"s": "h7", "h": "חילוק מחיצת צד ממחיצת מקום - מחיצה על כל צד מול הגדרת כל המקום"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"503\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">36\u003c/sup>\u003cspan class=\"ca\" data-c=\"503\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">והנראה מזה חילוק שיש לחלק בגדרי מחיצות דמקום לענין מה שיש להם להגדיר את השימוש בו, והיינו, דאמנם גדר מחיצות הוא במה שהן מפרידות, אך יש בזה שני שלבים הנובעים משני גדרים. האחד, במחיצת כל צד. והשני, במחיצת המקום הכוללת. ואמנם שהיות המקום נפרד נעשה ע\"י כלל המחיצות, ובזה אכן לא יועיל בקיעת הרבים, כי יש להגדיר שימוש הרבים עצמו, אך ביחס לגדר כל מחיצה לעצמה, שאין בכוחה להפריד את המקום אלא לחוץ צד שלה, אין בכוחה להגדיר שימוש הנוגע לכלל המקום, ובהיפך ששימוש הנוגע לכלל המקום יגדיר את המחיצה שלא כחלק מכלל המחיצות, וזה גדר אתי רבים ומבטלי מחיצתא. \u003c/span>"}, {"s": "h7", "h": "גדר בקיעת הרבים במחיצה וברשות - שימוש הרבים מגדיר המקום כאינו נפרד בכל צד"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"504\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">37\u003c/sup>\u003cspan class=\"ca\" data-c=\"504\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">והיינו, שאמנם בקיעת הרבים במחיצה לבדה במה שיש במעבר הבוקעים משמעות שהיא סותרת את המחיצה הנבקעת במובן איחוד הרשות הפנימית והרשות שחוצה לה, אין בה יכולת לבטל המחיצה, דעצם זה שמחיצה זו עושה רה\"י בכל מקום, הרי בהכרח שהיא מגדירה את המקום כנפרד ביחס לצד שלה, ואין שייך בזה בקיעה. אך אחר דאתי רבים ברשות, הרי שביחס למחיצה הנבקעת יש לרבים משמעות יותר, שאין המחיצה חוצצת אלא את הבקיעה ולא את עצם משמעות המקום. וע\"כ הבקיעה במחיצה עם משמעות השימוש ברשות תבטל את המחיצה. \u003c/span>"}, {"s": "h7", "h": "גדר סך כל המחיצות במקום - שם אחד לכלל המחיצות שאין שימוש הרבים מבטלו"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"505\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">38\u003c/sup>\u003cspan class=\"ca\" data-c=\"505\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">אלא שעדיין צ\"ב דיש לומר דאמנם אכן שיש לבקיעה שהיא ברשות לבטל המחיצה, אבל כיון שהמחיצה היא חלק מכלל המחיצות הנוגעות למקום, הרי שיש בה משמעות בכל המקום, ובמשמעות זו כאמור אין שימוש הרבים יכול לבטלה, שזה יחס הפוך. והיינו, שאמנם המחיצות דכל צד פועלות בנפרד לצד שלהם, אבל הרי יחד הם מגדירים מקום, ובהכרח שזה אינו חלק מכוח המחיצות בנפרד, אלא מכוח מושגי מקום. וכיון שאין המקום מתבטל ע\"י שימוש הרבים, שזה מגדרי מקום הראוי לרה\"י, הרי שלכל המחיצות יש שם אחד ביחס למקום. ושם זה אין בכח דשימוש הרבים לבטל, כיון שהוא נוגע למקום עצמו ולא לשימושו. \u003c/span>"}, {"s": "h7", "h": "יסוד מחלוקת פסי ביראות לר\"י - פסין משום שימוש ולא משום מחיצות מעלייתא במקום"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"1101\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">39\u003c/sup>\u003csup class=\"cb\" data-c=\"506\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">40\u003c/sup>\u003cspan class=\"ca\" data-c=\"1101 506\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">ובזה יבואר במה נחלקו ר\"י וחכ', דלדעת ר\"י אין גדר פסי ביראות דכל צד חשובים להיות יחד משום גדר מקום אלא משום שימוש שיש בו, היינו, שע\"י אלו הפסים יש משמעות שימוש אחת במקום, וע\"כ הוא נחשב נפרד. אך אין בפסי ביראות לבד בלא משמעות שימושם גדר במקום עצמו (ובזה ביארנו דין עד ב\"ס), אך במחיצות טובות שישנם בכל מקום הרי הם כאמור גדר במקום. וזה גדר מחיצות מעלייתא דאמר' לר\"י. והיינו, ביחס למחיצה אחת, ואין כוונתם דשני המחיצות יחד יש להם משמעות במקום דזה גדר בכלל המחיצות, דזה אף בפסי ביראות איתא אלא שכל מחיצה לעצמה בגלל שהיא בכל המקום יש לה משמעות בעצמה להתאחד. \u003c/span>"}, {"s": "h7", "h": "חשיבות שתי מחיצות מעלייתא לר\"י - מחיצה בכל המקום חשובה לעצמה להתאחד עם חברתה"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"507\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">41\u003c/sup>\u003cspan class=\"ca\" data-c=\"507\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">והיינו, דצ\"ל דאף לר\"י דמעלת מחיצות מעולות הוא במה שהן פועלות יחד, שלולי כן לא היה שייכות בין מחיצה שהיא ביחס לצד, לבין הגדרת המקום, אבל כיון שהמחיצה היא חלק מכלל המחיצות המגדירות מקום הרי שיש בה משמעות ביחס למקום, אבל סבר ר\"י שאין משמעות זו שייכת אלא במחיצה שהיא על פני כל המקום, אך במחיצה שהיא רק על חלק מהמקום, אף אחר שהיא חלק מהגדרת מקום אין לה משמעות מקום לעצמה (ויבואר לק' דזה הגדר הוא ביחס לחלל הרשות, והיינו, שגדר המחיצות הראשון הוא ביחס לשטח, וגדר המחיצות האחרון הוא ביחס לחלל). וחכ' סברי דאחר דהוגדר המקום ע\"י כל מחיצה בנפרד במקומה, הרי שמשמעות המחיצות גם היא ביחס לכל המקום והיא חלק מכלל המחיצות, וזה גדר שם ד' מחיצות. \u003c/span>"}, {"s": "h7", "h": "\u003csup class=\"cb\" data-c=\"1102\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">42\u003c/sup>\u003cspan class=\"ca\" data-c=\"1102\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">ביאור כאן הודיעוך כוחן של מחיצות - משמעות המחיצות ביחס למקום ולא רק לצדדיו\u003c/span>"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"508\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">43\u003c/sup>\u003cspan class=\"ca\" data-c=\"508\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">וזהו שאמרו כאן הודיעוך כוחן של מחיצות, היינו, דאית להו משמעות אחידה ביחס למקום. וע\"כ לא אמרה ר' יוחנן אר' יהודה דברייתא. דס\"ל דלדעת ר\"י אין זה גדר נוסף במחיצות אלא במקום (ולפמש\"כ, היינו, דאין זה גדר בחלל אלא בשטח), וכמש\"כ לעיל דודאי אף לר\"י אין מועילות שתי מחיצות הללו לבד, שהרי לבדם אף דס\"ל לר\"י דשתי מחיצות דאורייתא, כיון שהוא בדרך רה\"ר הרי הוא רה\"ר (וזה פשוט דהרי כל הדין דרה\"ר צריכה רוחב ט\"ז הוא ביחס לגבול הנעשה ע\"י שתי מחיצות, ואף דט\"ז הוי פירצה אין זה גדר ביחס למספר המחיצות), אלא דע\"י לחי או קורה הרי הם חשובים להגדיר המקום. \u003c/span>"}, {"s": "h7", "h": "ארבעה שלבים בהיתר מבוי לר\"י - מרה\"ר לנפרד ע\"י לו\"ק ועד מחיצות מעלייתא"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"509\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">44\u003c/sup>\u003cspan class=\"ca\" data-c=\"509\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">וראה כי יש בזה ארבעה שלבים, דלולא לחי וקורה מקום זה נחשב אחד עם רה\"ר, וע\"י לחי וקורה הוא נחשב לעצמו, אלא שעדיין בקעי בה רבים ואתי ומבטלי מחיצתא, אלא שכאמור אין זה מבטל מחיצות טובות, והדרן לרישיה. ובשלב הראשון כאמור לא פליגי וכ\"ע ס\"ל דהוא רה\"ר. אך בשלב השני חלקו חכ' כי לא מועיל לחי וקורה במקום שיש שימוש סותר, וזה בין אי עבדי זה המקום כרמלית, ובין אי עבדי ליה רה\"י. וזה כאמור מה שנחלקו אי רה\"ר מיערבא (וע\"כ אין להוכיח בדעתם אי לחי וקורה משום מחיצה או היכר וגם אין להוכיח אי שתי מחיצות דאורייתא או לא אלא אנן ידעינן זה רק מתנא דרשויות דהוה רה\"ר), אלא דכיון דאנן ידיענן דר\"י ס\"ל דאתי רבים ומבטלי מחיצתא בהכרח דהוא ס\"ל דהוי רה\"י, וע\"כ היה להוכיח שהוא סובר דלחי וקורה משום מחיצה, וע\"י מועיל שתי המחיצות להפוך אותו לרה\"י. ודחו משום דשתי מחיצות לבד מספיקים לחוץ מקום, ולא עבדי לחי וקורה אלא היכר. \u003c/span>"}, {"s": "h3", "h": "\u003csup class=\"cb\" data-c=\"1103\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">45\u003c/sup>\u003cspan class=\"ca\" data-c=\"1103\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">ז. חילוק העניינים בדברי הגמ' לפמשנ\"ת\u003c/span>"}, {"s": "h7", "h": "המוכרח מברייתא דשני בתים - שתי מחיצות דר\"י צריכות לו\"ק להגדיר המקום"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"510\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">46\u003c/sup>\u003cspan class=\"ca\" data-c=\"510\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">ובזה יש לבאר מה דבעו לאוכחי מיניה דלחי וקורה משום מחיצה, דיש להקשות מה דמשמע בגמ' דמהאי ברייתא מוכרח דר\"י ס\"ל שתי מחיצות דאורייתא. והנראה דגדר מה דר\"י ס\"ל דשתי מחיצות דאורייתא אין פירושו דבזה לבד יהיה המקום לרה\"י, דזה לא מצאנו בכלל. אלא פירושו דמחיצות במשמעותם כגידור צד שלהם אין צריך רק בשתי צדדים, אך ביחס לכלל המקום ובמשמעות כלל הצדדים, לא די בהם, אלא יש להגדירו ואם לא ע\"י מחיצות דסגי בתרי יהיה ע\"י דבר אחר. (והיינו ביחס למשמעות המקום דחלל). וזהו דין רה\"י, היינו, הגדרת המקום כנפרד שזה ראוי להיות רה\"י. \u003c/span>"}, {"s": "h7", "h": "גדר שלוש מחיצות ברשות היחיד - תל וחריץ רה\"י גמורה שיש להם ארבע מחיצות"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"511\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">47\u003c/sup>\u003cspan class=\"ca\" data-c=\"511\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">וזה דמוכחינן דלא כר\"י מדברי התנא דרשויות באומרו רה\"י גמורה, והיינו, דבתל וחריץ דחשיבי רה\"י יותר גמורה ממקום בעל שלושה מחיצות כי יש לו ארבעה מחיצות, ומוכח מזה שגדר ג' מחיצות גם הוא בגדר ארבעה מחיצות. ובאמת כל צדדי רה\"י היה להם להיות מוגדרים, אלא שג' מחיצות מגדירים כאילו איתא למחיצה רביעית גם. וע\"כ יהיה תוספת חשיבות ברשות בעלת ארבעה מחיצות, וע\"כ אמר התנא דאם יש ארבעה מחיצות הוי רה\"י גמורה. וא\"כ בהכרח דלא יהיה משמעות כלל בב' מחיצות, וע\"כ הרי זה כרה\"ר. אך מעצם מה שכתב התנא דתל וחריץ הוי רה\"י אין להוכיח דלא כר\"י, דהיה לומר דכוונתו ביחס להגדרת כלל המקום וביחס לטלטול בפנים, אבל ביחס לדין מחיצות, היינו, מה שרה\"י מוגדרת ע\"י מחיצות די בשתי מחיצות, והגדרה אחרת בשני צדדים הנותרים. ובאמת חכ' סוברים דמקום זה הוא רה\"י דאית ליה לחי וקורה דהם מגדירים את המקום, אך ביחס לעירוב הרי שאין בזה די להגדיר שימוש רה\"ר. וע\"כ כתב גמורה, דיש משמעות מחיצה בכל ד' צדדים. וא\"כ כיון שאין מועילים לחי וקורה להגדרת המקום מחמת שיש בו שימוש הרבים, הרי שאף אי ס\"ל לרבנן דלחי וקורה משום מחיצה, כיון שאין מועילים להגדרת המקום לא יועיל מה שיש להם שם מחיצה.\u003c/span>"}, {"s": "h7", "h": "ראיה מספיקא דתל המתלקט באתי רבים - אין דין אתי רבים תלוי במספר המחיצות"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"512\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">48\u003c/sup>\u003cspan class=\"ca\" data-c=\"512\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">וכן יש להוכיח ממה שהסתפקה הגמ' בתל המתלקט לעניין אתי רבים, דהנה מה שחלקה הגמרא בין תל המתלקט לפסי ביראות לדעת רבנן, דתל לא ניחא תשמישתיה, קשה, דהא בתל איכא ד' מחיצות מעלייתא, והאי ק\"ו דעדיפא, וביותר דהא לר\"י די בשתי מחיצות, ומה הספק. ובהכרח שאין דין אתי רבים תלוי במספר המחיצות, אלא למשמעותם כגודרים את המקום. ובגדר זה יתכן שלא יועילו מחיצות דתל כמו דלא מועילים בסוכה.\u003c/span>"}, {"s": "h3", "h": "\u003csup class=\"cb\" data-c=\"1104\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">49\u003c/sup>\u003cspan class=\"ca\" data-c=\"1104\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">ח. ביאור יסוד חילוק גדרי רשויות דאורייתא ודרבנן\u003c/span>"}, {"s": "h7", "h": "חילוק גדרי דאורייתא מדרבנן ברשויות - רשות דאורייתא נוגעת רק למקומו של חפץ"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"513\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">50\u003c/sup>\u003cspan class=\"ca\" data-c=\"513\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">וביתר ביאור מה שנראה דגדרים אלו נובעים מההבדל בין רשות דאורייתא (היינו, הדינים שנאמרו בתורה שביחס להם יש להיות דין רשות), ובין רשות דרבנן. כי הרי מן התורה אין משמעות לרשות מלבד לדין הוצאת חפץ, וכל גדרי רשויות דאורייתא נוגעות רק למשמעותם כמקומו של חפץ, ואף אי נימא דאל יצא איש ממקומו, היינו, אל יוציא, האי מקומו הוא מקומו של איש, וזה לכאורה גדר במקום אדם ולא במקום חפץ. אין זה אלא משום דגם גדר חפץ הוא מושג בשימושו של אדם, וע\"כ יהיה גדר מקומו ביחס למושגי מקום של אדם. אבל אין זה משום דדין הוצאה במקום אדם, והיינו, שנאמר דגדר הוצאה הוא הרחקת החפץ מאדם, והרחקה מאדם ביחס לחפץ היא במקום, וע\"כ יהיה הגדר מקומו של אדם, וכמו שהיה אפשר לומר בדין איגודו בידו, ובזה נשתנה גדר העברה ביד מזריקה. דזה אינו, דבזה הרי אין משמעות לשינויי רשויות דרה\"ר והיחיד, וגדר העברה ברה\"ר בגדר אחד, דנימא דגדר אחד לשניהם ביחס להוצאה. \u003c/span>"}, {"s": "h7", "h": "גדר מקום וההוצאה מגדרי חפץ - אין דין הוצאה במקום אדם אלא במקום חפץ"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"514\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">51\u003c/sup>\u003cspan class=\"ca\" data-c=\"514\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">ובהכרח דגדר מקום והוצאה הוא גדר במקום חפץ, ואין גדר מקום אדם בגדר מקום חפץ אלא משום דאין חפץ אלא ביחס לאדם, וע\"כ יהיה מקום חפץ ביחס לאדם ומקומו. וזה מוכח גם מעצם שינוי שיעור ד\"א דהעברה משיעור ד\"ט דרה\"י ומקום חפץ, ובהכרח דאיכא לדין מקום חפץ (וכן משמע ממה דאמרינן ידו של אדם חשובה וכו' וגדר אחשביה ביחס למקום ד\"ט, דאם היה הגדר ביחס לאדם, הרי היה לומר בהיפך דכל דין ד\"ט למקום חפץ הוא ביחס לאדם, ויש בזה ראיות רבות. ואכמ\"ל), והיינו, גדר הכנסה והוצאה והעברה, וזה גם משמעות שם הבאה דלשון תורה, דאין משמעות הבאה ביחס לעצם התרומה, ושם הבאה, היינו, שאף דאין חסרון בעצם התרומה, הרי שביחס להבאת התרומה הרי די למלאכה. וזה הרי בהכרח גדר בחפץ. \u003c/span>"}, {"s": "h7", "h": "גדר הוצאה בחפץ בנפרד לאדם - השוואה לגדר קנין הנפרד ממשמעות החפץ ביחס לאדם"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"515\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">52\u003c/sup>\u003cspan class=\"ca\" data-c=\"515\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">ועכ\"פ נלמד דגדר הוצאה וחשיבות מלאכת הוצאה הוא ביחס לחפץ בנפרד למשמעותו ביחס לאדם (ודומה לזה כמו מה דקנין הוא בנפרד למשמעות החפץ הנקנה ביחס לאדם, דאמנם כל גדר קנין חפץ משמעותו הוא ביחס לאדם, אך אין קנין מתייחס לגדר זה דבזה אין שינוי משמעות בין אדם לאדם (וזה שייך לעצם משמעות החפץ וכמו באיסורי הנאה), אלא דגדר קנין הוא אחר משמעות חפץ לאדם שיש לחלק משמעות זו בין אדם לאדם וזה בגדר נפרד (ואכמ\"ל וע' סוגיא דאיסורי הנאה)).\u003c/span>"}, {"s": "h7", "h": "גדרי רשויות הנובעים ממקום חפץ - עצם גדרי הרשויות המשותפים הם בגדרי מקום חפץ"}, {"s": "p", "h": "וא\"כ הרי שגם גדר רשויות נובעים ממשמעות זו ביחס לחפץ, וע\"כ עצם גדרי רשויות (היינו, לפני חלוקת רשויות, ומה שמשותף לרה\"ר והיחיד) הוא בגדרי מקום חפץ, וזה פשר השיווי דמקום ד\"ט ביחס לעקירה והנחה ברשויות היחיד והרבים, כי משמעות רשות עצמה ביחס להוצאה הוא ביחס לחפץ, ובגדר מקום חפץ, ושאר תנאים הם ביחס לגדר שינוי הרשות, והיינו, שעצם משמעות חפץ היא ביחס לאדם במה שחפץ נצרך וראוי לו וכן עצם גדר מקום גם הוא ביחס לאדם, אך גדר מקום חפץ הוא גדר מסדר שני, והיינו, שאחר דאיכא משמעות לחפץ ביחס לאדם, ואחר שיש משמעות למקום ביחס לאדם, הרי שיש משמעות למקום חפץ ביחס לאדם, וזה משמעות כללית במושג חפץ ומקום. אך ביחס לשייכות חפץ לאדם אין זה ביחס לאדם, אלא בשניהם, דאין משמעות חפץ ביחס לאדם אלא באדם, אבל עצם החפץ בלי משמעות זו הוא דבר נפרד, וע\"כ גדר השייכות הוא לא ביחס לאדם. וע\"כ אף דגם גדר מקום הוא רק ביחס לאדם, גדר מקום חפץ בנוגע לשייכות חפץ לאדם יהיה משמעות בחפץ בגדר נפרד."}, {"s": "h7", "h": "גדר מקום ביחס למקום חפצים - שינוי מקום דהוצאה הוא ביחס למקום חפצים כללי"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"516\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">53\u003c/sup>\u003cspan class=\"ca\" data-c=\"516\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">וכיון דגדר הוצאה הוא ביחס למקום חפץ, לא יהיו גדרי מקום לגבי הוצאה ביחס לאדם, אלא ביחס לחפץ. וכיון שכן יהיה משמעות במקום עצמו בנפרד ממשמעותו ביחס לאדם, וגדר זה הוא ביחס לגדר מקום דחפצים, דהיינו, שהרי גדר הוצאה מתייחס לשינוי מקום שאינו מגדרי חפץ מסוים, דהרי ביחס לחפץ מסוים, אין הבדל בין מקום למקום, דכל מקום שבו הוא נמצא הרי הוא מקומו באופן שווה, אלא דגדר זה הוא ביחס למקום חפץ כללי, וע\"כ לא יהיה נחשב שינוי מקום אלא ביחס לזה, וזה הרי במושגי מקום דחפצים באופן כללי, וע\"כ לא יחשב הוצאה אלא ביחס למשמעות מקום חפץ הכללי, וכיון שכן הרי שעצם מושגי שינוי מקום יהיו ביחס לגדרי מקום שלא במובן חפץ, וזה גדר מה שאין דיני רשויות כמקום חפץ באותו הגדר דמשמעות המקום כמקום שונה, שעיקר דיני רשויות הם ביחס לחפץ מסוים להגדירו כנמצא במקום, אך גדר השינוי במשמעות המקום הוא ביחס למקום חפצים באופן כללי.\u003c/span>"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"517\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">54\u003c/sup>\u003cspan class=\"ca\" data-c=\"517\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">וא\"כ יש פה כמה דרגות. א. אדם וחפץ ומקום. ב. מקום אדם ומקום חפץ וחפץ אדם. ג. חפץ ביחס למקום אדם. ד. מקום חפץ ביחס לאדם. ה. מקומות שונים ביחס לאדם. ו. שינוי משמעות במקום חפצים במקומות שונים הנ\"ל.\u003c/span>"}, {"s": "h3", "h": "\u003csup class=\"cb\" data-c=\"1105\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">55\u003c/sup>\u003cspan class=\"ca\" data-c=\"1105\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">ט. ביאור גדרי מקום דהוצאה ושם רשות\u003c/span>"}, {"s": "h7", "h": "גדר רשויות דאורייתא במקום חפץ - שייכות אדם וחפץ ומשמעות מקום חפץ בשינויי רשויות"}, {"s": "p", "h": "וכבר ביארנו לעיל את מושגי אדם חפץ ומקום, ועכ\"פ אם כנים הדברים הרי שגדר רשויות שמן התורה הוא בשני מובנים. האחד. הוא ביחס לשייכות שבין אדם וחפץ ביחס למקום, וזה גדר מקום חפץ. והשני, הוא במשמעות מקום חפץ ביחס למשמעות המקום לאדם, וזה גדר שינויי רשויות. וע\"כ יהיה גדר רשות כמקום חפץ בסיס לגדר רשות איזה שתהיה (וכיון שמצאנו גדר בשינוי מקום חפץ ביחס לרשות שאין בה שינוי (העברה), בהכרח שאין גדר שינוי מקום דחפץ מרשות לרשות, יותר מגדר שינוי במקום חפץ, ויהיה דין הוצאה דין בשינוי מקום חפץ, וכיון דאין זה דין בעצם השינוי, היינו, דאין מקום זה כמקום זה, בהכרח דהוא גדר במשמעות המקום עצמו כמקום חפץ, וביחס למשמעות חפץ במקומות שונים, וזה סתירה, ע\"כ בהכרח דגדר השינוי הוא ביחס לאדם, ואכמ\"ל). והיינו שדין רשויות שמן התורה אינו אלא ביחס לחפץ ומקום חפץ, וע\"כ גדרי רשויות עצמם יהיו ביחס למושג מקום דחפץ (וע\"כ יהיה גדר קרקע מקום בסיס לכל רשות, כי זה משמעות מקום ביחס לחפץ, לעומת שימוש בחפץ שאינו ממושגי מקום חפץ עצמו אלא ממושגי אדם ביחס לחפץ, וע\"כ לא יהיה תנאי ברשות התורה שאינו גדר במקום החפץ, היינו, הקרקע)."}, {"s": "h7", "h": "ביאור חילוק עיקר גדר רה\"י מרה\"ר - רה\"י מוגדרת בקרקעה נפרדת ורה\"ר מוגדרת בשימושה"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"518\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">56\u003c/sup>\u003cspan class=\"ca\" data-c=\"518\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">ובזה יבואר מה דאיכא ברה\"י דליכא ברה\"ר ביחס לגידור, ומה דאיכא ברה\"ר דליכא ברה\"י ביחס לשימוש, והיינו, דודאי אין גדר שינוי מקום חפץ דהוצאה אלא ביחס למקום חפץ, והוא בקרקע, וגדר רה\"י הוא גדר במקום אדם יחיד, וממילא גדר מקום חפץ הוא ביחס לשייכות אדם וחפץ, וגדר זה במקום הוא גדר סיום, היינו, מקום זה ולא מקום אחר, שזה המושג שייכות ביחס למקום. וע\"כ ביחס למקום חפץ, היינו, הקרקע, יהיה גדר שקרקע זו נפרדת. אך גדר רה\"ר אינו ביחס לאדם מסוים, שאין אדם אחד מגדיר רה\"ר, וע\"כ ביחס למקום חפץ לא יהיה הגדרת הקרקע במה שהיא נפרדת, ויותר מזה דאין כלל הגדרה בקרקע דרה\"ר בנפרד משימושה, דרוחב רה\"ר וצורתו הם גדרים שליליים דחוסר הגבלה. וא\"כ אין כלל הגדרה בצורת רה\"ר, אלא כל משמעות רה\"ר הוא בשימושה, וע\"כ לא תוגדר אלא בשימושה, וע\"כ תנאי רה\"ר הוא בשימוש. אלא דכיון שהוצאה נוגעת למקום חפץ, והיינו, קרקע הרי שגדר שימוש הרבים אינו רה\"ר עצמה, אלא ששימוש הרבים מגדיר את הקרקע, וזה באותה המשמעות כמו ברה\"י. וע\"כ כל שיעורי רה\"ר יהיו במובן של חוסר הגבלה, שאין הם משמעות חיובית בקרקע אלא בהגדרת השימוש. וע\"כ אם לא יהיה בהם משמעות ביחס לשימוש, היינו, שלא יהיה בהגבלה הנ\"ל, משמעות ביחס לשימוש, לא יהיה זה חסרון בהיות הקרקע רה\"ר, ואי איך שלא יהיה הרי שגדר רשות התורה הוא בקרקע המקום כי הם ביחס למקום חפץ, ואין מקום חפץ בכל הרשות אלא בקרקעה, וכל הדינים הנוגעים למה שהוא לא גדר בקרקע, הם בהכרח לא דינים עצמיים אלא ביחס לקרקע. וע\"כ לא יהיה גדר מחיצות דרה\"י אלא גדר בקרקע, והיינו, שאף שיש ברה\"י מה שאין ברה\"ר שיש בו משמעות שהוא תופס חלל, שהרי עולה עד הרקיע, אין זה חלק מהגדרת הרשות, שאין הגדרת הרשות אלא בקרקעה, והיא אינה אלא ביחס לגובה עשרה. וגם אין יועיל בה גדרים שאינם נוגעים לקרקעה באופן חיובי, ואם נמצא בדיניה גדרים הנוגעים לזה, הרי בהכרח שהם גדרים שליליים כמניעה וכו'.\u003c/span>"}, {"s": "h7", "h": "חילוק תקנ\"ח ברשויות מדיני דאורייתא - תקנת חכמים ביחס לחלל הרשות ולא לקרקעה לבד"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"1106\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">57\u003c/sup>\u003csup class=\"cb\" data-c=\"519\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">58\u003c/sup>\u003cspan class=\"ca\" data-c=\"1106 519\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">אך גדר מה שתקנו חכ' הוא ביחס הפוך, דאין הם דינים ביחס לקרקע, אלא ביחס לרשות עצמה, היינו, חללה. והיינו, שראו חכ' שאף שקרקע רה\"י מוגדרת היטיב כדינה מן התורה, הרי שהתייחסות האנשים לחלל הרשויות כזהות הרשות יביא להחליף את משמעות זהות הרשויות ממשמעות הקרקע למשמעות החלל. והרי אין דיני רשויות מן התורה מיועדים ומועילים להגדיר את החלל. וע\"כ תקנו דינים הנוגעים לחלל הרשות, והיינו, שאם היה ברור גדר זה דאין רשות אלא ביחס למקום חפץ, ואין רשות אלא בקרקעה, היה הבדל הרשויות ברור לאנשים. אך כיון דאין זה ברור, הרי שאנו נצרכים להגדיר אף את חלל הרשות, וזה משמעות מה שתיקוני מבוי שווים, בלי שייכות לדין מחיצות התורה, ובין אם יהיה הדין ב' או ג' מחיצות דאורייתא, יהיה דין להכשיר את המבוי מארבעה צדדים.\u003c/span>"}, {"s": "h3", "h": "\u003csup class=\"cb\" data-c=\"1107\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">59\u003c/sup>\u003cspan class=\"ca\" data-c=\"1107\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">י. במשמעות מחיצות להגדיר קרקע מקום\u003c/span>"}, {"s": "h7", "h": "חילוק מח' במספר המחיצות והכשר מבוי - הגדרת קרקע מדאורייתא לעומת הגדרת חלל בארבעה צדדים"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"1108\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">60\u003c/sup>\u003csup class=\"cb\" data-c=\"520\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">61\u003c/sup>\u003cspan class=\"ca\" data-c=\"1108 520\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">וזה ביאורו, כי גדר המח' ביחס למספר המחיצות הוא ביחס להגדרת קרקע, אך גדר הכשר מבוי נוגע להגדרת חלל, ובזה כ\"ע מודו דאין הוא מוגדר אלא ע\"י ארבעה צדדים, וזה גדר תיקון דמחיצה רביעית. דאין הכוונה דחכ' גזרו לתקן עוד מחיצה או ב' באותו הגדר דמחיצת תורה, אלא גדר מחיצה בזה הוא במשמעות ביחס לחלל, ובזה ודאי שהוא בארבעה צדדים. ובזה המשמעות יהיה שם מפולש, והיינו, דביחס לקרקע אין משמעות פילוש אלא רק בחסרון מחיצות, ואף בבקעי בה רבים אין החסרון בעצם הפילוש אלא בביטול המחיצה, והרי גדר מפולש הוא, היינו, הך, ובלי שייכות להיכן הוא מפולש. והוא כמו שאמרנו שגדר תקנת חכ' במבוי הוא ביחס לחלל הרשות, וביחס לחלל הרי כל אוויר הרשות במשמעות אחת, ויהיה משמעות בצורת הצדדים, ובזה יבואר גדר לחי ומה דאין לו שיעור רוחב, וגדר פס ארבעה ומה שהוא בלי שייכות לרוחב הרשות, והיינו, דתיקון שהוא ביחס לקרקע המקום ודאי שהוא תלוי ברוחבו דאין גובה הרשות אלא ביחס לקרקעה, והיא ברוחב. אבל כיון דגדר תקנת חכ' כאמור הוא ביחס לחלל, ובזה הרי שאין עדיפות לרוחב על הגובה, דהם באותה משמעות, וע\"כ יתכן להגדיר את החלל ע\"י משמעות גובה כללית.\u003c/span>"}, {"s": "h7", "h": "חילוק גדר לחי מגדר פס - פס מחיצה עצמית ולחי מחיצה רק עם כלל המבוי"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"521\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">62\u003c/sup>\u003cspan class=\"ca\" data-c=\"521\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">(ויש לצרף לזה הא דאיתא גמ' (יב:) אמר רב יהודה אמר רב מבוי שארכו כרחבו אינו ניתר בלחי משהו אמר רב חייא וכו' אינו ניתר בקורה טפח. אמר רבי זירא כמה מכוונן שמעתא דסבי כיון דארכו כרחבו הוה ליה חצר וחצר אינה ניתרת בלחי וקורה אלא בפס ארבעה. אמר רבי זירא אי קשיא לי הא קשיא לי ליהוי האי לחי כפס משהו ונשתרי. אישתמיטתיה הא דאמר ר' אסי אמר ר' יוחנן פסי חצר צריכין שיהא בהן ארבעה. והנה משמע דדין פס אף להו\"א דהוא משהו אינו בגדר לחי, וזה אף למאן דס\"ל דלחי משום מחיצה, וכן נראה דאין בפס חסרון דלחי העומד מאליו, והיינו, דפס הוא גדר מחיצה בעצמו, אך לחי אין חשוב מחיצה אלא במה שהוא חלק מצורת כלל המבוי. וכן משמע מלשון לחי. ומשא\"כ פס שמצאנוהו אף כשאינו מחובר למחיצות שבצדדיו, כמו ריבוי פסין בבאר. וע\"כ נראה שהוא גדר עצמי של מחיצה, ויהיה שייך בו דין מחיצה העשויה מאיליה דהוי מחיצה. \u003c/span>"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"522\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">63\u003c/sup>\u003cspan class=\"ca\" data-c=\"522\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">ואף למאן דס\"ל דלחי משום מחיצה אין הכוונה שלחי עצמו חשיב מחיצה, דאפילו לגבי שם ד' מחיצות לא חשיב, אלא ביאור גדר שום מחיצה דיליה הוא משום דבצירוף הלחי למבוי נחשב שהמבוי חלוק מרשות שלפניו כאילו היתה לו מחיצה, וזה גדר לחי משום מחיצה, היינו, שתיקון לחי הוא משום שע\"י יחשב שיש למבוי מחיצה. ולפי\"ז צ\"ל ביאור חילוק גדר לחי אי משום מחיצה אי משום היכר הוא, דגדר מחיצה הוא עצם החלוקה שנעשית ע\"י המחיצה. אך גדר היכר הוא מה שניכר צורת הרשות, ואף אמנם שאין לחי או קורה חוצצים למעשה את המבוי מרשות שלפניו שהרי ניתן לעבור בו אבל מורים על הפרדת הרשויות.)\u003c/span>"}, {"s": "h7", "h": "בירור מספר המחיצות הנדרש לרה\"י - שתי מחיצות שלמות דיים לגדר ריבוע הקרקע"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"523\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">64\u003c/sup>\u003cspan class=\"ca\" data-c=\"523\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">ובביאור גדר הנידון במספר המחיצות הנדרש לרה\"י, ובהקדם מה שאמרנו דגדר גובה דרה\"י הוא ביחס לקרקע וא\"כ הרי שאין משמעות שלילית בחסרון מחיצה, אלא משמעות חיובית, היינו, שיש להגדיר קרקע גם ע\"י גובה, והיינו, דודאי לכ\"ע די בהגדרת הקרקע ע\"י שתי מחיצות שלמות, או דיומדין, דבזה מוגדר ריבוע דקרקע היטיב, ובזה לכאורה לא היה אמור להיות שינוי בין שבת לסוכה, ואם היה, לא היה מועיל מיגו. ובהכרח דריבוע דקרקע מוגדר היטיב ע\"י שתי מחיצות בין דעריבן ובין לא, וכמו המסתבר. \u003c/span>"}, {"s": "h7", "h": "משמעות מחיצות לכל חלק בקרקע - מניעת כניסה לרשות מול הגדרת הקרקע ע\"י גובהה"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"1109\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">65\u003c/sup>\u003csup class=\"cb\" data-c=\"524\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">66\u003c/sup>\u003cspan class=\"ca\" data-c=\"1109 524\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">ובהכרח צ\"ל דמלבד שיש במחיצות משמעות הגדרת הקרקע, יש משמעות בעצם המחיצות ביחס לכל חלק בקרקע, ומה שיש בזה משמעות ביחס להגדרת הרשות, והיינו, דאף דאמרנו שגדר גובה עשרה הוא גובה דקרקע, אך הרי סיבת מה שגובה בכלל נוגע לקרקע הוא כי היא עצמה מוגדרת ביחס לחלל, וכן משמע מדברי רש\"י בסוכה בילפותא דר' שמעון מזרם, דיש שייכות בין גדר הרשות לסיבת מספר המחיצות, והנה מדברי רש\"י הנ\"ל יש לבאר עכ\"פ גדר מאן דס\"ל ד' מחיצות דאורייתא הוא שלא יהא כניסה לתוך הרשות דבזה כל צד הוא משמעותי, ולא יועיל צד אחד לצד שני. \u003c/span>"}, {"s": "h7", "h": "גדר מחיצות ביחס לרשות שבת - מניעת פריצה לרשות ומשמעות חלוקת הדין בצדו מראשו"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"525\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">67\u003c/sup>\u003cspan class=\"ca\" data-c=\"525\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">וביחס לרשות דשבת יש לומר דהוא במשמעות מניעת פריצה לרשות, וכן משמע בפרוץ מרובה ברוח אחת, ובשם נפרצה במילואה, ולשון נפרצה מב' רוחות, דמשמע דהוא חסרון בכל צד בנפרד. ובזה יהיה שייך חלוקת הדין בצדו מראשו. והיינו, שאף שאין מחיצות רה\"י במשמעות הגדרה שיש בהם יחס לפירצה מסויימת, הרי שיהיה משמעות במחיצות ביחס למושגי עירוב, וזה יהיה משמעות פירצה. וכיון שאין המחיצות רק כהגדרה לנפרדות הקרקע, יהיה בזה גדרים של רוב ובמילואה וכו'. \u003c/span>"}, {"s": "h3", "h": "\u003csup class=\"cb\" data-c=\"1110\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">68\u003c/sup>\u003cspan class=\"ca\" data-c=\"1110\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">יא. בגדר ג' מחיצות\u003c/span>"}, {"s": "h7", "h": "משמעות ג' מחיצות ברשות שבת - בקעי בה רבים ומפולש ולישנא דנכנסים ויוצאים"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"526\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">69\u003c/sup>\u003cspan class=\"ca\" data-c=\"526\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">ובגדר ג' מחיצות מצאנו דלגבי עירוב בפועל זה הוי בקעי בה רבים, ולגבי הגדרת מקום זה קרוי מפולש, וכבר כתבנו דאין משמעות מפולש בלי בקיעה ביחס לרשות דאורייתא, וגם אין חסרון דמפולש שווה בכל הצורות, ואף אי ס\"ל דמבוי עקום דינו כמפולש, אין הוא מפולש, ואין זה שייך למספר המחיצות. אך גם ביחס לבקיעה בפועל לא מצאנו אלא משמעות לשם ד' מחיצות, משמע דאין בקיעה גדר בשלוש מחיצות, וגם שם בקיעה הוא ביחס לדבר עצמו ולא לצדדיו. ועוד מצאנו שנקרא נכנסים לה בזה ויוצאים לה בזה, והיינו, דזה גדר מעבר, אך גדר זה הוא גדר רק ביחס לבקיעה בפועל. וזה אף ביחס לשלוש מחיצות יחד ולא כל אחד לחוד. ועוד דאין זה במשמעות המחיצה עצמה, ובפרט דזה נאמר במקום דהוא מועיל לשבת, והרי אין כניסה או יציאה חסרון בג' מחיצות.\u003c/span>"}, {"s": "h7", "h": "חילוק ג' מחיצות מב' וד' - שתי מחיצות לסתימת אורך ושלישית להגדרת אי פירצה"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"527\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">70\u003c/sup>\u003cspan class=\"ca\" data-c=\"527\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">וע\"כ נראה דבאמת אין משמעות לג' מחיצות באותו המובן שיש לא' וב' וד' שיש להם משמעות אחת, אלא יש בזה שני גדרים. האחד, בב' מחיצות לבד, ובגדרם הכולל יחד. והשני, במחיצה ג', ובמובן של מחיצה אחת. והיינו, כדאמרן דביחס להגדרת הקרקע, היינו, כל חלק שאין לו צדדים ביחס לשטח רשות, דאית בה ד' צדדים ויש משמעות, יהיה משמעות במחיצה אחת לגבי פירצה, ובשתיים לגבי סתימה, ובשלוש יהיו השתיים סתימה ביחס לאורך, והשלישית ביחס לפירצה. והיינו, שגדר סתימה דב' רוחות יגדיר רוחב המקום, ועומד דשלישית יגדיר אי פירצה ביחס לכל המקום דהיא בקיעה.\u003c/span>"}, {"s": "h7", "h": "העדר שייכות מנין מחיצות למקום - פס בחצר ודיומדין בפסי ביראות כראיה לגדר המקום"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"528\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">71\u003c/sup>\u003cspan class=\"ca\" data-c=\"528\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">ואחר העיון נראה דגדר מספר מחיצות אינו שייך בגדר המקום עצמו, דמצאנו שד' מחיצות הן סיבה לחילוק בין היתר טלטול דרבנן בחצר לעומת מבוי, כי בחצר יש ד' מחיצות. והנה חצר לא נשתנתה ממבוי אלא דבחצר צריך פס, ולא די לחי, והרי אין פס מחיצה למקום, שאינו ברוב המקום, ואין בו דין עריבן. אלא הוא מחיצה לעצמו, ואעפ\"כ נחשב חצר כיש ד' מחיצות, וכן הוא בפסי ביראות דנחשב שיש למקום שם ד' מחיצות, אף שאינם ביחס לכלל מקום, ואף שיש בשני אלה הגבלה ביחס לגודל המקום, עשר בחצר, ויג' ושליש בפסי ביראות, הרי אף אם נאמר שיש לשיעורים אלו גדר בהגדרת פירצה, אין זה מועיל לגדר המקום כבעל מחיצה, דבזה היה לומר רוב ושאר דינים. \u003c/span>"}, {"s": "h7", "h": "גדר ארבע מחיצות לר\"ש בסוכה - שייך בסוכה ולא בשבת ואינו דין במקום דאורייתא"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"529\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">72\u003c/sup>\u003cspan class=\"ca\" data-c=\"529\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">וע\"כ נראה דאמנם לר\"ש דסוכה (אי נימא דהוא יליף מזרם, וכפרש\"י) נראה שזה אכן גדר במקום, אך בשבת אין לזה שייכות למקום, ויותר מזה דאף בסוכה איתא להאי גדר, שהרי אף אי איתא להילכתא, יש גדר במחיצת טפח מבלעדיה. ויש לבאר גדר זה שאינו שייך לגדר המקום, ובפרט שלא מצאנו שתהיה מח' במספר המחיצות, ביחס לדין דאורייתא. \u003c/span>"}, {"s": "h3", "h": "\u003csup class=\"cb\" data-c=\"1111\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">73\u003c/sup>\u003cspan class=\"ca\" data-c=\"1111\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">יב. בגדר מחיצה עצמה\u003c/span>"}, {"s": "h7", "h": "חילוק מחיצת שבת מסוכה האמור בתוס' - מניעת רגל רבים ומחיצות מגיעות לסכך"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"530\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">74\u003c/sup>\u003cspan class=\"ca\" data-c=\"530\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">והנה בגדר מחיצה עצמה (בלי שייכות לצדדי גובה המקום או לרוחב הקרקע) מצאנו בתוס' שחילק בין שבת וסוכה, דגדר מחיצת שבת הוא למנוע רגל רבים, וע\"כ אין חסרון מרחק יותר מג' ביחס לגובה עשרה, מה שאין כן בסוכה שמחיצתה הוא משום דמגיעה לסכך. וכוונתם, דגדר עצם המחיצה עצמה הוא מניעת רגל רבים, ולא נתכוונו דזה גדר רשות המחוצה, שהרי אין פתח מונע רגל רבים, ולא צורת הפתח, ולא ג' מחיצות. וגם אין משמעות מגיעות לסכך שייך ברוחב או צד, והיינו, שהרי אין זה גדר השייך למחיצה עצמה לבד, אלא רק ביחס לגובהה, דברוחבה היא ביחס לקרקע, וברוחבה וגובהה יחד יש לומר, שזה גדר בגובה שטח. אלא כוונת תוס' לעצם המושג מחיצה שאם לא יועיל למנוע רגל רבים, לא יחשב כלל מחיצה ולא יועיל אפילו ללחי, ואין כוונתו למניעת כניסת רבים דבזה אין משמעות לרבים, ובוודאי אין משמעות לעצם המחיצה, דזה כאמור גדר ביחס לרשות, אלא כוונתו למאי דאמרינן דלא דרסי לה רבים, היינו, שאין הרבים משתמשים במקום זה ביחד עם השתמשותם ברה\"ר, דהשתמשות רבים היא השתמשות אחידה ללא מניעות.\u003c/span>"}, {"s": "h7", "h": "חומרת מחיצה בשבת מדינא דמגבשושית - מחיצה המונעת רגל רבים ולחי של אשירה"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"531\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">75\u003c/sup>\u003cspan class=\"ca\" data-c=\"531\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">וזה גם משמע בגדר גבשושית פחות מג', דאי לאו סברא דאי אפשר דתילקט או דין לבוד סברה הגמ' דלא הוה לה דין רה\"ר, וכן משמע מצואה וכו', וזה אפילו במשהו, וזה חומר דמחיצה בשבת (וזה פשר מה דעבדינן לק\"ו בעל גבי מחיצה, והיינו, דמשום מחיצה עצמה אין היא רק מקום פטור, דאין בה משמעות גובה עשרה, דזה רק צירוף לגבי הרשות, והק\"ו הוא ביחס לזה, ואכמ\"ל). וע\"כ שייך שיהיה לחי משהו, ולא יהיה בו חסרון דכתותי מיכתת שיעורה, שביחס לגובה אין זה חשיב שיעור, שזה ביחס לרשות. ואין בלחי עצמו אף למ\"ד משום מחיצה אלא מה שהוא חומר המונע רגל רבים, וזה משמעות שלילית, וליכא חסרון דהוא לשריפה. \u003c/span>"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"532\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">76\u003c/sup>\u003cspan class=\"ca\" data-c=\"532\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">אך גדר דמחיצת סוכה הוא גדר במחיצות מגיעות לסכך, היינו, דבעצם החומר של המחיצה יש משמעות בזה שהוא חיבור של הקרקע לסכך, ואף שאין דין שיגיעו לסכך ממש, זהו משום שאין דין מחיצה אלא בגובה הקרקע, אך חומר המחיצה צריך שיהיה לו משמעות הגעה לסכך. וא\"כ אין זה רק צירוף חלקים נפרדים, אלא יש משמעות בהמשכיותו, ויש לו אורך בעצמו, וא\"כ אי לאו דהוי לבוד, הרי אינו במשך אחד. ויש בזה תוספת ביאור בגדר דופן דאית במחיצה דסוכה. וכן נראה דזהו גדר טפח דסוכה ולהבדיל ממשהו דלחי, דזה גדר בחלל, היינו, שביחס למשמעות מחיצה שהיא מחברת קרקע לסכך, יש ברוחבה משמעות לגבי גדר חלל דהוא בטפח, ויבואר מה דלא מועיל בהאי טפח לבוד, דזה לא שייך רק על הרוחב הנוגע לקרקע, אבל בהגדרת המחיצה את חלל הקרקע כמסוכך אינו רוחב ואין בו צירוף (משא\"כ באוהל שהוא יחס ישיר לגבי חלל).\u003c/span>"}, {"s": "h7", "h": "חילוק לחי מפס בגדרי מחיצה - לחי הוי ביחס למחיצה שבצידו ולא כעומד לעצמו"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"533\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">77\u003c/sup>\u003cspan class=\"ca\" data-c=\"533\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">והנה לחי הוא ביחס למחיצה שבצידו, והיינו, דאין בו כח להיחשב מחיצה ע\"י עצמו, וגם אינו מחיצה ביחס לצד שהוא נמצא בו. והיינו, דפס חשיב מחיצה, וחשיב שיש למקום ד' מחיצות, אך לא ביחס לכל צד, שהרי פרוץ מרובה, וגם אין משמעותו מחיצה לעצמו, היינו, ביחס לשטח שהוא נמצא בו, דהא נראה מבחוץ גם חשיב לחי. ובאמת דזה מבואר מעצם שמו כלחי שפירש רש\"י שהוא ביחס למחיצה שבצידו. היינו, שהוא תוספת הגדרה במחיצה שבצידו שתהיה נחשבת גם ביחס לצידה. \u003c/span>"}, {"s": "h7", "h": "משמעות לחי בהגדרת מקום מבוי - חילוק בין מקום שאורכו יתר על רחבו לחצר"}, {"s": "p", "h": "וכמו שאמרנו בביאור דעת מאן דס\"ל שתי מחיצות דאורייתא, דאף הוא מודה דאיכא למקום ד' צדדים, ושא\"כ יקשה איך שייך שיוגדר המקום ע\"י שתי מחיצות, וביארנו שלדעתו דין מחיצות הוא ביחס לעצם הגדרת המקום, דכיון שהוא מרובע הרי ששתי מחיצות יגדירוהו, דיש בעצם צורת המקום המוגדרת בשתי מחיצות וגבול השפעתם, הגדרה לכלל המרובע, אלא שאין זה הגדר מכוח המחיצה עצמה לבדה אלא רק מכוח מה שאנו מתייחסים למקום כמרובע, וע\"כ לא יהיה זה הגדרה לכלל שטח הקרקע."}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"534\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">78\u003c/sup>\u003cspan class=\"ca\" data-c=\"534\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">וזה גדר לחי, שע\"י לחי יש במחיצה שבצד עצמה הגדרה לצד שבראשה, וזה משמעות שם לחי, ובזה יבואר במה שאין לחי מועיל אלא במקום שאורכו יתר על רוחבו, כי משמעות מחיצות צד במקום שמוגדר בצד אחד יותר מצד אחר, והרי שאין צדדיו שווים בחשיבותם ביחס להגדרתו, ויהיה משמעות יתירה למחיצות הצדדים החשובים, וע\"כ יועילו להגדרת צד מסויים, וזה כמו רוב ביחס לשטח. אך בחצר מרובעת שאין משמעות יתירה לצדדים מסויימים, לא תועיל תוספת משמעות במחיצה לגבי צד זה, שאין כלל משמעות מחיצה בצד זה, וע\"כ יצטרכו לפס להגדיר מחיצה בצד זה.\u003c/span>"}, {"s": "h3", "h": "\u003csup class=\"cb\" data-c=\"1112\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">79\u003c/sup>\u003cspan class=\"ca\" data-c=\"1112\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">יג. בגדר קרקע מקום\u003c/span>"}, {"s": "h7", "h": "עירוב דקרקע בכלאיים לעומת שבת - עירוב קרקע בכלאיים נוגע לגידוליה דקרקע"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"535\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">80\u003c/sup>\u003cspan class=\"ca\" data-c=\"535\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">ובזה הגדר נמצא חילוק שיש בין מחיצת מקום למחיצת כלאיים, והיינו, כי אין דין עירוב דכלאים מחמת היות המקום עצמו מעורב, היינו, שקרקע מחוברת לקרקע שבצידיה, דבגדר זה לא יועיל הרחקה, אלא הגדר הוא בעירוב הגידולים. ואך חיבור הגידולים שייך בשני אופנים או בעירוב של הגידולים עצמם, או במה שהגידולים מגדירים את הקרקע, וממילא כל שיהיה יחד באותה קרקע יוגדר שהוא מעורב בגידולים אלו ע\"י קרקע. וכיון שמשמעות קרקע הוא ביחס לגידולים, גם משמעות עירוב קרקע הוא ביחס לגידולים, וע\"כ לא יהיו שני קרקעות מחוברים לעניין זה אלא ביחס למשמעות קרקע דגידולים. ובזה הגדר יהיה חילוק הדין שבין כלאים דכרם לכלאים דזרעים, דשם כרם מגדיר את כל המקום שלו כקרקע אחת דכרם, וע\"כ יהיה בקרקע גדר כרם. והיינו, דגדר קרקע דכלאים בזרעים אין הוא שם בקרקע במושגי קרקע כשלעצמה, אלא רק במושגי גידול שיש בה, וע\"כ לא יהיה עירובו נובע מהגדרות השייכות למקום. אך דין כרם דתליא בגדרי מקום, והיינו, דמלבד מה שבקרקע זו יש גידולים מסויימים שגדר כלאיים דגידולים מוגדר על ידה כי הם בקרקע, יש גדר בקרקע עצמה שהיא קרקע של גידולים אלו, אבל גם בגדר זה אין מושגי עירוב קרקע ביחס למושגי קרקע הכלליים (כמקום שימוש סתם), אלא ביחס למושגי קרקע דגידולים.\u003c/span>"}, {"s": "h7", "h": "משמעות מחיצה לגבי עירוב כלאיים - מחיצת כלאיים במשמעות הרחקה וניתוק ולא הגדרת נפרדות"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"536\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">81\u003c/sup>\u003cspan class=\"ca\" data-c=\"536\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">וע\"כ יהיה גדר העירוב דקרקע ביחס לשימושי קרקע לצורך גידולים, וע\"כ יהיה משמעות זו כמו במשמעות עירוב דגידולים, וכיון דעירוב דגידולים נוגע לחיבור שני דברים, וביחס לכל אחד מהם הרי זה בגדר קירבה והרחקה, הרי שגם משמעות קרקע שלהם תהיה בגדר זה. וע\"כ יהיה משמעות מחיצה ביחס לעירוב קרקע זה גם בגדר הרחקה וניתוק, ולא במשמעות הגדרה ונפרדות. וע\"כ גם כשתהיה הגדרה למקום, לא תהיה משמעות המקום אחד אלא ביחס לזה.\u003c/span>"}, {"s": "h7", "h": "גדר עירוב דקרקע ברשויות שבת - עירוב ביחס למשמעות שימושית כללית ולא לשימוש מסויים"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"537\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">82\u003c/sup>\u003cspan class=\"ca\" data-c=\"537\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">אבל גדר עירוב דקרקע ביחס לרה\"י אין הוא במשמעות מסויימת בשימוש קרקע, אלא מעצם עירוב דקרקע במשמעותה השימושית (וזה עיקר משמעותה לעירובה), והיינו, דכיון שגדר רה\"י בקרקע אינו נוגע לעצם הגדרת רשות, שהגדרת רשות היא בעצם מה שמיועדת לשימוש, וכמו ברה\"ר, אלא הוא נוגע להיותה רשות נפרדת, והרי אין גדר זה של רשות נפרדת במובן רשות המיועדת לשימוש שייך אלא ע\"י הגדרת המקום כנפרד, הרי שזה חשוב כגדר בקרקע עצמה, וביחס למושגי קרקע עצמה יהיו כל הקרקעות אחת. וע\"כ ע\"מ להגדיר קרקע נפרדת ע\"י מחיצה, נצטרך להגדירה כאחת. שהרי זה משמעות קרקע הבסיסי שהיא אחת, והיותה נפרדת גם פירושו שהיא אחת נפרדת. וע\"כ יהיו גדרי מחיצה דמקום רשות במשמעות אחת, ודלא כגדרה בכלאיים.\u003c/span>"}, {"s": "h7", "h": "חקירה באוקיינוס המקיף כולי עלמא - אי החסרון בכח מחיצות או בעצם אחדות הקרקע"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"538\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">83\u003c/sup>\u003cspan class=\"ca\" data-c=\"538\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">ואחר העיון נראה שאין זה מוכרח, והיינו, שמדברינו משמע דגדר עירוב קרקע דרשות הוא במשמעות קרקע עצמה, ולא במשמעותה לגבי רשות (לעומת כלאיים שאינו בגדרי קרקע עצמה, אלא בגדרי קרקע דגידולים), והיינו, שמשמעות עירוב קרקע הוא כמו מה דאמרי' לגבי קנין דסדנא דארעא חד הוא. ולכאורה י\"ל זה תלוי בסיבת מה שאין כולי עלמא רה\"י דמקיף ליה אוקיינוס, אם הוא חסרון במחיצה או חסרון במקום. והיינו, שאם הוא חסרון במחיצות (או בגדר היקף, או בגדר צד, אך לא בגדר מניעת רגל רבים), ביאורו שאין בכוח מחיצות להגדיר מקום בגודל כזה, ואף שביחס לקרקע אין חסרון בהגדרת קרקע גדולה כזו, שהרי כל משמעות מחיצות הוא ביחס לקרקע, וכיון שקרקע זו אחת היא יש אפשרות להגדירה, אלא שזה אי אפשר ע\"י מחיצות (או מחיצות רגילות בכל אופן). או דילמא אין זה חסרון במחיצות וכי כל גדר מחיצות הוא ביחס לקרקע ומשמעותה, ואם קרקע עולם אחת היא, הרי שיש למחיצות להועיל בה, אלא שאין קרקע עולם אחת, והיינו, דלא כמו שכתבנו דגדר הגדרת רה\"י, הוא ביחס למושגי קרקע עצמה, וכמו גדר סדנא דארעא חד הוא, אלא באמת גם גדר קרקע דרשות, כמו גדר קרקע דכלאיים, מוגדר ע\"י מושגי רשות עצמה., והיינו, טעמא דלא הוה רה\"י, דכיון שאין משמעות רשות אחת ביחס לכל העולם, הרי שאין שלא יועיל בזה מחיצות. ויש חסרון בעצם הקרקע להיות אחת.\u003c/span>"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"539\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">84\u003c/sup>\u003cspan class=\"ca\" data-c=\"539\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">(ובעיקר הא דאמרו כולי עלמא מקיף וכו' ומשמע דנדחה, מצאנו דיש מי שאומר שהוא חסרון דווקא במחיצות שאינם נעשות ע\"י אדם (ובתוס' כתבו דהוא לרבנן דלא אתי רבים, וזה קשה דאף לר\"י הרי איכא הכא ב' מחיצות מעלייתא. וא\"ת שאין חשיבי מעלייתא משום גודל המקום, או שאין נעשות ע\"י אדם, א\"כ יש לומר דגם לא חשיבי שם ד' מחיצות, ומהיכי תיתי לחלק, ובפרט דהכא איכא יותר מטז' אמה ודלא כבפסי ביראות). וזה צ\"ב שלא מצאנו גדר בגודל מקום ביחס למחיצה, אלא ביותר מב' סאתיים. ואף בזה מחיצה העומדת מאליה חשיבא מחיצה ופה לא מצאנו שיעור אחר. ובאמת יש לבאר לשון ר\"י דאין חייבין עליה משום רה\"ר, שהרי לא מצאנו שיש למחיצות גדר ברה\"ר אלא ברה\"י. והווה ליה למימר דהוי רה\"י לזרוק, ואף אי נימא דיש חסרון ברה\"ר שיש לה מחיצות אפילו ביותר מטז' אמה (ודלא כהרשב\"א בדין פלטיא), הרי בשני מחיצות ודאי ליכא חסרון, ואף דבארץ ישראל יש ארבעה מחיצות (היינו ים וירדן ויש לבאר למה לא פירשו זה בגמ'), הרי הקשו בגמ' מבבל דליכא ליה אלא שתיים. ובאמת דזה קשה איך שלא יהיה, דאף אי נימא דהוא לדעת ר\"י, הרי מודה דלא חשיב רה\"י ביותר מטז' אמה. ומעצם דברי הגמ' משמע דאין זה חלק מגדרי רה\"ר עצמה, שהרי דין מחיצות דרה\"ר ביותר מט\"ז, היה לדון בו בלי שייכות לארץ. ולפמש\"נ לק' יתבאר קצת.)\u003c/span>"}, {"s": "h7", "h": "גדר קרקע דרשות לגבי מחיצות - חסרון מחיצת אוקיינוס בהיות הקרקע אחת למקום שימוש"}, {"s": "p", "h": "וע\"כ נראה דאין גדר דקרקע רשות גדר קרקע סתם, וכמו מה דאמרינן סדנא דארעא חד הוא (וגם בזה היה לחקור אי מהני לאיים שבים, ובפשטות נראה שהוא ביחס להגדרת קרקע כאינה נגזלת, ואכמ\"ל), אלא הוא גדר נפרד ביחס למושגי רשות, היינו, משמעות שימושים שיש בקרקע. וחסרון דמחיצת אוקיינוס אינו במחיצה, אלא בקרקע, והיינו, רבותא דאוקיינוס לכולי עלמא לעומת בבל, דהרי ודאי לא נאמרו דיני התורה ביחס למקום ללא גבול, דזה אינו במציאות, ובהכרח דגדר קרקע ומקום קרקע לגבי רשויות, הוא ביחס למשמעותה כמקום שימוש, ואכן שוו בזה להדדי גדר כרם וגדר רשות, אלא הבדל שיש ביניהם הוא משום שגדרי קרקע דכרם וקרקע דשבת שונים זה מזה, וכמש\"כ."}, {"s": "h7", "h": "גדר קרקע ביחס לרשויות שבת - שימוש אדם מגדיר קרקע וקרקע רשות ורשות מקום"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"540\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">85\u003c/sup>\u003cspan class=\"ca\" data-c=\"540\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">וע\"כ לא יהיה משמעות קרקע לגבי רשויות כשלעצמה אלא ביחס להיותה מקום שימוש, וכך יהיו גם גדרי רשות ורשות נפרדת, ששימוש אדם מגדיר קרקע, וקרקע מגדירה רשות, ורשות מגדירה מקום, ומקום גדר בחפץ. ובזה יהיה כדי ביאור מה דאין חסרון דמפולש משער לשער בסרטיא, והיינו, דאל\"כ לא היה גדר זה בעיר, דממה נפשך אי אין סרטיא אלא המפולשת, הרי בהכרח דעיר חשיב רה\"ר, ואיך אפשר להגדיר עיר במה שמפולשת לסרטיא. אלא בהכרח דגדר מפולש אין שייך בסרטיא, ואפילו יהיה רה\"י בשתי ראשיה חשיבא רה\"ר, כי משמעותה בהיותה דרך הרבים בעצמה, ולא במה שהיא מחוברת למקום אחר. \u003c/span>"}, {"s": "h3", "h": "\u003csup class=\"cb\" data-c=\"1113\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">86\u003c/sup>\u003cspan class=\"ca\" data-c=\"1113\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">יד. הצ\"ב בבריתא דיתר על כן\u003c/span>"}, {"s": "h7", "h": "בחסרון מבוי דלו\"ק מכאן ולו\"ק מכאן – ובטעמא דר' יהודה להיתר"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"541\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">87\u003c/sup>\u003cspan class=\"ca\" data-c=\"541\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">ובעיקר הברייתא דתני יתר על כן א\"ר יהודה מי שיש לו שני בתים בשני צידי רה\"ר עושה לחי מכאן ולחי מכאן או קורה מכאן וקורה מכאן ונושא ונותן באמצע, אמרו לו אין מערבין רה\"ר בכך. ע\"כ. הנה איירי במקום שהוא חלק מרה\"ר שיש בשני צידי דרך הרבים בתים, ובתוס' דנו ברוחבה ע\"ש, ועכ\"פ משמע דשני ראשיו רה\"ר, ואף הוא עצמו חשיב רה\"ר, וגם לא נראה דר' יהודה פליג בזה, דלשון שני בתים בשני צידי רה\"ר הוא מלישנא דר\"י. \u003c/span>"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"542\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">88\u003c/sup>\u003cspan class=\"ca\" data-c=\"542\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">ומצאנו בגמ' כמה סיבות במקום הנ\"ל לענין דלא הוי רה\"י ולאיסור טלטול בו. הא דהוא רה\"ר, והוא פרוץ לרה\"ר, ואין לו ג' מחיצות, ובקעי ביה רבים, ולית ליה תיקוני מבוי. ועל זה אמר ר\"י דעושה לו לחי או קורה מכאן ומכאן, ונעשה המקום רה\"י, וניתר לטלטל בו, ואמרו לו דאין מערבין רה\"ר בכך. והנה לכאורה הא דאמרו לו איירי רק לגבי מה שהתיר ר\"י לטלטל בו, דע\"ז אמרו לו דאין ניתר בלחי או קורה. \u003c/span>"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"1114\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">89\u003c/sup>\u003csup class=\"cb\" data-c=\"543\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">90\u003c/sup>\u003cspan class=\"ca\" data-c=\"1114 543\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">ובגמ' ביארו דעת ר\"י להיתר בכמה פנים, בהכשר מקום רה\"ר ולמקום הפרוץ לרה\"ר, בגדר תיקון לחי וקורה משום היכר או מחיצה, במנין מחיצות דרה\"י, באי בקעי רבים ומבטלי מחיצתא ובאי רה\"ר מיערבא. וכן מצאנו לר\"י דחשיבי שתי מחיצותיו מעולות, ובאיכא לחי אחד חשיב מבוי מפולש, בשנים נחשב למבוי מתוקן.\u003c/span>"}, {"s": "h7", "h": "הצריך ביאור בסוגיית תל וחריץ - בגדר גמורה דתני לאפוקי מדעת ר' יהודה"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"544\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">91\u003c/sup>\u003cspan class=\"ca\" data-c=\"544\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">והנה איתא בשבת דביארו בהא דתני בברייתא דרשויות דתל וחריץ הוי רה\"י גמורה, דאתי לאפוקי מדעת ר\"י דידן. דלשון גמורה דתני אתל וחריץ אשמועינן דלא פליגי רבנן רק אי הוה רה\"י לטלטל אלא אף דפטור אזריקה מרה\"ר לשם. ומזה דהתנא בא למעט מקום זה מגדר רה\"י, משמע דאית ביה חסרון בעצם הגדרתו כרה\"י, וגם בלי שאר נידונים האמורים.\u003c/span>"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"545\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">92\u003c/sup>\u003cspan class=\"ca\" data-c=\"545\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">והנה צ\"ב בעצם מה דנקט התנא תל וחריץ ולא סתם מקום המוקף מחיצות, לכאורה הוא עיקר דינא דרה\"י, דבתל הלא בעינן לדין גוד אסיק (ואף בחריץ לכאורה צריך לגוד אסיק ביחס לאוויר שכנגד רה\"ר). ועוד קשה למה נקט בתל וחריץ דאיתא להו ד' מחיצות שלימות, והוה ליה למינקט עיקר הדין דג' מחיצות עם לחי או פס, ועוד צ\"ב דכיון דאית להו ד' מחיצות איך נמעט מהם דעת ר\"י דאית ליה רק ב' מחיצות, ויותר היה משמע למעט ג' מחיצות, ועוד דהלא מח' ר\"י וחכ' אינה בדין מחיצות רה\"י לבד אלא היא תלויה כאמור גם בגדרי הכשר מבוי וגדרי לחי וקורה דבתל וחריץ לא בעינן להו. ועוד קשה איך דייקינן מלשון גמורה דתני הכא אמח' דר\"י וחכ', ומי תני גבי הדדי דנמעט (והיא תוספתא דעירובין), ואי הוה אמר לאפוקי ניחא אבל הרי פשטות מילת למיעוטי הוא ביחס לדין ולא למקרה המסויים. והנה ברש\"י כתב דלשון גמורה הוא ביחס לד' מחיצותיה, וקשה ביותר א\"כ נמעט אפילו ג' מחיצות, וכדלעיל (ובעיקר דברי רש\"י קשה דאי איירי אמחיצות מה שייך לומר דאיידי זה כתב לשון גמורה ארה\"ר. וע' בתוס').\u003c/span>"}, {"s": "h7", "h": "\u003csup class=\"cb\" data-c=\"1116\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">94\u003c/sup>\u003csup class=\"cb\" data-c=\"1115\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">93\u003c/sup>\u003cspan class=\"ca\" data-c=\"1115 1116\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">הצריך ביאור בסוגיית עירובין ברישא - בגדר אין מערבין רה\"ר בכך ובדלתות ננעלות\u003c/span>"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"546\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">95\u003c/sup>\u003cspan class=\"ca\" data-c=\"546\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">והנה לגבי מה דנח' אי חשיב מבוי מתוקן איתא בגמ' דהא דחלקו חכ' אר\"י הוא משום דלערב רה\"ר לא די בכך, והקשו אברייתא דמשמע דבדלת וכו'. והנה סוגיא זו צ\"ב מכמה פנים, דעיקר לשון מערבין ארה\"ר אינו ברור, דאי מהני האי עירוב הרי לא חשיב רה\"ר, וביותר קשה בהא דלקמן דלר\"י מהני, ואי תימא דאין לשון מערבין איירי לגבי הכשר דמבוי אלא לבקיעת הרבים, הרי שהיה להוכיח מדברי חכ' בפסי ביראות ההיפך דהתם ליתא לדלתות, ואי תימא דשם ד' מחיצות הוי כמו דלתות, קשה דיש לומר כן אפילו באין ננעלות, ובפרט אחר דבעו לדייק דדוקא בכך הוא דלא מיערבא, דא\"כ מה מהני דברי ר'\"י דאתיא לר\"י, ועד שנלמד מר' יוחנן לגבי חכ' להקשות אברייתא, יש להקשות אר'\"י מדיוקא דבכך, וכן משמע מסוגיא דעיר של יחיד דאין זה דין בבקיעת רבים. \u003c/span>"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"547\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">96\u003c/sup>\u003cspan class=\"ca\" data-c=\"547\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">ועוד יש לבאר דכיון דהו\"א לומר דדעת ר\"י משום דלחי וקורה משום מחיצה, א\"כ מהיכי תיתי דלחכ' לא יהני צורת הפתח ודלת דלכ\"ע הוי מחיצה. וגדר מחיצה מעלייתא האמור בתוס' צ\"ב, דביחס לשתי מחיצות דר\"י ניחא, אבל מהיכי תיתי דדלת שננעלת רק בלילה שתחשב מחיצה מעלייתא גם ביום, ובפרט אי נימא דחשיב רה\"ר או בקיעת רבים. \u003c/span>"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"1117\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">97\u003c/sup>\u003csup class=\"cb\" data-c=\"548\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">98\u003c/sup>\u003cspan class=\"ca\" data-c=\"1117 548\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">והנה לקמן מותבינן לרבא דאמר לחי משום היכר מר\"י דהו\"א דס\"ל ג' מחיצות דאורייתא, והקשו בתוס' דעד דאתה מקשה מר\"י סייע מרבנן, ותירצו דרבנן לא אסרו אלא משום דמדרבנן בעינן ג' מחיצות גמורות, והיינו, דמח' ר\"י וחכמים הוא רק אהיתר מבוי ולכ\"ע הוי רה\"י, ולכ\"ע לחי וקורה משום מחיצה, ואיתא לד' מחיצות, אלא דרבנן סברי דתקנו חכ' דאין מועיל תיקון דלחי וקורה רק ברוח רביעית. ולדעת תוס' צ\"ל דחלק מאיסור מבוי הוא שלא יועיל לחי וקורה בלי ג' מחיצות, וא\"כ אין לחי וקורה תקנת חכ' אלא עיקר הדין, ולפ\"ז צ\"ל גם דתקנו דאין מועיל בחצר מרובעת. וע' ברע\"א. ועכ\"פ משמע בתוס' דזה פשטות הברייתא (דאל\"כ מאי קושיא) וכאמור כך גם משמע מלשון דאין מערבין, דהוא בהיתר גזרת מבוי.\u003c/span>"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"549\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">99\u003c/sup>\u003cspan class=\"ca\" data-c=\"549\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">והנה בגמרא שם תירצו דהא דר\"י אינו משום דלו\"ק משום מחיצה, אלא דס\"ל לר\"י דב' מחיצות דאורייתא, ולפ\"ז צ\"ל דרבנן דאסרי הוא משום דס\"ל ג' מחיצות דאורייתא. והנה בעיקר הסוגיא צ\"ע למה הקשו זה רק ארבא ולא לכ\"ע דר\"י נקט גם קורה. ועוד קשה דבגמ' שבת הנ\"ל אמרו דפליגי אף בלזרוק וקשיא למ\"ד לחי משום מחיצה (ואולי י\"ל לדעתו דפליגי בלחי בלטלטל וקורה בלזרוק, ומה שאמרו אין מערבין, היינו, לכל הפחות). \u003c/span>"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"1118\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">100\u003c/sup>\u003csup class=\"cb\" data-c=\"550\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">101\u003c/sup>\u003cspan class=\"ca\" data-c=\"1118 550\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">והנה לקמן מותיב אביי לרבה מהאי ברייתא דבהכרח דס\"ל לר\"י ב' מחיצות דאורייתא ואודי ליה, וקשה דהכא משמע דאיכא למימר דפליגי בלו\"ק, וי\"ל דכיון דמותיב לרבה ורבה הרי ס\"ל דקורה משום היכר, א\"כ מוכרח לומר דהוא משום ב' מחיצות בעינן לכל הפחות לדלתות ננעלות בלילה והוכיחו כן מדר' יוחנן ועולא וזה קשה. \u003c/span>"}, {"s": "h3", "h": "\u003csup class=\"cb\" data-c=\"1119\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">102\u003c/sup>\u003cspan class=\"ca\" data-c=\"1119\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">טו. סוגיא דמעלות ומורדות דא\"י\u003c/span>"}, {"s": "h7", "h": "חילוקי גדרים הנמצאים בסוגיא דמעלות ומורדות - דגלי מדבר, אתי רבים, ניחא תשמישתיה, ומסור לרבים"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"551\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">103\u003c/sup>\u003cspan class=\"ca\" data-c=\"551\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">איתא בגמ' (כב.) דאמר ר' יוחנן דמעלות ומורדות דארץ ישראל אין חייבין עליה משום רה\"ר. ובעי רחבה בתל המתלקט לר\"י ודין שבילי בית גלגול לכ\"ע וכו'. והנה בטעמא דר' יוחנן אמרו דאינו דומה לדגלי מדבר, ומשמע דהוא גדר דאורייתא, ואין מעלות ומורדות דא\"י בכלל רה\"ר. ומאידך בשבילי בית גלגול משמע דמדינא אכן היה להם להיות רה\"ר, ואף דלא ניחא תשמישתיה. וטעמא דלא הוו רה\"ר, אינו אלא משום שיהושע לא מסרה לרבים, ומסרה ליחיד. ויש כאן ארבעה דינים נפרדים דיני רה\"ר דדגלי מדבר. ודין אתי רבים. ודין ניחא תשמישתיה. ודין מסור לרבים. ומשמע דדין מעלות ומורדות אינו שייך לדין רה\"י, שדינא דדגלי מדבר הוא בהגדרת רה\"ר, ובלי שייכות למחיצות וכו'. ודין תל המתלקט הרי יש בו סיבה לרה\"י, אלא דכיון דבוקעים בו באו לדון אי אמרינן בו דין אתי רבים, וזה יהיה תלוי בניחא תשמישתיה. ושבילי בית גלגול גם יש בהם גדרי רה\"י, ולא אמרינן ביה אתו רבים משום שלא נמסרו לרבים אלא ליחיד. ומשמע בגמ' דאלו נידונים נפרדים, ולא נתבאר גדרם היטיב. \u003c/span>"}, {"s": "h7", "h": "גדר ניחא תשמישתיה בתל המתלקט - הילוך ע\"י הדחק ברקק לעומת בקיעת רבים בתל"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"552\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">104\u003c/sup>\u003cspan class=\"ca\" data-c=\"552\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">והנה גדר דניחא תשמישתיה כבר מבואר במקומות אחרים כשאין בוקעים בו דלא הוי רה\"ר, ודין אתי רבים הרי לא תלוי בתשמיש אלא בהילוך, והילוך ע\"י הדחק הוי הילוך בפחות מי', אבל כאן אפילו בי' הוה הילוך, והיינו, דהילוך ע\"י הדחק במשנה דרקק הוא ביחס למים, ולא ביחס לגובה הרקק דשם הוי האי רקק לא במתלקט, ובחריץ י' ליכא למ\"ד דהוי רה\"ר, ואין הילוך הרבים מועיל דאין זה נחשב הילוך אחד. אלא דהכא אף דאיכא י' כיון דאיירי במתלקט דאין חסרון דהילוך, אלא רק מה שיש לו מחיצה, ולמ\"ד אתי רבים היה להם לבטל המחיצה, אלא דלא ניחא תשמישתיה דהאי תל, היינו, בו עצמו, והיה לומר שאף למאן דס\"ל דין אתי רבים, היינו, דווקא כששימושם במקום שבוקעים בו הוא נוח, וע\"כ יש להגדירו כחלק מרה\"ר, אבל במקום שעצמו אינו נוח לשימוש דילמא לא. והבקיעה היא בכלל המקום ומקום זה הוא רה\"י, וזה למדנו דר\"י ס\"ל דאתי וכו'. אבל ניחא תשמישתיה הוא ביחס לעצם השימוש.\u003c/span>"}, {"s": "h7", "h": "ביאור גדר הילוך רבים ותשמיש ברה\"ר - הילוך מגדיר קרקע ותשמיש מחבר מקום למשמעות הקרקע"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"553\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">105\u003c/sup>\u003cspan class=\"ca\" data-c=\"553\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">והיינו, דכמו שכתבנו הילוך הרבים הוא גדר רה\"ר עצמה, והוא מגדיר את הקרקע כרה\"ר. אך שימוש הוא ביחס לחיבור המקום המשומש שיהיה במשמעות אחת עם שימוש הקרקע, וממילא יחשב רה\"ר (ולכן הוא לא תופס אוויר עשרה). ואמנם מקום הילוך שע\"י הדחק נחשב להילוך, אבל יש לדון במה דר\"י סובר דאתי רבים, אי כוונתו דהילוך הרבים הוא דמבטל מחיצה, או שימוש הרבים הוא דמבטל המחיצה. והיינו, שאף דיש להילוך הרבים להגדיר את קרקע הרשות, הרי כאן יש מחיצות, ואין לו להגדיר יותר מחריץ, אלא במה דס\"ל ר\"י דהשימוש של הרבים מבטל את המחיצה, יש לדון אי הילוך עצמו שאין בו חסרון דע\"י הדחק יספיק בזה, וזה רבותא דחבל ובית מרון. \u003c/span>"}, {"s": "h7", "h": "ניחא תשמישתיה דשבילי בית גלגול - תנאי בהגדרת רשות הרבים עצמה ולא בביטול מחיצות"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"554\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">106\u003c/sup>\u003cspan class=\"ca\" data-c=\"554\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">אך גדר דשבילי בית גלגול נוגע להגדרת רה\"ר עצמה, והיינו, דאף דגדר רה\"ר בכל מקום נוגע למצב המקום בפועל, ושבילי בית גלגול מצבם בפועל הוא דהוו רה\"ר כדחזינן מטומאה (אף דטומאה אינו מוגדר בשימוש ע\"י הדחק ב\"ב יב:). אבל הרי אין גדר מצב זה אלא ביחס לחפץ, וזה משום גדר מקום רה\"ר לגבי הוצאה המוגדר כך ע\"י הגדרים האמורים. אך כיון שחלק מתנאי רה\"ר הוא שימוש הרבים, באם לא יוגדר שימושם לא יושלם תנאי זה. \u003c/span>"}, {"s": "h3", "h": "\u003csup class=\"cb\" data-c=\"1120\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">107\u003c/sup>\u003cspan class=\"ca\" data-c=\"1120\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">טז. ביאור גדר שימוש הרבים ותנאיו\u003c/span>"}, {"s": "h7", "h": "\u003csup class=\"cb\" data-c=\"1122\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">109\u003c/sup>\u003csup class=\"cb\" data-c=\"1121\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">108\u003c/sup>\u003csup class=\"cb\" data-c=\"555\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">110\u003c/sup>\u003cspan class=\"ca\" data-c=\"1121 1122 555\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">שימוש הרבים כתנאי ברשות הרבים - הגדרה מוקדמת לשימוש בפועל בקרקע ולא מעצם המשתמשים\u003c/span>"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"1123\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">111\u003c/sup>\u003csup class=\"cb\" data-c=\"556\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">112\u003c/sup>\u003cspan class=\"ca\" data-c=\"1123 556\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">והיינו דכמו שאמרנו שימוש הרבים הוא תנאי במקום שבלי זה אין קרקע המקום תחשב כרה\"ר, וצ\"ב מה גדר שימוש דרבים, שהרי אין שימוש דכל אחד אלא לעצמו, והרי הוא יחיד, ומהו שיגדיר את המקום כרה\"ר, וא\"ת דזה נעשה ע\"י כלל המשתמשים יחד, הרי אין גדר מוקדם לרה\"ר מלבד שימוש הרבים, ואם יש לומר בזה ששימוש כל אחד הוא בגדר שימוש היחיד, במה יש לכלול כולם. ובהכרח צ\"ל דשימוש דרבים הוא הגדרה בכל יחיד ומה שהוא משתמש במקום של הרבים, והגדרה זו היא הגדרה מוקדמת לשימוש בפועל, שנגדיר את שימושו כשימוש של הרבים (ובפרט לרש\"י דס' ריבוא), וכיון שאין הגדרה זו ברורה מעצם השימוש, הרי שצ\"ל שהיא הגדרה בקרקע עצמה. דע\"י שימוש הרבים נעשה גדר זה בקרקע, ונעשה בחדא מחתא עם גדר הקרקע כמשמשת בפועל, וכמו שנבאר. וע\"כ יהיה זה שייך דווקא במקום שאין לו משמעות רבים ויחיד. \u003c/span>"}, {"s": "h7", "h": "\u003csup class=\"cb\" data-c=\"557\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">113\u003c/sup>\u003cspan class=\"ca\" data-c=\"557\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">גדר תיקון יהושע בארץ ישראל - קביעת דרכים לרבים במקום שתשמישו נח וליחיד באינו\u003c/span>"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"558\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">114\u003c/sup>\u003cspan class=\"ca\" data-c=\"558\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">אך בארץ ישראל כיון שיהושע אוהב ישראל היה עמד ותיקן להם דרכים וסרטיא, ועצם תקנת יהושע היתה לצורך הרבים שלא יהיה היחיד תופס מקום ומונע מעבר הרבים, וכיון שעשה זה בתנאים מסויימים, יש לנו ללמוד מה נחשב מקום הראוי לרבים. וראינו שקבע שמקום שתשמישו נח יהיה לרבים ואם לאו יהיה ליחיד, משום דסבר שדבר שתשמישו אינו נח ראוי לרבים. ואמנם ודאי שיהיה שייך רה\"ר בכל מקום ואין תלוי במה שהוא של רבים, וכמו בחוצה לארץ לגבי אתי רבים. אך ביחס להגדרת מקום ע\"י שימושם של רבים, חזינן מיהושע מהו גדר שימוש של רבים ושבמקום שתשמישו אינו נח אין זה נחשב זה תשמיש הרבים, אלא תשמיש היחיד. ואין זה דין שחידש יהושוע בדיני הוצאה ורה\"ר, אלא מעצם מה שקבע יהושע דרכים רק במקום שנח תשמישו, ממילא הוגדר שזה גדר שימוש הרבים דא\"י, ושימוש שאינו נח לא יחשב כשימוש של רבים. והיינו, שביחס למשמעות שימושם של רבים כהגדרה של קרקע, הרי שניטל מהם כח זה במקום שלא ניחא תשמישתיה (אך זה רק ביחס לשימוש הרבים, אך ביחס לרה\"י כמו שאמרנו אין השימוש בפועל מגדיר את קרקע רה\"י, וגם ודאי דחילק ליחיד גם מקומות שתשמישם נח, אלא שמזה שכשתיקן דרכים וכשנמצא מקום שלא נח תשמישו נתנו ליחיד, חזינן שאין ראוי זה לרבים). \u003c/span>"}, {"s": "h7", "h": "שימוש הרבים במשמעות סוג השימוש - חילוק בין ריבוי משתמשים לסוג השימוש"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"559\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">115\u003c/sup>\u003cspan class=\"ca\" data-c=\"559\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">ויצא לנו בזה עוד גדר ביחס להגדרת רה\"ר. שאף ששימוש הרבים בפועל הוא מתנאים המגדירים את המקום, אין זה (רק (רש\"י)) במשמעות שימוש של הרבה אנשים, אלא בסוג השימוש. שיש בשימוש הרבים משמעות שימוש שונה משימוש היחיד, ובשאר ארצות כיון שלא הוגדר שימוש הרבים, כל שהרבים משתמשים נחשב שימוש הרבים ביחס לקרקע, אך בא\"י נוסף גדר בשימוש הרבים עצמו שהוא נחשב כך ביחס לנוחות השימוש בקרקע. וא\"כ אף שגדר קרקע להיות נחשבת רה\"ר הוא ביחס לשימוש, יש חילוק במה נחשב שימוש המגדיר קרקע, ובהכרח אין זה ביחס לקרקע במובנה כמקום חפץ, שהרי זה נעשה ע\"י השימוש בפועל, אלא הוא ביחס לקרקע לעניין השימוש של האדם.\u003c/span>"}, {"s": "h7", "h": "שלבי הגדרת מקום כרשות בשבת - מקרקע כמקום הינוח חפץ לשימוש הילוך או תשמיש"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"560\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">116\u003c/sup>\u003cspan class=\"ca\" data-c=\"560\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">וא\"כ מצאנו כמה שלבים בהגדרת מקום כרשות (להחשיב חפץ הנמצא במקום). הראשון, הוא דאין מקום נחשב כמקום ביחס לרשות אלא בקרקע, וע\"כ נצטרך להגדיר קרקע, וקרקע רה\"י מוגדרת כך בנפרדותה, וקרקע רה\"ר נחשבת כך בשימוש שיש בה (ובזה יש שני סוגי שימושים שימוש דהילוך, ושימוש סתם. וברה\"ר ביחס להגדרת הקרקע כנ\"ל הוא ביחס לשימוש הילוך), היינו, שימוש הרבים (ואף שביחס לשימוש האדם אין שימוש הרבים מעלה אלא חסרון ביחס לשימוש היחיד, ביחס לקרקע המשמשת הרי זה חשוב כשני סוגי שימוש). \u003c/span>"}, {"s": "h7", "h": "הגדרת שימוש הרבים בקרקע בפועל - חילוק בין רה\"ר דא\"י דהוי בגדר חיובי לחו\"ל"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"561\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">117\u003c/sup>\u003cspan class=\"ca\" data-c=\"561\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">ושימוש הרבים מוגדר כך ע\"י השימוש בפועל, היינו, ששימוש כל אחד הנחשב כשימוש הרבים מגדיר את הקרקע (ולרש\"י דבעי ס' ריבוא צ\"ל שצריך גם כמות שימוש כזה, או שבזה הכמות יוגדר שימוש דכל חד), והיות נחשב שימוש זה כשימוש הרבים חלוק, דבשאר ארצות גדר זה הוא בעצם השימוש של הרבים, ואין זה גדר בעצם השימוש, וע\"כ שימוש היחיד והרבים הוא רק ביחס זה לזה, ובזה הרי אין הבדל אלא בצורת השימוש עצמו. אך בארץ ישראל כיון דיהושע הגדיר מקומות לשימוש הרבים, הרי שיש גדר חיובי בשימוש דרבים ויחיד, היינו, שבזה שהגדיר מקומות לשימוש הרבים, נעשה גדר בשימוש הרבים שהוא ביחס למקום. \u003c/span>"}, {"s": "h3", "h": "\u003csup class=\"cb\" data-c=\"1124\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">118\u003c/sup>\u003cspan class=\"ca\" data-c=\"1124\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">יז. בגדר מקום רה\"ר\u003c/span>"}, {"s": "h7", "h": "\u003csup class=\"cb\" data-c=\"1127\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">121\u003c/sup>\u003csup class=\"cb\" data-c=\"1126\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">120\u003c/sup>\u003csup class=\"cb\" data-c=\"1125\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">119\u003c/sup>\u003cspan class=\"ca\" data-c=\"1125 1126 1127\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">בירור מקום להיחשב רשות הרבים – בכח תקנת יהושע להגדיר הנלמד מדגלי מדבר\u003c/span>"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"562\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">122\u003c/sup>\u003cspan class=\"ca\" data-c=\"562\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">אלא שהיה לשאול כיון שדין התורה דרה\"ר נאמר אפילו בלי גדר זה, שהרי דינו תלוי בדימוי לדגלי מדבר, והמדבר הרי לא הוגדר כנ\"ל, שלא היה צורך בהגדרתו שלא היה קבוע. וא\"כ בהכרח שאין גדר דיהושע במה ששימוש הרבים מגדיר את הקרקע וכאילו אמר שאין שימוש הרבים מגדיר קרקע דלא ניחא תשמישתיה, דא\"כ היה צריך אף בשאר ארצות גדר זה שזהו גדר מוכרח, וזה לא מצאנו. וע\"כ צ\"ל שגדר זה הוא בעצם שימוש הרבים, שהגדיר יהושע מה יחשב שימוש הרבים, וגם זה קשה שהרי לכאורה גדר רה\"ר דאורייתא ומה שהוא מוגדר ע\"י שימוש הרבים אינו דווקא בשימוש במקום המסור לרבים, ואין המסירה גדר בשימוש, והרי ודאי אין חצר היחיד נחשבת מסורה לרבים, ואיך יעשה יהושע גדר חדש בדין רה\"ר (ובפרט דמשמע דלא עביד אלא תיקון דרכים וסרטיא). \u003c/span>"}, {"s": "h7", "h": "\u003csup class=\"cb\" data-c=\"563\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">123\u003c/sup>\u003cspan class=\"ca\" data-c=\"563\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">משמעות שימוש הרבים לגבי קרקע - הרבים מגדירים משמעות שימוש הקרקע ולא הקרקע עצמה\u003c/span>"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"564\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">124\u003c/sup>\u003cspan class=\"ca\" data-c=\"564\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">והביאור בזה בהקדם מה דצ\"ב איך בכלל יגדיר שימוש הרבים גדר בקרקע, אחר שהקרקע אינה מושפעת ע\"י שימוש בה. ובהכרח שאין זה דין בקרקע עצמה, אלא במה שיש בה אפשרות שימוש, ובזה יש לרבים להגדיר את משמעות שימוש הקרקע, והיותה מוכנה לשימוש, שהרי גדרה הנ\"ל הוא מכוחם (שאין משמעות שימוש בקרקע בלי משתמשים). וע\"כ עצם גדר הקרקע אין הוא מוגדר ע\"י הרבים, וההפך שהוא מגדיר את השימוש (והרי זה ההבדל בין רשות לסתם אוויר מקום שאין שייך רשות באוויר אלא בקרקע). \u003c/span>"}, {"s": "h7", "h": "גדר תיקון יהושע בהנחלת הארץ - כח יהושע להגדיר סוג הקרקע לשימוש הרבים והיחיד"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"565\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">125\u003c/sup>\u003cspan class=\"ca\" data-c=\"565\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">ולפ\"ז יש למצוא גדר במה דזה תלוי במסירת יהושע ובכוחו להנחיל את הארץ, כי דין התורה במה נחשב רה\"ר הוא בקרקע שאין לה משמעות שימושית בעצמה, שבזה אמרה תורה ששימוש הרבים בה יחשיבה כרה\"ר, ובאמת בזה אין ליהושע לחדש דין (יותר ממה שאין לחכ' בכל דור), דבהגדרת שימוש הרבים עצמם ודאי שאין ליהושע כח, שלא ניתן לו כח באנשים, ואף בקרקע הרי לא ניתן לו כח אלא לחלוקתה, ואין לו בה קניין, ואין לו כח להגבילה בגדרים קניניים, וגם אין גדר רה\"ר תלוי בקניין (דא\"כ לא אתי מה דאמר ר' יוחנן בירושלים אלא למ\"ד דלא נתחלקה לשבטים, ואף אי נימא דאין קנין השבט כמו קנין יחיד לגבי זה, הרי שהיה לברר בכל מקום מה הונחל ליחיד ומה לא. וגם אין אפשרות לברר זה בקרקע שאין נוחות תשמישה קבוע, וגם ברור דאין זה גדר תפיסת שבט או תפיסת יחיד דשבט, דזה שייך לגדרי אחוזת אבות ולא לגדרי קנין, דלמי חוזרת ביובל. ואכמ\"ל). אלא שכיון שניתן לו להנחיל ולחלקה לכל ישראל, היה לו גם כח להגדיר מקום לכל ישראל, היינו, מה שזה צורכם, וגם זה בגדר חלוקה, שזה שיהיה מקום שהוא לשימוש הרבים אין זה גדר של זכות וחובה הסותר לזכות היחיד, וכולם צריכים לזה, וע\"כ גם זה הוא מדין חלוקה. וחלוקת הארץ לשימושיה אכן היה בכוחו, ובזה שחילק סוג הקרקע ביחס לשימוש הרבים והיחיד, הרי שהגדיר שבארץ ישראל יש משמעות בסוג הקרקע לשימושיה, וזה כמש\"כ קודם לדין רה\"ר דאורייתא שבדין התורה גדר הקרקע דרה\"ר הוא גדר שלילי (ושאין זה חלק מדיני התורה שהרי אינו אלא בקרקע דארץ ישראל ואין דין הוצאה תלוי בארץ), ודין התורה שיחשב קרקע רה\"ר ע\"י שימוש הרבים הוא ביחס לקרקע, ותקנת יהושע הוא ביחס לשימוש, אך הגדרת השימוש תשפיע על דיני התורה בהגדרת קרקע ע\"פ שימוש, וע\"כ לא יהיה זה שייך אלא בהנחלת יהושע את הארץ, ולא בשאר ארצות אף שיהיו חוקקים חוק דומה, כי אף שיהיה להם שלטון על אנשים (ודינא דמלכותא דינא), אין זה גדר ביחס לרבים ככלל אלא לכל יחיד בפרט וכו'. וע\"כ יבואר מה שחסרון דמעלות ומורדות דא\"י הוא חסרון בדיני התורה, ובמה שאין דומה קרקע דמעלות ומורדות דא\"י לדגלי מדבר.\u003c/span>"}, {"s": "h7", "h": "סיכום תנאי רשות הרבים בקרקע - שלבי הגדרת מקום מקרקע לרשות של הילוך לרבים"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"566\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">126\u003c/sup>\u003cspan class=\"ca\" data-c=\"566\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">וא\"כ מצאנו כמה תנאים ברה\"ר, זה לפנים מזה, דגדר הקרקע כמקום הראוי להנחת חפץ הוא תנאי ראשון, ובזה אין צורך שיהיה תשמישו נח, אלא גדרו הוא בעצם מושג קרקע לעומת אוויר, וזה גדר קרקע לכל הרשויות. ובהשלם מקום זה התנאי הרי שניתן להגדירו כמקום דרשות. ורה\"י הוא מקום תשמיש ליחיד, ורה\"ר הוא מקום הילוך לרבים (וגדר זה ואיך זה נעשה ע\"י שימוש הרבים יבואר בעז\"ה). והגדרת קרקע כמקום נפרד הוא במשמעותה ביחס לתשמיש, והגדרת קרקע כמקום הרבים הוא ביחס להגדרתה כמקום שימוש, ויהיה הגדרתה בזה ע\"י שימוש הרבים בפועל, ששימוש הרבים מגדיר את הקרקע במשמעותה השימושית כמקום הרבים, וגדר שימוש הרבים הרי שזה ביחס לשימושי אדם באופן כללי. ובזה נחלקו א\"י וחו\"ל שבא\"י אין נחשב שימוש דרוב יחידים במקום דלא ניחא תשמישתיה כשימוש הרבים, ובחו\"ל ליתא לזה. וע\"כ היא ביחס לשימושי אדם באופן כללי, ושאר תנאי רשויות ושייכות מקום לרשות (שלא בגדר קרקע) שונים מרשות לרשות ע\"פ החלוקה האמורה, ושאר דיני הוצאת חפץ שווים בכל הרשויות.\u003c/span>"}, {"s": "h3", "h": "\u003csup class=\"cb\" data-c=\"1128\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">127\u003c/sup>\u003cspan class=\"ca\" data-c=\"1128\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">יח. בגדר תשמיש והילוך דרה\"ר\u003c/span>"}, {"s": "h7", "h": "\u003csup class=\"cb\" data-c=\"1131\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">130\u003c/sup>\u003csup class=\"cb\" data-c=\"1130\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">129\u003c/sup>\u003csup class=\"cb\" data-c=\"1129\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">128\u003c/sup>\u003cspan class=\"ca\" data-c=\"1129 1130 1131\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">הצריך ביאור ברש\"י באי דימוי מו\"מ דא\"י לדגלי מדבר - שייכות חסרון דמישור למדבר לבדו\u003c/span>"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"567\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">131\u003c/sup>\u003cspan class=\"ca\" data-c=\"567\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">אלא דלפ\"ז יקשה הא דכתב רש\"י בביאור מה דאמר ר' יוחנן שאינו דומה וכו' שהוא משום דדגלי מדבר היו במקום מישור. ולפמש\"כ אין כלל חסרון במעלות ומורדות במדבר ובכל מקום מלבד א\"י, ואם יש הרי שהיה צריך להיות חסרון זה בכל הארצות. ועוד יש לבאר דהרי אף פסי ביראות אינם דומים לדגלי מדבר, ומה זה שייך לאתי רבים. ועוד צ\"ב מה שכתבנו לעיל בגדר הילוך דרה\"ר דאין בו חסרון דע\"י הדחק, ולמה שכאן יהיה בו חסרון. וכן יש לבאר עצם גדר דתשמיש והילוך ביחס לרה\"ר.\u003c/span>"}, {"s": "h7", "h": "\u003csup class=\"cb\" data-c=\"568\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">132\u003c/sup>\u003cspan class=\"ca\" data-c=\"568\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">הילוך ותשמיש בסוגיא דרקק ברה\"ר – שיעור רקק תליא בחיבורו לרשות שלפניו ולאחריו\u003c/span>"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"569\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">133\u003c/sup>\u003cspan class=\"ca\" data-c=\"569\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">והנה בגמ' שם מבואר דאף דאיכא הילוך, ואף במקום פחות מי', אי הוה האי מקום פחות מרוחב ד\"א לא חשיב רה\"ר, וכן אי לא הוה באורך ד\"ט משום שאין הולכים בה, וביארנו דאין זה שייך לנידון דאתי רבים דשם איכא לרה\"ר לפני ואחרי הרקק, ואין הרקק חלוק לעצמו, והילוך ותשמיש הוא רק להחשיבו כחלק מרשות זו. אך גדר אתי רבים הוא ביחס לרשות שהיא נפרדת (היינו לפני שנתבטלו המחיצות) ויש להגדיר את המקום הנפרד בהיותו נפרד שיחשב שאתי רבים לענין ביטול המחיצות. והיינו, דחסרון דהילוך ותשמיש ברקק דחשיב ע\"י הדחק, אין הכוונה ביחס לרקק עצמו (דא\"כ מה ראיה יש לגומא), אלא הכוונה ביחס לשאר הרשות, והיינו, במה שיש חסרון במשמעותם כחלק מכלל הרשות כיון ששימושם כחלק מרשות הוא רק ע\"י הדחק (דמשמעות דחק, היינו, שלא משתמשים בהם משום דחק הקיים ברה\"ר) וע\"י הדחק הוא בסיבת השייכות, היינו, שהרי קרקע שהיא בחילוק יותר מג' כבר לא נחשבת כקרקע אחת עם זו שלידה, והוה ליה להיות כרמלית (ולא מצאנו דין תל המתלקט לגבי זה), ושייכותה הוא רק משום שיש בה הילוך אחד דרה\"ר ויש להחשיבה כחלק מרה\"ר, וכיון דהאי הילוך הוא רק מחמת הדוחק יש לדון אם יש בזה לחבר את שני המקומות ולהגדירם כקרקע שימושית אחת. וע\"כ יהיה בהם חסרון דפחות בד\"א, והיינו, דאין זה שיעור בחשיבות הרקק (דאז הוה ליה להיות במרובע), אלא בשימוש הרבים ומשום שהקפת ד\"א לא חשיבא להם, וכן הוא גדר פסעי לה בד\"ט. \u003c/span>"}, {"s": "h7", "h": "חילוק הילוך מתשמיש בהגדרת רה\"ר - הילוך בקרקע עצמה ותשמיש משייך המקום לקרקע"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"570\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">134\u003c/sup>\u003cspan class=\"ca\" data-c=\"570\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">ובזה חלקה הגמרא בין מקום הילוך למקום תשמיש, וכי הם שני סוגי שימוש שיהיה ברשות (הרבים). ותשמיש, היינו, במקום עצמו, ויהיה נחשב כחלק מרה\"ר משום שהוא משמש את הקרקע שלה, וכמו בכיתוף שהאדם עומד בקרקע ומכתף על העמוד, ואף שאין בזה להגדיר את העמוד כקרקע, אבל יהיה בזה השימוש לבטל ממנו דין קרקע נפרד שהיה לו (וזה מה שאין חסרון בחורי רה\"ר במה שאין הם בגובה ט', דכיון שאין בחורים צורך בהגדרת שימושם עם קרקע, שזה נצרך רק כצריך להגדיר קרקע נפרדת כתשמיש הרשות, אבל בחורים שאין גדר קרקע נפרד לא יהיה צריך אלא שישמשו את רה\"ר, ויהיו כאווירה, היינו, אחר שיש רשות (וזה גופא נסתפקו בחורי רה\"ר אי איכא ברה\"ר גדר שלא ביחס לקרקע). וע\"כ לא יהיה בהם חסרון מחיצות ושיעור וכו'), אבל הילוך הוא בקרקע עצמה והילוך אחיד מחשיב את הקרקע כאחת, ולא משום שמשמש את הקרקע, וע\"כ אם יהיה ההילוך בקרקע שהיא נפרדת בעצמה כמו ע\"י מחיצה, לא יועיל בזה הילוך, שנפרדות הקרקע תגדיר את ההילוך כנפרד ולא ההילוך אותה, שהנפרדות גדר בקרקע, וההילוך גדר בשימוש בה (ולא שלה). אבל תשמיש הרי אינו בקרקע, וגם אינו מגדיר את המקום כקרקע אחת, וע\"כ אפשר שע\"י שימוש המוגדר אחד עם שימוש הקרקע דרה\"ר יחשיב המקום כחלק מרה\"ר לר\"י.\u003c/span>"}, {"s": "h7", "h": "פעולת אתי רבים בביטול מחיצה - בקיעה ושימוש כשני חלקים בפעולת אתי רבים ברשות"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"571\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">135\u003c/sup>\u003cspan class=\"ca\" data-c=\"571\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">וא\"כ יהיה בפעולת אתי רבים שעושים ברשות כאן שני חלקים, האחד, הוא מה שבוקעים בו, ויעשו בזה שיהיה שייכות למקום שבוקעים בו עם מקום הרבים. והשני, הוא בשימושם במקום. וספק דרחבא הוא בתוצאת פעולה הנ\"ל, והיינו, שביטול מחיצה ע\"י דאתי רבים הוא בשלושה שלבים, בקיעת הרבים הנ\"ל, וביטול המחיצות, דבזה מתבטל שם רה\"י, ורה\"ר, היינו, מה שנחשב חלק מרה\"ר. וכיון דהיות המקום ניחא תשמישתיה הוא תנאי ברה\"ר, אף בליכא מחיצות, וכמו בקרן זווית, לא יהני בזה מה דאתי רבים, ומאידך כיון שזה תנאי רק בשיוך מקום לרה\"ר, ור\"י ס\"ל דע\"י בקיעת רבים המקום משוייך אף כנגד מחיצות שאין לך מפריד גדול מהם, כ\"ש כאן. \u003c/span>"}, {"s": "h3", "h": "\u003csup class=\"cb\" data-c=\"1132\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">136\u003c/sup>\u003cspan class=\"ca\" data-c=\"1132\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">יט. גדר קרקע הראויה לשימוש ברה\"ר וברה\"י\u003c/span>"}, {"s": "h7", "h": "חילוק קרקע דרה\"י מקרקע דרה\"ר – תשמיש רה\"י בחפץ ותשמיש רה\"ר באדם"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"572\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">137\u003c/sup>\u003cspan class=\"ca\" data-c=\"572\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">והנה מה שכתבנו בענין תשמיש הרשות יש לבאר בזה כי יש הבדל בין גדר ראוי לשימוש דקרקע רה\"ר וראוי לשימוש דקרקע רה\"י, דלגבי רה\"י מצאנו שגדר תשמיש הוא ביחס לחפץ, ולא ביחס לאדם. וכן מצאנו שאין צריך שתהיה הקרקע ראויה לשימוש בפועל, אלא די שתהיה ראויה לראויה, והיינו, דאפשר דתלי ביה מידי, שהוא ביחס לחפץ. וכן מצאנו שדי שתהיה ראויה להניח עליה איזה דבר שאז תהיה ראויה לשימוש. ודין זה האחרון אינו שייך ברה\"ר כלל. וגם שונה גדר ראוי לשימוש דרה\"ר דבעי לשימוש דכיתוף, ודרסי ליה רבים, ומסגי בהדיא, שכל אלו גדרים בשימוש אדם במקום. וגם גדר דניחא תשמישתיה הוא רק ביחס לשימוש אדם, ולא להנחת חפץ, שזה אפשר בכל דהו, כדחזינן ברה\"י, או לכל היותר בד\"ט. \u003c/span>"}, {"s": "h7", "h": "עיקר גדרי רשויות בהוצאת חפץ - קרקע רשות ביחס למקום מנוחת חפץ בשיעור נפרד"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"573\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">138\u003c/sup>\u003cspan class=\"ca\" data-c=\"573\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">והנה כמו שביארנו במק\"א עיקר גדרי רשויות הם ביחס להוצאת חפץ, היינו, ביחס למה שיש לרשות לתת משמעות בחפץ בהיותו במקום זה, וביחס לזה יהיה ראויה קרקע להיות לה שם רשות, דאם היתה משמעות קרקע בגדר אחר, הרי היה לומר בזה לבוד או ביטול, ולא מה דתלי ביה מידי. והיינו, שעצם מושג קרקע לעומת אוויר, והיותו תנאי ברשויות הוא ביחס לגדרי חפץ. וזה לכאורה ביחס למקום מנוחת חפץ, שאין בקרקע גדר מקום יותר מאוויר אלא בזה, וע\"כ צריך שיהיה לרשות קרקע, וגדר זה של קרקע הוא בנפרד בכל חלק מהקרקע, שהרי זה ביחס לחפץ כל שהוא, ואין גדר זה גדר של הכלת חפץ, דאי הוה רק חלקו ברשות אין מספיק (והיינו שאם היה הגדר בגודל חפץ כל שהוא, הרי שזה גדר חיובי בהכלת חפץ, והיה להגדיר חפץ כנמצא ברשות אפילו אם חלק ממנו אינו, ואין זה הדין). \u003c/span>"}, {"s": "h7", "h": "דין ד' על ד' טפחים בקרקע - תוספת גדר על מקום מנוחת חפץ לשימוש אדם"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"574\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">139\u003c/sup>\u003cspan class=\"ca\" data-c=\"574\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">אבל דין ד\"ט הוא ביחס לשימוש אדם, והיינו, שיהיה קרקע בגדרה כמקום מנוחת חפץ בשיעור של מקום הראוי לשימוש אדם, ושיהיה נצרך תוספת גדר זה ולא די שיהיה ראוי לחפץ המסוים דהוצאה הוא לכאורה ברור, שאף שלגבי מקום חפץ עצמו הרי די לו במקומו, אך לגבי מעשה הוצאה שהוא שינוי משמעות מקום בחפץ גדר מקום הוא ביחס לגדרי מקום כללי. שהרי אין דין הוצאה בהנחת חפץ לבד, ובהיות לו מקום, אלא בהנחת חפץ במקום שיש לו משמעות מלבד עצם היותו מונח, ובהכרח שאין זה ביחס למקום חפץ סתם. וכיון שכל משמעות חפץ ומקומו היא ביחס לאדם, הרי שגדר קרקע כמקום בעל משמעות יהיה ביחס למקום שימוש של אדם. וא\"כ הרי שאין זה נוגע לגדרי קרקע כמקום הינוח, אלא לקרקע כמקום הראוי לשימוש. וביחס להינוח חפץ יהיה זה גדר קרקע כמקום הראוי לשימוש אדם להנחת חפץ. \u003c/span>"}, {"s": "h3", "h": "\u003csup class=\"cb\" data-c=\"1133\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">140\u003c/sup>\u003cspan class=\"ca\" data-c=\"1133\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">כ. בגדר שיעורי מקום כגדר בקרקע רשות\u003c/span>"}, {"s": "h7", "h": "\u003csup class=\"cb\" data-c=\"1134\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">141\u003c/sup>\u003cspan class=\"ca\" data-c=\"1134\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">גדרים חלוקים במקום ד' טפחים - ריבוי מקומות הינוח לעומת שיעור שימוש כולל באדם\u003c/span>"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"575\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">142\u003c/sup>\u003cspan class=\"ca\" data-c=\"575\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">וא\"כ הרי שמקום ד\"ט חלוק בגדריו, שביחס להיותו ראוי לשימוש אדם כולו אחד, וביחס להינוח חפץ הוא חלוק. ויהיה גדר שיעור ד\"ט ריבוי מקומות הינוח הראויים לשימוש אדם. וע\"כ מקום הינוח הוא גדר בקרקע, אך שיעור ד\"ט הוא ביחס לשימוש. וכיון שתנאים אלו הם בהגדרת קרקע עצמה, לא שייך בהם דין לבוד, שאין לבוד אלא במקום שיש גדר מוקדם לחיבור וכסיבה לו (והיינו כאן ביחס לאוויר). אך כיון שגדר מקום הינוח הוא ביחס לקרקע עצמה ואין אוויר רשות (י\"ט) אלא במובן קרקע, הרי שאין זה שייך להגדיר קרקע עצמה ע\"י אוויר שעצמו מוגדר ביחס אליה. וע\"כ לא יועיל בזה לבוד (ואין זה שייך לדין גבשושית דהתם איכא לרשות כבר, ואין זה אוויר קרקע אלא אוויר רשות. ויתבאר בעז\"ה). אבל כיון שכל שיעור ד\"ט בגדרו האחיד הוא ביחס לשימוש אדם, אם יהיה המקום יחד ראוי לאיזה שימוש אדם דהנחת חפץ די בזה שיחשב זה המקום אחד.  \u003c/span>"}, {"s": "h7", "h": "גדר שטח ד' על ד' טפחים - חילוק בין מקום הינוח בקרקע לשיעור שימוש בשטח"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"576\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">143\u003c/sup>\u003cspan class=\"ca\" data-c=\"576\" style=\"--a:#d97706;--abg:rgba(217,119,6,0.1)\">אלא שעדיין היה שייך לדון דאמנם שיעור ד\"ט הוא ביחס לשימוש אדם, אבל דין שטח של ד\"ט על ד\"ט הרי זה כבר דין בשטח הקרקע. ואמנם ביחס למקום הינוח אחד שייך לומר שהרי הוא מתחבר לשאר הקרקע משום שראוי לשימוש, אך אם השטח עצמו מחולק כבר לא יועיל זה, וע\"ז אמרו דכיון שאין שיעור שטח דד\"ט שיעור בעצם חשיבות הקרקע לשימוש אלא בהגדרת מקום שיש בו רוחב הראוי לשימוש, כיון ששטח זה ראוי להניח עליו דבר ויהיה ראוי לשימוש, אף ביחס לרוחב הנ\"ל יש לו להיות נחשב אחד. ומבואר דעצם גדר קרקע דרשות (היינו לעומת אוויר) הוא ביחס להנחת חפץ ואין בו שיעור כמו שאין שיעור בחפץ. וגדר שיעור רוחב ד\"ט הוא ביחס לשימוש אדם, וגדר שטח ד\"ט הוא בהגדרת הקרקע כמקום. וע\"כ אין זה ראוי דראוי שביחס לרוחב ד\"ט הוא דראוי משום דתלי ביה מידי, וביחס לשטח קרקע הוא ראוי ע\"י שיניח שם איזה דבר וישתמש. \u003c/span>"}, {"s": "h7", "h": "חילוק רוחב ד' משטח ד' טפחים - רוחב שיעור תפיסה ושטח שיעור מקום לחפץ"}, {"s": "p", "h": "וביתר ביאור כי אין גדר ד\"ט ברוחב שווה לגדר ד\"ט דשטח, והיינו, דאף שמה שצריך שיעור ד\"ט ברוחב הוא משום רוחב קרקע הראוי לשימוש אדם, אין זה משמעות שטח עצמו שהוא בגדר קרקע הראוי לרשות שהיא פני השטח. ששיעור רוחב הוא שיעור תפיסה, ופירושו שכאילו אנו רואים שמקום זה מלא, וע\"כ אם יהיה יתד שאינו באותו גדר שימוש הרי שהוא ממעט ברוחב שעכשיו אין ראוי שיהיה במקום זה דבר בעל רוחב זה. אך שיעור השטח הוא שיעור מקום והוא ביחס לחפץ, ואין בו חסרון שהוא מחולק. וביחס לשטח הרי החסרון במקרה הנ\"ל הוא רק במה שאין בשטח זה רוחב כזה, וע\"כ די שיניח דבר. והיינו, שאף שהנחת דבר יש בה משמעות שטח אחר ולא זה, אין בזה חסרון, כי אין החסרון בשטח, ואין התיקון בשטח, דאף לולי האי מידי נחשב האי שטח כשטח אחד, אלא שיש בו דין שיהיה ראוי לשימוש, ובזה מועיל מה שראוי להניח וכו'. "}, {"s": "h7", "h": "חילוק קרקע רה\"ר מקרקע רה\"י - חפץ המונח ברה\"ר אינו בכלל הרשות שלא כברה\"י"}, {"s": "p", "h": "ועכ\"פ מצאנו דגדר קרקע הנצרך לרה\"י הינו ביחס לשימוש אדם להנחת חפץ. אך אין זה הגדר בקרקע דרה\"ר, והיינו, דאף שצריך שיהיה מקום דרה\"ר ראוי להנחת חפץ, אין זה משמעות רה\"ר עצמה. כי אין משמעות חפץ המונח ברה\"ר (היינו, תוספת המשמעות האמורה לעיל המוגדרת כהוצאה) גדר רה\"ר עצמה. ודבר זה מוכח מזה שחפץ המונח ברה\"ר אינו נחשב שמקומו בכלל הרשות שנמצא בה, דא\"כ לא הוי ביה דין העברה, ובהכרח שמשמעות הרשות שלעצמה אינה בהיותה מקום חפץ. ויותר מזה דכיון שהיותה רה\"ר הוא גדר בדין העברה, בהכרח שביחס למקום חפץ דין רה\"ר הוא דין שלילי, ושלא יהיה חפץ הנמצא במקום הרשות כנמצא בכל הרשות (ויותר מזה מצאנו לדעת ר' יוסי דאף שתי רשויות הרבים נפרדות הוי אחד לגבי הוצאה)."}, {"s": "h7", "h": "שיתוף גדר רה\"ר ורה\"י בהוצאה - שני גדרים במקום חפץ מונח ומשמעות היותו ברשות"}, {"s": "p", "h": "וא\"כ הוא שאין רה\"ר גדר מקום חפץ, וא\"כ הוא שביארנו שדין רשות דהוצאה הוא דין במקום חפץ, הרי שביחס להגדרת שינוי שיש בדין הוצאה יהיה זה גדר שלילי, והיינו, שמה שמותר להעביר ד\"א בכרמלית זה משום שאין לנו לומר שיש הבדל ביחס למקום חפץ בין מקום זה שבכרמלית למקום אחר. וזה משום שכמו שאמרנו יש כאן שני גדרים, האחד, הוא מקום חפץ מונח, היינו, עצם מה שחפץ תופס מקומו, וזה משום חשיבות חפץ מונח ביחס למקום חפץ לעומת שאינו מונח. והגדר השני, הוא משמעות שיש בהיותו במקום, וכיון שמשמעות זו היא מוקדמת לעצם מקום חפץ והיא המגדירה שטח שמקום חפץ יהיה חלק ממנו, הרי שמשמעות רשות היא הגדרת מקום שאינו חלק מהגדרת מקום חפץ מונח מסוים, וכיון שזה אמור ביחס לקרקע לעומת אוויר, וכיון שאין ברה\"י אלא הגדרה זו, בהכרח שגם רה\"ר הוא בהגדרה זו. שאם אין הם באותו גדר לא יתכן לקרותו שינוי, אלא תוספת, וזה ברור. "}, {"s": "h3", "h": "\u003csup class=\"cb\" data-c=\"1135\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">144\u003c/sup>\u003cspan class=\"ca\" data-c=\"1135\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">כא. במשמעות מקום חפץ לגדרי רשות\u003c/span>"}, {"s": "h7", "h": "משמעות מקום חפץ בקרקע רה\"י - מקום רה\"י מוגדר כנפרד ומאוחד ומקום רה\"ר מחולק"}, {"s": "p", "h": "וביתר ביאור שאם היה ברה\"י גדר שימוש, אז היה לומר שגדר תוספת משמעות במקום חפץ הוא ביחס לגדר שימוש שבקרקע, אך כיון שאין השימוש חלק מהגדרת רה\"י, אלא רק מה שהוא מוגדר כנפרד, בהכרח שאף משמעות שימוש שמצאנו ברה\"ר, אין היא אלא ביחס לגדר זה. וכיון שאין גדר היותו נפרד גדר שינוי האסור עצמו, דא\"כ היה לאסור הוצאה לכרמלית, בהכרח שאף מה שנחשב רה\"י נפרד, אין זה גדר תוספת המשמעות דמקום חפץ האמורה. וכדלעיל. "}, {"s": "p", "h": "וע\"כ מוכרחים אנו לומר שמשמעות שיש ברה\"י ביחס למקום חפץ הוא בגדר אחר. ואין למצוא בזה אלא שני אפשרויות, והיינו, שגדר מקום רה\"י כנפרד מגדירו כמקום אחד, שיש בכל המקום משמעות אחת, וא\"כ גדר רה\"ר יהיה מה שאין היא אחת, וכיון שאין זה גדר ברשות (שהיא ודאי אחת), הרי בהכרח שזה גדר במקום חפץ, היינו, שאין נחשב חפץ המונח במקום כנמצא במקום מאוחד, דאף שגם ברה\"ר הרי איכא לגדר מקום חפץ, ויותר מזה שאין דין העברה אם לא יצא החפץ ממקומו, ובהכרח שזה גדר במקום, שאף בזמן שהחפץ במקום אחד ביחס לתוספת משמעות האמורה, אין הוא נחשב במקום אחד ביחס לרשות. וכיון שמצאנו שאין דין העברה בכרמלית, בהכרח שזה דין חיובי בקרקע רה\"ר, שאותו גדר קרקע הגורם שיחשב החפץ במקום אחר לענין הוצאה מרה\"י, הוא הגדר בקרקע להחשיב העברה ד\"א ברה\"ר כהוצאה. וכיון שגדר זה הוא באחת בכל רה\"ר, שאל\"כ לא היה גדר העברה ד\"א בגדר אחד, וכיון שגדר זה הוא סותר בעצם למשמעות מקום חפץ כמקום אחד, בהכרח שאין זה גדר בקרקע עצמה אלא בשימושה, והרי אין רה\"ר נעשית אחת אלא ע\"י השימוש האחיד בכל הרשות, היינו, שימוש הרבים. וא\"כ יהיה הגדרת רה\"ר במה שאין נחשב קרקעה כמקום אחד ביחס להינוח חפצים, וזה הגדר ביחס להנחת חפץ הוא משמעות שלילית, היינו, שאינה ראויה לשימוש דהינוח חפצים, וזה גדר תנאי דשימוש הרבים. "}, {"s": "h7", "h": "מקום חפץ והנחתו ביחס לשימוש - חשיבות שימוש דהנחה קיימת דוקא ביחס לשימוש הרבים"}, {"s": "p", "h": "ונבאר שהרי אין משמעות למקום חפץ אלא ביחס לשימוש אדם, כי אין משמעות חפץ בכלל אלא ביחס לאדם החפץ בו. וגם גדר מקום הרי אף הוא ביחס לאדם, שאין משמעות למקום אלא ביחס לאדם. וא\"כ אין משמעות שימוש דהנחת חפץ (היינו תוספת המשמעות שיש בחפץ מונח במקום משאינו) במקום אלא ביחס לשימוש האדם. ואף הגדרת מקום עצמה, היינו, רשות, היא ביחס לשימוש האדם. וע\"כ ביחס לשימוש דהנחת חפץ יהיה הגדרת מקום, היינו, רשות, או ראוי לו או לא. וע\"כ יהיה משמעות שימוש המגדירה רה\"ר משמעות שלילית ביחס להנחת חפץ, כלומר, שאין מקום זה ראוי להנחת חפץ, וכיון שביחס לאדם אחד הרי אין זה משמעות חיובית (ואדרבה הרי זה גדר רה\"י מה שהוא ראוי לשימוש אדם בהנחת חפץ כי אין לאדם היחיד אלא יתרון בהיות מקום ראוי להנחת חפץ), וכיון שאין רשות אלא במשמעותה החיובית, הרי שאנו נצרכים למשמעות שימוש חיובית במקום שהיא סותרת להנחת חפץ, וזה שימוש הרבים. שכיון שאין משמעות הנחת חפץ אלא בחפץ, ואין חפץ אלא ליחיד (שזה ההבדל בין קרקע לחפץ, היינו, השימוש המסוים), הרי שקרקע כמקום הראוי לשימוש הרבים יהיה בסתירה להנחת חפץ. וכיון שאנו חפצים בהגדרת קרקע (שהיא מגדירה מקום ביחס להנחת חפץ), לא יהיה הגדרת קרקע דרה\"ר אלא בשימוש דהילוך, היינו, שהוא גדר שלילי ביחס לחפץ, וחיובי ביחס לשימוש אדם. וכיון שגדר אחדות דקרקע דרה\"ר היא ביחס להילוך, היינו, שימוש אדם. לא יהיה זה הגדרה מאחדת ביחס לחפץ המונח במקום זה, ותהיה הרשות אחת ביחס לשימוש האדם דהילוך, אך ביחס לחפץ המונח ברשות אין הרשות אחת, שאין אחדותה מיועדת להנחת חפץ. ואמנם חפץ מסוים המונח בה הרי זה מקומו, אבל ביחס למשמעות הרשות, כלומר, הגדרת הקרקע, יהיה זה נחשב כאילו הוא מונח במקומות רבים, שהרי אינם מיועדים להנחה. וזה יהיה משמעות הוצאה מרה\"י לרבים, לעומת הנחה, היינו, שחוץ מעצם השינוי, יש בקרקע רה\"ר משמעות שאינה מקום ביחס לחפץ, וזה משמעות שלילית דחוץ לעומת פנים. "}, {"s": "h7", "h": "גדר קרקע לעומת אוויר – היותה ראויה להנחת חפץ כגדר באחדות המקום ושיעור ד'"}, {"s": "p", "h": "ונסכם דגדר קרקע לעומת אוויר הוא במשמעות היותה ראויה להנחת חפץ, דהוא עצמו גדר באחדות המקום, היינו, מה שהמקום משמשו באחת לעומת אוויר שמשמשו בנפרד. וגדר זה מגדיר את עצם המושג קרקע כדבר יציב לעומת אוויר. וגדר שימוש בקרקע הוא ביחס לאדם, וע\"כ יהיה גדר אחד בכל הקרקע ביחס לשימוש אדם, וזה גדר ד\"ט רוחב, וגדר מקום לעצמו הוא ביחס לזה, שגדר שטח דמקום יהיה אחד ביחס לשימוש אדם, היינו, בהיותו בעל רוחב ד\"ט, אך שיעור ד\"ט על ד\"ט הוא בחשיבות מקום, ולא בתפיסת רוחב, וזה גדר מקום הקטן ביותר ביחס להגדרה מוקדמת למקום דחפץ מונח, שנגדיר שחפץ נמצא במקום לעומת חפץ התופס מקום, וע\"כ כשנרצה להגדיר שינוי בחפץ ביחס למקומו, יהיה זה בהגדרת מקום המוקדם לעצם מושג קרקע התפוסה ע\"י חפץ מונח, והיא ביחס למקום אדם. וזה בקרקע ד\"ט על ד\"ט, וזה אינו משמעות רשות. "}, {"s": "h7", "h": "גדר קרקע ואוויר ברשויות שבת - מקום תפיסה ומקום חלל ומקום הינוח לעומת הילוך"}, {"s": "p", "h": "ושם רשות הוא בהגדרה נוספת של מקום שימוש, ובזה מצאנו שתי משמעויות, מקום שימוש במובן תפיסה, ומקום במובן חלל, שיש מקום הראוי להנחת דבר, והוא מקום הראוי לתפיסה, היינו, שיהיה מלא. ויש מקום הראוי למעבר דבר, והוא מקום חלל, היינו, שיהיה ריק. ובמשמעות שימוש דאדם הם, מקום הינוח, ומקום הילוך. מקום הינוח, היינו, שימוש חיובי במקום, ומקום הילוך הוא שימוש שלילי במקום. וביחס לקרקע, היינו, לעומת אוויר, שניהם חיוביים. אלא שביחס לשימוש חיובי, היינו, תפיסה, תהיה הקרקע שהיא ביחס למקום תפיסה, וביחס לשימוש שלילי תהיה הקרקע נפרדת, והגדרת קרקע דרה\"י תהיה ביחס למושגי קרקע כנפרדת משאר קרקעות, והגדרת קרקע דרה\"ר תהיה ביחס לשימושי קרקע כנפרדת משאר קרקעות, והגדרת קרקע כרה\"י היא ע\"י הגדרת הקרקע עצמה, והגדרת קרקע דרה\"י היא ביחס לשימוש בקרקע. וקרקע המוגדרת כרה\"י תהיה אחת ביחס לקיום חפצים בה, וקרקע המוגדרת כרה\"ר תהיה מחולקת ביחס לזה, ואחת ביחס לשימוש בה, וביחס למקום חפץ מסוים, היינו, היות בא למקום, יהיה שתי משמעויות. משמעות קרקע ביחס לחפץ והיא המקום התפוס ע\"י החפץ, ומשמעות קרקע כמקום לחפץ והיא המקום הראוי להיתפס ע\"י חפץ. "}, {"s": "h7", "h": "גדר שימוש רה\"ר בהילוך ותשמיש - דריסת קרקע ללא תפיסת היחיד ברוחב ט\"ז אמה"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"577\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">145\u003c/sup>\u003cspan class=\"ca\" data-c=\"577\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">וא\"כ גדר רה\"ר הוא ביחס לשימוש אדם, ושימוש אדם במקום הוא בשני פנים, הילוך, ועמידה. וגדר שימוש הרבים הוא בהילוך, והילוך אדם אחד הוא ברוחב ד\"א, והילוך דרבים ברוחב ט\"ז אמה, והילוך דיחיד דד\"א הוא שיעור תפיסה, היינו, שהוא תופס בהילוכו רוחב ד\"א הנצרכים לו. והילוך דרבים דט\"ז אמה הוא בשלילת זה, היינו, שיהיה הילוך מבלי תפיסה ע\"י מי שהולך. והילוך, היינו, המשכיות הפסיעה, ופסיעה אחת דאדם היא באורך ד\"ט (דביותר מזה אין נחשב פסיעה, אלא קפיצה מהילוך להילוך, ואין נחשב ההילוך אחד, ואין קרקע נחשבת לשימוש אחד אלא בהילוך), והילוך הוא ביושר, והילוך ביושר הוא בתוך רוחב ד\"א, ויותר מזה הוא עיקוף. והילוך הרבים הוא הילוך הנוח והמיידי (היינו ללא עמידה), ודין רה\"ר כמו ברה\"י מוגדר בקרקע, והיינו, קרקע המשמשת להילוך הרבים, וכיון דאין הילוך הרבים אלא בט\"ז אמה, יהיו כל ט\"ז אמה אחד ברה\"ר ביחס להילוך, וע\"מ שיהיה נחשב הקרקע כקרקע המשמשת לרה\"ר צריך שיהיה בה ט\"ז אמה, והיינו, שהקרקע עצמה אינה מאוחדת בט\"ז אמה אלא שימוש הרבים אינו נחשב ככזה אלא ברוחב קרקע זה, ובפחות אינו נחשב הילוך הרבים. אך קרקע רה\"ר אינה אחת בט\"ז אמה, ואין לה רוחב, וע\"כ גדר ההילוך ביחס לקרקע הוא ע\"י דריסה, היינו, מה שדורסים בה הרבים בהילוכם, שאין משמעות בכל חלק מהקרקע במשך ההילוך, אלא בדריסה, וע\"כ כל מקום שיהיו הרבים דורסים כחלק מהילוכם יחשב כרה\"ר, וע\"כ לא יהיה עמידה חסרון בהגדרת קרקע כרה\"ר, אלא בהגדרת שימוש כזה כשימוש הרבים, וע\"כ אם יהיה עמידה שהיא מוגדרת כשימוש הרבים דריסת קרקע זו, גם תחשוב את הקרקע כרה\"ר. \u003c/span>"}, {"s": "h3", "h": "\u003csup class=\"cb\" data-c=\"1136\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">146\u003c/sup>\u003cspan class=\"ca\" data-c=\"1136\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">כב. בגדר קרקע דרשות\u003c/span>"}, {"s": "h7", "h": "קרקע דרשות האמור ביחס להילוך - קרקע רשות להנחת חפץ אינה מוגבלת לגדרי הילוך"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"578\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">147\u003c/sup>\u003cspan class=\"ca\" data-c=\"578\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">ודין קרקע האמור לגבי רשות הוא ביחס להנחת חפץ כאמור, ואין זה שייך לגדרי הילוך, וע\"כ אף שלא יחשב שימוש המגדיר רה\"ר אלא בדריסת קרקע דהילוך קרקע, הרשות עצמה לא תוגבל בגדר זה, וע\"כ שימוש הרבים אינו מגדיר ביחס לקרקע הרשות כדין בהילוך, וכל שימוש שיחשב שימוש הרבים יגדיר את הקרקע כמקום הנחשב כרה\"ר. והיינו, שאמנם רה\"ר המוגדרת כך היא ע\"י שימוש הרבים, והמושג שימוש הרבים הוא בהילוכם, וכל שימוש אחר אינו מוגדר שימוש הרבים אלא שימוש היחיד, אך אין הילוך עצמו הגדרת קרקע דרה\"ר, אלא עצם השימוש שביחס להילוך נקרא דריסה, אך כל שימוש שיחשב שימוש הרבים יגדיר את המקום המשומש כרה\"ר, וע\"כ שימוש שנחשב אחד עם הילוך גם הוא יחשב שימוש הרבים, וע\"כ עמידה שהיא חלק מהילוך כמו עמידה לכתף גם היא נחשבת לשימוש הרבים, כי אין גדר הילוך הרבים כסוג שימוש גדר חיובי של שימוש אדם, אלא גדר שלילי, היינו, שימוש המועט שאינו מבטל שימוש הרבים, שהרי אין הרבים אלא הרבה יחידים, ואין שימוש במקום אלא שימוש היחיד, והגדרת רבים אין היא חיובית ביחס ליחידים, אלא ביטול היחיד. \u003c/span>"}, {"s": "h7", "h": "גדר שימוש הרבים ביחס למקום - שימוש שאינו סותר היות המקום לרבים כהילוך וכיתוף"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"579\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">148\u003c/sup>\u003cspan class=\"ca\" data-c=\"579\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">וע\"כ יהיה גדר שימוש הרבים ביחס למקום גדר ברבים ולא בשימוש, והיינו, עצם מה שהמקום הוא לרבים. ואם היה אפשר שיהיה הגדרה במקום שהוא לרבים, בלי היותם לא היה צריך את השימוש. אלא כיון שאין הגדרת המקום כרה\"ר אלא ע\"י היותם, ואין היותם אלא ע\"י שימושם, אלא שאין היחיד משתמש אלא לעצמו (ואף בהילוך), וא\"כ אין שימושו ראוי להגדיר רה\"ר, ע\"כ יהיה השימוש המגדיר את המקום שימוש שאינו סותר את היות המקום לרבים והיינו, הילוך, אלא שהרי הילוך דיחיד הוא תפיסת המקום ע\"י יחיד, ואמרו דבט\"ז אמה אין נחשב שהיחיד תופס המקום, דאין בשימושו כח לתפוס כזה רוחב (וזה גדר דהתפשטות ד\"א דיחיד ביחס למקום המיועד לשימוש הנ\"ל). וא\"כ יש כאן שימוש בלי תפיסה, וזה גדר שימוש דרבים אפילו ביחיד. ואמנם אין עמידה לפוש נחשבת הילוך, היינו, שימוש בלי תפיסה, אך עמידה לכתף אף היא נחשבת שימוש הרבים, שאף היא חלק מהילוך, וע\"כ כיתוף יחשב כשימוש הרבים להגדיר את המקום הראוי לכיתוף כחלק מהרשות, והיינו, עמוד ט'. ואף שאין הוא חלק מהקרקע דרה\"ר במובנה כמקום הרשות, הרי הוא נחשב חלק מהרשות עצמה במובן קרקע דהנחת חפץ, וכמו בדריסה דהילוך. ובזה יבואר גדר תשמיש, דהרי אף הילוך אינו אלא תשמיש ביחס להגדרתו את הקרקע כנדרסת, וכך הוא נקרא בכל מקום, אלא שהילוך נחשב לתשמיש ביחס להגדרת קרקע דרשות ביחס למקום חפץ, אך ביחס להגדרת שימוש הרבים הרי שהוא נחלק בזה מתשמיש, שתשמיש הוא במקום מסויים, והילוך הוא השימוש ההמשכי. ובזה יבואר מה שאין תשמיש מגדיר את הקרקע כהילוך דקרקע, דהילוך יש לה תפיסת י\"ט שהיא הגדרת קרקע הרשות, אך תשמיש רק מגדיר את המקום כמקום הרשות, וכמו אווירה, ולא כקרקע הרשות. וזה במשמעות קליטת רשות, היינו, שגדר קרקע הרשות הוא במשמעות קודם לרשות, אך קליטת הרשות הוא רק אחר שיש רשות, שחפץ הנמצא במקום הרשות יחשב כמונח ברשות. \u003c/span>"}, {"s": "h7", "h": "דריסת הרבים בהגדרת קרקע רה\"ר - עמידה לכתף חלק משימוש הרבים כמו הילוך ממש"}, {"s": "p", "h": "וא\"כ הרי שדריסה ביחס לקרקע קודם הגדרת הרשות הוא בגדרי שימוש, וע\"כ יחשב דריסה שאינה נוחה כלא ניחא תשמישתיה, היינו, ביחס להגדרת קרקע כמשמשת לרבים, שאין שימוש כזה נחשב לשימוש לגבי דריסה, ולא נחשב דריסת רבים אפילו שרבים דורסים, דכיון שזה חסרון בצורת שימוש של רבים, אין זה רבים אלא הרבה יחידים (וזה גדר רבים מכתפים לה בכומתא וסודרא ברה\"י, שאף שודאי אין לזה גדר רה\"ר, דכיון שהוא רה\"י גם שימוש רבים נחשב לשימוש יחידים, אבל לגבי עירובי חצרות הרי אף הרבה יחידים הוא חסרון. ועוד יתבאר בעז\"ה), אך בזה יש גדר שני, והיינו, שאף אחר שישנם התנאים בקרקע להגדרת שימוש כשימוש הרבים, הרי אין הקרקע נחשבת לקרקע רה\"ר אלא ע\"י שימוש הרבים, ובזה איכא הבדל בין רה\"ר ליחיד, שכיון שאין רה\"י אלא בנפרדותה, וזה גדר חיובי, אין שייך שזה יתפשט למקום אחר, שאין נפרדות מתפשטת בחיבורה עם מקומות אחרים (אלא אדרבה היא נפרצת ע\"י החיבור), מאידך כיון שהגדרת רה\"ר היא ע\"י שימושה, וזה הרי שייך שיתפשט, והיינו, שכל מקום שיהיה משמש את הרבים באחת עם מקום שימוש הרבים, יחשב גם הוא רה\"ר. וגדר זה הוא בכל רה\"ר, שכיון שאין רה\"ר מוגדרת אלא ע\"י שימוש הרבים, הרי שכל מקום ומקום מוגדר בנפרד ע\"י שימוש הרבים."}, {"s": "h7", "h": "התפשטות שימוש הרבים במקום - עמוד ט' חשיב רה\"ר מחמת שימוש אחד עימה"}, {"s": "p", "h": "וע\"כ יהיה שייך שאף במקומות שאין בהם תנאים להגדרת השימוש כשימוש הרבים מחמת רוחבם וכו', כיון שהם משמשים כאחת עם רה\"ר גם הם יחשבו כך מחמת השימוש עצמו. ובזה לא נצטרך לתנאים דלעיל אלא רק מה שלא יחשב המקום נפרד ביחס לשימוש. וע\"כ עמוד תשעה יחשב לרה\"ר אף שהוא נחשב מקום נפרד מצד קרקע, אך הוא אחד עם השימוש. ובזה גם שייך שתהיה רה\"ר נפרדת ביחס לדבר הצריך חיבור כמו הנחת חפץ, היינו, שאף ששני מקומות יחשבו לרה\"ר ולא יהיה ביניהם נפרדות קרקע, כיון שהם נפרדים ע\"י שימוש לא יחשב לרשות שימוש אחת. "}, {"s": "h7", "h": "גדרים בהתפשטות שימוש הרבים - חסרון בהתפשטות הבאה מכח הדחק כבקרן זווית"}, {"s": "p", "h": "ובהתפשטות שימוש הרבים לעוד מקומות נמצא כמה גדרים, וכמו ע\"י הדחק, היינו, שאף אם יהיה מקום המשמש את הרבים באחת עם רה\"ר שלידו, והיה לו להיחשב כאחד, כיון שאין זה מכוחו אלא מכח התפשטות של שימוש שלידו, צריך שהוא יהיה משמש באחת, ומקום שמתפשט שימוש הרבים אליו משום הדחק שיש ברה\"ר, הוא חסרון בעצם ההתפשטות להגדיר את השימוש אחד עם שימוש שלידו, ושימוש שהוא משום שאין מקום ברה\"ר, אין הוא נחשב שימוש אחד. ועל זה אמרו שהילוך שע\"י הדחק נחשב הילוך, ותשמיש שע\"י הדחק אינו נחשב תשמיש. וביאורו שכיון ששימוש הרבים בהילוך הוא עיקר שם שימוש הרבים, אף שנעשה ע\"י הדחק, אחר שנעשה אין הבדל בינו לבין שימוש מקודם לו. אך תשמיש שאין הוא נחשב חלק משימוש רבים דקרקע, ואין הוא משמעות שימוש הרבים עצמו, אלא רק בזה שהוא מחובר להילוך שלידו, אם נעשה שימוש זה ע\"י הדחק, אין נחשב להיקרות מחובר. אך הילוך כזה נחשב הילוך, וזה גדר קרן זווית, שאמנם יש בה הילוך ע\"י הדחק, ונחשב הילוך אחד, אך מקום קרן זווית עצמה יש בו חסרון בהילוך שלא נוח תשמישו. וזה חסרון בהגדרת שימוש הרבים, ולא יועיל ההתפשטות. וזה גם גדר מאי דלא מסגי בהדיא, שאין זה נחשב שימוש אחד אלא שימוש אחר, וכיון שאין במקום עצמו גדר רה\"ר אין זה נחשב שימוש הרבים. "}, {"s": "h7", "h": "גדר בקיעת רבים במקום נפרד - חילוק בין מקום שקרקעו נפרדת למקום בעל מחיצות"}, {"s": "p", "h": "מלבד זה מצאנו גדר בהגדרת מקום ע\"י שימוש הרבים הנקרא בקיעה, והיינו, דאין זה מחמת עצם השימוש שנחשב שימוש אחד עם שימוש הרבים, אלא הוא ביחס למקום, והיינו, שאף שיהיה המקום נפרד ממקום שימוש הרבים, ושימוש שבו לא יחשב שימוש אחד, כיון שאין הוא מפסיק את שימוש הרבים, המקום עצמו נחשב כחלק ממקום שימוש הרבים. וגדר זה הוא ביחס למקום, היינו, חיבור המקומות, שגדר הילוך אחד מגדיר את קרקע המקום ע\"י שימוש שיש בו, משום שגם הוא נחשב שימוש הרבים, היינו, שדריסת הקרקע נחשבת לדריסת הרבים. אך גדר בקיעה אין זה בשימוש, שאין בו שימוש או שאין שימושו נחשב שימוש הרבים מסיבה אחרת, אך כיון שהרבים בוקעים בו הוא נחשב חלק מרה\"ר. ובזה חלוק הדין, שאם אין המקום נפרד לעצמו אלא רק קרקעו נפרד, היינו, ע\"י שאין משתמשים בו, בזה איתא לרב אשי דחשיב רה\"ר, אך אם המקום עצמו נפרד ע\"י מחיצות בזה איכא למחלוקת ר\"י ורבנן אי אתי רבים ומבטלי מחיצתא, והיינו, שאף ששימוש המקום אינו נחשב שימוש הרבים בגלל מחיצותיו, כיון שבוקעים בו רבים אין נחשב המקום נפרד, ואין הקרקע נפרדת, ממילא שימוש הרבים בו נחשב שימוש רבים, ומגדיר את הקרקע כרה\"ר. ובזה נסתפקו בתל דלא ניחא תשמישתיה, והיינו, שהרי במקום דאין מחיצות, ואין צורך לביטול מחיצות, אין נוחות השימוש במקום חסרון בבקיעה, שהרי אין אנו מחברים את המקום בגלל השימוש במקום עצמו, אלא בגלל חוסר חשיבותו השימושית ובקיעת רבים בו, אך כאן כיון שהמקום נפרד, הרי שיש לומר שמה שמבטל את המחיצות הוא שימוש הנחשב חלק משימוש הרבים ע\"י הבקיעה, ואם השימוש עצמו אינו נוח, יש לומר שאין זה מועיל. והיינו, דשימוש שלא ע\"י בקיעה כמו בקרן זווית אינו נחשב שימוש רבים משום שלא נוח תשמישו, אך בבקיעה הרי אין חסרון בשימוש, וכמו בגודא דגמלא. אלא ששם אין מחיצות, אבל כאן הרי יש מחיצות, ואנו רוצים לבטלם ע\"י בקיעה, ולהגדיר את השימוש כשימוש הרבים. ובמקום שנוח תשמישו וכמו בפסי ביראות, יש לומר שאף שהשימוש לבד אינו מספיק, שהמחיצות מגדירות את השימוש כלא שימוש הרבים, אך ע\"י בקיעה יש להגדיר את השימוש. אך בתל שהשימוש עצמו לא נוח היה להסתפק בדעת ר' יהודה אם הבקיעה רק מגדירה את השימוש כשימוש הרבים, ביחס לחסרון שהמקום נפרד ואמרינן שהשימוש אחד עם שימוש הרבים, וע\"כ בטלים המחיצות, אך השימוש עצמו להחשיב המקום רה\"ר צריך שיחשב שימוש בלי גדרי בקיעה, וכמו בקרן זווית. או דלמא הבקיעה מגדירה גם את השימוש עצמו, שלא יהיה בו חסרון דלא נוח תשמישו, וכמו שכתבנו לעיל הרי בלא נוח תשמישו יש חסרון בחשיבות השימוש כשימוש של רבים הנצרך להגדרת קרקע ע\"י דריסה, אלא דדעת ר' יהודה שבקיעת הרבים מגדירה את השימוש עצמו כשימוש הרבים, ונחשבת דריסתם את המקום להגדיר את הקרקע, וזה משמעות מה שאמר ר' יוחנן במעלות ומורדות דא\"י, והיינו, שבארץ ישראל אפילו במקום שיש לו תנאי רה\"ר (היינו ואין צריך לבקיעה או הילוך ע\"י הדחק), ויש בו עצמו שימוש רה\"ר אין זה חשיב רה\"ר, שלא נמסרה לרבים. אך בחו\"ל אין חסרון בזה לגבי רה\"ר. וספק דרחבא הוא אחר דברי ר' יוחנן, שהוא נסתפק שלר\"י אף בארץ ישראל יחשב כן עכ\"פ בגלל בקיעה, או לא יחשב אף בחו\"ל, כיון שלא ניחא תשמישתיה. וזה פשט לו שבא\"י אף ברשות עצמה לא נחשב משום שלא נמסרה, ובחו\"ל אף בלא ניחא תשמישתיה נחשב רה\"ר משום בקיעה."}, {"s": "h7", "h": "סיכום גדרי רשות הרבים ושימושה - עיקר שימוש הרבים בהילוך ותוצאתו בהגדרת קרקע הנדרסת"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"1137\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">149\u003c/sup>\u003cspan class=\"ca\" data-c=\"1137\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">וא\"כ מצאנו דעיקר גדר רה\"ר הוא במה שהרבים משתמשים בו, ועיקר שימוש הרבים הוא הילוך, היינו, דריסת הרגל, דהוא שימוש היחיד שאינו נצרך למקום נפרד, כי אין חסרון לגבי מקום דריסת רגל דיחיד במה שאף אחרים דורסים בו, וכמש\"כ אין נחשב שימוש הרבים אלא במקום שאין שימוש כל אחד תופס הרשות, וזה שיעור ט\"ז אמה. אך אחר שיחשב המקום ראוי לשימוש הרבים יהיה זה גדר בשימושם שיחשב שימוש הרבים, וכל קרקע שיהיו רבים משתמשים בה תחשב כקרקע הרבים, אף אם אין בה שיעור זה (וזה הדין בכל רה\"ר ואף בט\"ז אמה שלה) וכמש\"כ אף שעצם שימוש הרבים הוא בכל הרשות תהיה הגדרתם ביחס להוצאה רק בקרקע שהיא נחשבת לגבי מקום הראוי להנחת חפץ, וכל מקום שיהיה ראוי לזה יחשב לקרקע, אך כיון ששימוש הרבים הוא בהילוך צריך שיהיה זה המקום משמש כחלק מהילוך, וכן אין קרקע רה\"ר נפרדת אלא ביחס לשימוש, היינו, הילוך, וכל מה שישמש הילוך אחד עם שימוש הרבים יחשב כרה\"ר.\u003c/span>"}, {"s": "h3", "h": "\u003csup class=\"cb\" data-c=\"1138\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">150\u003c/sup>\u003cspan class=\"ca\" data-c=\"1138\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">כג. בגדר בקיעה\u003c/span>"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"1139\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">151\u003c/sup>\u003cspan class=\"ca\" data-c=\"1139\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">והנה גדר בקיעה עצמו, היינו, משמעות מה דרבים העוברים במקום חשובים כבוקעים, צ\"ב, דלכאורה ביאורו משום שהוא חלק מהילוך שבשני גבולותיו, וכמו גדר מפולש. אך מצאנו ברש\"י סוכה שהזכיר מושג קפנדריא ביחס לבקיעת רבים, והוא לכאורה גדר נוסף.\u003c/span>"}, {"s": "h7", "h": "\u003csup class=\"cb\" data-c=\"1142\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">154\u003c/sup>\u003csup class=\"cb\" data-c=\"1141\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">153\u003c/sup>\u003csup class=\"cb\" data-c=\"1140\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">152\u003c/sup>\u003cspan class=\"ca\" data-c=\"1140 1141 1142\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">בירור במשמעות גדר בקיעה - צורת שימוש דבקיעה מגדירה את ההילוך כאחד ברשות\u003c/span>"}, {"s": "p", "h": "והיינו שהיה לדון מהו המחבר בין שני השימושים להגדיר את המקום כנבקע, שהרי יש ביניהם מקום שאינו באותו גדר שימוש. ואין בדריסתם גדר שימוש הרבים. ויש לומר שצורת השימוש של בקיעה היא המגדירה את ההילוך כאחד, ויש בהילוך זה שם שימוש הרבים, ויש בדריסתם להגדיר את הקרקע. אלא שגדר זה מצאנו אף במקום שאין כלל דריסה וכדאיתא בגודא דגמלא, ויש לומר שבמקום שאין בו סיבה נגדית להגדרת השימוש כשימוש הרבים, אכן די בעצם הבקיעה, היינו, ההילוך, אך לגבי מקום שיש בו סיבה כנ\"ל הרי בעינן לדריסה המוגדרת ע\"י אחדות ההילוך, אך אין ההילוך עצמו מוגדר כך. וגדר זה אין לו שייכות לקפנדריא, שגדר קפנדריא הוא חילוף העיקוף, היינו, שלולי זה היה מקיף המקום, וזה חסרון שיש בעצם השימוש במקום, שכיון שאין השימוש אלא חלופת העיקוף, אין הוא נחשב שימוש במקום (והיינו שאף בדין קפנדריא בביהכנ\"ס, יש לדון אם רק כניסה שאין נכנס להתפלל נחשב קפנדריא, וכגון שרוצה לקרוא למישהו שאם החסרון הוא בעצם השימוש במקום שלא לצרכי תפילה וכו', אפילו זה אסור. אבל אם הוא חסרון רק במה ששימוש שהוא חילוף העיקוף אינו נחשב שמשתמש במקום, אין כניסה סתם קפנדריא, שזה שייך בעצם לשימוש בביהכנ\"ס אם מותר שימוש כזה, ואין זה שייך למה שהגיע מבחוץ, ובזה לא יועיל מה שישהה, או ילמד דעצם השימוש שלא לתפילה אסור. ומה יועיל עוד שימוש להכשיר השימוש, אלא שיש לומר דגם זה גדר בשימוש במקום ביחס למקום תורה ותפילה. וצ\"ע). ואף כאן היה שייך לומר שגדר שימוש הרבים בבקיעה (היינו, דאיכא לרה\"ר משני צדדיה), משאינו בבקיעה, הוא מה שהשימוש אינו במקום, היינו, בעצם המעבר במקום, שהיו יכולים לעבור במקום אחר, וכמו יסלקנה לצדדים. וע\"כ אין השימוש האחיד נחשב תלוי במקום הנפרד, וע\"כ אין הוא חסרון באחידות השימוש. ואין עצם הבקיעה גדר בשימוש, אלא שאחר שאין חסרון כזה, ויהיה במקום שימוש שהוא חלק משימוש אחד של הרבים, לא מועיל בו מחיצות להגדירו. ונחלקו ר\"י וח\"כ אי עצם שימוש הרבים חשיב לבטל מחיצה. "}, {"s": "h7", "h": "גדר בקיעת רבים כקפנדריא האמור ברש\"י - חילוף עיקוף מגדיר השימוש כאינו תלוי במקום הנפרד"}, {"s": "p", "h": "אך מהגדרת רש\"י בקיעה כקפנדריא נראה לומר שאין ביכולת העיקוף רק חיבור דשני השימושים, אלא הוא גדר בצורת השימוש עצמו. כלומר, שכיון שאין מעבר הרבים במקום רק חלופת העיקוף, יש בשימוש כזה משמעות שאינו מוגדר ע\"י המקום, וזה גדר חיובי בבקיעת רבים, היינו, שהרי אין שימוש במקום נפרד נחשב שימוש הרבים, ואף אם יהיה שימוש זה חלק משימוש הרבים לפני ואחרי אין די בזה בהגדרת השימוש, משום ששימוש במקום נפרד הוא גדר חיובי בשימוש שאינו נחשב שימוש הרבים (וכמו שכתבנו שלהחשיב שימוש הרבה יחידים כשימוש הרבים הוא מחמת חסרון בגדר שימוש היחיד שיש בכל אחד), אלא שכיון שאין השימוש במקום זה רק כחלופת עיקוף הרי שיש בשימוש כזה סיבה שלא יוגדר ע\"י מקום השימוש, וע\"כ אף שבדר\"כ יהיה בנפרדות המקום סיבה להגדרת השימוש בו, אין זה מועיל לכזה שימוש. "}, {"s": "h7", "h": "גדר שימוש הרבים הנשמע מדין רקק - שימוש שהוא חלופת עיקוף אינו חסרון בהגדרת מקום"}, {"s": "p", "h": "והנה סברא כזו כבר ראינו ביחס להגדרת שימוש רבים במקום כרה\"ר ביחס לרקק, דאמרינן התם שהיה לומר שאין שימוש רבים ברקק מחשיבו לרה\"ר, רק אם הוא עד ד' אמות רוחב, אבל אם הוא ד' אמות הרי יקיפוהו, וקמ\"ל שלא. וכתב רש\"י שכיון שהוא פחות מד' אין זה טורח לעבור בו מלהקיף. וקשה לי דאדרבה אם הוא רחב ד', אז יש לומר שזה הוא טורח להקיף, וע\"כ עוברים בו וי\"ל דהוי רה\"ר. וביאורו כמו שכתבנו שהרי ממה נפשך אם באמת כשהוא רחב ד' אין עוברים אלא מקיפים, אז ודאי לא הוי ליה להיות רה\"ר, שאין רה\"ר מהלכת בו, וזה הרי כל הסיבה להגדירו כרה\"ר, וא\"כ בהכרח דאיירי שאף בד' לא מקיפים אותו. אלא חידוש המשנה הוא בהגדרת השימוש עצמו, שאף שבשני המקרים (רחב ד' ופחות) המציאות היא שרה\"ר מהלכת בו, יש הבדל בגדר השימוש. והיינו, דאף שאמרנו ששימוש ע\"י הדחק הוי שימוש, יש לומר שזה דוקא שימוש שהוא במקום, וכדאמרן, אך אם הרקק רחב ארבע אמות, כיון שיש לומר שאין הרבים עוברים בו אלא משום שיש להם טירחא בעקיפתו, אין זה נחשב שימוש במקום, וזה יותר מסתם ע\"י הדחק. וזה אמרו שאין זה חסרון בשימוש המגדיר מקום. "}, {"s": "h7", "h": "הבדל רה\"ר מרה\"י בכלל מקומם - רה\"ר מוגדרת בכל חלק בנפרד ורה\"י כמכלול אחד"}, {"s": "p", "h": "ובאמת כמש\"כ הרי זה יוצא מההבדל בין גדרי רה\"י ורה\"ר, שאין נחשבת קרקע כרה\"ר ע\"י תנאיה כהגדרה כוללת לכלל המקום, אלא כל חלק וחלק מרה\"ר יש בו גדר רה\"ר בנפרד. משא\"כ ברה\"י שכל גדריה הוא הגדרת המקום כאחד. וזה פשר שיש ברה\"י חסרון ברוב גודלה שהוא ביחס לאחידות המקום. "}, {"s": "h7", "h": "גדרי מקום רה\"ר בשימושה בפועל - הגדרת קרקע ע\"י שימוש הרבים היא בעצם המשתמשים"}, {"s": "p", "h": "וא\"כ הרי בהכרח שאין גדרי מקום דרה\"ר אלא גדרים בשימוש, ולא ביחס לקרקע עצמה. שאף אחר הגדרתה כרה\"ר אין היא במשמעות רשות אחת ביחס לקרקע. וכמ\"ש, שביחס לעצם הקרקע אין משמעות שימוש הרבים. אלא דריסה, ולא הילוך. שזה גדר שימוש דהילוך ביחס לכל חלק וחלק בקרקע (וזה גדר דריסת הרגל בכל מקום וכמ\"ש במק\"א). וכיון שכן הרי שעיקר הגדרת קרקע ע\"י שימוש הרבים, הוא עצם מה שמשתמשים בה הרבים, ואין בה משמעות של סוג השימוש (ובאמת זה ברור בכל הגדרת קרקע שאין לומר בה סיבה מוקדמת לאחדותה). "}, {"s": "h3", "h": "\u003csup class=\"cb\" data-c=\"1143\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">155\u003c/sup>\u003cspan class=\"ca\" data-c=\"1143\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">כד. ביאור במח' ר\"י וחכ' לפמשנ\"ת\u003c/span>"}, {"s": "h7", "h": "\u003csup class=\"cb\" data-c=\"1148\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">160\u003c/sup>\u003csup class=\"cb\" data-c=\"1147\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">159\u003c/sup>\u003csup class=\"cb\" data-c=\"1146\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">158\u003c/sup>\u003csup class=\"cb\" data-c=\"1145\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">157\u003c/sup>\u003csup class=\"cb\" data-c=\"1144\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">156\u003c/sup>\u003cspan class=\"ca\" data-c=\"1144 1145 1146 1147 1148\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">ביאור דין אתי רבים לפי גדר הנ\"ל - בקיעה מגדירה שימוש שאינו במקום וממילא מבטלת מחיצות\u003c/span>"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"1149\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">161\u003c/sup>\u003cspan class=\"ca\" data-c=\"1149\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">ולפי זה, היינו, אם נאמר שגדר בקיעה הוא כקפנדריא, יש לבאר דעת ר\"י דאתי רבים ומבטלי מחיצתא באופ\"א, כלומר, שאין פירושו ששימוש הרבים שלפני ואחרי המקום מגדיר את השימוש כשימוש הרבים במובן חיובי, אלא הוא מגדיר את השימוש במקום במובן שלילי, ושאין השימוש נחשב שימוש במקום אלא שימוש סתם, שהיות השימוש חלק משימוש הרבים מגדיר את השימוש כשימוש שאינו במקום, וממילא אין משמעות למחיצות, כיון שכל גדר מחיצות רה\"י הוא להגדיר את המקום כמשמש שימוש אחד, ואם בקיעת רבים חשובה להגדיר את השימוש כשימוש שאינו במקום, הרי שביחס לקרקע המקום יש גדר שאינה משמשת שימוש אחד, היינו, רה\"ר (כי הרי אין המחיצות מגדירות אלא קרקע וכמש\"כ). \u003c/span>"}, {"s": "h7", "h": "\u003csup class=\"cb\" data-c=\"1152\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">164\u003c/sup>\u003csup class=\"cb\" data-c=\"1151\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">163\u003c/sup>\u003csup class=\"cb\" data-c=\"1150\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">162\u003c/sup>\u003cspan class=\"ca\" data-c=\"1150 1151 1152\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">שתי מחיצות מעלייתא לר' יהודה - מחיצות המגדירות מעבר מסויים אינן בטלות ע\"י בקיעה\u003c/span>"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"1153\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">165\u003c/sup>\u003cspan class=\"ca\" data-c=\"1153\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">וא\"כ זה פשר מה דס\"ל לר\"י דאי איכא שתי מחיצות מעלייתא חשיבי שלא יחשב אתי רבים, והיינו, שודאי אין משמעות במה ששני מחיצות אלו שלמות ביחס לעצם בקיעת הרבים במקום, דמסתגי להו להדיא. אלא, היינו, טעמא, דכיון שביחס למקומות שחוץ למחיצות אלו מגדירות המחיצות את שימוש המעבר במקום, כשימוש נפרד ממעבר שלידו, הרי שיש להם משמעות של מעבר נפרד, ואין מעבר הרבים נחשב לשימוש סתם, אלא שימוש במעבר מסויים. ובגדר זה יש להבחין כי שני המחיצות אינם פועלות יחד, אלא כל מחיצה מגדירה את המקום בנפרד ביחס למעבר בצד שלה, וביחס למקום הכולל הרי שזה גדר שלילי. אלא שביחס לשימוש הרבים דחילוף העיקוף זהו גדר חיובי, שנחשב שעוברים במעבר מסויים, ואין זה שימוש סתם אלא שימוש במקום. \u003c/span>"}, {"s": "p", "h": "וא\"כ אין מה דב' מחיצות עדיפא ליה תלוי בגדר רה\"י, שמה שעושים ב' המחיצות רה\"י זה ביחס להגדרתם יחד את הקרקע, ובזה הרי ס\"ל לר\"י דאתי רבים, שאם אין זה נחשב לשימוש במקום אלא לשימוש סתם, אתי ומבטלי מחיצתא, דאין הגדרת הקרקע שייך לשימוש. אלא זה דווקא בגלל שמחיצות אלו לאורך הרשות, ויש להם להגדיר את שימוש הרבים עצמו כמעבר מסויים, וכדאמרן. "}, {"s": "h7", "h": "דעת חכמים החולקים על ר' יהודה - מחיצות מגדירות קרקע נפרדת ולא רק צורת מעבר"}, {"s": "p", "h": "ולפ\"ז י\"ל דחלקו רבנן על ר\"י בתרי אנפי, והיינו, דאף רבנן מודו דמשמעות מחיצות דרה\"י ביחס למקום, היא רק במה שהם מגדירים את הקרקע כנפרדת, ואין מטרתם להגדיר קרקע בצורה ששימוש בה יחשב שימוש דרה\"י בעצם צורת השימוש במקום, אלא המחיצות רק מגדירות קרקע נפרדת, וממילא שימוש בה יחשב שימוש היחיד (והיינו, שאכן המושגים הנ\"ל הם מושגים שימושיים, שמושג קרקע לעומת אוויר הוא ביחס לשימוש בחפץ, ומה שהיא נפרדת הוא ביחס לשימוש שעושה האדם בקרקע נפרדת, ואינו עושה בקרקע שאינה. וכן מחיצות דשבת יש בהם משמעות שימוש שלילית דמניעת רגל רבים, אך אין זה הגדר הנעשה ע\"י מחיצות. היינו, שנאמר שרה\"י הוא מקום שאין בו רגל רבים וזה נעשה ע\"י מחיצות, שהרי מן התורה אין אנו צריכים להגדיר השימוש עצמו, אלא רק את הקרקע כראויה לשימוש. וע\"כ אף שגדר השימוש זה עיקר משמעות מחיצות ביחס להגדרת רה\"י, אין הם עושים רק הגדרה לקרקע). אלא דדעתם שעכ\"פ יש במחיצות גם הגדרה בקרקע במה שחוצצים אותה, וזה במובן כל מחיצה בנפרד, וכדלקמן. "}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"1154\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">166\u003c/sup>\u003cspan class=\"ca\" data-c=\"1154\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">ולפי זה יבואר מה שאמרו כאן הודיעוך כוחן של מחיצות, כלומר, שאין מחיצות רה\"י רק במשמעות שלילית דמניעת רגל רבים, וממילא קרקע זו המנועה מרגל רבים נחשבת נפרדת מבחינה שימושית, אלא יש למחיצות גם משמעות חיובית להגדיר קרקע. \u003c/span>"}, {"s": "h7", "h": "העדר כוחן דמחיצות בב' לר\"י - שתי מחיצות מגדירות מקום שלילי ואינן מגדירות קרקע"}, {"s": "p", "h": "ולפ\"ז מבואר למה לא אמרו ר\"י ור\"א מאמר זה ביחס לשתי מחיצות מעלייתא דר\"י (דלכאורה הוא ריבוי כוחן), דמה ששתי מחיצות דר\"י מועילות זה כאמור בגדרם השלילי, כלומר, שאין מקום זה מחובר למקום שלידו וכדלעיל. ואין בזה כוחן של מחיצות, שבגדר זה אין להם כלל התנגדות ע\"י דבקעי ביה רבים. אך חכ' הרי סוברים כן אף ביחס למחיצות הצד הנבקע (שאין מי שיתיר פסי ביראות בלי דיומדין), והיינו, דאף דאית לן למימר דב' מחיצות דאורייתא, אין זה אלא במשמעות המחיצות בהגדרת המקום יחד, וזה גם רבנן וגם ר\"י מודו דבקיעת רבים ושימושם חשיב להגדיר את המקום כרה\"ר, דאין הגדרה דכלל המחיצות עושה אלא מקום נפרד, ולא קרקע נפרדת, ושימוש הרבים הרי פועל בדריסת קרקע, ואם אין בכח המחיצות להגדיר הקרקע עצמה, אלא רק ע\"י הגדרת מקום כנפרד מסביבותיו, הרי ששימוש הרבים עדיף בהגדרת המקום, שבזה אין משמעות המחיצות אלא משמעות שלילית (מניעת רגל רבים), ביחס לשימושיות הקרקע כשימושית באופן חיובי (שימוש נפרד דיחיד), ושימוש הרבים הוא חיובי (רגל רבים) ביחס לשימושיות הקרקע באופן שלילי (שימוש הרבים שאינו מוגדר). אלא סברה דרבנן הוא ביחס למחיצות כל צד בנפרד, מה שיש בהם הגדרה לקרקע שחוצצים (וזה גדר דיומדין שמחיצות כל צד דדיומדין פועלות בנפרד ביחס לכל צד, וביחס לחוץ, ועירובן בדיומדין חשיב לאחדם להגדרת הקרקע). "}, {"s": "h7", "h": "\u003csup class=\"cb\" data-c=\"1155\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">167\u003c/sup>\u003cspan class=\"ca\" data-c=\"1155\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">מחיצות כל צד להגדרת קרקע - דיומדין בד' מחיצות מגדירים קרקע בפני שימוש הרבים\u003c/span>"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"1156\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">168\u003c/sup>\u003cspan class=\"ca\" data-c=\"1156\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">ואמנם כדאמרן עצם הגדרת המקום דדיומדין לא חשיב כנגד שימוש הרבים, דשימוש הוא בקרקע, ודיומדין הם במקום. אך ד' מחיצות, היינו, מחיצות כל צד חשובים להגדיר את הקרקע עצמה. ויחד יש בהם הגדרה מד' צדדים, וכיון שהם מגדירים קרקע עצמה אין בכוח שימוש הרבים להגדירה (שיהיה זה יהיה חסרון בשימוש הרבים עצמו). אך ר\"י ס\"ל שאין במחיצות עצמם הגדרה לקרקע, אלא שיחד, היינו, ביחס למקום השימושי, הרי הם מגדירים קרקע. אך אם תבוא סיבה להגדרת קרקע עצמה, לא יועיל מחיצות המקום וכלעיל.\u003c/span>"}, {"s": "h3", "h": "\u003csup class=\"cb\" data-c=\"1157\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">169\u003c/sup>\u003cspan class=\"ca\" data-c=\"1157\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">כה. גדר מחיצות רה\"י\u003c/span>"}, {"s": "h7", "h": "\u003csup class=\"cb\" data-c=\"1158\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">170\u003c/sup>\u003cspan class=\"ca\" data-c=\"1158\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">גדר מחיצות רה\"י בקרקע וברוחב - קרקע ביחס לחפץ בכל חלק ושיעור ד' ברוחב\u003c/span>"}, {"s": "p", "h": "ואחר כל זה נבאר גדר מחיצות רה\"י, דכמו שאמרנו הרי אין קרקע ביחס להנחת חפץ דהוצאה בעלת גדר מקום, אלא רק מה שהיא קרקע לעומת אוויר שראויה להינוח, וכיון שזה ביחס לחפץ, ואין גודל חפץ סתם, הרי שיהיה כל חלק וחלק מהקרקע בגדר קרקע לבד. וע\"כ אם נרצה להגדיר קרקע כזו ביחס לשימושיות, היינו, קרקע הראויה לשימוש סתם, ולא ביחס לחפץ מסויים. יהיה זה בגדר כמות ביחס לקרקע, וכיון שבהגדרת קרקע לעומת אוויר, אין לנו להגדיר שטח, היינו, כגודל אחד, שאין צורך לזה ביחס לחפץ סתם, הרי שיהיה גודל הקרקע ברוחב לבד. והוא רוחב ד\"ט, היינו, שיעור חשיבות של קרקע (במובנה לעומת אוויר). אלא שביחס להגדרת רשות, היינו, קרקע מקום, הוא קרקע ד' על ד'. וא\"כ תהיה הגדרת קרקע זו כמקום אחד ביחס לשימוש, וע\"כ גם גדר מחיצה דרה\"י, ושימוש דרה\"ר הוא ביחס לקרקע זו. ויהיה בזה משמעות לכל חלק מהקרקע בנפרד ובאורך ורוחב בנפרד (וכמו פס משהו דר' זירא, היינו, ביחס ישיר לקרקע המועטת). "}, {"s": "h7", "h": "ביאור דיני מחיצה לאורכם ורוחבם - משמעות בכל צד בנפרד ובכל רוחב בחלוקת הקרקע"}, {"s": "p", "h": "וע\"כ יהיה גדר לכל מחיצה, בכל צד, ובכל רוחב, בנפרד, שהרי יש בקרקע מקום אורך ורוחב כאחידות לכל חלק וחלק בה, והיינו, שכל חלקי הקרקע שבאורך מסויים יוגדרו בנפרד, ותהיה המחיצה עליהם בנפרד, ביחס לפריצת צד, ושתי מחיצות נגדיות ביחס להגדרתם כסתומים, וגדר דשתי מחיצות שלמות יהיו רק בהגדרת האורך של כל הקרקע, וד' מחיצות יהיו רק הגדרת כל האורך והרוחב בנפרד, ואם יהיו עריבן הרי שיש מחיצה אחת לכל השטח יחד. ודעת ר\"י שאין שום משמעות למחיצות אורך קרקע לבד, וא\"כ דעתו שאין המחיצות עושות כלום, לא ביחס לפירצה, ולא ביחס לסתימה, חוץ מהיותם מגדירים את כלל השטח יחד. וכמו שאמרנו זוהי הגדרת שטח מקום, המגדירה קרקע. ואף בפסי ביראות אין גדר של ד' מחיצות שהרי אין זה בכלל השטח, אלא לאורך ורוחב, וע\"י דיומדין יוגדר שטח כמקום שע\"י זה יוגדר כל הקרקע. אך לדעת חכמים שיש משמעות בהגדרת כל אורך בנפרד, וא\"כ יש משמעות בד' מחיצות מה שאין בב', שבב' אין הגדרה רק לאורך ולא לרוחב, אך בד' יש הגדרה לאורך ורוחב, ויש בזה תוספת הגדרה לחלקי הקרקע, וכל חלק בקרקע מוגדר לאורכו ורחבו. וכן בפסי ביראות שאף שגם ר\"י מודה שהוא רה\"י דאורייתא, אך דעת ר\"י שאין זה מחמת הגדרת הקרקע, אלא מחמת הגדרת השטח כמקום המגדיר את הקרקע. אך רבנן סברי שיש במחיצות פסי ביראות גם הגדרת הקרקע עצמה, והיינו, שע\"י שם ד' מחיצות יש גדר באורך ורוחב הקרקע עצמה, וממילא יש הגדרה בקרקע, ואין כאן שימוש הרבים. אבל בב' מחיצות טובות, אף אי נימא דסברי רבנן דב' מחיצות דאורייתא, יהיה זה באותו גדר דר\"י, היינו, ששני מחיצות המגדירות את כל חלקי הקרקע באורכם, חשובות להגדיר את כלל המקום כאחד. אבל אין גדר בקרקע, שהרי אין בהם אלא הגדרה לאורך, ואין זה הגדרת מקום. ודריסת הרבים בכל חלק בקרקע פועלת בקרקע להגדיר מקום. "}, {"s": "h7", "h": "משמעות מחיצת צד למרחק מקומה - בשיעור ההשפעה של כח המחיצה במרחק"}, {"s": "p", "h": "והנה לצורך ביאור האמור לעיל, נקדים מה שצ\"ב בגדר משמעות מחיצת דצד ביחס למרחק מקום שהוא חוצץ, והיינו, דבמחיצה דכלאיים ניחא שהרי אין אנו צריכים אלא לחוץ מפני דבר מסויים, וביחס לזה הרי ממה נפשך אם ישנה השפעה, הרי מחיצה תועיל, ואם אין השפעה אין צורך במחיצה, וממילא אין צורך בהגדרת השפעת מרחק מחיצה. ובאמת כך הוא שבכלאים אף המרחק מוגדר, וביותר ממנו אין צריך מחיצה, ואין גדר כח מחיצה ביחס לחיבור מקומות, אלא במרחק זה. וכמו בגדר דכרם. אבל מחיצות שבת שהן ביחס להגדרת מקום שלהם, הרי היה צריך שיהיה בזה איזה שיעור. ואמנם מצאנו שיעור דבית סאתיים, אך אין גדר בית סאתיים ביחס למחיצות, אלא ביחס לשטח, ואף למ\"ד שהוא בצורה מסויימת, אין זה גדר בכל מחיצה בנפרד, דא\"כ הוה ליה להיות בריבוע, ואף לר' יוסי דעיקרה ריבוע, הרי מועיל גם במלבן. ואף לפר\"ח הוא גדר במקום, דאין אלכסון גדר במחיצות באופן שלילי, שהרי יש מחיצות על כל חלק מהאי אלכסון ביושר, ובהכרח שהוא גדר בקרקע, ואיך שלא יהיה ודאי שאין זה גדר בכוח מחיצה אחת (אלא בשניים, ואין משמעות שניים אלא כגדר בקרקע לבד, ולא כגדר בכח מחיצה). "}, {"s": "h7", "h": "גדר מחיצת צד ביחס למקום - אין הגבלה לפירצה ביושר אלא בכלל הצדדים יחד"}, {"s": "p", "h": "ובאמת הרי במחיצה כגדר במקום, היינו, מה שהיא פועלת בכל שטח מקום שלה יחד, יש הבדל אפילו ביחס לפירצה, שהרי ככל שהמקום מרוחק, כך יתיישרו פריצות אלכסון, ולכאורה ביחס למקום אין להגביל פירצה ביושר, ואדרבה הרי אמרינן דפיתחא בקרן זווית לא עבדי אינשי, והיינו, דאף דהתם הוא ביחס לכלל מחיצות מקום, דזה גדר פתח, הרי יש לבאר דעכ\"פ אין פירצה ביחס לכל צד, דאינו בד', וזה הרי אפילו ביחס לצד מסויים. אך נראה דאין זה דומה, דשם גם משמעות מחיצת הצד הוא ביחס לכלל המקום, וממה נפשך ביחס לצד אחד, אין היא הגדרה במקום, וביחס לכלל צדדי המקום, הרי יש לה לפעול ביחד עם המחיצות, וע\"כ אינה פועלת אלא ביושר. ואף כאן יש לומר דאין גדר מחיצת צד רק ביחס למקום, ורק ביחס ליושר מחיצה, ובאמת אם נרצה לחוץ מקום, יהיה פירצת אלכסון פירצה. ועדיין יש לנו לבאר גדר מחיצת צד ביחס למקום."}, {"s": "h7", "h": "חילוק אורכו יתר על רחבו - לחי בצד המיוחד לעומת מחיצה כללית בכל שטח"}, {"s": "p", "h": "ואין להביא ראיה מהיתר לחי וקורה באורכו יתר על רוחבו, כלומר, דאמנם שם מוכח דיש להגביל מחיצת לחי וקורה (אי הוה משום מחיצה), רק אם משמעותם חשובה בזה שצד שהם חוצצים הוא חשוב משאר צדדים, אבל הרי פס דהוא מחיצה אין לו גדר זה. ועוד יש לומר שזה שייך רק ביחס למקום שיש לו צורה, שאז יש להחשיב צד ע\"פ חלקו ביחס לכלל הצדדים, אבל בנידון דידן שהוא ביחס למחיצת צד אחד לא מצאנו זה. ובפרט, שאף בכלאיים שגדר מקומו הוא מרחק, מועיל מחיצת ארבעה לחומרא ולקולא, אפילו לגבי מקום ארוך עד ד', ומוכח שאין משמעות במחיצת צד ביחס לשאר צדדים, אלא יש במחיצת צד חשיבות לחוץ לבדה, ואי איך שלא יהיה גדר קרקע דכלאיים, הרי אינו שיעור במחיצה, אלא בחשיבות קרקע כמקום בעל חשיבות מרחק. ויש לומר שגדר זה יגדיר גם משמעות מחיצה לחומרא. אבל הרי חשיבות קרקע כמקום הוא חשיבות תפיסה, ולא מרחק, היינו, רוחב ד\"ט, וכמשנ\"ת באריכות, וא\"כ אין לזה משמעות במחיצות כלל אלא במקום (ובמחיצות שחשיבותם ביחס למקום כמו בהיקף לדירה). ובאמת בור וחולייתה מצטרפים שאין חסרון במחיצה, המגדירה מקום מה שאין לה מקום ד' שהרי היא מגדירה את המקום, ולא המקום אותה, ואנחנו דנים במחיצה כזאת (ולא במחיצה ביחס למקום קיים, שבזה אין חשיבות המחיצה אלא למקום, וכמו בקורה משום מחיצה לגבי מיעוט גובה, או במחיצת קרפף. והרי בחריץ בין חצירות בעינן לסברא דפסעי לה, שזה גדר באחידות הקרקע במובן חיובי ולא בחסרון כח מחיצה. וז\"ב) ואיך שיהיה פשוט שאין גדר ד\"ט במרחק מחיצה, ואין לפעולת מחיצה להגדיר מקום גדר חיובי בד\"ט. "}, {"s": "h7", "h": "שיעור ד' טפחים במחיצה ובמקום - שיעור בתפיסת קרקע ביחס לחפץ ולא מרחק מחיצה"}, {"s": "p", "h": "וביתר ביאור שאם היה שיעור ד\"ט שיעור מרחק אכן היה לומר שמחיצה להגדיר מקום לא תועיל אם אין לה ד\"ט מקום, שהרי מרחק הוא מקצה השיעור לקצהו השני, והיה גדר במחיצה שהיא בקצה המקום, ולא יהיה חשיבות קצה המקום בלי שיעור שיחשב קצה, ואחר שאין זה גדר שיעור מקום, אלא שיעור תפיסה וכמשנ\"ת לעיל, בהכרח שכל חלק וחלק בקרקע יש לו משמעות עצמית של תפיסה, ושיעור ד\"ט הוא כמות תפיסת דבר חשוב לעניין מקום דרשות (וכתבנו שלא מצאנו גדר בד\"ט אלא ברוחב מעבר אדם ונצטרך לומר שגדר זה הוא היות המקום חשוב לשימוש אדם). וכיון שאין למחיצה כמגדירה מקום גדר ד\"ט, הרי שכל חלק וחלק בקרקע מוגדר בנפרד ע\"י המחיצה. והתחדד לנו גדר החקירה, היינו, דכיון שאין המחיצה מתייחסת למקום כאחד, הרי שכל חלק וחלק בקרקע מוגדר בנפרד ע\"י מחיצה זו, וא\"כ אף שאין זה גדר ד\"ט, אבל יש לנו לדון עד היכן תהיה המחיצה האחת, מגדירה את הקרקע המחולקת, שהרי אין היא מגדירה את כל המקום באחת, אלא זה פועל יוצא אחר שיש מחיצה, וא\"כ יש גדר מרחק מהמחיצה. "}, {"s": "h3", "h": "\u003csup class=\"cb\" data-c=\"1160\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">172\u003c/sup>\u003csup class=\"cb\" data-c=\"1159\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">171\u003c/sup>\u003cspan class=\"ca\" data-c=\"1159 1160\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">כו. במשמעות מחיצות ובגדר הנפעל ע\"י במקום\u003c/span>"}, {"s": "h7", "h": "בגמ' דא\"י אין חייבין עליה משום רה\"ר – בגדר חסרון הנמצא במחיצת ארץ"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"580\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">173\u003c/sup>\u003cspan class=\"ca\" data-c=\"580\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">והנה מצאנו בסוגיית א\"י אין חייבין עליה משום רה\"ר, שהיה צד לומר שזה משום שמקיף לה תל וחריץ, ופשטו שזה אינו משום שגם ארץ בבל יש לה זה, ועוד דחו דא\"כ כל העולם מקיף לו אוקיינוס. ומשמע שזה תוספת דחיה מה שלא יתכן שיהיה זה גדר לגבי רה\"ר אחר שאין מקום בעולם שאין הוא נכלל בזה. והנה לא הקשו ז\"ל שאין לומר שיועילו מחיצות בכזה גודל ומרחק, ומשמע שאכן אין שיעור כזה. ועכ\"פ מצאנו שאין מחיצות ארץ נחשבות מחיצה לפטור שטחה משום רה\"ר, אבל אין להוכיח משם גדר במחיצות. דהנה מעצם הוכחת הגמ' מזה שאין יתכן שיהיה העולם כולו חסר דין רה\"ר על דין א\"י משמע שלא חלקה, ואף שיש הבדל ביחס למרחק, והיינו, שפשיטא להו שאין הבדל ביחס לגודל. וא\"כ גם מסקנת הגמ' הוא לא ביחס לגודל, ואכן יש לדון בזה אם הוא משום חסרון במחיצות שהם חלק מצורת קרקע של העולם, או משום חשיבות מקום הראוי להיות בו רה\"ר כמו ארץ, אבל לא משום גודל כאמור. \u003c/span>"}, {"s": "h7", "h": "חילוק מחיצות רה\"ר ממחיצות רה\"י - מחיצות הקרקע לעצמן מול מחיצות המגדירות מקום נפרד"}, {"s": "p", "h": "ובכלל גם אין להוכיח גדר מחיצות המבטלות דין רה\"ר למחיצות רה\"י, שהרי לא פרטו בא\"י ובבל רק שני מחיצות (ומחיצה דגדר הוא לכאורה בצד מזרח וסולמא דצור הוא בצפון וזה לא מועיל ברשות דשבת), ואין זה שייך לענייננו, שהיה לומר שזה גדר דווקא במקום קיים, היינו, שיש ברה\"ר גדר שלא יהיה לה מניעת התפשטות, ומסקנת הגמ' דאין כזה גדר כלל. אבל מחיצות רה\"י אין המקום מגדירם, אלא הם מגדירים את המקום, ובזה יתכן לומר שיש שיעור מרחק שאין מחיצות פועלות, או שנאמר שזה רק ביחס למחיצות שאינם בידי אדם, אבל מחיצות רגילות יועילו על כל מרחק. ולא מצאנו בגמ' גדר בזה. "}, {"s": "h7", "h": "דעת הראשונים בשיעור מחיצות ניכרות - צורך שיוכל לראות המחיצות המגדירות רה\"י דאורייתא"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"581\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">174\u003c/sup>\u003cspan class=\"ca\" data-c=\"581\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">ובראשונים מצאנו שיש שאמרו שהשיעור הוא שצריך שידע שהוא בתוך מחיצות, ובריטב\"א דימה זה לדין מחיצות ניכרות בסוכה, והנה יש לדון על מקום ראיתן, אם די שיראה אותן באיזה מקום, או שצריך שיוכל לראות בכל מקום. ובר\"ן כתב שצריך שיראה כולן מכל מקום שיש ברשות. והנה עצם הנידון הוא ביחס לרשות, דביחס לקרקע הרי סדנא דארעא חד, או שכל חלק וחלק נפרד. וכן עצם גדר ראיה הרי לא נוגע לקרקע לבד, אלא לשימוש בקרקע (והנה גדר ראיה אמנם נתבאר בכמה מקומות ביחס לאבידה ולרעיה, אבל הרי אבידה ודאי אינו שייך לכאן שהוא ראיה שיש בה התעלמות, וברועה זה ביחס לראיית דבר מסוים. ובכלל יש לדון דהרי דין מחיצות ניכרות הוא אפילו בתל שלא נחשב ניכר כיון שאין רואה אותם, אבל בשבת כיון שתל חשיב הרי שדי בראיית גבולות הדבר. ויש לדון מה נחשב ראיית מחיצות, ואם צריך שיראה את כל המחיצה, או די חלקה. ואולי יש לראות את חיבור המחיצה לקרקע דווקא, שזה גבול המקום, ועוד דודאי שככל שיגבהו המחיצות יראה ביותר. ועוד יש לדון אי ברשות מקום נמוך או גבוה במקום שאין בגבוהו להתלקט ואין יכול לראות. והנה בר\"ן כתב שצריך שיוכל לראות כל המחיצות הדרושות לדין דאורייתא, ובזה יש לדון במחיצות העשויות כמרזב אם די שרואה חלקן או שצריך לראות כולן). וע\"כ צ\"ל שאין זה גדר בכוח מחיצה, אלא בגדר מקום דרשות, וע\"כ זה ביחס לכל המחיצות. \u003c/span>"}, {"s": "h7", "h": "דברי הר\"ן דבעינן מחיצות שיראה בכל מקום - יכולת ראיה בכל מקום ברשות כגבולות המקום"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"582\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">175\u003c/sup>\u003cspan class=\"ca\" data-c=\"582\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">אלא דבר\"ן דכתב שצריך שיראה זה בכל מקום ברשות, ומשמע שזה ביחס לכל מחיצה, והיינו, שלא אמר שרק במקום שרואים נחשב שיש לו מחיצות, אלא שצריך שיהיה בכל המקום יכולת לראות, וזה גדר בקרקע בנפרד, ולא בהגדרתה כרשות, והרי ביחס לזה כל מחיצת צד פועלת נפרד. ובר\"ן אמנם כתב שצריך שיראה המחיצות וכמו ניכרות, והיינו, שאין זה גדר מרחק ראיה בין שני דברים, וכמו בכלאיים דזרעים, אלא זה גדר בקרקע, כמקום שימוש אדם, שלא תחשב שיש לה מחיצות. וכיון שאין זה שיעור מרחק, בהכרח שהוא דין בראיית מחיצות במשמעותם כמחיצות. וכמו גדר אוויר מחיצות, וכיון שאין מחיצות אלא לקרקע, יהיה זה גדר במחיצת עשרה, ולא יועיל ראיה של שאר מחיצה, וק\"ל. ונראה שאין זה גדר במחיצות עצמם, וכמ\"ש הרי בכל תל אין זה חסרון, אלא זה גדר בגבולות המקום, \u003c/span>"}, {"s": "h7", "h": "שני דינים נפרדים במחיצת רשות - מחיצה להגדרת קרקע להנחה ומחיצות יחד להגדרת שימוש"}, {"s": "p", "h": "והיינו, שיש כאן שני דינים נפרדים, דין במחיצה כהגדרת קרקע להנחת חפץ, ובזה יש דין מניעת רגל רבים וכו', וסוג המחיצה וכו', ומלבד זה יש דין במחיצות יחד, כהגדרת מקום שימוש אדם, ובזה יש דין שיהיו מחיצות ניכרות. וכמש\"כ אין זה דין במחיצות עצמם, אלא במה שהם גבולות המקום. וזה יובדל מאוד ביחס לתל, והיינו, שודאי מחיצות דתל כהגדרת קרקע הם בצידי התל וכל התל עצמו, ובזה אין חסרון שלא נראה. אך גדר מחיצות המקום, היינו, גבולותיו, אין זה גוף התל אלא עצם הבדל הגובה, והיינו, שביחס לקרקע במובנה כמקום הנחת חפץ, דין גובה עשרה דמחיצות הוא לא דין בגובה אלא בתפיסת קרקע את אווירה, ובזה אין משמעות אם זה למעלה או למטה ממנה, וגדר מחיצות הוא גדר חיובי, היינו, שנצטרך להגדיר קרקע ע\"י שנגדיר את אווירה, ובזה גדר המחיצה מניעת רגל רבים. אך ביחס להגדרת הקרקע כמקום שימוש אחד, אין המחיצות רק גבולות, ואין למחיצה עצמה משמעות, ובתל יהיה זה הפרש הגובה, והאי דינא דהר\"ן יהיה בחלק זה, היינו, שצריך שיראה את הפרש הגובה. "}, {"s": "h7", "h": "חילוק גדר מחיצה בשבת ובסוכה - פירצה כגבול מול בקיעת גדיים כדין חיובי במחיצה"}, {"s": "p", "h": "ובזה יהיה ההבדל בין מחיצת רה\"י ומחיצת רה\"ר שמחיצת רה\"ר אין לה משמעות רק בהיותה גבול. ובזה יהיה גם ההבדל בין שבת וסוכה לגבי מחיצות ניכרות שיש בדין מחיצת סוכה מה שאין בשבת, דודאי ביחס למחיצה כהגדרת קרקע עצמה שתהיה נפרדת, ובלי שם מקום, שוו דיניהם. אלא שביחס למחיצה כהגדרת מקום הרי יש למקום שלה דיני תקרה, וא\"כ יהיה דין שתהיה גם גבול ביחס לתקרה, וע\"כ צריך שתהיה ניכרת ביחס לסכך, וזה משמעות גוד אסיק. וזה יש לומר גם בגבולות רשות שבת ביחס לתל. וזה הבדל הנמצא בין גדר פירצה לגדר בקיעת גדיים, דפירצה היא דין במחיצה כהגדרה למקום וכגבולותיו, וע\"כ שייך שיהיה בזה דין רוב שזה ביחס למקום שהוא אחד, אך בקיעת גדיים הוא דין במחיצה כהגדרה לקרקע ע\"י אווירה, שזה דין חיובי במחיצה ועל זה לא יועיל רוב. ובזה יבואר גדר היקף לדירה, והיינו, שמדין התורה אין גוף המחיצה למקום, אלא כיון שגזרו חכ' שיהיה מחיצה למקום, היינו, שאף שיהיה מקום מוגדר בגבולותיו, והיינו, שאין בדין מחיצות רק להגדיר קרקע ע\"י אווירה, ואין משמעות במחיצות עצמם לגבי המקום מלבד היותם גבולותיו, כיון שתקנו דינים במקום עצמו, היינו, ביחס לשימוש, והיינו, שיהיה משמעות שימוש גם בהגדרת רה\"י, וזה גזרת מבוי ששימושו נראה כרה\"ר, וזה משמעות יותר מבית סאתים, שאין המחיצות מגדירות את המקום שאין בהם תוך. וזה משמעות כרמלית שלא תובדל מרה\"ר אלא בשימוש. "}, {"s": "h7", "h": "ביאור הגמרא בהכשר מבוי לב\"ש - צורך בלחי וקורה יחד עם ג' מחיצות דאורייתא"}, {"s": "p", "h": "\u003csup class=\"cb\" data-c=\"1161\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">176\u003c/sup>\u003csup class=\"cb\" data-c=\"583\" style=\"--a:#2563eb;--abg:rgba(37,99,235,0.1)\">177\u003c/sup>\u003cspan class=\"ca\" data-c=\"1161 583\" style=\"--a:#15803d;--abg:rgba(21,128,61,0.1)\">וזה ביאור הגמרא בהכשר מבוי דהו\"א דמה דבעי לב\"ש גם לחי וגם קורה זה אינו משום גדר ההכשר, אלא משום דבעי ד' מחיצות, וע\"כ צריך אחד למחיצה ואחד להכשר מבוי, וצריך שניהם. ודחתה הגמ' דזה נצרך לטלטל (ויש להסתפק אם עדיין כל אחד עושה גדר אחר), והיינו, שצריך לחי או קורה אפילו במקום שהוא רה\"י, ואח\"כ שאלה הגמרא דאם צריך לחי או קורה אפילו ברה\"י במה דב\"ה צריכי לחי במבוי סתום, יש לדייק דג' מחיצות דאורייתא, והיינו, שסברה הגמ' דאין מועיל לחי או קורה אלא ברה\"י, וזה דחתה הגמ' דדי בב' מדאורייתא אלא דלטלטל בעינן ג'. והיינו, בהצטרף לחי או קורה. והנה לכאורה סוגיא זו היא בין למ\"ד משום מחיצה ובין למ\"ד משום היכר, ומצאנו דלמ\"ד לחי משום מחיצה מועיל האי לעשות רה\"י, ולא יהיה לחי גדול ממחיצה מעלייתא. אלא בהכרח דעביד תרוויהו, אך לא מועיל אלא במבוי סתום. וכן יש להקשות למ\"ד משום היכר איך יועיל לחי וקורה יחד ומשמע דזה אפשר להגדיר את שימוש הרבים במקום. ובזה יש ללמוד ממי דס\"ל דהאי מחיצות אינם מועילות להגדרת מקום רה\"י, איך ניתן בכל אופן להגדיר את השימוש עצמו, וממילא יועילו המחיצות. וזה משמעות ההבדל בין בקעי בה רבים לבין רה\"ר, דבקעי בה רבים נוגע לשיוך המקום לרה\"ר שמחוץ למקום וזה משמעות בקיעה, אך גדר רה\"ר הוא בעצם השימוש. \u003c/span>"}], "comments": [{"id": "1082", "n": 1, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-285 | סוג: חיבור עצמאי | מקור: קבצים ערוכים להטמעה / ביאורי רש\"י (פרק א חלק ו' במסמך הבדיקה)\u003c/p>\u003cp>כותרת מוצעת בסגנון הכותרות שבקובץ: ביאורי רש\"י למסכת עירובין - דלתות ירושלים, מבוי, פרצה ובקיעה, איסור חצרות (אותיות 26-31, עירובין ו.-צב.)\u003c/p>\u003cp>חלק רביעי של הלקסיקון: ביאורי רש\"י בסוגיות עירובין - נעילת דלתות ירושלים, מבוי ופרצותיו, אתו רבים ומבטלי מחיצתא ואיסור חצרות. מקום השילוב: כנספח לדיון בגדרי הרשויות.\u003c/p>\u003cp>הצעת קטע קישור בפתיחת הקטע: ולביאור הסוגיות יסייעו הביאורים הבאים בדברי רש\"י:\u003c/p>\u003cp>נוסח הקטע בשלימותו:\u003c/p>\u003cp>26. נעילת דלתות בירושלים (עירובין ו.)\u003c/p>\u003cp>\\&gt; רש\"י (עירובין ו.): *\"ירושלים. רשות הרבים שלה מכוון משער לשער ומפולש ויש בה דריסת ששים ריבוא ורחב שש עשרה אמה ואילמלא שנועלין דלתותיה בכל לילה חייבין עליה בשבת משום רה''ר אבל נעילת דלתות משויא לה כחצר של רבים ומערבין את כולה וכל זמן שלא עירבו הויא כרמלית ולא מיחייבי עלה והכי נמי אמרינן בפרק בתרא (ד' קא.) דירושלים כרמלית היא.\"\u003c/p>\u003cp>ביאור: לא נתבאר גדר מה שנחשב זה כחצר של רבים, וכל זמן שלא עירבו הוי כרמלית, דחצר שלא עירבו בה מותר לטלטל בתוכה. ולקמן כתב אבל עכשיו דדלתותיה ננעלות לאו רשות הרבים שאינה כדגלי מדבר, שהוא דרך פתוח כל שעה, והיינו, שלא הועיל דלתות ננעלות, אלא לגבי שלא תהוי רשות הרבים. וקשה דאם נאמר שאין דלתות ננעלות מועילות לעשותה רה\"י (שזה קשה דמשמע דדלתות מהני לכ\"ע), איך יועיל ע\"י עירוב.\u003c/p>\u003cp>ולקמן בסוגיא דעיר של יחיד משמע דאי אינה ט\"ז אמה, והוה של יחיד, מערבין את כולה, דהוי כחצר אחת, ומחיצות שיש סביבה הוי מחיצות, ואין צריך תיקון. אבל אי הוי של רבים, אין מערבין את כולה, אע\"ג דהוי כחצר אחת, דלא תשתכח תורת רשות הרבים. ואי הוה ט\"ז אמה ואית לה דלתות ננעלות, או לר\"י בלחי מכאן ולחי מכאן, אי הוה של יחיד מערבין את כולה דווקא, ולא לחצאין, ואי הוה של רבים והיא של רבים, אין מועיל עירוב, אלא אם כן אית לה פתח אחד בלבד. וברש\"י כאן משמע דדלתות הועילו לירושלים שיהיה אפשר לערב את כולה בלי שיור, והיינו, דאף בעיר של רבים ונעשית של רבים ורוחבה ט\"ז, אי הוה דלתות ננעלות הוה כחצר של רבים, ומשמע שהוא משום שאוסרים זה על זה.\u003c/p>\u003cp>ונראה דזה משום דכיון שלא ניתרת אלא ע\"י שיערבו את כולה, הרי שאוסרים זה על זה וכמו בשיתוף לרב, והיינו, שלא חשיבה למהוי רשות כולם יחד, כיון דלית בה דיורין, והוה רשות כל מבוי ומבוי לבדו, ואוסרים זה על זה. וצ\"ע שלא הזכיר כאן דעת רב.\u003c/p>\u003cp>27. חצר ורחבה ומבוי שנפרץ (עירובין ח:)\u003c/p>\u003cp>\\&gt; רש\"י (עירובין ח:): *\"ומסיים בה\\... רחבה מוקפת ארבע מחיצות: אין צריך כלום\\... סתם רחבה אין בה דיורין לצאת ולבא ואין תשמישה תדיר\\... והוא הדין לחצר שיש בה דיורין וערבו\\... חצר מותרת\\... ומבוי אסור\\... כאן שעירבו כאן שלא עירבו\\... בשלא עירבו\\... בנראה מבחוץ ושוה מבפנים\\...\"\u003c/p>\u003cp>ביאור: והיינו שהבדל יש בין חצר ובין רחבה: או דבחצר אית בה דיורין לצאת ולבוא מבית למבוי, ורחבה אינה אלא לתוכה; וכן דחצר תשמישה תדיר, ורחבה לא, ואפילו נפרץ מבוי לרחבה אינו אסור, דלית ביה דיורין שיאסרו. ושני גדרים אלו -- היינו דאינו לצאת ולבוא, ודאין תשמישה תדיר -- הם בשני פנים:\u003c/p>\u003cp>האחד, משום בית: והיינו דמקום שהוא עשוי לצאת ולבוא יש בו גדר שהוא משמש את הבית, אפילו אין תשמישו תדיר, וכמו במבוי. וע\"כ יש לבני בתים לאסור, והיינו דכיון שבית יש בו גדר שהוא מיוחד לבעליו, ואין אדם דר בבית עם מי שאין דיוריו משותפין עימו, כך כל שימושים המשמשים את הבית יש בהם יתרון אם יהיו מיוחדים שאז יהיה דיורי הבית מיוחדים בשלימות, וחיסרון באם לאו. וע\"כ יש גדר במקום שהוא משמש את הבית, שבני בתים אוסרים אחד על השני, דכיון שיש להם צורך בשימוש מיוחד מחמת בית, וזכות שיש לשני מונעת מהם זה, הרי שיש בשימושם משמעות שמשתמשים בזכותם הפרטית על מקום השימוש ולא בגדר המקום הכללי כמשמש את כולם יחד. וזה גדר \"לצאת ולבוא\".\u003c/p>\u003cp>השני, שאין תשמישה תדיר: הוא כמו גדר דבית עצמו, ומה שאסור להוציא מבית לבית ומותר ממבוי למבוי אף לרבנן; כי לא יהיה גדר במקום המשמש שהוא מיוחד לאחד יותר משאינו מיוחד (חוץ ממה שמשמש בית כדלעיל) אלא במקום שיש בו שימוש תדיר, שאז יהיה צורך שיהיה המקום מיוחד בכדי שלא יימנע זה משימוש מחמת זה. אך במקום שאין שימוש תדיר אין מעלה במה שהוא מיוחד, וע\"כ לא יהיה גדר מי שמשתמש כמשתמש בשלו ויהיה חברו אוסר עליו במה שאין לו זכות במקום כמו במקום שהוא מיוחד רק לו.\u003c/p>\u003cp>וזה הוכיח רש\"י דליתא לשניהם: דאמרינן התם דרחבה לית בה דיורין, והיינו שאין שם מי שיש לו בית שישמש לו המקום כמעבר לרה\"ר; וכן מהא דאין אוסרין בני שביל אבני מבוי שהרי פתוחים לה, והיינו שאם היה בה גדר שתשמישה תדיר אף שאינה עשויה לצאת ולבוא, היה לבני שביל לאסור אבני מבוי כיון שהיא עשויה לשימוש תדיר ויש לבני שביל להשתמש בה ותהא משמשתם שהרי אינה של בני מבוי ויהיו אוסרים. וכן בענייננו לגבי מה דלא תיאסר פירצה שנפרץ מבוי במילואו לרחבה, ומה שאינה אוסרת כשאינה במילואו הוא משום שאינה עשויה לצאת ולבוא, ומה שאינה אוסרת כשהוא פרוץ במילואו הוא משום שהוא מקום המותר לה שהרי לא נחלקו בדיורין שאין שם דיורין כלל.\u003c/p>\u003cp>ודברי רב בחצר תלויים באם עירבו בני חצר עם בני מבוי: דאם עירבו בני חצר עם בני מבוי ואין רשות חצר נפרדת מרשות מבוי, אף שנפרצה אין נפרצה למקום האסור לה, ואף שדיורי החצר במבוי אין אוסרים על בני מבוי שהרי עירבו עימם. אבל אם לא עירבו בני חצר עם בני מבוי, אף שחצר עצמה לא נפרצה ואין לומר שהם נחשבים למקום אחד, עכ\"פ לגבי מה דצריך שיהיה למבוי מחיצה נחשב לפרוץ; והיינו דלגבי מה שנחשב לבני מבוי שמשתמשים במבוי שמשתמשים בשלהם, וכיון שנפרצה אין המבוי מקום נפרד שלהם והוא מחובר למקום שאינו שלהם, וכיון שכן אין להגדיר את המבוי כרשות שלהם, וא\"כ המשתמש במבוי משתמש בשלו, וכיון שאין להגדיר את מקום שימושו כאחד ע\"י השימוש (וכמו ברה\"ר), הרי שטלטול יותר מארבע אמות הוי כמוציא מרשות לרשות.\u003c/p>\u003cp>(והנה לא חילקו בגמרא הא דעירבו ולא עירבו כמו מה שמבואר בגמרא בשבת לגבי איסור מבוי, ואיפכא דבעירבו היינו בני חצר לעצמם, והרי נאסר להוציא מחצר למבוי וממבוי לחצר והוו שתי רשויות, ומבוי רשות שנפרצה למקום האסור לה; ובלא עירבו הווה רשות אחת ולנפרצה למקום המותר לה. דכיון שנפרץ במילואו אף אם לא עירבו הרי בית פתוח למבוי ואיכא לדיורי בית במבוי כמו דאיכא בחצר; ולא דנו שיהיה עירבו יותר סיבה לאיסור במבוי רק משום שנחשב החצר רשות הבית, וממילא הנמצאים שם נחשבים דיורי בית, וכיון שהמבוי משמש את החצר שהיא רשות בית והיא פתוחה לו, הרי שדיורי הבית במבוי ואוסרים בני חצרות זה על זה שאינם משותפין משום חצר כמו בני חצר אחת; וגם אין נחשב המבוי רשות לחצר לבד בלי בתים [וכמו בלא עירבו], דכיון דהחצר רשות הבתים אין חשוב שימוש חצר עצמה להגדיר שימוש במבוי כשימושה שנאמר שיהיה המבוי רשות שלה, דחשיבא דיור בית יותר מדיור חצר שהוא מיוחד ותדיר יותר. אבל בלא עירבו אין החצר רשות בית [וגם אם יבטלו לאחד אין הגדר שהחצר כולה רשות ביתו אלא דכולה רשותו שלו], ואין הדרין בה נחשבים כדרים בבית, ושימוש שלהם במבוי עושה אותה רשות החצר, ורשות חצרות במבוי היא רשות אחת כמו דחצרות רשות אחת. וביאור מה דדיורי בתים יחד במבוי אין בו להגדיר רשות אחת לכולם, הוא משום שדיורי בית הוי מיוחדים לדר, ויהיה משמעות בשימוש דבית במבוי שאין הוא כשימוש של בית, וכיון שמה שאינו מיוחד הוא משום שאר בני מבוי, יש בזה להבדילו משאר בני מבוי, ואין שימושו של זה חלק משימוש כולם, וכן כולם. ואין שליטת החצרות במבוי אחת שיהיה המבוי רשות כל החצרות באחת ושיהיה המבוי רשות אחת לעצמו, וכמו בחצר שאינה מעורבת. ואין לדמותם, דכיון שאין במבוי ארבע מחיצות ואין בו שימוש תדיר אינו חשוב לעשות רשות לעצמו [לעומת חצרות ששולטות עליו ובטל להם]. וכיון שאין בו רשות אין המקום אחד, וכיון דאין המקום אחד כל מקום ומקום חלוק לעצמו, ומעביר ארבע אמות הוי כמרשות לרשות).\u003c/p>\u003cp>וביאור סברת שמואל בנראה מבחוץ ושוה מבפנים: דכיון שאין החצר רגילה במבוי אין להחשיב את המבוי רשות החצר, וגם דיורי החצר אינם אוסרין על בני מבוי כיון שאינם במבוי שיש מחיצה ביניהם; אבל בחצר שרגילה בו הווה המבוי רשות החצר. ושמואל סבר דאין נידון משום שיור, וא\"כ נפרץ המבוי במילואו לחצר, ואף שאין רשות החצר פרוצה לו שנאמר שמקום המבוי אחד עם מקום החצר ואין לעשות שתי רשויות במקום אחד, כיון שהוא פרוץ לה נחשב מקום אחד לגבי דיורי החצר; והיינו שגדר מחיצה רביעית הוא להגדרת המקום כמשמש וזה אין לו מחיצה, וכיון שכן נחשב שמשמש כאחד עם חצר שלידו; ואף שאין לו להיחשב כמשמש את החצר שאינם רגילים בו, כיון שיש בשימוש בו לבני החצרות נפרדות ביחס לדיורי חצר שלידו, הרי שאין הוצאתם לרשות האחת של כולם יחד אלא למבוי שיש לו זכות השתמשות בו, והווה כמוציא מרשות לרשות.\u003c/p>\u003cp>ולשון \"שיור\" שכתב רש\"י היינו גדר נראה מבחוץ וכו' בפס ולחי יחד: שדהא דמהני לחי הוא מכוח מחיצה שלידו דחשיב מחיצה או היכר, ופס הוא מחיצה רביעית; ואף בשני לחיים, שאמנם הוא מכוח מחיצות שבצידו אך עי\"ז חשיב שיש מחיצה בצד רביעי, ואף שאין זה מחיצה למקום עצמו כבר נחשב שיש מחיצה בצד רביעי כיון שהוא חוצץ במקומו בין החוץ לאוויר שכנגדו, וע\"כ יועיל כל עוד תהיה המחיצה הנ\"ל קשורה למקום המבוי אפילו נראה מבחוץ.\u003c/p>\u003cp>28. חצר קטנה שנפרצה לגדולה (עירובין צב.)\u003c/p>\u003cp>\\&gt; רש\"י (עירובין צב.): *\"חצר קטנה שנפרצה. במלואה לגדולה גדולה מותרת ולא אסרי בני קטנה עילויה דלגבי גדולה פתח הוא דיש לה שיור מכאן ומכאן והוו כשתי חצירות ופתח אחד ביניהן דלא אסרן אהדדי\\... וקטנה אסורה. דלדידה לאו פתח הוא אלא פירצה ונעשית רשותן של בני גדולה שהרי נתערבה עמהן.\"\u003c/p>\u003cp>ביאור: ושוב חזינן דדייק רש\"י לומר דהאי חצר נעשית רשות של בני גדולה, והיינו בני החצר הגדולה; ויש בזה גדר כמו שהיתה פתוחה לקטנה ודריסתה עליה.\u003c/p>\u003cp>29. אתי רבים ומבטלי מחיצתא (עירובין יא:)\u003c/p>\u003cp>\\&gt; רש\"י (עירובין יא: / שבת ו:): *\"אי מהתם. מחצר שהרבים נכנסין לה כו' דקתני רשות היחיד לשבת: הוה אמינא. האי דקרי ליה רה''י: לזרוק. כלומר מדאורייתא רה''י הוא והזורק מרה''ר לתוכו חייב: אבל לטלטל. בתוכו: אימא לא. משתריא ומדרבנן דליגזור רבנן עליה: קמ''ל. רב מותרת.\"\u003c/p>\u003cp>ביאור: ומשמע דלא פסקינן כרבי יהודה לגבי אתי רבים ואפילו לטלטל, וכן כתב רש\"י בשבת (ו:).\u003c/p>\u003cp>30. תיקון מבוי בקורה (עירובין יב.)\u003c/p>\u003cp>\\&gt; רש\"י (עירובין יב.): *\"לדברי המתיר. להשתמש תחת הקורה אלמא חיצון יורד וסותם אוסר כל המבוי הזה עד שיביאו קורה אחרת דאין הסתימה מחוברת לכתלים ויש אויר ביניהם והכא לאו מחיצה ממש הוא להכשיר הפסק אויר שמכאן ומכאן ע''י לבוד.\"\u003c/p>\u003cp>ביאור: וזה משום מה דאמרן לעיל, דגדר תיקוני מבוי הוא תיקון שייחשב היקף רשות השימוש באופן הפחות, וע\"כ כתבו רבי ברישא.\u003c/p>\u003cp>31. איסור חצרות וסייג להוצאה (עירובין יב:)\u003c/p>\u003cp>\\&gt; רש\"י (עירובין יב:): *\"חצירות של רבים. שפתוחין בתים הרבה לחצר ואוסרים בני הבתים זה על זה שאין יכולין להוציא מן הבתים לחצר בלא עירוב מפני שהבית רשות מיוחדת לו וחצר רשות חבירו מושל בה ונמצא מוציא מרשות לרשות ורבנן גזור שלא להוציא מרשות היחיד לרשות היחיד גזירה דילמא אתי לאפוקי מרשות היחיד לרשות הרבים אבל בחצר מותר לטלטל בה כדאמרינן במסכת שבת בפ' רבי אליעזר אומר אם לא הביא כלי כו' (ד' קל:).\"\u003c/p>\u003cp>ביאור: ויש להבחין מה שנמצא כאן שלושה חלקים ברש\"י:\u003c/p>"}, {"id": "1083", "n": 2, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-286 | סוג: כותרות חסרות | מקור: גרסאות עדכניות של החיבורים\u003c/p>\u003cp>כותרות תמצית חסרות לקטע זה (3 כותרות, מנוסחות בסגנון כותרות המשנה שבקובץ):\u003c/p>\u003cp>1. מחלוקת ר\"י וחכ' אי רה\"ר מיערבא\u003c/p>\u003cp>2. מחלוקת ר\"י וחכמים אי רשות הרבים מיערבא - הוכחה משתי סוגיות שהמחלוקת בעצם המושג ולא בצורת התיקון\u003c/p>\u003cp>3. הצריך ביאור בנידון מחלוקתם - קושי כיצד יועיל לו\"ק להפוך רה\"ר לרה\"י אם דין הכשר שייך רק ברה\"י\u003c/p>"}, {"id": "487", "n": 3, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0913 | עיר של יחיד שנעשית של רבים – אינה ראיה ישירה למחלוקת אם רשות הרבים מתערבת | חומרה: קריטית לבירור יש להפריד בין סוגיית שני הבתים שבעירובין ו ע״ב/יב ע״ב, שבה נאמר „אין מערבין רשות הרבים בכך” ומבואר שרבי יהודה סובר שתי מחיצות דאורייתא, לבין משנת עיר של יחיד שנעשית של רבים (נט ע״א), העוסקת בעירוב העיר ובשיעור שיור כדי שלא תשתכח תורת רשות הרבים. במשנה זו מחלוקת רבי יהודה ורבי שמעון היא בעיקר בשיעור השיור, ולא מחלוקת מפורשת אם רשות הרבים עצמה ניתנת לעירוב. לכן אין להציג את שתי הסוגיות כראיה שוות־משקל למחלוקת כללית אחת בלי להסביר את הקשר ביניהן.\u003c/p>"}, {"id": "488", "n": 4, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0914 | תשובת הגמרא „התם קסבר רבי יהודה שתי מחיצות דאורייתא” היא נתון יסודי במהלך | חומרה: קריטית לבירור בעירובין יב ע״ב הגמרא מיישבת את שיטת רבי יהודה ב„מי שיש לו שני בתים בשני צידי רשות הרבים” באומרה: „התם קסבר רבי יהודה שתי מחיצות דאורייתא”. זהו הסבר מפורש למקור ההיתר, ואין לדלג עליו לטובת הסבר כללי שלפיו לחי וקורה הופכים רשות הרבים לרשות היחיד. יש לברר אם לשיטת רבי יהודה המקום כבר נחשב רשות היחיד מן התורה מחמת שתי המחיצות, ותיקון הלחי/קורה משלים את ההיתר מדרבנן, או אם המחבר מציע רובד נוסף. ההבחנה מכרעת לשאלה אם מדובר בהכשר מבוי או בשינוי מעמד רשות הרבים.\u003c/p>"}, {"id": "1084", "n": 5, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-287 | סוג: כותרות חסרות | מקור: גרסאות עדכניות של החיבורים\u003c/p>\u003cp>כותרות תמצית חסרות לקטע זה (7 כותרות, מנוסחות בסגנון כותרות המשנה שבקובץ):\u003c/p>\u003cp>1. אי דין תיקון מבוי נאמר כדין תיקון דרה\"י\u003c/p>\u003cp>2. דיוק דברי רש\"י בריש מסכתין והנפק\"מ לגדר תיקון מבוי\u003c/p>\u003cp>3. וכן נראה מדעת רב לאסור טלטול במבוי שאינו משותף\u003c/p>\u003cp>4. וכן משמע מדין מבוי שאינו ראוי לשיתוף\u003c/p>\u003cp>5. דיוק דברי רש\"י בריש מסכתין והנפק\"מ לגדר תיקון מבוי - הבאת מבוי מפולש כדוגמה שאינו רה\"י כלל\u003c/p>\u003cp>6. וכן משמע מהא דאמר רב יהודה - מבוי שאינו ראוי לשיתוף עדיין כרמלית לעניין הכנסה אף שהוכשר בקורה\u003c/p>\u003cp>7. חיזוק היסוד מדין מבוי שאינו ראוי לשיתוף\u003c/p>"}, {"id": "1085", "n": 6, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-288 | סוג: קטע חסר | מקור: 04_רשויות/רשויות.pdf\u003c/p>\u003cp>מיקום השילוב המוצע: לאחר הפסקה שלפני הערה זו (\"ב. במשמעות תיקוני מבוי להגדיר הרשות...\").\u003c/p>\u003cp>הקטע משתלב כאן כהמשך ישיר לדברים שלפניו; אין צורך בקטע קישור.\u003c/p>\u003cp>נוסח הקטע:\u003c/p>\u003cp>אי דין תיקון מבוי נאמר כדין תיקון דרה\"י\u003c/p>\u003cp>וכן משמע מהא דאמר ר\"י\u003c/p>"}, {"id": "489", "n": 7, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0915 | היתר בכרמלית – להבחין בין תיקון מבוי לבין שינוי מעמד הרשות | חומרה: גבוהה ההבחנה בין „לחי משום מחיצה” ל„קורה משום היכר” אכן נידונה בעירובין יב ע״ב, ושם נאמר במבוי שאינו ראוי לשיתוף שהזורק לתוכו חייב אם הוכשר בלחי ופטור אם הוכשר בקורה. אולם אין להסיק מכך שכל כרמלית נעשית מותרת בטלטול על ידי קורה, או שההיתר אינו קשור כלל למעמד המקום. הסוגיה עוסקת במבוי מסוים שאינו ראוי לשיתוף, ובשאלה אם תיקון הלחי/קורה יוצר רשות היחיד לעניין חיוב זריקה. יש להגדיר מהו בדיוק „הותרה לטלטול” כאן: היתר טלטול מדרבנן בתוך המבוי, פטור מחיוב תורה על זריקה, או שינוי שם הרשות.\u003c/p>"}, {"id": "1086", "n": 8, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-289 | סוג: קטע חסר | מקור: 04_רשויות/רשויות.pdf\u003c/p>\u003cp>מיקום השילוב המוצע: לאחר הפסקה שלפני הערה זו (\"וכן משמע בהקדמת רש\"י לדין המשנה בריש מסכתין, דכתב דהאי מבוי איירי במקום שאינו חשיב רה\"ר, וכמו דמבוי שאינו רחב ...\").\u003c/p>\u003cp>הקטע משתלב כאן כהמשך ישיר לדברים שלפניו; אין צורך בקטע קישור.\u003c/p>\u003cp>נוסח הקטע:\u003c/p>\u003cp>יבאר בזה לשון עירוב רה\"ר\u003c/p>\u003cp>ויבואר יסוד מח' ר\"י וחכ' בתיקון לו\"ק ביחס להגדרת השימוש\u003c/p>\u003cp>היוצא מהנ\"ל שני גדרים במקום לעניין הכשרו בלו\"ק\u003c/p>"}, {"id": "490", "n": 9, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0916 | ראיית רש״י מריש המסכת – להבחין בין מבוי סתום למבוי מפולש | חומרה: בינונית-גבוהה הדיוק מרש״י בריש המסכת עשוי לחזק את הטענה שתיקון קורה אינו זהה ליצירת רשות היחיד, אך יש לציין במדויק לאיזה מבוי רש״י מתייחס: מבוי סתום בעל שלוש מחיצות, או מבוי מפולש הפתוח משני צדדיו. אין להשליך מן העובדה שהמשנה עוסקת במבוי שאינו רשות הרבים על כל מבוי מפולש, שבו נדרשת צורת הפתח בצד אחד ולחי או קורה בצד האחר. מומלץ להביא את לשון רש״י בשלמותה ולהעמיד את שני המקרים בנפרד.\u003c/p>"}, {"id": "491", "n": 10, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0917 | „מבוי שאינו ראוי לשיתוף” – פטור מזריקה אינו קביעה מפורשת שהוא כרמלית | חומרה: גבוהה המקור הוא עירובין יב ע״ב: „מבוי שאינו ראוי לשיתוף, הכשירו בלחי – הזורק לתוכו חייב; הכשירו בקורה – הזורק לתוכו פטור”. רש״י מפרש את המבוי שאינו ראוי לשיתוף כמבוי מפולש. מכאן עולה שקורה אינה יוצרת את המחיצה הנדרשת לחיוב רשות היחיד, אבל „פטור” על זריקה אינו כשלעצמו הגדרה מלאה של המקום ככרמלית לכל דיני טלטול והכנסה. יש להבחין בין פטור מחטאת/חיוב תורה, איסור טלטול מדרבנן, ושם הרשות. אם מבקשים להסיק כרמלית, יש להביא את המקור שמגדיר זאת ולא להסתפק בלשון „פטור”.\u003c/p>"}, {"id": "1087", "n": 11, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-290 | סוג: קטע חסר | מקור: 04_רשויות/רשויות.pdf\u003c/p>\u003cp>מיקום השילוב המוצע: לאחר הפסקה שלפני הערה זו (\"וכן נראה מדין טלטול במבוי שאינו משותף דס\"ל לרב דאסור (לדעת מי שאינו סובר כרש\"י דהוא בכלי בית), דקשה א\"כ מה הוע...\").\u003c/p>\u003cp>הקטע משתלב כאן כהמשך ישיר לדברים שלפניו; אין צורך בקטע קישור.\u003c/p>\u003cp>נוסח הקטע:\u003c/p>\u003cp>דיוק דברי רש\"י בריש מסכתין והנפק\"מ לגדר תיקון מבוי\u003c/p>\u003cp>וכן נראה מדעת רב לאסור טלטול במבוי שאינו משותף\u003c/p>"}, {"id": "492", "n": 12, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0918 | שיתוף מבוי והכשר קורה – שני תנאים שונים ולא בהכרח שתי רשויות | חומרה: גבוהה ההבחנה בין תיקון הלחי/קורה לבין שיתוף מבואות נכונה כנקודת מוצא: שיתוף מסדיר את היחסים בין הדיורים, ואילו לחי וקורה הם תיקון הפתח. אך אין להסיק מכך שהכשר המבוי „אינו ענין להיתר טלטול” כלל; הוא תנאי אחד בהיתר, והשיתוף תנאי נוסף במקום שבו הוא נדרש. העובדה שמבוי מתוקן אך לא משותף עדיין אסור בטלטול אינה מוכיחה שההכשר אינו נוגע לטלטול, אלא שאין בו לבדו כדי להשלים את כל תנאי ההיתר. כדאי לנסח את ההבחנה כחלוקת תפקידים בין שני דינים, לא כניתוק מוחלט ביניהם.\u003c/p>"}, {"id": "1088", "n": 13, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-291 | סוג: כותרות חסרות | מקור: גרסאות עדכניות של החיבורים\u003c/p>\u003cp>כותרות תמצית חסרות לקטע זה (9 כותרות, מנוסחות בסגנון כותרות המשנה שבקובץ):\u003c/p>\u003cp>1. משמעות לישנא דעירוב רשות הרבים - שייכת לרשות הילוך ולא לעצם גדרי מקום דרה\"י\u003c/p>\u003cp>2. ויבואר יסוד מח' ר\"י וחכ' בתיקון לו\"ק ביחס להגדרת השימוש\u003c/p>\u003cp>3. היוצא מהנ\"ל שני גדרים במקום לעניין הכשרו בלו\"ק\u003c/p>\u003cp>4. שייכות לשון עירוב אתיקון לו\"ק ושייכות התיקון בכרמלית\u003c/p>\u003cp>5. שורש המחלוקת באי יש בלו\"ק להגדיר מחדש משמעות השימוש במקום\u003c/p>\u003cp>6. שני גדרי מקום ואופני הכשרתם בלו\"ק לר\"י\u003c/p>\u003cp>7. ביאור שם עירוב אתיקון לו\"ק ודמהני הכשר לו\"ק בכרמלית\u003c/p>\u003cp>8. יבואר בזה לשון עירוב רה\"ר - שייכת רק לגדרה כרשות הילוך ולא לעצם חסרון גדרי מקום דרה\"י\u003c/p>\u003cp>9. ויבואר יסוד מח' ר\"י וחכ' בתיקון לו\"ק ביחס להגדרת השימוש - חילוק בין הגדרת מקום להגדרת שימוש\u003c/p>"}, {"id": "493", "n": 14, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0919 | לשון „עירוב רשות הרבים” – לעמוד על תיקון הגמרא ולא רק על המונח | חומרה: גבוהה בעירובין ו ע״ב נשאל „אין מערבין רשות הרבים בכך”, ובהמשך רב יהודה מפרש: „כיצד מערבין מבואות המפולשין לרשות הרבים – עושה צורת הפתח מכאן ולחי וקורה מכאן”. כלומר, נוסח המסקנה מדבר על מבואות הפתוחים לרשות הרבים, ולא על עירוב רשות הרבים עצמה באמצעות לחי וקורה. לכן ההצעה לקרוא „עירוב רשות הרבים” כגדר כללי של חיבור רשויות היא חידוש מושגי, אך אין להציג זאת כפשט לשון הברייתא או הגמרא. כדאי להבחין בין לשון השאלה, תיקון רב יהודה, והמשמעות העיונית שהמחבר מבקש לחדש.\u003c/p>"}, {"id": "1089", "n": 15, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-292 | סוג: קטע חסר | מקור: 04_רשויות/רשויות.pdf / 08_הקדמות_והצעות_נוסח/תוכניות להטמעת קטעים.txt\u003c/p>\u003cp>מיקום השילוב המוצע: לאחר הפסקה שלפני הערה זו (\"ובזה נחלקו ר\"י וחכ' ברה\"ר אי מיערבא או לא. דר\"י סבר דכיון דיש בלחי וקורה להגדיר מקום בצורתו יש לו להגדיר גם מש...\").\u003c/p>\u003cp>הקטע משתלב כאן כהמשך ישיר לדברים שלפניו; אין צורך בקטע קישור.\u003c/p>\u003cp>נוסח הקטע:\u003c/p>\u003cp>הערת עריכה: המשפט המובא הוא היחיד בכל האוסף שנדרש בו חיתוך-קטע (לא ניסוח מחדש). הפסקה המקורית (כותרת 7 מס' 567) פותחת בבירור מחלוקת ר\"י וחכמים בעניין עירוב רה\"ר, ורק בהמשכה (מהמילה \"נמצא\") עוברת לניסוח הכללי המובא כאן. סימנתי בתחילת הציטוט [...] במקום תחילת המשפט המקורי \"ובזה נחלקו ר\"י וחכ' ברה\"ר אי מיערבא או לא... וביאורו בהקדם משנ\"ת במק\"א באריכות ד\" - שכולו רקע להצגת המחלוקת הספציפית. מנקודת [...] ואילך, הציטוט מדויק ומילולי לחלוטין ללא שום שינוי.\u003c/p>\u003cp>C2. רה\"י מוגדרת בקרקעה הנפרדת; רה\"ר מוגדרת בשימושה (ותקנת חכמים ביחס לחלל)\u003c/p>"}, {"id": "494", "n": 16, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0920 | מחלוקת רבי יהודה וחכמים – להפריד בין שלוש שאלות הלכתיות | חומרה: קריטית לבירור המהלך מזהה מחלוקת כללית בשאלה אם רשות הרבים „מיערבא”, אך בסוגיות מצויות כמה שאלות נפרדות: האם שתי מחיצות יוצרות רשות היחיד מן התורה (עירובין יב ע״ב); האם ניתן לתקן מבואות המפולשים לרשות הרבים; והאם עיר של רבים זקוקה לשיור כדי שלא תשתכח תורת רשות הרבים (נט ע״א). אין הכרח שכל אלה מחלוקת אחת של רבי יהודה וחכמים. בפרט, סוגיית יב ע״ב תולה את היתר רבי יהודה בשתי מחיצות דאורייתא. מומלץ למפות את הדעות לכל שאלה בנפרד לפני שמעמידים את כולן על ציר מושגי אחד.\u003c/p>"}, {"id": "495", "n": 17, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0921 | שתי שכבות ההגדרה – לא לייחס לגמרא חלוקה שאינה מפורשת בה | חומרה: גבוהה החלוקה בין הגדרת המקום מצד צורתו לבין הגדרתו מצד שימוש הרבים היא מסגרת מושגית של המחבר. היא עשויה ליישב מקורות שונים, אך יש להציג אילו נתונים מפורשים בגמרא ואילו נובעים מן המודל. בפרט, „שתי מחיצות דאורייתא” בעירובין יב ע״ב הוא נתון בסוגיה, ואילו ההבחנה בין צורת המקום לבין שימושו אינה נאמרת שם בלשון זו. כדאי לציין שההבחנה היא כלי פרשני להסביר את היחס בין שני דיני המחיצות והכשר המבוי, ולא מסקנה מפורשת של רבי יהודה או של חכמים.\u003c/p>"}, {"id": "496", "n": 18, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0922 | הכשר בכרמלית – לא להרחיב ממבוי מסוים לכל כרמלית | חומרה: גבוהה העובדה שתיקון מבוי מועיל גם במקום שאינו רשות היחיד מן התורה אינה מוכיחה שכל כרמלית ניתנת לתיקון בלחי וקורה. תקנת מבוי נאמרה במבנה שיש לו גדרי מבוי ופתח, ובו קיים חשש החלפה ברשות הרבים; אין זה דין כללי בכל שטח כרמלית. כדאי להגדיר מהו המקרה המדויק שעליו נסמך החידוש, ולהבחין בין „כרמלית” כשם רשות לבין „מבוי שאינו ראוי לשיתוף” שבסוגיית יב ע״ב. כך לא תיווצר הכללה רחבה יותר ממה שהמקורות מוכיחים.\u003c/p>"}, {"id": "1090", "n": 19, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-293 | סוג: כותרות חסרות | מקור: גרסאות עדכניות של החיבורים\u003c/p>\u003cp>כותרות תמצית חסרות לקטע זה (7 כותרות, מנוסחות בסגנון כותרות המשנה שבקובץ):\u003c/p>\u003cp>1. גדר גזירת מבוי משום שימוש דמבוי דומה לשימוש דרה\"ר ולזה מהני תיקון דלו\"ק\u003c/p>\u003cp>2. ביאור מעליותא דדלתות ננעלות ושהביאוה מדר\"י\u003c/p>\u003cp>3. ובזה יבואר מה דפשיטא ליה לגמ' (עירובין ו:) דמהני לחכ' בזה דלתות ננעלות ולא מהני דלתות שאינם ננעלות, שאין למצוא בזה שינוי גדר ביחס לדלת עצמה, כי איך יהיה זה דין בדלת, ומשום נעילה עצמה, אחר דביום אין נעולות. ולפמשנ\"ת י\"ל דהיינו מעליותא דאית בננעלות, ביחס להגדרת השימוש במקום, שדלתות ננעלות בלילה חשיבי להגדיר את גדר השימוש במקום עצמו.\u003c/p>\u003cp>4. ובזה יבואר מה דפשיטא ליה לגמ' דמהני לחכ' בזה דלתות ננעלות ולא מהני דלתות שאינם ננעלות, שאין למצוא בזה שינוי גדר ביחס לדלת עצמה, כי איך יהיה זה דין בדלת, ומשום נעילה עצמה, אחר דביום אין נעולות. ולפמשנ\"ת י\"ל דהיינו מעליותא דאית בננעלות, ביחס להגדרת השימוש במקום, שדלתות ננעלות בלילה חשיבי להגדיר את גדר השימוש במקום עצמו.\u003c/p>\u003cp>5. הביאור בהנ\"ל - איסור העברה ברה\"ר הוא דין ברשות המחייב הגדרה גם לחלל המבוי מלבד קרקעו\u003c/p>\u003cp>6. יבואר בזה גדר דלתות ננעלות - חילוק בין נעילה עצמה להגדרת שימוש המקום כשימוש הרבים\u003c/p>\u003cp>7. חילוק מהותי בין לחי וקורה לשאר מחיצות\u003c/p>"}, {"id": "497", "n": 20, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0923 | איסורי כרמלית – להבחין בין טלטול בתוכה להעברה ממנה ואליה | חומרה: גבוהה בשבת ו ע״א נמנים בנפרד האיסור לשאת ולתת בתוך הכרמלית והאיסור להוציא ממנה לרשות הרבים או להכניס ממנה לרשות היחיד. שניהם מדרבנן, אך אין די בכך כדי לקבוע שהם „בגדר אחד” במובן המושגי שאתה מציע. יש להראות מהו הצד המשותף המדויק: דמיון לרשות הרבים, גזירת החלפה, או הגדרת חלל. כמו כן, אין לומר בפשטות שהכרמלית אינה חסרה מתנאי המקום של רשות הרבים: היא מוגדרת דווקא במאפיינים החסרים בה דין רשות הרבים גמורה. מומלץ להפריד בין לשון הברייתא, טעם הגזירה, והמודל המחודש של המחבר.\u003c/p>"}, {"id": "1091", "n": 21, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-294 | סוג: הערת שוליים | מקור: שמעתתא דרשות הרבים ומבטלי מחיצתא, שמעתתא עותק 1 (הערת שוליים 3)\u003c/p>\u003cp>נושא ההערה: שלושה חילוקים בדין דלתות נעולות - דלת או דלתות, נעולה או שאינה נעולה; נכתבה על שיטת רש\"י שבעניין דלתות נעולות.\u003c/p>\u003cp>נכתבה במקור כהערת שוליים על: א] באמת דלת אחת לא מועילה אפי' אם נעולה אלא צריך ב' דלתות, ומוכרח דס\"ל שדלת נעולה אינה 'מחיצה', ורק בשתים מהני, וטעם הדבר כתב לקמן (דף קא. ד\"ה חייבין עליה) משום דלא דמיא לדגלי מדבר שהוא דרך פתוח כל שע\u003c/p>\u003cp>נוסח ההערה:\u003c/p>\u003cp>הנה יל\"ע אי קאי גם למסקנא, ואין מוכרח. ובאמת דיש לדקדק בלה\"ק שכ' וז\"ל חייבין עליה כו'. אלמא נעילת דלתות בעינן בכל לילה והכא קתני עושה דלת מכאן ולחי וקורה מכאן לבית הלל. ע\"כ. דהא יש למצוא בזה שלושה חילוקים, אחד, דלת או דלתות, השני, ננעלת או שאינה ננעלת, השלישי, דלתות ננעלות או דלת שאינה ננעלת, היינו, ודליתא למעליותא דננעלת אלא בב' דלתות (וזה יש לומר אף לצד דצריך לנעול, היינו, דבב' ננעלות אאחת ננעלת איכא מעליותא הן ביחס לב' דלתות אדלת אחת (או מטעם מספר הדלתות (וכדאמרו בב' ג' וד' מחיצות), או מטעם שלימות ההיקף) והן ביחס לנעילה עצמה שהיא נעילה מעולה יותר (ביחס להיות הנעילה עושה את הרשות נעולה). והנה מאחר דדדלת דחנניא אי בעינן ננעלת הוא בעיא לק', לא מסתבר דיהא מקשה בזה. ולכן היותר נראה דכוונתו לחילוק השלישי.\u003c/p>"}, {"id": "1092", "n": 22, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-295 | סוג: הערת שוליים | מקור: שמעתתא דרשות הרבים ומבטלי מחיצתא, שמעתתא עותק 5 (הערת שוליים 1)\u003c/p>\u003cp>נושא ההערה: רש\"י הקשה בתרתי - בעי תרי דלתות ובעי נעילה; נכתבה על הדיון בדברי רש\"י בדלתות.\u003c/p>\u003cp>נכתבה במקור כהערת שוליים על: בתוס' ד\"ה והאמר רבה כו'. יש כאן שתי מהלכים בגמ'. האחד הוא דעת רש\"י שהמקשן שואל על זה שבית הלל מתירים בלחי וקורה ברוח רביעית והרי בר' יוחנן מבואר שצריך גם שם דלת, וע\"ז אומרים תוס' שמזה שמצריך ריו\"ח נעי\u003c/p>\u003cp>נוסח ההערה:\u003c/p>\u003cp>אמנם מדברי רש\"י עצמו י\"ל דהקשו בתרתי דבעי תרי דלתות ודבעו נעילה (ולבאר סתימת הדברים י\"ל דפשיטא ליה לרש\"י דליכא למעליותא דנעילה אי לאו בתרי דלתות).\u003c/p>"}, {"id": "1093", "n": 23, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-296 | סוג: הערת שוליים | מקור: שמעתתא דרשות הרבים ומבטלי מחיצתא, שמעתתא עותק 5 (הערת שוליים 2)\u003c/p>\u003cp>נושא ההערה: אם יש הכרח שתוס' הקשו על המקשן; נכתבה על פירוש הגמרא בדברי תוס'.\u003c/p>\u003cp>נכתבה במקור כהערת שוליים על: ותוס' שואלים לפי רש\"י מה הקושיא הלא לב\"ה סגי בג' מחיצות מדאורייתא לעשות רה\"י, ודלת נמי הוי מחיצה, ומתרצים דדלת לא הוי מחיצה גמורה ולכן רק אם יהיה שתי דלתות יועיל. וצ\"ב מה החסרון בדלת, ואיך שתי דלתות מ\u003c/p>\u003cp>נוסח ההערה:\u003c/p>\u003cp>אין למצוא בדברי תוס' הכרח דהקשו אמקשן (אמנם בתוס' הרא\"ש אכן וכו').\u003c/p>"}, {"id": "1094", "n": 24, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-297 | סוג: הערת שוליים | מקור: שמעתתא דרשות הרבים ומבטלי מחיצתא, שמעתתא עותק 5 (הערת שוליים 3)\u003c/p>\u003cp>נושא ההערה: הצעת נוסח מתוקן לדברי תוס' במה מועילות שתי דלתות; נכתבה על הקושיא מה מועילות שתי דלתות.\u003c/p>\u003cp>נכתבה במקור כהערת שוליים על: ותוס' שואלים לפי רש\"י מה הקושיא הלא לב\"ה סגי בג' מחיצות מדאורייתא לעשות רה\"י, ודלת נמי הוי מחיצה, ומתרצים דדלת לא הוי מחיצה גמורה ולכן רק אם יהיה שתי דלתות יועיל. וצ\"ב מה החסרון בדלת, ואיך שתי דלתות מ\u003c/p>\u003cp>נוסח ההערה:\u003c/p>\u003cp>אולי יותר נכון לומר \"וכן צ\"ב מה מהני תרי דלתות, בין אי נימא דמהנו לגופייהו כתרי דלתות, ובין אי נימא דמהני להאי דלת דמחיצה שלישית, אחר דאית בכל חד האי חסרון\"\u003c/p>"}, {"id": "1095", "n": 25, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-298 | סוג: קטע חסר | מקור: 08_הקדמות_והצעות_נוסח/הצעות נוסח להקדמה - נושא הרשויות.docx\u003c/p>\u003cp>מיקום השילוב המוצע: לאחר הפסקה שלפני הערה זו (\"ובזה יבואר מה שפשוט לגמרא שגדר דלתות ננעלות שונה מגדר דלתות שאינם ננעלות, כי אין זה דין בדלת משום נעילה עצמה ד...\").\u003c/p>\u003cp>הקטע משתלב כאן כהמשך ישיר לדברים שלפניו; אין צורך בקטע קישור.\u003c/p>\u003cp>נוסח הקטע:\u003c/p>\u003cp>דקדוק לישנא דברייתא\u003c/p>\u003cp>חילוק מח' ר\"י וחכ' באי רה\"ר מיערבא ממח' באתי רבים\u003c/p>"}, {"id": "498", "n": 26, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0924 | דלתות ננעלות – לא לשלול את תפקידן כמניעת מעבר בפועל | חומרה: גבוהה בעירובין ו ע״ב מובאת ירושלים כדוגמה למקום שהיה חייב עליו משום רשות הרבים אלמלא דלתותיה ננעלות בלילה, וכן אבולי מחוזא. הנתון המפורש בסוגיה הוא נעילת השערים; אין בה אמירה מפורשת שהנעילה אינה פועלת כמחיצה או כמניעת רגל רבים, אלא רק כהגדרה מופשטת של סוג השימוש. אפשר להציע שהנעילה משנה את זיקת השימוש בין פנים העיר לחוץ, אך יש להציג זאת כביאור המחבר ולא כמסקנת הגמרא. כדאי גם להבחין בין דלתות ננעלות, דלתות הראויות להינעל, וצורת הפתח.\u003c/p>"}, {"id": "1096", "n": 27, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-299 | סוג: הערת שוליים | מקור: שמעתתא דרשות הרבים ומבטלי מחיצתא, שמעתתא עותק 5 (הערת שוליים 7)\u003c/p>\u003cp>נושא ההערה: גדר לחי וקורה הנצרכים לרבי יהודה; נכתבה על הדיון בחילוק תיקון דלו\"ק מדין מחיצה.\u003c/p>\u003cp>נכתבה במקור כהערת שוליים על: בתוד\"ה וכי תימא. וצ\"ל לפי זה כו'. י\"ל שהפשט בתוס' הוא כך, שבהלכות לחי וקורה מצינו שעד י\"ג ושליש מהני ויותר מזה לא, והיינו כי עד י\"ג ושליש לא הוי פירצה ויותר מזה הוי פירצה, והיינו שזה חסרון בהמחיצות , \u003c/p>\u003cp>נוסח ההערה:\u003c/p>\u003cp>לכאורה הוא הוא גדר לו\"ק הנצרכים לרבי יהודה (ויותר י\"ל כן לדעת רש\"י דדקדק הכא ובגמ' שבת דבעינן שיהו הלחיים שמכאן ומכאן באותו הצד), ובפרט אי נימא דבעינן ללחו\"ק מדאורייתא (וכדבעו כמה אחרונים למימר בסוגיא דגשרים (צה.).\u003c/p>"}, {"id": "1097", "n": 28, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-300 | סוג: כותרות חסרות | מקור: גרסאות עדכניות של החיבורים\u003c/p>\u003cp>כותרות תמצית חסרות לקטע זה (10 כותרות, מנוסחות בסגנון כותרות המשנה שבקובץ):\u003c/p>\u003cp>1. דקדוק לישנא דברייתא במילת בכך - כוונת חכמים להגדרת מקום ולא להגדרת שימוש בדלתות\u003c/p>\u003cp>2. חילוק מח' ר\"י וחכ' באי רה\"ר מיערבא ממח' באתי רבים\u003c/p>\u003cp>3. שני משמעויות שימוש ביחס להגדרת מקום\u003c/p>\u003cp>4. חילוק גדר שימוש הנוגע לרשויות דאורייתא משימוש דאינו אלא מגזירת חכמים\u003c/p>\u003cp>5. חילוק מחלוקתם בעירוב רה\"ר מאי אתי רבים וכו'\u003c/p>\u003cp>6. שני גדרי מחיצה - מחיצת צד ומחיצה מקום\u003c/p>\u003cp>7. בהבדל לו\"ק משאר מחיצה - הוכחה מדחיית הגמ' שאין ב' מחיצות דר\"י מועילות בלי לחי וקורה\u003c/p>\u003cp>8. שני משמעויות שימוש ביחס להגדרת מקום - חילוק בין מחיצות המגדירות מקום נפרד לתיקון המגדיר שימוש\u003c/p>\u003cp>9. דקדוק לישנא דברייתא - כוונת חכמים בלשון בכך היא הגדרת מקום ולא הגדרת שימוש אף בדלתות\u003c/p>\u003cp>10. חילוק מח' ר\"י וחכ' באי רה\"ר מיערבא ממח' באתי רבים - נפרדות נושא הכשר מבוי מנושא ביטול מחיצה\u003c/p>"}, {"id": "1098", "n": 29, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-301 | סוג: קטע חסר | מקור: 04_רשויות/רשויות.pdf\u003c/p>\u003cp>מיקום השילוב המוצע: לאחר הפסקה שלפני הערה זו (\"ואחר העיון נראה שזה סיבת שינוי בין הכשר מבוי למחיצות, דהרי אנן ס\"ל כאביי דלחי משום מחיצה, וא\"כ אמאי לא מודו חכ...\").\u003c/p>\u003cp>הקטע משתלב כאן כהמשך ישיר לדברים שלפניו; אין צורך בקטע קישור.\u003c/p>\u003cp>נוסח הקטע:\u003c/p>\u003cp>חילוק גדר מחיצת צד ממחיצת מקום לענין הגדרת מקום שימוש\u003c/p>\u003cp>גדר בקיעה השייך בהנ\"ל\u003c/p>"}, {"id": "499", "n": 30, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0925 | „אנן ס״ל כאביי” – לברר את מעמד שיטת אביי מול רבא | חומרה: קריטית לבירור בעירובין יב ע״ב נאמר במפורש: אביי ורבה סוברים „לחי משום מחיצה וקורה משום היכר”, ואילו רבא סובר „אחד זה ואחד זה משום היכר”. לכן המשפט „אנן ס״ל כאביי” דורש מקור הלכתי או הגדרה מדויקת: האם כוונתך להנחת הסוגיה המקומית, לשיטה מסוימת בראשונים, או לפסק ההלכה? אין להציג את שיטת אביי כעמדה מוסכמת בלי בירור, ובפרט כשהגמרא מביאה מיד את מחלוקת רבא. ההבחנה מכרעת לכל המהלך שמבקש לבנות על לחי כמחיצה.\u003c/p>"}, {"id": "500", "n": 31, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0926 | „הכשר המגדיר שימוש” לעומת „מחיצה המגדירה מקום” – לסמן כחידוש | חומרה: גבוהה החלוקה בין מחיצות היוצרות מקום נפרד לבין תיקון מבוי המגדיר „שימוש מסוים” אינה לשון מפורשת בעירובין יב ע״ב. בסוגיה נאמרים דיני לחי וקורה, מחיצה והיכר, ושתי מחיצות דאורייתא; מכאן אתה בונה מסגרת מושגית רחבה יותר. המסגרת עשויה להיות מועילה, אך יש לסמן במפורש היכן מסתיים תיאור המקורות והיכן מתחיל המודל. רצוי להגדיר מהו „שימוש מסוים” מבחינה הלכתית, ואיזה דין מעשי משתנה בעקבות ההגדרה, כדי שהמונח לא יישאר מטפורה בלבד.\u003c/p>"}, {"id": "501", "n": 32, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0927 | דיוק „בכך” – לעגן בנוסח המלא ובתיקון רב יהודה | חומרה: גבוהה הביטוי „אין מערבין רשות הרבים בכך” מופיע בברייתא בעירובין ו ע״ב, אך רב יהודה מפרש את לשונה: „כיצד מערבין מבואות המפולשין לרשות הרבים – עושה צורת הפתח מכאן ולחי וקורה מכאן”. לכן אין לבסס את החידוש רק על המילה „בכך” בלי להביא את תיקון הסוגיה ואת ההקשר. אם כוונתך לטעון שהמילה מלמדת על הגדרת מקום ולא על תיקון מסוים, זהו דיוק מחודש שיש להצדיקו מול פירוש רב יהודה, ולא פשט מוסכם של הברייתא.\u003c/p>"}, {"id": "502", "n": 33, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0928 | עירוב רשות הרבים ו„אתי רבים” – ההפרדה אפשרית, אך טעונה מפת מקורות | חומרה: קריטית לבירור ההבחנה בין מחלוקת הכשר המבוי לבין דין „אתי רבים ומבטלי מחיצתא” אכן עשויה להיות מפתח למהלך, אך יש להעמיד מולה את רצף הסוגיות: בעירובין כ ע״א נידונים פסי ביראות ובקיעת רבים; בעירובין כב ע״א משווים את מחלוקת רבי יהודה וחכמים בברייתת שני הבתים למחלוקתם בפסי ביראות; ובעירובין ו ע״ב נידונות דלתות ירושלים והכשר מבואות. אין להניח מראש שהמחלוקות נפרדות לחלוטין או זהות לחלוטין. מומלץ למפות מה נאמר בכל מקור ומהו הגשר הפרשני שאתה מציע.\u003c/p>"}, {"id": "1099", "n": 34, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-302 | סוג: כותרות חסרות | מקור: גרסאות עדכניות של החיבורים\u003c/p>\u003cp>כותרות תמצית חסרות לקטע זה (10 כותרות, מנוסחות בסגנון כותרות המשנה שבקובץ):\u003c/p>\u003cp>1. חילוק גדר מחיצת צד ממחיצת מקום לענין הגדרת מקום שימוש\u003c/p>\u003cp>2. גדר סך כל המחיצות שהוא נובע מגדרי המקום\u003c/p>\u003cp>3. יסוד מח' ר\"י וחכ' בפסי ביראות ע\"פ הנ\"ל\u003c/p>\u003cp>4. שורש מחלוקת אי אתי רבים וכו' בהגדרת מקום\u003c/p>\u003cp>5. שתי מחיצות כיצירת מקום שלם לשיטת ר\"י\u003c/p>\u003cp>6. ביאור היכי בעו לאוכחי מיניה דר\"י דלו\"ק משום מחיצה\u003c/p>\u003cp>7. גדר בקיעה השייך בהנ\"ל - שימוש הרבים בעצם היותם מגדיר את המקום כאינו נפרד ביחס לכל צד\u003c/p>\u003cp>8. גדר סך כל המחיצות שהוא נובע מגדרי המקום - שם אחד לכלל המחיצות שאין שימוש הרבים יכול לבטלו\u003c/p>\u003cp>9. יסוד מח' ר\"י וחכ' בפסי ביראות ע\"פ הנ\"ל - אין גדר פסים כגדר מקום אלא משום השימוש שיש בהם\u003c/p>\u003cp>10. ד' שלבים בהיתר הנ\"ל - מרה\"ר גמורה לנפרד ע\"י לו\"ק לביטול הבקיעה למחיצות טובות שאינן בטלות\u003c/p>"}, {"id": "1100", "n": 35, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-303 | סוג: קטע חסר | מקור: 01_גרסאות_הספר/הקדמות וכללים - רשויות - הוצאה - עירובין - תחומין.docx / 01_גרסאות_הספר/מקום בינה.txt / 04_רשויות/רשויות.pdf\u003c/p>\u003cp>מיקום השילוב המוצע: לאחר הפסקה שלפני הערה זו (\"ו. במשמעות מחיצות להיות גדר במקום...\").\u003c/p>\u003cp>הקטע משתלב כאן כהמשך ישיר לדברים שלפניו; אין צורך בקטע קישור.\u003c/p>\u003cp>נוסח הקטע:\u003c/p>\u003cp>והנה, צורת פסין שתי סתימות בקצה כל רוח וחיבורן ע\"י דיומדין, ועניין מחיצה הפרדה, ומערכתם הגדרת מקום נפרד ורשות מיוחדת, להבדיל ולייחד מרחב (שטח ורומו, ולהבדיל משטח לבדו עי' ירו' כל' פ\"ב ה\"ו). ובאמת שהנדרש הוא הייחוד לבד (ורמז לזה גזוזטרא), והעירוב חיסרון, וההבדל מכמה פנים יבטל העירוב ויבוא הייחוד, והעירוב הוא מד' פנים (משום דהוו ד' רוחות או בהיפך המסובב ושמטעמם יהיו הרוחות ד').\u003c/p>\u003cp>וא\"כ יש לומר שדין ג' מחיצות דאורי' ולא ד' הוא גדר בהייחוד (שהיחוד עניין פנימי לרשות, והפרד העירוב יחסי לחוץ ולהבדל).\u003c/p>\u003cp>כותרת 7 מספר 268 - ביאור גדר פסין כמחיצות מקום והיותם בד' - גדר פסין הוא ההבדל היחסי לעירוב\u003c/p>\u003cp>ונרא' דגדר פסין הוא ההבדל היחסי לעירוב (ודין הוא דארבעה דיומדין בפסי ביראות, אע\"פ שהיה אפשר להקיף מקום גם בשלושה דיומדין טריגון), שבזה יועיל הגידור הצורתי (והרי אין משמעות לפינת הדיומד הפנימית כמקום בעל שתי מחיצות, עי' רש\"י אבן מרובעת), וזה פשר שם ד' מחיצות (ובזה יבדל מגדר לחי משום מחיצה, דגדרו פנימי ויועיל מצד אחד, ואולי עפ\"ז י\"ל גדר בד' מחיצות דגוד אסיק, ויש לחלק, ואכמ\"ל.) וד' דווקא.\u003c/p>"}, {"id": "503", "n": 36, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0929 | שתי שכבות במחיצה – להגדיר מהו מבחן ההבחנה | חומרה: גבוהה החלוקה בין „מחיצת כל צד” לבין „מחיצת המקום הכוללת” היא הצעה מושגית של המחבר, ולא חלוקה שמופיעה בלשון הסוגיות. כדי שתהיה ניתנת לבחינה, כדאי להגדיר לכל שכבה תנאי ברור: האם היא תלויה ברציפות המחיצה, בהיקף השטח, במניעת מעבר, או בצירוף כמה צדדים. לאחר מכן יש להראות מקרה שבו מחיצה קיימת בשכבה אחת אך חסרה בשנייה. בלי מבחן כזה עלול להיווצר שימוש משתנה במונח „מחיצה” לאורך הפרק.\u003c/p>"}, {"id": "504", "n": 37, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0930 | בקיעה במחיצה לעומת בקיעה בתוך הרשות – להבחין בין המקרים שבמקורות | חומרה: גבוהה בסוגיות עירובין כ ע״א וכב ע״א נידונים מקרים שונים של בקיעת רבים: פסי ביראות, חצר שהרבים נכנסים בה מצד אחד ויוצאים מצד אחר, ותל המתלקט. אין די לומר שהבקיעה „ברשות” מוסיפה משמעות לבקיעה שבמחיצה בלי לפרט מהו הנתון בכל מקרה. בפרט, בפסי ביראות נאמר שחכמים אינם מבטלים את המחיצות, ואילו בדין ירושלים נאמר שדלתותיה הננעלות נחוצות. כדאי לציין בכל שלב אם הרבים עוברים בין המחיצות, דרך פרצה, או בתוך חלל מוקף.\u003c/p>"}, {"id": "505", "n": 38, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0931 | אחדות כלל המחיצות – לא להניח שהצירוף יוצר כוח נוסף בלי הגדרה | חומרה: בינונית-גבוהה הטענה שכל המחיצות מקבלות „שם אחד” מכוח הגדרת המקום היא נדבך חדש במודל. יש להבהיר אם מדובר בכלל הלכתי שמקורו במושג היקף, בתוצאה גאומטרית של סגירת השטח, או במעמד עצמאי של „מקום”. כדאי לבחון את ההשלכה על מקום בעל שלוש מחיצות, מקום בעל שתי מחיצות, ופסי ביראות: האם בכל אחד מהם יש „שם אחד” לכלל המחיצות, ומה מונע את ביטולו. כך תתברר גם נקודת המחלוקת עם בקיעת הרבים.\u003c/p>"}, {"id": "1101", "n": 39, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-304 | סוג: חיבור עצמאי | מקור: קבצים ערוכים להטמעה / מיגו דהווה דופן (פרק א חלק ב' במסמך הבדיקה)\u003c/p>\u003cp>כותרת מוצעת בסגנון הכותרות שבקובץ: מיגו דהווה דופן - פסי ביראות, סוכה ושיטת הראבי\"ה\u003c/p>\u003cp>חיבור עצמאי בסוגיית מיגו דהווה דופן בפסי ביראות, שהוכן להטמעה ולא הוטמע. מקום השילוב הטבעי: סמוך לדיון ביסוד מחלוקת פסי ביראות לר\"י, כהרחבה למחלוקת מחיצות שבת וסוכה.\u003c/p>\u003cp>הצעת קטע קישור בפתיחת הקטע: ובגדר מה שמועילות מחיצות פסי ביראות לסוכה מכח מיגו דהווה דופן, יש לעיין בדברי ביאור הלכה (תר\"ל ס\"ז ד\"ה או):\u003c/p>\u003cp>נוסח הקטע בשלימותו:\u003c/p>\u003cp>מיגו דהווה דופן: פסי ביראות, סוכה ושיטת הראבי\"ה\u003c/p>\u003cp>כתב בביאור הלכה (תר\"ל ס\"ז ד\"ה או) בעניין פסי ביראות דמיגו דהוי דופן לשבת הוי דופן לסוכה, דמש\"כ בשו\"ע (שם) באר שיש לה פסים וז\"ל הוא לשון הרמב\"ם, ומשמע לכאורה דדווקא כשיש שם באר ולא כדעת הראבי\"ה דס\"ל אף על פי שאין שם בור כמובא ברא\"ש, ועיין במאמר מרדכי וצ\"ע, ע\"כ.\u003c/p>\u003cp>והוקשה בזה: דהרי לעניין מיגו במבוי ולחי, דעת השו\"ע דאיירי במבוי מפולש וכהרא\"ש כדפירש שם, והיינו אע\"ג דלא הותר בשבת מבוי מפולש ולחי זה אינו אלא מדרבנן, אבל מדאורייתא הרי לחי משום מחיצה והוי שלוש דפנות והוי רשות היחיד מדאורייתא ואמרינן מיגו; וכאן משמע שלא התירו מיגו דהווה דופן אלא בדין שמותר בשבת אפילו מדרבנן, שפסים אפילו דמועילים ומחייבים מדאורייתא לא הותרו אלא לבאר וכו', וצריך ביאור.\u003c/p>\u003cp>והנה בעצם דין פסי ביראות צריך ביאור, שנתחדשו בו כמה דינים: דהוא פרוץ מרובה, ופרצתו יותר מעשר, ומפולש (ולרבנן אפילו אתי רבים). ומבואר בגמרא דההיתר הוא רק בבאר, ומים, ועולי רגלים, ובהמה לבד. ומבואר בגמרא דמחיצותיו הוי מחיצה דאורייתא (ולא רק אינו רשות הרבים), והזורק לתוכו חייב (לגמרא דידן). וביארו הראשונים דגדר מחיצותיו הוא משום דהוי ליה שם ארבע מחיצות, ועדיין צריך ביאור (דאינם סביב הרשות, ואי סגי בטפח אפילו מחיצה לא הוי, ובפרט דקיימא לן שלוש מחיצות דאורייתא, ובכלל מאי אולמיה דארבע).\u003c/p>\u003cp>והנה, צורת פסים היא שתי סתימות בקצה כל רוח וחיבורן על ידי דיומדין; ועניין מחיצה הוא הפרדה, ומערכתם הגדרת מקום נפרד ורשות מיוחדת, להבדיל ולייחד מרחב (שטח ורומו, ולהבדיל משטח לבדו, עיין ירושלמי כלאים פ\"ב ה\"ו). ובאמת שהנדרש הוא הייחוד לבד (ורמז לזה גזוזטרא), והעירוב הוא חיסרון, וההבדל מכמה פנים יבטל העירוב ויבוא הייחוד, והעירוב הוא מארבעה פנים (משום דהוו ארבע רוחות, או בהיפך המסובב ושמטעמם יהיו הרוחות ארבע).\u003c/p>\u003cp>והנה יש לומר שדין שלוש מחיצות דאורייתא ולא ארבע הוא גדר בהייחוד (שהייחוד עניין פנימי לרשות, והפרד העירוב יחסי לחוץ ולהבדל). ונראה דגדר פסים הוא ההבדל היחסי לעירוב (ודין הוא דארבעה דיומדין בפסי ביראות, אע\"פ שהיה אפשר להקיף מקום גם בשלושה דיומדין טריגון), שבזה יועיל הגידור הצורתי (והרי אין משמעות לפינת הדיומד הפנימית כמקום בעל שתי מחיצות, עיין רש\"י אבן מרובעת), וזה פשר שם ארבע מחיצות (ובזה ייבדל מגדר לחי משום מחיצה, דגדרו פנימי ויועיל מצד אחד, ואולי עפ\"ז י\"ל גדר בארבע מחיצות דגוד אסיק, ויש לחלק, ואכמ\"ל), וארבע דווקא.\u003c/p>\u003cp>וכיוון שכן, יקשה ביותר: איך יועיל מיגו לסוכה, שמשמע שעניינה ייחוד פנימי (היינו, הקדמת מחיצות, ליצור מה שראוי להכיל ישיבת סוכה שבוודאי עניינה מאוחד)?\u003c/p>\u003cp>ונראה: שהנה בכל מקום בעל מחיצות בא ההבדל והייחוד בחדא מחתא, היינו, ההפרדה מהעירוב ושם החוץ, והייחוד הפנימי ושמו העצמי (המאחד חלקי המקום); ובפסים זה אינו, שכולם רק הפרדה והבדלה, ואין במחיצותיו ייחוד להגדיר המקום אחד לרשות ושירות אחד, ולזה נצרך הבאר לתת שם רשות אחת למקום. ועל כן נראה שהבאר אינו כשאר תנאים הנ\"ל, אלא הוא חלק מהגדרת הרשות (ושו\"ר דקדוק רמב\"ם י\"ז כ\"ו, ועיין תירוץ תוספות כ: ד\"ה מחיצות אמאי לא אמרינן הותרה ביבשו מים בשבת). ואע\"פ שבלעדו הוי רשות היחיד לזרוק, על מנת להגדיר חלקי המקום רשות אחת לטלטל נדרש הבאר (ועפ\"ז יש לבאר בעוד מקומות כקרפף וכו', ואכמ\"ל).\u003c/p>\u003cp>ועל כן יבואר דעת השו\"ע: שלעניין מבוי מפולש ולחי, כיוון דמדאורייתא הוי רשות היחיד גמורה ומחיצותיה יגדירוה כרשות, וגזירת חכמים שלא לטלטל הוא משום חשש (עיין שו\"ע סימן שמ\"ה סי\"ד ונושאי כלים שם) ואינה עניין לסוכה, אז אמרינן מיגו דהוי מחיצה לרשות שבת (והיינו שאין המיגו להגדיר מחיצות נפרדות שהמחיצות חשיבי מחיצות בלי דיני שבת, רק הכוונה להגדיר המחיצות לאחד המקום); אבל לעניין פסי ביראות, כיוון שבלי הבאר חסר בהם בשם רשות, ואינם אלא הבדלה, לא יועיל לעשות מיגו לסוכה.\u003c/p>\u003cp>(ויותר מזה נראה שאין שייך כלל מיגו על זה, ולפ\"ז יש לבאר מה דלא אמרינן מיגו לחומרא, ובזה יבואר מה דלא אמרינן מיגו בתל, ובהקדם רמב\"ן שבת צט:).\u003c/p>\u003cp>מראי מקומות ועוגני עיון:\u003c/p>\u003cp>רמב\"ם: תנאי דבאר בתנאי מחיצה (הלכות שבת פרק י\"ז הלכה כ\"ו).\u003c/p>\u003cp>תוספות עירובין כ. ד\"ה מחיצות: אמאי לא אמרינן הותרה ביבשו מים בשבת, ותירצו דליכא מחיצה.\u003c/p>\u003cp>גמרא עירובין: באו מים בשבת הוי מחיצה שנעשית בשבת; ובעיא דבאו מים אי איירי בבאו לפני שבת ויבשו ובאו (רש\"י וירושלמי).\u003c/p>\u003cp>דין ארבע מחיצות בפרוץ מרובה: רש\"י סוכה; ארבע מחיצות דגוד אסיק; ודין ארבעה דיומדין בפסי ביראות אע\"פ שהיה אפשר להקיף מקום גם בשלושה דיומדין (טריגון).\u003c/p>\u003cp>הצעת קטע קישור בסיום הקטע: ומעתה יבואר על פי זה כל הסוגיא.\u003c/p>"}, {"id": "506", "n": 40, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0932 | פסי ביראות לשיטת רבי יהודה – להפריד בין לשון הסוגיה להסבר המחבר | חומרה: גבוהה בעירובין כ ע״א נאמר על פסי ביראות שאף על פי שהרבים בוקעים בהם, אין המחיצות בטלות; ובעירובין כב ע״א מובא חילוק בין „שתי מחיצות מעלייתא” לבין „שם ארבע מחיצות”. הסוגיות אינן אומרות במפורש שפסי ביראות פועלים משום „משמעות שימוש אחת” ולא משום מחיצות. זהו ההסבר שאתה מציע. כדאי להביא תחילה את לשון הגמרא ואת פירושי הראשונים למעלת המחיצות ולשם ארבע מחיצות, ורק אחר כך להציג את ההמשגה שלך כהצעה ליישובם.\u003c/p>"}, {"id": "507", "n": 41, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0933 | „שתי מחיצות מעלייתא” – לברר אם הכוונה לשתי דפנות שלמות או למעמדן | חומרה: גבוהה בעירובין כב ע״א נאמר „התם איכא שתי מחיצות מעלייתא”; הראשונים מבארים את מעלתן בהקשר של פסי ביראות ובקיעת הרבים. יש להיזהר מלהפוך את הביטוי לכלל שלפיו כל מחיצה המתפרסת על פני „כל המקום” מקבלת מעצמה משמעות עצמאית. יש לברר אם מדובר בשתי דפנות רציפות, בשתי רוחות שאין הרבים בוקעים בהן, או במעמד אחר של מחיצה. רצוי להביא את פירוש התוספות והריטב״א לפני בניית ההסבר הגאומטרי.\u003c/p>"}, {"id": "1102", "n": 42, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-305 | סוג: קטע חסר | מקור: 01_גרסאות_הספר/ארבעת חלקי המסמך - מקורי התוספות.txt\u003c/p>\u003cp>מיקום השילוב המוצע: לאחר הפסקה שלפני הערה זו (\"ביאור כאן הודיעוך כוחן של מחיצות - משמעות המחיצות ביחס למקום ולא רק לצדדיו...\").\u003c/p>\u003cp>הקטע משתלב כאן כהמשך ישיר לדברים שלפניו; אין צורך בקטע קישור.\u003c/p>\u003cp>נוסח הקטע:\u003c/p>\u003cp>ביאור מה דאין למצוא כוחן של מחיצות בשתי מחיצות דר\"י\u003c/p>"}, {"id": "508", "n": 43, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0934 | „כאן הודיעוך כוחן של מחיצות” – להבחין בין רבי יוחנן לרבי אלעזר | חומרה: קריטית לבירור בעירובין כ ע״א נאמר „כאן הודיעוך כוחן של מחיצות” על אף בקיעת הרבים בפסי ביראות. אולם הראשונים מדגישים שהייחוס אינו אחיד: לפי התוספות, רבי אלעזר סובר „כאן וסבירא ליה”, ואילו רבי יוחנן אינו סובר כך בכל מקום, כפי שעולה מדין ירושלים בעירובין ו ע״ב וכב ע״א. לכן אין להשתמש במימרה כעיקרון מוחלט בשם רבי יוחנן בלי לציין את ההסתייגות. יש להפריד בין כוח המחיצות בפסי ביראות לבין שאלת דלתות ירושלים.\u003c/p>"}, {"id": "509", "n": 44, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0935 | ארבעת שלבי ההיתר – להציג כמודל מסביר ולא כרצף מפורש בסוגיה | חומרה: גבוהה חלוקת המהלך לארבעה שלבים — חיבור לרשות הרבים, הפרדה באמצעות לחי וקורה, ביטול המחיצה בבקיעת רבים, וחזרה להכרעת המחיצות הטובות — היא סינתזה של המחבר. הסוגיות אינן מציגות רצף כרונולוגי או הלכתי כזה, אלא דנות במקרים ובמחלוקות שונות. מומלץ לציין אילו שלבים נלמדים מעירובין ו ע״ב, אילו מעירובין יב ע״ב, ואילו מעירובין כ–כב. אפשר להוסיף תרשים קצר של „נתון – מקור – מסקנת המחבר” כדי למנוע רושם שמדובר במהלך מפורש של הגמרא.\u003c/p>"}, {"id": "1103", "n": 45, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-306 | סוג: כותרות חסרות | מקור: גרסאות עדכניות של החיבורים\u003c/p>\u003cp>כותרות תמצית חסרות לקטע זה (7 כותרות, מנוסחות בסגנון כותרות המשנה שבקובץ):\u003c/p>\u003cp>1. ביאור סתירת הסוגיות בהמוכרח מברייתא דשני בתים\u003c/p>\u003cp>2. גדר ג' מחיצות כסתימת המקום בעל ד' צדדים\u003c/p>\u003cp>3. ראיה מספיקא דגמ' בתל המתלקט לעניין אתי רבים\u003c/p>\u003cp>4. מה דלמ\"ד ג' מחיצות דאורייתא שייך גדר גמורה בד' מחיצות\u003c/p>\u003cp>5. ראיה מתל המתלקט דאתי רבים תליא במשמעות מחיצות כגודרים\u003c/p>\u003cp>6. חילוק גדרים אלו תליא בהבדל שיש בין רשויות דאורייתא ודרבנן\u003c/p>\u003cp>7. גדר ג' מחיצות כסתימת המקום בעל ד' צדדים - תל וחריץ עדיפים על ג' מחיצות משום שיש להם ד' צדדים ממש\u003c/p>"}, {"id": "510", "n": 46, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0936 | „שתי מחיצות דאורייתא” – לא לצמצם את לשון הסוגיה להגדרת צדדים בלבד | חומרה: קריטית לבירור בעירובין יב ע״ב הגמרא מיישבת את רבי יהודה: „התם קסבר רבי יהודה שתי מחיצות דאורייתא”. זהו נתון מפורש על מעמד שתי המחיצות מן התורה. ההסבר שלך, שלפיו שתי המחיצות מגדירות רק את צדדיהן ועדיין נדרשת הגדרה נוספת לכלל המקום, הוא פירוש מחודש וצריך להתבאר ביחס ללשון „דאורייתא”. יש להציג את ההבנה הפשוטה האפשרית — ששתי מחיצות עשויות ליצור רשות היחיד מן התורה — ואז להסביר מדוע לדעתך אין בכך לבדו להכריע את שאלת הטלטול או הכשר המבוי.\u003c/p>"}, {"id": "511", "n": 47, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0937 | „רשות היחיד גמורה” – להבחין בין שתי הופעות „גמורה” בשבת ו ע״ב | חומרה: גבוהה בשבת ו ע״ב מופיעות שתי שאלות נפרדות על „גמורה”, ויש להבחין ביניהן. בראשונה נאמר „זו היא רשות היחיד גמורה”, והגמרא שואלת „ואמאי קרו ליה גמורה” ומשיבה: „מהו דתימא כי פליגי רבנן עליה דרבי יהודה דלא הוי רה״י, הני מילי לטלטל אבל לזרוק מודו ליה, קמ״ל”. רש״י מפרש שם „קמ״ל גמורה” — „זו היא שנגמרו מנין מחיצות שלה שיש לה מחיצות מכל צד”, ומעמיד זאת כנגד רשותו של רבי יהודה שיש בה שתי מחיצות בלבד. רק בהמשך, לאחר „אמר מר זו היא רה״ר”, באה השאלה השנייה „ואמאי קרו ליה גמורה”, ועליה נאמר „איידי דתנא רישא גמורה תנא נמי סיפא גמורה”. תשובת „איידי” מתייחסת אפוא ל„רשות הרבים גמורה” שבסיפא, ולא ל„רשות היחיד גמורה” שברישא. ההערה הקודמת ערבבה בין שתי ההופעות. בבירור P02768 יש להביא את התשובה הראשונה ואת פירוש רש״י, ולהציג את הרחבת ההבחנה למודל של שלוש/ארבע מחיצות כחידוש פרשני של המחבר, ולא לייחס לה את תשובת „איידי”.\u003c/p>"}, {"id": "512", "n": 48, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0938 | תל המתלקט – תשובת הגמרא מחייבת גם כשהעלייה קשה | חומרה: גבוהה בעירובין כב ע״ב נשאל רבא אם בתל המתלקט עשרה מתוך ארבע, שרבים בוקעים בו, חייבים משום רשות הרבים לשיטת רבי יהודה; התשובה היא „חייבין”, ואף „עולין לו בחבל” ו„במעלות בית מרון”. לכן אין להסיק מן הסוגיה בפשטות שנוחות השימוש היא תנאי הכרחי לביטול מחיצה לשיטת רבי יהודה. יש להבחין בין „לא ניחא תשמישתיה” של שבילי בית גילגול ומעלות ארץ ישראל לבין התל המתלקט, שבו הגמרא משיבה במפורש לחיוב גם בתנאי עלייה קשים.\u003c/p>"}, {"id": "1104", "n": 49, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-307 | סוג: כותרות חסרות | מקור: גרסאות עדכניות של החיבורים\u003c/p>\u003cp>כותרות תמצית חסרות לקטע זה (6 כותרות, מנוסחות בסגנון כותרות המשנה שבקובץ):\u003c/p>\u003cp>1. חילוק הנ\"ל תלוי בחילוק גדרי רשויות דאורייתא ודרבנן\u003c/p>\u003cp>2. גדר מקום וההוצאה בו מגדרי מקום חפץ\u003c/p>\u003cp>3. גדר הנ\"ל ביחס לחפץ במשמעות נפרדת ממשמעותו לאדם\u003c/p>\u003cp>4. הנובע מזה דגם גדר מקום יהיה ביחס לגדרי מקום חפץ\u003c/p>\u003cp>5. גם גדר רשויות נובע ממשמעות הנ\"ל\u003c/p>\u003cp>6. השווה בין גדר מקום לגדר חפץ ונביעתם\u003c/p>"}, {"id": "513", "n": 50, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0939 | „אל יצא איש ממקומו” – מקור הפסוק אינו מכריע לבדו את גדר מקום החפץ | חומרה: גבוהה הפסוק „אל יצא איש ממקומו” (שמות טז, כט) עוסק בלשונו באדם ובמקומו. כדי ללמוד ממנו שגדר הוצאה הוא דווקא „מקום חפץ” ולא מקום האדם, יש להביא את דרשת חז״ל ואת המקורות המגדירים את איסור הוצאה והעברה. בפרט, דין ארבע אמות ברשות הרבים ודין עקירה והנחה ברשויות אינם נלמדים בהכרח מאותו ניסוח בלבד. מומלץ להציג את הפסוק, את דרשת חז״ל, ואת המסקנה המושגית בשלושה שלבים נפרדים.\u003c/p>"}, {"id": "514", "n": 51, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0940 | ארבע אמות לעומת ארבעה טפחים – אין לערב שיעור העברה עם שיעור מקום | חומרה: גבוהה יש להבחין בין ארבע אמות של העברה ברשות הרבים לבין ארבעה על ארבעה טפחים, שהוא שיעור מקום חשוב בהגדרת רשות ובדיני עקירה והנחה. אלו שיעורים בעלי תפקידים שונים: האחד מתאר מרחק העברה, והאחר שטח מינימלי. עצם השוני ביניהם אינו מוכיח שהאיסור נובע מ„מקום חפץ” בניגוד ל„מקום אדם”. כדאי לבסס את הקשר על סוגיות שבת צו ע״ב ועירובין מח ע״א, ולנסח מה בדיוק נלמד מן ההבדל.\u003c/p>"}, {"id": "515", "n": 52, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0941 | ההשוואה לקניין – להבהיר את גבולות האנלוגיה | חומרה: בינונית-גבוהה ההשוואה בין מושג „מקום חפץ” לבין קניין מועילה להמחשת ההבחנה בין תכונת החפץ לבין זיקתו לאדם, אך אין היא ראיה הלכתית. קניין, איסורי הנאה והוצאה בשבת נשענים על מערכות מושגים שונות. כדאי לנסח במפורש מה מועתק מן האנלוגיה ומה אינו מועתק: האם מדובר רק בהבחנה בין עצם הדבר לבין זיקתו לאדם, או גם במבנה משפטי של „שייכות” נפרדת. כך לא תשתמע זהות בין גדרי קניין לגדרי רשויות.\u003c/p>"}, {"id": "516", "n": 53, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0942 | „מקום חפצים כללי” – להגדיר את המושג באמצעות דוגמה הלכתית | חומרה: בינונית-גבוהה המונח „מקום חפצים באופן כללי” הוא מרכזי למסקנה, אך אינו מונח מוכר בלשון הסוגיות. כדאי להגדירו בדוגמה: מהו ההבדל בין שינוי מקום של חפץ מסוים לבין שינוי במרחב המוגדר כמקום לחפצים? לאחר מכן יש להראות כיצד ההבדל מסביר דין מסוים בהוצאה, ולא רק מייצר שכבת הפשטה נוספת. בהיעדר דוגמה, קשה לבדוק אם המושג מוסיף הבחנה הלכתית או רק מנסח מחדש את מושג שינוי המקום.\u003c/p>"}, {"id": "517", "n": 54, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0943 | שש הדרגות – מומלץ להפוך לרשימת הגדרות יציבה | חומרה: בינונית הסיכום מונה שש דרגות, אך חלק מן הביטויים קרובים זה לזה: „מקום אדם”, „מקום חפץ”, „חפץ אדם” ו„מקום חפצים”. כדי שהרשימה תשמש מפתח להמשך, כדאי לתת לכל מונח הגדרה של שורה אחת ולדוגמה אחת, ולשמור על אותם שמות בדיוק בפסקאות הבאות. בפרט יש להבדיל בין „מקום שבו נמצא חפץ” לבין „מקום המוגדר כמקום לחפצים”. אפשר להציג זאת בטבלה קצרה, בלי לשנות את הטיעון עצמו.\u003c/p>"}, {"id": "1105", "n": 55, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-308 | סוג: כותרות חסרות | מקור: גרסאות עדכניות של החיבורים\u003c/p>\u003cp>כותרות תמצית חסרות לקטע זה (3 כותרות, מנוסחות בסגנון כותרות המשנה שבקובץ):\u003c/p>\u003cp>1. ביאור חילוק גדר רה\"י בגידור מרה\"ר בשימוש\u003c/p>\u003cp>2. גדר קרקע דרשויות והבדל רה\"י מרה\"ר בזה\u003c/p>\u003cp>3. גדר רשויות דאורייתא ע\"פ האמור - שני מובנים במקום חפץ כבסיס ומשמעות מקום חפץ ביחס לאדם כשינויי רשות\u003c/p>"}, {"id": "518", "n": 56, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0944 | רשות הרבים אינה מוגדרת בשימוש בלבד – להשלים את תנאי הגדרתה | חומרה: גבוהה הקביעה שרשות הרבים אינה מוגדרת אלא בשימוש עלולה להיות רחבה מדי. בסוגיית שבת ו ע״א ובפירושי הראשונים נידונים גם רוחב הדרך, היותה מפולשת, ותנאים הנוגעים למספר המשתמשים לפי שיטות שונות. ייתכן שהמחבר מבקש להבחין בין הגדרה חיובית של רשות היחיד לבין תנאים שליליים ברשות הרבים, אך יש להבהיר שאין בכך מחיקה של יתר תנאי רשות הרבים. מומלץ לפרט אילו תנאים נחשבים „שימוש” ואילו הם תנאי צורה או שיעור.\u003c/p>"}, {"id": "1106", "n": 57, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-309 | סוג: קטע חסר | מקור: 04_רשויות/רשויות.pdf / 08_הקדמות_והצעות_נוסח/תוכניות להטמעת קטעים.txt\u003c/p>\u003cp>מיקום השילוב המוצע: לאחר הפסקה שלפני הערה זו (\"אך גדר מה שתקנו חכ' הוא ביחס הפוך, דאין הם דינים ביחס לקרקע, אלא ביחס לרשות עצמה, היינו, חללה. והיינו, שראו חכ...\").\u003c/p>\u003cp>הקטע משתלב כאן כהמשך ישיר לדברים שלפניו; אין צורך בקטע קישור.\u003c/p>\u003cp>נוסח הקטע:\u003c/p>\u003cp>C3. הגדרת רה\"ר כ\"גדר שלילי\" ביחס למקום חפץ (רה\"ר אינה מאחדת את מקומות החפץ שבתוכה)\u003c/p>\u003cp>מיקום הכנסה מוצע: להוסיף בהמשך ישיר ליחידה C2 לעיל (אותו מיקום, מיד אחריה) - זו נקודת-הליבה המשלימה את ההגדרה החיובית/שלילית.\u003c/p>\u003cp>מקור: חלק ג', כותרת 3 מס' 152 (\"כו.\")\u003c/p>"}, {"id": "519", "n": 58, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0945 | תקנות חכמים ביחס לחלל הרשות – לדייק את מקור גזירת כרמלית | חומרה: גבוהה יש לדייק במראה המקום: בשבת ו ע״ב הגמרא מסווגת כרמלית כמי שאינה לא רשות היחיד ולא רשות הרבים, אך אינה מנסחת שם במפורש את טעם הגזירה כחשש שתתחלף ברשות הרבים. הניסוח המפורש מופיע ברמב״ם, הלכות שבת יד, יא: „שאיסור הכרמלית מדבריהם מפני שהיא דומה לרשות הרבים שמא תתחלף ברשות הרבים”. לכן יש להפנות לרמב״ם כמקור הישיר לטעם זה, ולהבחין בינו לבין עצם סיווג הכרמלית בסוגיית שבת. גם לאחר תיקון מראה המקום, אין להסיק מכאן שכל תיקוני המבוי הם תקנה אחידה המגדירה את החלל בארבעה צדדים; יש להבחין בין גזירת כרמלית, תיקון מבוי בלחי וקורה, ושיתוף מבואות, שכל אחד מהם פועל בהקשר הלכתי אחר.\u003c/p>"}, {"id": "1107", "n": 59, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-310 | סוג: כותרות חסרות | מקור: גרסאות עדכניות של החיבורים\u003c/p>\u003cp>כותרות תמצית חסרות לקטע זה (13 כותרות, מנוסחות בסגנון כותרות המשנה שבקובץ):\u003c/p>\u003cp>1. גדר מחיצות ומנינם במשמעות הכוללתם יחד\u003c/p>\u003cp>2. מספר מחיצות נובע מגדר מקום הנחצץ בשמו ומטרתו\u003c/p>\u003cp>3. וכן משמע מדברי רש\"י בסוכה (ו:) אילפותא דר' שמעון מזרם דיש שייכות בין גדר הרשות לסיבת מספר המחיצות. (וז\"ל הק' שם (ד\"ה למחסה ולמסתור) ובלא ארבע מחיצות לאו מחסה מזרם הוא שהרוח משיב את הזרם דרך דופן הפרוץ. ע\"כ.) והנה מדברי רש\"י הנ\"ל יש לבאר עכ\"פ גדר מאן דס\"ל ד' מחיצות דאורייתא, והוא שלא יהא פריצה לתוך הרשות, ודבזה כל צד הוא משמעותי, ולא יועיל צד אחד לצד שני.\u003c/p>\u003cp>4. גדר כלל המחיצות דשבת אי נימא שהוא נובע מגדרי המקום והרשות\u003c/p>\u003cp>5. ביאור גדר הנידון במספר המחיצות הנדרש לרה\"י\u003c/p>\u003cp>6. דינים שיש למצוא בהם משמעות דג' מחיצות\u003c/p>\u003cp>7. גדר מחיצות ביחס לכל חלק בקרקע\u003c/p>\u003cp>8. גדר אפשרי בג' מחיצות לפי דרך הנ\"ל\u003c/p>\u003cp>9. לחי כקביעת קצה מקום ופס כיצירת מחיצה\u003c/p>\u003cp>10. ביאור חילוק הנ\"ל - מחלוקת מספר המחיצות ביחס להגדרת קרקע וגדר הכשר מבוי ביחס להגדרת חלל\u003c/p>\u003cp>11. גדר מחיצות ביחס לכל חלק בקרקע - משמעות נוספת שיש במחיצות לכל חלק בקרקע מלבד הגדרת המקום כולו\u003c/p>\u003cp>12. ומשמעות זו בג' מחיצות היה למצוא בשתי בחינות, האחד, לגבי עירוב בפועל, היינו, דין בקעי בה רבים, והשני לגבי הגדרת מקום, היינו, דין מקום מפולש. ובבחינה זו השניה כבר כתבנו דאין משמעות מפולש בלי בקיעה ביחס לרשות דאורייתא, וגם אין חסרון דמפולש שווה בכל הצורות, ואף אי ס\"ל דמבוי עקום דינו כמפולש, אין הוא מפולש, ואין זה שייך למספר המחיצות.\u003c/p>\u003cp>13. מעלות ומורדות כקובעות שימוש\u003c/p>"}, {"id": "1108", "n": 60, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-311 | סוג: קטע חסר | מקור: 08_הקדמות_והצעות_נוסח/הצעות נוסח להקדמה - נושא הרשויות.docx\u003c/p>\u003cp>מיקום השילוב המוצע: לאחר הפסקה שלפני הערה זו (\"וזה ביאורו, כי גדר המח' ביחס למספר המחיצות הוא ביחס להגדרת קרקע, אך גדר הכשר מבוי נוגע להגדרת חלל, ובזה כ\"ע מו...\").\u003c/p>\u003cp>הקטע משתלב כאן כהמשך ישיר לדברים שלפניו; אין צורך בקטע קישור.\u003c/p>\u003cp>נוסח הקטע:\u003c/p>\u003cp>ביאור חילוק גדר רה\"י בגידור מרה\"ר בשימוש\u003c/p>\u003cp>חילוק גדר תקנת חכמים ברשויות מדאוריתא\u003c/p>"}, {"id": "520", "n": 61, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0946 | ארבעה צדדים בחלל – לבדוק את הקשר בין גובה, רוחב ומספר המחיצות | חומרה: גבוהה הטענה שתקנת המבוי מכוונת לחלל ולכן ארבעת הצדדים שווים במשמעותם היא חידוש מושגי. אולם בדיני מחיצות יש הבחנות מפורשות בין גובה עשרה, רוחב ארבעה, רוחב הפתח, פרוץ מרובה, ולחי או קורה. אין להסיק מהיעדר שיעור רוחב בלחי שאין משמעות להבדל בין רוחב לגובה בכל דיני ההכשר. רצוי להביא מקרה שבו גובה ורוחב אכן מתחלפים מבחינת הדין, ולהסביר כיצד המודל מתמודד עם שיעורי המבוי המפורשים.\u003c/p>"}, {"id": "521", "n": 62, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0947 | מבוי ארכו כרחבו – להביא את כל תנאי ההגדרה ולא רק את צורתו | חומרה: גבוהה בעירובין יב ע״ב נאמר שמבוי שארכו כרחבו אינו ניתר בלחי משהו או בקורה טפח, משום שנחשב כחצר; ובהמשך רב נחמן מגדיר מבוי שניתר בלחי וקורה ככזה שארכו יתר על רחבו ובתים וחצרות פתוחים לתוכו. לכן אין לצמצם את ההבחנה בין מבוי לחצר ליחס האורך והרוחב בלבד. יש לציין גם את תנאי הבתים והחצרות ואת שיעור הפס בחצר. חידושך שלחי הוא חלק מצורת כלל המבוי ופס הוא מחיצה עצמאית צריך להיבחן על רקע מכלול התנאים.\u003c/p>"}, {"id": "522", "n": 63, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0948 | לחי „משום מחיצה” – להבחין בין תוצאת התיקון לבין זהות החפץ | חומרה: גבוהה ההצעה שגם למאן דאמר „לחי משום מחיצה” אין הלחי עצמו מחיצה אלא הוא גורם למבוי להיחשב מחולק, היא דרך אפשרית לנסח את תפקידו. עם זאת, בעירובין יב ע״ב מחלוקת אביי/רבה מול רבא מנוסחת במפורש בשאלה אם הלחי „משום מחיצה” או „משום היכר”. לכן יש להגדיר אם „מחיצה” כאן היא חפץ פיזי, דין תוצאה, או מעמד המקום. כדאי להראות כיצד ההגדרה מסבירה את דיני לחי העומד מאליו ואת ההבדל בין לחי לפס, ולא להציג את ההבחנה כהכרח העולה מעצם המונח.\u003c/p>"}, {"id": "523", "n": 64, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0949 | שתי מחיצות לצורך „ריבוע הקרקע” – לא להכליל מכל שיטה לכל רשות היחיד | חומרה: גבוהה הדיון בעירובין יב ע״ב הוא בשיטת רבי יהודה שלפיה שתי מחיצות דאורייתא, ואילו בסוגיות אחרות נידונים מספרי מחיצות שונים. אין להציג „לכולי עלמא די בשתי מחיצות שלמות” בלי מקור מדויק, ובפרט כאשר בהמשך אתה מביא דעות על שלוש או ארבע מחיצות. יש להבחין בין שתי מחיצות היוצרות רשות היחיד לשיטה מסוימת, שתי דפנות שלמות שאינן נבקעות, והצורך בתיקון מדרבנן לטלטול. אלו אינם בהכרח אותו דין.\u003c/p>"}, {"id": "1109", "n": 65, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-312 | סוג: קטע חסר | מקור: 04_רשויות/רשויות.pdf\u003c/p>\u003cp>מיקום השילוב המוצע: לאחר הפסקה שלפני הערה זו (\"ובהכרח צ\"ל דמלבד שיש במחיצות משמעות הגדרת הקרקע, יש משמעות בעצם המחיצות ביחס לכל חלק בקרקע, ומה שיש בזה משמעות...\").\u003c/p>\u003cp>הקטע משתלב כאן כהמשך ישיר לדברים שלפניו; אין צורך בקטע קישור.\u003c/p>\u003cp>נוסח הקטע:\u003c/p>\u003cp>דינים שיש למצוא בהם משמעות דג' מחיצות\u003c/p>\u003cp>חילוק גדר ג' מחיצות מא' ב' וד' מחיצות\u003c/p>"}, {"id": "524", "n": 66, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0950 | הראיה מרש״י בסוכה – להביא את המקור ואת מהלך הדרשה במדויק | חומרה: גבוהה כאן אתה נשען על „דברי רש״י בסוכה בילפותא דרבי שמעון מזרם”. יש לציין את דף הסוגיה ואת לשון רש״י המדויקת, ולהבהיר מה נלמד מן הדרשה: מספר דפנות, גובהן, או מניעת כניסה. בלי מראה מקום מדויק קשה לבדוק אם רש״י אכן מייחס לכל צד תפקיד עצמאי או שמדובר בביאור אחר. חשוב גם להפריד בין דרשת סוכה לבין גדרי מחיצות שבת, שאינם נלמדים אוטומטית מאותו פסוק.\u003c/p>"}, {"id": "525", "n": 67, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0951 | פרוץ מרובה, נפרצה במלואה ונפרצה משתי רוחות – להפריד בין שיעורים למושגים | חומרה: גבוהה הביטויים „פרוץ מרובה”, „נפרצה במילואה” ו„נפרצה משתי רוחות” מתארים מצבים הלכתיים שונים, ויש לעגן כל אחד במקור ובשיעוריו. אין להסיק מהם לבדם שכל מחיצה בשבת מוגדרת רק כמניעת פריצה, או שחלוקת דין צד/ראש נובעת מאותו עיקרון. כדאי להביא את המקורות בעירובין טו ובסוגיות שבת הרלוונטיות ולבדוק האם כל אחד מן הדינים תלוי ברוב עומד, במלוא הפתח, או במבנה הפתחים.\u003c/p>"}, {"id": "1110", "n": 68, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-313 | סוג: כותרות חסרות | מקור: גרסאות עדכניות של החיבורים\u003c/p>\u003cp>כותרות תמצית חסרות לקטע זה (12 כותרות, מנוסחות בסגנון כותרות המשנה שבקובץ):\u003c/p>\u003cp>1. חילוק גדר ג' מחיצות מא' ב' וד' מחיצות\u003c/p>\u003cp>2. גדר מספר מחיצות אינו שייך בגדר המקום עצמו\u003c/p>\u003cp>3. ביאור דברי תוס' בחילוק מחיצת שבת מסוכה\u003c/p>\u003cp>4. חילוק גדר הכולל בג' מחיצות מא' ב' וד' מחיצות\u003c/p>\u003cp>5. לא מצאנו שחילוק במנין המחיצות יהיה נובע מתנאים שהם מגדרי המקום עצמו\u003c/p>\u003cp>6. ביאור דברי תוס' דמחיצות שבת הוא למנוע רגל רבים\u003c/p>\u003cp>7. חילוק גדר ג' מחיצות מא' ב' וד' מחיצות - שני גדרים נפרדים בשתי המחיצות הראשונות ובמחיצה השלישית\u003c/p>\u003cp>8. גדר מספר מחיצות אינו שייך בגדר המקום עצמו - הוכחה מדין פס בחצר ומדיומדין בפסי ביראות\u003c/p>\u003cp>9. גדר ד' מחיצות לר\"ש דסוכה - שייך בסוכה אך לא בשבת ואף בסוכה תלוי בהילכתא\u003c/p>\u003cp>10. ביאור דברי תוס' בחילוק מחיצת שבת מסוכה - מניעת רגל רבים לעומת חיבור מקום לסכך\u003c/p>\u003cp>11. ד' מחיצות כסגירת מקום גמור ולא כתנאי חיצוני\u003c/p>\u003cp>12. חילוק מחיצות שבת וסוכה מצד מהות המקום\u003c/p>"}, {"id": "526", "n": 69, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0952 | שלושה מושגים שאינם זהים: מפולש, בקיעת רבים, ונכנסים ויוצאים | חומרה: גבוהה הפסקה מזהה שלושה תיאורים: „מפולש”, „בקעי בה רבים”, ו„נכנסים לה בזה ויוצאים בזה”. יש לברר אם אלו שלושה שמות לאותו מצב או שלושה תנאים נפרדים. בעירובין כב ע״ב דוגמת החצר שהרבים נכנסים בה מצד אחד ויוצאים מצד אחר משמשת לבירור דין מחיצות, אך אינה בהכרח הגדרה כללית של כל מבוי מפולש. מומלץ להגדיר כל מונח ולציין באיזה הקשר הוא נאמר — הגדרת רשות מן התורה, ביטול מחיצה, או הכשר לטלטול.\u003c/p>"}, {"id": "527", "n": 70, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0953 | מודל שתי המחיצות והשלישית – להראות כיצד הוא מתיישב עם סוגיות שלוש דפנות | חומרה: גבוהה החלוקה שלפיה שתי מחיצות סוגרות את האורך והשלישית מגדירה את הפירצה היא חידוש. כדי לבסס אותה, יש לבדוק את דיני שלוש מחיצות ברשות היחיד, מבוי סתום ומבוי מפולש, ואת ההבחנה בין רוח רביעית הפתוחה לבין פרצה בתוך דופן. כדאי להראות אם אותו ניתוח מסביר גם חצר בעלת שלוש מחיצות וגם מבוי שיש לו לחי או קורה, או שמדובר בשני דינים שונים.\u003c/p>"}, {"id": "528", "n": 71, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0954 | „שם ארבע מחיצות” בפסי ביראות – לא מדובר בארבע דפנות רציפות | חומרה: גבוהה בעירובין כב ע״א הגמרא מיישבת את שיטת חכמים: בפסי ביראות „איכא שם ארבע מחיצות”, ואילו בברייתת שני הבתים אין שם ארבע מחיצות. זהו נתון חשוב לטענתך, אך יש לדייק: בפסי ביראות מדובר בפסים/דיומדין היוצרים שם ארבע מחיצות, ולא בארבע דפנות רציפות המקיפות את כל השטח. כדאי להציג את ההבדל הגאומטרי ואת פירושי הראשונים, כדי שלא תשתמע זהות בין „שם ארבע מחיצות” לבין ארבעה קירות שלמים.\u003c/p>"}, {"id": "529", "n": 72, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0955 | שיטת רבי שמעון בסוכה – מקור הדרשה והיקפה ביחס למספר הדפנות | חומרה: גבוהה המקור המדויק הוא סוכה ו ע״ב: רב מתנה אומר „טעמיה דרבי שמעון מהכא” ומביא את הפסוק „וסוכה תהיה לצל יומם... ולמחסה ולמסתור מזרם וממטר”. רש״י שם מפרש: „ובלא ארבע מחיצות לאו מחסה מזרם הוא שהרוח משיב את הזרם דרך דופן הפרוץ”. יש לדייק לצד זה שהברייתא עצמה מתארת את שיטת רבי שמעון כך: „שלש כהלכתן, ורביעית אפילו טפח”. לכן אין לנסח את שיטתו כדרישה לארבע דפנות שלמות ושוות; יש להבחין בין לשון רש״י על תפקיד ארבע המחיצות בהגנת הסוכה לבין שיעור הדופן הרביעית המפורש בברייתא. המקור תומך בהסבר של מחסה מפני הזרם בסוכה, אך אינו מוכיח כשלעצמו שכל צד ברשות שבת הוא גדר עצמאי או שדיני מחיצות שבת זהים לדיני סוכה. את ההשלכה לשבת יש לסמן כחידוש המחבר.\u003c/p>"}, {"id": "1111", "n": 73, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-314 | סוג: כותרות חסרות | מקור: גרסאות עדכניות של החיבורים\u003c/p>\u003cp>כותרות תמצית חסרות לקטע זה (10 כותרות, מנוסחות בסגנון כותרות המשנה שבקובץ):\u003c/p>\u003cp>1. חומרת מחיצה בשבת במשהו מגבשושית - מחיצה המונעת רגל רבים ולחי שאין בו כתותי\u003c/p>\u003cp>2. (ובזה תמצא פשר בק\"ו דעולא (שבת צט:), והיינו, דמשום מחיצה עצמה אין היא רק מקום פטור, דאין בה משמעות גובה עשרה, דלא הוי אלא כצירוף ולגבי רשות, והק\"ו הוא ביחס לזה, ואכמ\"ל)\u003c/p>\u003cp>3. ביאור דבריהם ז\"ל דהא דבסוכה בעינן מחיצות מגיעות לסכך הוא גדר במחיצה עצמה\u003c/p>\u003cp>4. בגדרי עירוב דקרקע לגבי כלאים\u003c/p>\u003cp>5. חילוק לחי מפס לגבי גדרי מחיצה\u003c/p>\u003cp>6. בגדר לחי ומשמעותו להגדיר מקום מבוי\u003c/p>\u003cp>7. חילוק מחיצת כלאיים ממחיצת מקום\u003c/p>\u003cp>8. ראיה מגבשושית ומלחי של אשירה - חומרת מחיצה בשבת אף במשהו ובלא צירוף הרשות עצמה\u003c/p>\u003cp>9. בגדרי עירוב דקרקע לגבי כלאים - עירוב קרקע בכלאים נוגע למושגי קרקע דגידולים ולא קרקע סתם\u003c/p>\u003cp>10. עירוב קרקע כיצירת רציפות מקום\u003c/p>"}, {"id": "530", "n": 74, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0956 | תוספות על מחיצת שבת וסוכה – מראה מקום מדויק וגבולות ההשוואה | חומרה: גבוהה המקור הוא תוספות סוכה ד ע״ב, ד״ה „פחות משלשה טפחים כשרה”, בסוף הדיון על צירוף גידוד ומחיצה. התוספות מקשים מדוע בבית שאין תוכו עשרה וחקק בו להשלימו לעשרה אין מחלקים בין מרחק של שלושה טפחים מן הכותל לבין פחות משלושה, כפי שמחלקים בסוכה, ומשיבים: „ויש לומר דלא דמי רשות שבת שהוא למנוע רגל רבים לסוכה דבעינן מחיצות סמוכות לסכך”. נמצא שהביטויים „למנוע רגל רבים” ו„מחיצות סמוכות לסכך” אכן מופיעים בלשון התוספות, ואין צורך להשאיר את הייחוס כלא מזוהה. עם זאת, דבריהם נאמרו ליישב הבדל מסוים בדין צירוף הגידוד והמחיצה ובמרחק מן הכותל; אין להרחיבם בלי ראיה להגדרה אוניברסלית של כל מחיצת שבת כחומר המונע מעבר רגל, או לקביעה שכל מחיצת סוכה צריכה להגיע פיזית לסכך. התוספות מדברים על סמיכות לסכך, וניתן לברר את אופן הרציפות גם מכוח לבוד. יש להפריד בין לשון המקור לבין ההפשטה המושגית שלך.\u003c/p>"}, {"id": "531", "n": 75, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0957 | גבשושית, צואה ולחי של אשירה – שלושה מקורות ושלושה שיעורים שונים | חומרה: גבוהה יש להפריד בין שלוש סוגיות שהפסקה מצרפת. (א) שבת ז ע״א: בלבינה זקופה ברשות הרבים, אביי ורבא אומרים שעל גבה פטור כשהיא גבוהה שלושה, „דלא דרסי לה רבים”; בהיזמי והיגי הם מקילים אף בפחות משלושה משום שאין רבים דורכים על הקוצים; חייא בר רב ורב אשי חולקים בפרטי היזמי, היגי וצואה. זו סוגיה של מעמד חפץ מסוים ברשות הרבים לפי דרך דריכת הרבים, ולא כלל מוסכם שכל מחיצה היא חומר המונע רגל. (ב) שבת צז ע״א: רב חסדא שואל מדוע פחות משלושה נידון כלבוד, ונענה „לפי שאי אפשר לה לרשות הרבים שתילקט במלקט וברהיטני”; לאחר מכן הגמרא מקשה „אי הכי שלשה נמי” ומעמידה את דין הגדיים הבוקעים במחיצה, ולבסוף קובעת „כל פחות משלשה כלבוד דמי הלכתא גמירי לה”. לכן סברת אי־אפשר ליישר את רשות הרבים היא הסבר מקומי במהלך, ולא המקור היחיד או הכללי לדין לבוד. (ג) דין לחי של אשירה ו„כתותי מיכתת שיעוריה” הוא בעירובין פ ע״ב: רב חייא בר אשי מתיר לחי אשירה וריש לקיש דן בקורה; למאן דאמר לחי ולא קורה הטעם הוא שקורה צריכה שיעור חשוב. רש״י שם מסביר שלחי אינו צריך שיעור לרוחבו ועוביו, ואילו תוספות מדגישים שאף לחי צריך גובה עשרה ורוחב משהו, אלא שהשיעור הקטן אינו נפסל באותו אופן. לפיכך אין לכתוב שלחי „אינו צריך שיעור כלל”; ההבחנה היא בין שיעור גובה עשרה לבין רוחב מזערי של משהו, ובין שיעור קורה של טפח וחוזק לקבל אריח. יש להציג את שלושת המקורות בנפרד ולסמן את ההפשטה של „מניעת רגל רבים” כחידוש המחבר.\u003c/p>"}, {"id": "532", "n": 76, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0958 | „מגיעות לסכך” – לברר מתי חל לבוד ומהו שיעור הרציפות | חומרה: גבוהה יש להבחין בין מחיצה שמגיעה ממש לסכך לבין מחיצה שאינה מגיעה אליו אך הפער קטן משלושה טפחים ונידון בלבוד. אם כוונתך לומר שהמחיצה צריכה להיחשב רציפה עד הסכך, יש לציין שהרציפות יכולה להיווצר מכוח לבוד ואינה מחייבת מגע פיזי. כמו כן, אין להסיק מכך שכל חומר המחיצה נושא „אורך עצמי” במובן המושגי שאתה מציע. כדאי לפרט את המקרה ההלכתי ואת מקורו בסוגיית סוכה, ואז לסמן את ההפשטה כחידוש.\u003c/p>"}, {"id": "533", "n": 77, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0959 | פירוש רש״י ללחי – מראה המקום והגבול של ההיסק | חומרה: בינונית-גבוהה נמצא מראה מקום מדויק: רש״י עירובין ב ע״ב, על המשנה „לחי”, מפרש: „קנה או לוח נעוץ אצל כותל האחד בראשו”. לשון זו מתארת את צורת הלחי ואת מיקומו בסמוך לאחד מכותלי המבוי, בראשו. היא יכולה לתמוך בתיאור היחס הגאומטרי שבין הלחי לכותל, אך אין בה לבדה פירוש אטימולוגי לשם „לחי”, וגם לא נאמר בה שהלחי אינו נידון כמחיצה עצמאית בכל הקשר. יש להעמיד את לשון רש״י מול מחלוקת הגמרא בעירובין יב ע״ב אם לחי משום מחיצה או משום היכר, ומול דיון הרשב״א בעירובין כב ע״א שלחי עשוי להיחשב מחיצה גרועה שאינה מצטרפת ל„שם ארבע מחיצות חשובות”. לכן יש להפריד בין מיקום הלחי ביחס לכותל, מעמדו ההלכתי בהכשר מבוי, והחידוש שלך בדבר „תוספת הגדרה” למחיצה שבצידו.\u003c/p>"}, {"id": "534", "n": 78, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0960 | לחי במקום שאורכו יתר על רוחבו – להבחין בין מקור הדין להסבר הגאומטרי | חומרה: גבוהה בעירובין יב ע״ב נדרש שמבוי יהיה ארכו יתר על רחבו, ולפי רב נחמן גם שיהיו בתים וחצרות פתוחים לתוכו; כשארכו כרחבו דינו כחצר וצריך פס. המקור אינו מסביר את ההבדל באמצעות „חשיבות יתרה” של צדדים ארוכים. זהו ביאור המחבר, ויש להציגו ככזה. כדאי גם לדייק שהיתרון יכול להיות אפילו משהו, כמסקנת הגמרא, ולכן יש להסביר כיצד הבדל מזערי יוצר שינוי איכותי במעמד הצדדים.\u003c/p>"}, {"id": "1112", "n": 79, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-315 | סוג: כותרות חסרות | מקור: גרסאות עדכניות של החיבורים\u003c/p>\u003cp>כותרות תמצית חסרות לקטע זה (9 כותרות, מנוסחות בסגנון כותרות המשנה שבקובץ):\u003c/p>\u003cp>1. גדר הנ\"ל תליא בחסרון דלא עביד אוקיינוס כ\"ע רה\"י\u003c/p>\u003cp>2. גדר קרקע דרשות כגדר קרקע סתם\u003c/p>\u003cp>3. שני אופני עירוב גידולים בכלאיים בקרקע גידולים דכרם ובגידולים דזרעים\u003c/p>\u003cp>4. עירוב קרקע האמור ברה\"י הוא במשמעותה השימושית\u003c/p>\u003cp>5. קרקע רשות עירובה ונפרדותה ביחס למשמעות שימוש בה\u003c/p>\u003cp>6. חילוק בין מחיצות השוללות רה\"ר למחיצות רה\"י\u003c/p>\u003cp>7. משמעות מחיצה ביחס לעירוב הנ\"ל - מחיצת כלאים במשמעות הרחקה וניתוק ולא הגדרה ונפרדות\u003c/p>\u003cp>8. גדר הנ\"ל תליא בחסרון דלא עביד אוקיינוס כולי עלמא רה\"י - חקירה אם החסרון במחיצות או במקום\u003c/p>\u003cp>9. גדר קרקע דרשות כגדר קרקע סתם - חסרון אוקיינוס אינו במחיצה אלא בעצם היות הקרקע אחת\u003c/p>"}, {"id": "535", "n": 80, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0961 | עירוב קרקע בכלאיים – המקורות המפורשים לגידולים, הרחקה ומחיצה | חומרה: גבוהה נמצאו מקורות ראשוניים שמאפשרים לדייק את החילוק, אך הם עוסקים בכמה דינים נפרדים: (א) משנה כלאים ד,ב מגדירה „מחול הכרם” שבין הכרם לגדר וקובעת שיעור י״ב אמה; הרמב״ם, כלאים ז, יא–יג, מפרט את קרחת הכרם ומחול הכרם ואת שיעורי ההרחקה. (ב) הרמב״ם, כלאים ז, א–ד, מגדיר מתי שורות הגפנים מצטרפות לכרם אחד ומתי ריחוק של שמונה אמות מפריד ביניהן; כאן אכן ניכרת תלות גדר הכרם במבנה הגידולים ובמרחקיהם. (ג) הרמב״ם, כלאים ז, טו–יז, דן בגדר המבדיל בין כרם לירק: גדר עשרה ורוחב ארבעה, מחיצת קנים שהרווח בין קנה לקנה פחות משלושה, דין פרצה עד עשר אמות ופרצה מרובה על העומד, וכן מחיצת כרם שנפרצה. (ד) בירושלמי כלאים ח, ט מובא „אין האוסר נעשה מחיצה להציל” — שדה של גידול האסור בכלאיים אינו נעשה מחיצה המצילה את הגידולים שמאחוריו; ההכרעה המובאת שם היא שרק דבר המותר בזריעה יכול לשמש מחיצה להציל. לכן יש בסיס לדון בגדרי קרקע וגידולים ובתפקיד המחיצה בכלאיים, אך אין מקור יחיד שמנסח את המודל שלך כ„עירוב קרקע” במובן האונטולוגי. יש להציג את ההבחנות בין שם כרם, שיעורי הרחקה, מחיצה פיזית, והאפשרות של גידול אסור לשמש מחיצה, ואז לסמן את איחודן למודל אחד כחידוש המחבר.\u003c/p>"}, {"id": "536", "n": 81, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0962 | מחיצה בכלאיים – להעמיד את גדר ההפרדה מול גדרי שבת | חומרה: גבוהה המקור אינו רק דין הרחקה מופשט: הרמב״ם, הלכות כלאים ז, טו, כותב במפורש שגדר בגובה עשרה טפחים וחריץ בעומק עשרה וברוחב ארבעה מאפשרים ליטוע כרם מצד אחד וירקות מצד אחר; אף מחיצת קנים מועילה כאשר אין בין הקנים שלושה טפחים. בהלכה טז הוא קובע שגדר המבדיל שנפרץ עד עשר אמות נידון כפתח, ומבחין בפרצות מרובות בין עומד כפרוץ לפרוץ מרובה על העומד. בהלכה יח הוא מחיל „פי תקרה יורד וסותם” כהפרדה בין גפנים לירקות. נמצא שיש בכלאיים דין מחיצה ממש, אך תוצאתו היא היתר הזריעה משני צדדים ביחס לאיסור הגידולים, ולא בהכרח הגדרת רשות אחת או חלוקת רשות היחיד כפי שהן בשבת. הירושלמי כלאים ח,ט מוסיף שאין גידול האסור בכלאיים נעשה מחיצה להציל גידולים אחרים. לכן ההשוואה שלך למחיצת שבת יכולה לעמוד על הבדל בתכלית ובמושא ההפרדה; אין לומר שאין בכלאיים גדר מחיצה, אלא שיש לברר מה היא מפרידה ומהו הדין שהתיקון מתיר.\u003c/p>"}, {"id": "537", "n": 82, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0963 | „סדנא דארעא חד הוא” – מקורו ותנאי „חדא תשמישתא” | חומרה: גבוהה המקור המדויק הוא בבא בתרא סז ע״א: שמואל אומר שמי שמכר עשר שדות בעשר מדינות, אם החזיק באחת מהן קנה את כולן; הגמרא מנמקת „התם הוא דסדנא דארעא חד הוא וכולה חדא תשמישתא הוא”. כלומר, כבר בניסוח הגמרא מצורפים שני תנאים: חיבור התשתית הקרקעית, וגם אחדות השימוש. בבבא בתרא סז ע״ב הגמרא משווה לחולסית ומצולה ודוחה את ההשוואה משום „הא תשמישתא לחוד והא תשמישתא לחוד”; רשב״ם מסביר שהחולסית משמשת להוצאת חול והמצולה היא מקום מים/עומק, ולכן אלו שני שימושים ושני שמות. מכאן שהביטוי אינו קובע שכל הקרקעות מאוחדות בכל דין; הוא נאמר בדיני קניין חזקה, בצירוף אחדות התשתית ואחדות השימוש. אם אתה מבקש להעתיק ממנו עיקרון מושגי לרשות שבת, יש לציין במפורש שההעתקה היא אנלוגיה ולא דין הנלמד מן הסוגיה. שאלת האיים שבים אינה מוכרעת מן הביטוי לבדו.\u003c/p>"}, {"id": "538", "n": 83, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0964 | אוקיינוס המקיף את העולם – לקרוא את רצף הסוגיה בעירובין כב ע״ב | חומרה: גבוהה בעירובין כב ע״ב הגמרא דוחה את ההסבר שהיקף ארץ ישראל נובע מן הנהרות והגבולות, שהרי „כולי עלמא נמי מקיף אוקיינוס”, ומעמידה את הדיון במעלות ומורדות. לכן יש להבהיר שהאוקיינוס מובא במהלך כקושיה/דחייה, ולא כקביעה מוסכמת שמחיצת האוקיינוס אכן יוצרת רשות היחיד לכל העולם. החקירה שלך אם החסרון הוא במחיצה או בקרקע היא הרחבה פילוסופית מעבר למהלך המקומי, וצריך לסמן אותה ככזו.\u003c/p>"}, {"id": "539", "n": 84, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0965 | בית סאתיים, שש עשרה אמה ושתי מחיצות – שלושה שיעורים שונים | חומרה: גבוהה בפסקה נזכרים שיעור בית סאתיים, רוחב שש עשרה אמה ושתי מחיצות. יש להפריד בין שיעור שטח של מקום שהוקף שלא לדירה, תנאי רוחב רשות הרבים, ומספר המחיצות הנדרש לרשות היחיד. אין מקור אחד שמאפשר להסיק משיעור בית סאתיים על מגבלת גודל המחיצות או על דין שתי מחיצות. כדאי לציין ליד כל מספר את מקורו ואת תפקידו, ולבדוק במיוחד את הביטוי „יותר מט״ז אמה” כדי שלא יובן כשיעור שטח.\u003c/p>"}, {"id": "540", "n": 85, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0966 | סרטיא ומבואות מפולשין – להבחין בין דרך בין־עירונית לבין מעבר עירוני | חומרה: גבוהה יש להפריד בין שני מקורות ברש״י: בשבת ו ע״א, על ברייתת „ארבע רשויות”, רש״י מפרש „סרטיא – מסילה שהולכין בה מעיר לעיר”; „פלטיא” היא רחבת עיר שמתקבצים בה לסחורה; „מבואות” הם של עיר ורחבים שש עשרה אמה; ו„המפולשין” הם מבואות ששני ראשיהם פתוחים לפלטיא. לעומת זאת, בעירובין ו ע״ב, רש״י מתאר רשות הרבים עירונית, כגון ירושלים, כדרך המכוונת משער לשער ומפולשת, בצירוף רוחב שש עשרה אמה ודריסת ששים ריבוא לפי שיטתו. אלו אינם אותו ניסוח: „סרטיא” מוגדרת לפי תפקידה כדרך מעיר לעיר, ואילו „מפולש משער לשער” מתאר את צורתה של דרך עירונית מסוימת בהגדרת רשות הרבים. לכן ניתן לבחון את טענתך שסרטיא אינה זקוקה לצירוף שני ראשי רשות הרבים עירוניים, אך אין לייחס לרש״י הגדרה אחת המאחדת את שני המקרים. כמו כן, אין לבלבל בין מבוי מפולש לשני פלטיות לבין סרטיא עצמה.\u003c/p>"}, {"id": "1113", "n": 86, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-316 | סוג: כותרות חסרות | מקור: גרסאות עדכניות של החיבורים\u003c/p>\u003cp>כותרות תמצית חסרות לקטע זה (9 כותרות, מנוסחות בסגנון כותרות המשנה שבקובץ):\u003c/p>\u003cp>1. חמש סיבות במבוי שאינו רה\"י - ברייתא דיתר על כן ודברי ר' יהודה להתירו\u003c/p>\u003cp>2. ביאור דעת ר' יהודה להיתר - הכשר מקום הפרוץ לרה\"ר בלו\"ק וב' מחיצות מעולות\u003c/p>\u003cp>3. בטעם דלא הוי רה\"י ושריותא דר\"י בלו\"ק\u003c/p>\u003cp>4. הנשמע מסוגיא דד' רשויות בביאור הברייתא והצ\"ב\u003c/p>\u003cp>5. בירור כנ\"ל בסוגיא דלו\"ק משום מחיצה או היכר\u003c/p>\u003cp>6. בטעם דלא הוי רה\"י ושריותא דר\"י בלו\"ק - חמישה סיבות שהמקום אינו רה\"י ודברי ר\"י להתירו\u003c/p>\u003cp>7. טעם ר\"י להתיר - ביאור דעתו בכמה פנים בהכשר מקום הפרוץ לרה\"ר ובתיקון לו\"ק\u003c/p>\u003cp>8. הצריך ביאור בסוגיא דשבת - קושי בלשון גמורה דתני אתל וחריץ ומיעוט מדעת ר\"י\u003c/p>\u003cp>9. הצריך ביאור בסוגיא דעירובין (ו:) - קושי בגדר אין מערבין רה\"ר בכך ובראיה מדלתות ננעלות\u003c/p>"}, {"id": "541", "n": 87, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0967 | ברייתת שני בתים לעומת תנאי מבוי רגיל – להפריד בין שתי הסוגיות | חומרה: גבוהה יש להבחין בין נוסח הברייתא בעירובין יב ע״ב לבין הדיון בתנאי ההכשר הרגילים של מבוי. הברייתא עצמה אומרת: „מי שיש לו שני בתים בשני צידי רשות הרבים עושה לחי מכאן ולחי מכאן או קורה מכאן וקורה מכאן ונושא ונותן באמצע”. זהו מקרה של שני בתים המצויים משני צידי רשות הרבים, ולא נוסח מפורש של שתי חצרות ושני בתים בכל חצר. לעומת זאת, בהמשך אותו דף, בדיון על „בתים וחצרות פתוחות לתוכו” כתנאי למבוי, רש״י מפרש שתי חצרות ובית אחד לכל חצר; תוספות דנים בשתי חצרות ושני בתים בכל חצר; והרשב״א מביא את פירוש רש״י והראב״ד ודוחה את ההקלה של בית אחד בכל חצר, ומצריך שני בתים בכל חצר לפי הירושלמי והמקורות המקבילים. לכן יש להפריד בין מבנה המקרה של הברייתא לבין שיעור הדיורין הנדרש במבוי רגיל, ולהציג את מחלוקת הראשונים בתנאי הדיורין במקומה. אין לייחס את שיטות תוספות או הרשב״א לנוסח הברייתא עצמה.\u003c/p>"}, {"id": "542", "n": 88, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0968 | הברייתא דשני בתים – לסווג כל נתון לפי דין הרשות או תיקון הטלטול | חומרה: גבוהה יש להפריד בין שכבות הדין ולא למנות את כולן כסיבות חלופיות לאותו חסרון: (א) ברייתת שני הבתים בעירובין יב ע״ב אומרת „מי שיש לו שני בתים בשני צידי רשות הרבים עושה לחי מכאן ולחי מכאן או קורה מכאן וקורה מכאן ונושא ונותן באמצע”; חכמים משיבים „אין מערבין רשות הרבים בכך”. (ב) באותו דף נחלקו אם לחי משום מחיצה וקורה משום היכר (רב יהודה ורבה) או שניהם משום היכר (רבא); ובהמשך נאמר שרבי יהודה סובר שתי מחיצות דאורייתא. לכן מספר המחיצות ומעמד הלחי נוגעים לשאלת הגדרת הרשות מן התורה. (ג) „בקעי ביה רבים” עשוי להיות נתון הנוגע לביטול מחיצות או לאופי המעבר, אך יש לבדוק בכל סוגיה אם הוא נידון בפועל ולא להוסיף אותו כסיבה אוטומטית. (ד) תיקון בלחי וקורה מתיר טלטול במבוי שאינו מפולש, אך אין להסיק ממנו כשלעצמו שכל רשות הרבים נעשית רשות היחיד; זו בדיוק נקודת המחלוקת שבברייתא. רצוי למיין את הנתונים לפי ארבע שאלות: מעמד המקום מן התורה; איכות ומניין המחיצות; דין בקיעת הרבים; והכשר הטלטול מדרבנן. כך יהיה אפשר לברר אם רבי יהודה חולק בהגדרת הרשות, בהיקף התיקון, או בשניהם.\u003c/p>"}, {"id": "1114", "n": 89, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-317 | סוג: קטע חסר | מקור: 04_רשויות/רשויות.pdf\u003c/p>\u003cp>מיקום השילוב המוצע: לאחר הפסקה שלפני הערה זו (\"ובגמ' ביארו דעת ר\"י להיתר בכמה פנים, בהכשר מקום רה\"ר ולמקום הפרוץ לרה\"ר, בגדר תיקון לחי וקורה משום היכר או מחי...\").\u003c/p>\u003cp>הקטע משתלב כאן כהמשך ישיר לדברים שלפניו; אין צורך בקטע קישור.\u003c/p>\u003cp>נוסח הקטע:\u003c/p>\u003cp>בטעם דלא הוי רה\"י ושריותא דר\"י בלו\"ק\u003c/p>\u003cp>טעם ר\"י להתיר\u003c/p>\u003cp>הצריך ביאור בסוגיא דשבת\u003c/p>"}, {"id": "543", "n": 90, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0969 | מפת סוגיות רבי יהודה – לא לאחד את כל הדיונים לראיה אחת | חומרה: גבוהה הרשימה משלבת סוגיות ממקומות שונים: עירובין ו ע״ב (דלתות והכשר מבואות), יב ע״ב (לחי משום מחיצה/היכר ושתי מחיצות דאורייתא), כ ע״א (פסי ביראות וכוח מחיצות), וכב ע״א–ע״ב (מחלוקת רבי יהודה וחכמים, מעלות ומורדות ותל המתלקט). מומלץ לציין ליד כל טענה את הדף המדויק ואת השאלה הנדונה בו. כך ניתן יהיה לבדוק אם מדובר בשיטות מקבילות, ביישובים של סתירות, או בהצעה מושגית של המחבר.\u003c/p>"}, {"id": "544", "n": 91, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0970 | ברייתת „תל וחריץ” – להבחין בין שיעור ארבעה לבין מספר המחיצות | חומרה: גבוהה בשבת ו ע״א ברייתת רשויות מגדירה חריץ עמוק עשרה ורחב ארבעה וגדר גבוה עשרה ורחב ארבעה כרשות היחיד גמורה. „ארבעה” כאן הוא רוחב המקום, ולא נאמר שיש בכל אחד מהם ארבע מחיצות נפרדות. לכן יש להיזהר מלהשתמש בתל ובחריץ כראיה ישירה למספר הדפנות. יש להפריד בין ממדי המשטח, עומק/גובה, והיקף המחיצות, ולבדוק מה בדיוק מבקשת הגמרא למעט בדעת רבי יהודה.\u003c/p>"}, {"id": "545", "n": 92, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0971 | „גמורה” בתל וחריץ – להבחין בין שתי שאלות הגמרא בשבת ו ע״ב | חומרה: גבוהה בפסקה זו נדונה ההופעה הראשונה של „גמורה” בשבת ו ע״ב: „זו היא רשות היחיד גמורה”. על השאלה „ואמאי קרו ליה גמורה” משיבה הגמרא: „מהו דתימא כי פליגי רבנן עליה דרבי יהודה דלא הוי רה״י, הני מילי לטלטל אבל לזרוק מודו ליה, קמ״ל”. רש״י מפרש על „קמ״ל גמורה”: „זו היא שנגמרו מניין מחיצות שלה שיש לה מחיצות מכל צד”, ומביא כדוגמה חריץ וגדר הנידונים בגוד אסיק מארבעה צדדים. רק בהמשך, בהופעה השנייה — „זו היא רשות הרבים גמורה” — נשאלת שוב השאלה „ואמאי קרו ליה גמורה”, ועליה בא התירוץ „איידי דתנא רישא גמורה תנא נמי סיפא גמורה”. לפיכך אין לייחס את תשובת „איידי” ל„רשות היחיד גמורה” או לתל וחריץ; היא מתייחסת למונח „רשות הרבים גמורה” שבסיפא. לדיון שלך בתל וחריץ יש להעמיד את תשובת „קמ״ל” ואת פירוש רש״י בדבר השלמת מניין המחיצות. עם זאת, יש להבחין בין פירוש רש״י למונח „גמורה” לבין המסקנה המושגית שלך בדבר היחס בין ארבע מחיצות לבין חסרון בשתי מחיצות; המסקנה האחרונה עדיין טעונה ביסוס עצמאי.\u003c/p>"}, {"id": "1115", "n": 93, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-318 | סוג: הערת שוליים | מקור: שמעתתא דרשות הרבים ומבטלי מחיצתא, שמעתתא עותק 2 (הערת שוליים 8)\u003c/p>\u003cp>נושא ההערה: פריצת מזרח ומערב של ירושלים ונעילת דלתות; נכתבה על דברי הריטב\"א בגדר ארומ\"מ.\u003c/p>\u003cp>נכתבה במקור כהערת שוליים על: ד] בגדר דין ארומ\"מ משמע בלשון הריטב\"א שהם מבטלין גם המחיצות עצמן על פני כל הרוח ולא רק כנגד הפרוץ שלא ייחשב סתום, וז\"ל \"שמפילין מחיצות שבמזרח ומערב כיון שבוקעין בהם תדיר דרך הפתחים וכאילו אין שם פתח ו\u003c/p>\u003cp>נוסח ההערה:\u003c/p>\u003cp>לכאורה כוונתו לומר דלא מסתבר שהיו מזרח ומערב דירושלים פרוצין במילואם בלא צורת הפתח ובלא גיפופי, וא\"כ מוכח כדכתב דמהני בקיעת הרבים לבטלם.\u003c/p>"}, {"id": "1116", "n": 94, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-319 | סוג: הערת שוליים | מקור: שמעתתא דרשות הרבים ומבטלי מחיצתא, שמעתתא עותק 5 (הערת שוליים 4)\u003c/p>\u003cp>נושא ההערה: דין דלתות במבוי ששימושו מעבר; נכתבה על דברי תוס' במוציא מחנות לפלטיא.\u003c/p>\u003cp>נכתבה במקור כהערת שוליים על: תו יש להעיר בדבריהם, דהקשו על המקשן, אבל בעצם זו קושיא בדברי ריו\"ח גופיה אמאי הצריך שתי דלתות ולא סגי בחד, אכן י\"ל דהא לא קשיא דהוא דיבר על מציאות שהדלתות ננעלות בלילה אבל ביום פתוחות הם, וא\"כ מצד הלכ\u003c/p>\u003cp>נוסח ההערה:\u003c/p>\u003cp>עוד י\"ל דדוקא במבוי דשימושו מעבר (מבוא), לא מהני דלתות אי לאו בנעילה ביוצא ונכנס.\u003c/p>"}, {"id": "546", "n": 95, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0972 | „אין מערבין רשות הרבים בכך” – להשוות את שאלת הגמרא לתשובת רב יהודה | חומרה: קריטית לבירור בעירובין ו ע״ב הגמרא מקשה מן הברייתא על האפשרות לערב רשות הרבים, אך רב יהודה מפרש שהברייתא עוסקת ב„מבואות המפולשין לרשות הרבים”. לכן יש להבחין בין השאלה הראשונית שנוסחה בלשון „רשות הרבים” לבין מסקנת הסוגיה, המצמצמת את הדיון למבואות. אם החקירה שלך מבקשת להחזיר את הדיון לרשות הרבים עצמה, יש לנמק מדוע דוחים את פירוש רב יהודה או מה נותר ממנו לאחר התירוץ.\u003c/p>"}, {"id": "547", "n": 96, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0973 | צורת הפתח, דלת ומחיצה מעלייתא – אין לזהות בין שלושת התיקונים | חומרה: גבוהה הפסקה משווה צורת הפתח, דלתות ננעלות ולחי/קורה כמחיצות, אך הסוגיות מבחינות ביניהם. בעירובין ו ע״ב צורת הפתח מועילה למבואות המפולשין לרשות הרבים בצד אחד, ואילו בירושלים נזכרות דלתות הננעלות בלילה. בעירובין יב ע״ב נידונה השאלה אם לחי הוא משום מחיצה או היכר. יש להציג כל תיקון לפי תפקידו ומיקומו, ולא להסיק שכל מה שמקבל שם „מחיצה” מועיל באותה מידה לביטול בקיעת רבים או להגדרת רשות היחיד.\u003c/p>"}, {"id": "1117", "n": 97, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-320 | סוג: קטע חסר | מקור: 04_רשויות/רשויות.pdf\u003c/p>\u003cp>מיקום השילוב המוצע: לאחר הפסקה שלפני הערה זו (\"והנה לקמן מותבינן לרבא דאמר לחי משום היכר מר\"י דהו\"א דס\"ל ג' מחיצות דאורייתא, והקשו בתוס' דעד דאתה מקשה מר\"י ס...\").\u003c/p>\u003cp>הקטע משתלב כאן כהמשך ישיר לדברים שלפניו; אין צורך בקטע קישור.\u003c/p>\u003cp>נוסח הקטע:\u003c/p>\u003cp>והנה בסוגיין מצאנו שלושה גדרים והן א .דשיעור כ' הוא משום היכרא ואינו שייך לגדר פתח ,ויש לדון האם לדעה זו הכוונה שאמנם פתח הוא עד כ' כמו שמצאנו בהיכל ,אך אין זה סיבת שיעור כ' .ובזה יש לומר שני פנים ,או משום דאין הכשר מבוי נוגע לגדר פתח ,או דגדר פתח האמור הוא רק ביחס לפתח ללא קורה ,אך קורה כמו צורת הפתח יש לה כח להגדיר פתח אף ביותר מעשרים ,או שנאמר דלא ילפינן גדר פתח מהיכל כלל משום שאין הגבלת גובהו משום פתח אלא מסיבה אחרת ,ב .דשיעור כ' נלמד מפתחו של היכל וממילא בביאור דברי רב דילפינן דין כ' מפתחו של היכל נראה דאנן צריכים לכמה הקדמות ,והיינו שדין כ' דמבוי נובע מגדר פתח ,וזה כולל שני דברים ,דדין קורה אינו מועיל אלא בצירוף גדר פתח ,וזה משום דהכשר מבוי נעשה ע\"י גדר פתח .וכן שגודל מבנה כניסת ההיכל מוגבל ע\"י גדר פתח (דהא משמע דאי אף פתחו של אולם היה נקרא פתח אין\u003c/p>\u003cp>לרבנן ללמוד מפתחו הקטן יותר של ההיכל דהא אית לן בסוגיין שלושה גדרים\u003c/p>"}, {"id": "548", "n": 98, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0974 | תוספות בסוגיית דלתות – להפריד בין שני מהלכי התירוץ | חומרה: גבוהה בתוספות עירובין ו ע״ב, ד״ה „והאמר רבה”, מובאים שני מהלכים, ואין לצרף אותם לתירוץ יחיד. לפי המהלך הראשון (המבאר את פירוש רש״י), אם שתי מחיצות הבתים קיימות והדלת הננעלת יוצרת מחיצה שלישית, היה מקום לומר שיש כאן שלוש מחיצות דאורייתא; תוספות משיבים ששלוש מחיצות נחשבות דאורייתא דווקא כשהן „גמורות”, ואילו כאן השלישית נעשית באמצעות דלת, ולכן נדרשת גם דלת ברוח הרביעית. לאחר מכן תוספות כותבים „ולר״י נראה” שהקושיה אינה מניחה שבית הלל מצריכים נעילה כלל, משום שבברייתא לא פורשה אצלם נעילה כמו אצל בית שמאי. בהמשך הם מציעים דרך נוספת להבין את ההשוואה: כשם שלרבי יהודה שם ארבע מחיצות שאינן חשובות גורם לדרישת נעילה, כך לרבנן שתי מחיצות שאינן חשובות עשויות להצריך נעילה; והם מפנים לעירובין כב ע״א. לכן יש לציין את שני המהלכים בנפרד. אין להציג את דברי תוספות כקביעה כללית שחכמים תיקנו תמיד שלוש מחיצות גמורות מדרבנן, או כהוכחה שכל המבוי בעל שתי מחיצות אינו רשות היחיד מן התורה. יש להבחין בין איכות המחיצות, היות השלישית באמצעות דלת, הצורך בנעילה בפועל או בדלת הראויה להינעל, ודרישת ההכשר לטלטול.\u003c/p>"}, {"id": "549", "n": 99, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0975 | „רבנן סברי שלוש מחיצות דאורייתא” – לבדוק אם זו מסקנה הכרחית | חומרה: גבוהה הגמרא בעירובין יב ע״ב מיישבת את רבי יהודה בכך שהוא סובר שתי מחיצות דאורייתא. אין מכאן לבדו הוכחה מפורשת שחכמים סוברים דווקא שלוש מחיצות דאורייתא; ייתכנו הבדלים בין הגדרת רשות היחיד מן התורה לבין תנאי היתר המבוי מדרבנן. אם זו מסקנתך מתוך הברייתא או מדברי התוספות, יש להביא את המקור ולהראות את ההיסק. כמו כן, יש להפריד בין שיטת רבא בקורה משום היכר לבין שאלת מספר המחיצות.\u003c/p>"}, {"id": "1118", "n": 100, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-321 | סוג: קטע חסר | מקור: 01_גרסאות_הספר/מלאכת שבת רשויות עירובי חצירות תחומין.pdf / 04_רשויות/רשויות - עותק 2.docx\u003c/p>\u003cp>מיקום השילוב המוצע: לאחר הפסקה שלפני הערה זו (\"והנה לקמן מותיב אביי לרבה מהאי ברייתא דבהכרח דס\"ל לר\"י ב' מחיצות דאורייתא ואודי ליה, וקשה דהכא משמע דאיכא למימ...\").\u003c/p>\u003cp>הקטע משתלב כאן כהמשך ישיר לדברים שלפניו; אין צורך בקטע קישור.\u003c/p>\u003cp>נוסח הקטע:\u003c/p>\u003cp>בביאור שאלת ר' זירא וההבדל בין גדר פס לגדר לחי\u003c/p>"}, {"id": "550", "n": 101, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0976 | רבה ורבא – לדייק את שם בעל המימרה ואת הנחת הקושיה | חומרה: גבוהה בפרק זה מופיעים רבה ורבא בשאלת לחי משום מחיצה/היכר, וההבחנה ביניהם מהותית: רבה סובר לחי משום מחיצה וקורה משום היכר, ואילו רבא סובר ששניהם משום היכר. לכן יש לוודא בכל שלב אם אביי מקשה לרבה או לרבא, ומהי השיטה שממנה נובעת הקושיה. אין להסיק מהקושיה על שיטת רבה מסקנה על רבא, או להפך. מומלץ לציין את לשון הגמרא בעירובין יב ע״ב במדויק ולהעמיד את רצף השקלא וטריא.\u003c/p>"}, {"id": "1119", "n": 102, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-322 | סוג: כותרות חסרות | מקור: גרסאות עדכניות של החיבורים\u003c/p>\u003cp>כותרות תמצית חסרות לקטע זה (9 כותרות, מנוסחות בסגנון כותרות המשנה שבקובץ):\u003c/p>\u003cp>1. ארבעה דינים נפרדים בסוגיית מעלות - דגלי מדבר, אתי רבים, ניחא תשמישתיה, ומסור לרבים\u003c/p>\u003cp>2. חילוק גדר ניחא תשמישתיה דשבילי בית גלגול מהנ\"ל\u003c/p>\u003cp>3. בירור בשייכות תנאי דניחא תשמישתיה לגבי דין אתי רבים וכו'\u003c/p>\u003cp>4. חילוק גדר הילוך ברה\"ר משימושה ובירור באיזה מהם אמרו דאתו רבים\u003c/p>\u003cp>5. בירור במשמעות שימוש הרבים להגדרת רה\"ר\u003c/p>\u003cp>6. חילוקי דינים שמצאנו בסוגיא - ארבעה דינים נפרדים דגלי מדבר אתי רבים ניחא תשמישתיה ומסור לרבים\u003c/p>\u003cp>7. גדר ניחא תשמישתיה - חילוק בין הילוך הרבים המגדיר רשות לשימוש הנוגע לחיבור מקום לרשות\u003c/p>\u003cp>8. ביאור גדר הנ\"ל - הילוך הרבים מגדיר את הקרקע כרה\"ר ושימוש מחבר מקום למשמעות אחת עם הקרקע\u003c/p>\u003cp>9. חילוק גדר ניחא תשמישתיה דשבילי בית גלגול מהנ\"ל - נוגע להגדרת רה\"ר עצמה ולא לביטול מחיצות\u003c/p>"}, {"id": "551", "n": 103, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0977 | ארבעת הדינים בסוגיית מעלות ומורדות – למיין לפי לשון הגמרא | חומרה: גבוהה בעירובין כב ע״ב מופיעים ברצף: מעלות ומורדות בארץ ישראל שאינן כדגלי מדבר; ספק תל המתלקט לשיטת רבי יהודה; חצר שהרבים נכנסים בה מצד אחד ויוצאים מצד אחר; ושבילי בית גילגול, שבהם יהושע מסר לרבים את הדרכים שנוח תשמישן. החלוקה לארבעה דינים היא הצעה טובה, אך יש להבהיר אילו מהם הם תנאי בהגדרת רשות הרבים, אילו בביטול מחיצה, ואילו נובעים ממסירת הדרך לרבים. אין לייחס את כולם לאותו מנגנון של שימוש.\u003c/p>"}, {"id": "552", "n": 104, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0978 | „ניחא תשמישתיה” בתל המתלקט – לשלב את תירוץ התוספות המפורש | חומרה: קריטית לבירור בעירובין כב ע״ב נשאל אם רבים הבוקעים בתל המתלקט עשרה מתוך ארבע מבטלים את המחיצות לשיטת רבי יהודה, והגמרא משיבה „חייבין”, ואף אם עולים בחבל ובמעלות בית מרון. אין לקרוא מכאן ש„ניחא תשמישתיה” הוא תנאי אחיד לכל המקרים. תוספות (ד״ה „ואיזהו שבילי בית גלגול”) מבהירים ששבילי בית גילגול היו אף הם מתלקטים עשרה מתוך ארבע, אך לא היו נוחים כלל; נדרש שלא יהיו עשויים כמדרגה, כדי שלא תהיה המחיצה „נדרסת” ולא תיחשב מחיצה. תוספות מוסיפים שדווקא שבילי בית גילגול אינם נוחים כלל, ואילו מבוי מפולש לבורות וחצר שהרבים נכנסים בה מצד אחד ויוצאים מצד אחר עשויים להיחשב רשות הרבים לרבי יהודה, אף שהם של יחיד, כאשר נוח תשמישם והם ראויים להימסר לרבים, מכוח בקיעת הרבים. יש להבחין אפוא בין צורת התל והשיפוע היוצרים מחיצה של עשרה מתוך ארבעה; נוחות המעבר והחשש למחיצה נדרסת; מסירת הדרך לרבים בארץ ישראל; ובקיעת רבים בפועל. לפי רש״י ותוספות, „חייבין” בתל המתלקט אינו סותר את החריג של מעלות ומורדות שנמסרו ליחיד בארץ ישראל: רש״י ותוספות מעמידים את החיוב האמור בתל בשאר ארצות, ולא בדרכים שלא נמסרו לרבים בארץ ישראל. יש להביא את תירוץ התוספות במפורש, ולא להשאיר את המתח כקושיה פתוחה.\u003c/p>"}, {"id": "553", "n": 105, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0979 | הילוך רבים ותשמיש רבים – להבחין בין שני מבחנים ולא למזגם | חומרה: גבוהה בשבת ק ע״ב הגמרא מבחינה במפורש: „הילוך על ידי הדחק שמיה הילוך, תשמיש על ידי הדחק לא שמיה תשמיש”. זהו מקור ישיר להבחנה שאתה מציע, אך יש לדייק את תחולתו: הסוגיה שם עוסקת ברקק מים ובשאלת צירופו לרשות הרבים, ולא בהכרח בכל גדרי ביטול מחיצה. לעומת זאת, בעירובין כב ע״ב נאמר בתל המתלקט „חייבין ואפילו עולין לו בחבל”. יש להראות כיצד שני המקורות מצטרפים למודל שלך, ולא להפוך את ההבחנה המקומית לכלל כולל בלי שלב ביניים.\u003c/p>"}, {"id": "554", "n": 106, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0980 | „רשות היחיד לשבת ורשות הרבים לטומאה” – לדייק את דין ספק הטומאה ואת מחלוקת רבי אלעזר | חומרה: גבוהה המקור הוא משנה טהרות ו,ו: „ספק רשות היחיד טמא... ספק רשות הרבים טהור”, ובהמשך נמנים שבילי בית גילגול והדרכים המפולשות לבורות, לשיחין, למערות ולגיתות כרשות היחיד לשבת ורשות הרבים לטומאה. „רשות הרבים לטומאה” כאן היא סיווג לצורך דיני ספק טומאה, ולא קביעה שהמקום הוא רשות הרבים לעניין שבת או שהוא בבעלות ציבורית. יש לציין גם את דעת רבי אלעזר באותה משנה: „לא הוזכרו שבילי בית גילגול אלא שהם רשות היחיד לכך ולכך”; אין להציג את דין שבילי בית גילגול כאילו הוא מוסכם. חצר שהרבים נכנסים בה בפתח אחד ויוצאים באחר מופיעה בנפרד במשנה טהרות ו,י. לכן יש להבחין בין הדוגמאות ובין ההקשר של כל אחת, ולא לצרף אותן למעמד אחד. בעירובין כב ע״ב הגמרא דנה בדוגמאות כדי לברר את שיטת רבי יהודה בבקיעת רבים, אך משיבה שהברייתא הובאה לצורך דין רשות הרבים לטומאה. יש אפוא להגדיר בדיוק מה לומדים מן הסיווג לטומאה ומה אין ללמוד ממנו ביחס להוצאה ולטלטול בשבת.\u003c/p>"}, {"id": "1120", "n": 107, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-323 | סוג: כותרות חסרות | מקור: גרסאות עדכניות של החיבורים\u003c/p>\u003cp>כותרות תמצית חסרות לקטע זה (13 כותרות, מנוסחות בסגנון כותרות המשנה שבקובץ):\u003c/p>\u003cp>1. הגדרת שימוש הרבים בקרקע בפועל - חילוק בין א\"י שיש בה גדר חיובי לחו\"ל\u003c/p>\u003cp>2. בירור מקום להיחשב רשות הרבים - קושי כיצד יגדיר יהושע דין חדש מחוץ למדבר\u003c/p>\u003cp>3. שימוש האמור מוגדר ע\"י השימוש בפועל וחלוק גדרו בא\"י מבשאר ארצות\u003c/p>\u003cp>4. בירור חילוק שימוש הרבים כתנאי דרשות משימוש היחיד\u003c/p>\u003cp>5. בירור בגדר מקום להיחשב רה\"ר\u003c/p>\u003cp>6. גדר שימוש הרבים במשמעות סוג השימוש\u003c/p>\u003cp>7. גדר שימוש הרבים הוא בשימוש בפועל\u003c/p>\u003cp>8. גדר שימוש הרבים בסוג השימוש ולא (רק) ברוב המשתמשים\u003c/p>\u003cp>9. בירור חילוק שימוש הרבים כתנאי דרשות משימוש היחיד - הגדרה מוקדמת לשימוש בפועל בקרקע עצמה\u003c/p>\u003cp>10. בגדר תיקון יהושע ע\"פ הנ\"ל - יהושע קבע מהו הראוי לרבים ע\"י תיקון דרכים במקום שתשמישו נח\u003c/p>\u003cp>11. גדר מקום כרשות ברה\"י וברה\"ר - שלבים בהגדרת מקום מקרקע לשימוש הילוך או תשמיש\u003c/p>\u003cp>12. גדר שימוש הרבים הוא בשימוש בפועל - חילוק בין א\"י שיש בה גדר חיובי לשאר ארצות שאין בהן\u003c/p>\u003cp>13. בירור בגדר מקום להיחשב רה\"ר - קושי כיצד יגדיר יהושע דין חדש ברה\"ר שנאמר כבר לגבי מדבר\u003c/p>"}, {"id": "1121", "n": 108, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-324 | סוג: הערת שוליים | מקור: שמעתתא דרשות הרבים ומבטלי מחיצתא, שמעתתא עותק 2 (הערת שוליים 1)\u003c/p>\u003cp>נושא ההערה: גדר \"מסור לרבים\" כגדר נפרד או כגדר אחד ברשות; נכתבה על שיטת הרשב\"א בדלת נעולה ברה\"ר.\u003c/p>\u003cp>נכתבה במקור כהערת שוליים על: א] הא דמהני דלת ננעלת ברה\"ר הוא משום דאין רה\"ר אלא המסור לרבים כל שעה, כלומר וכיון שבלילה אינו מסור שוב לא הוי רה\"ר כל היממה . וסגי בדלת אחת .\u003c/p>\u003cp>נוסח ההערה:\u003c/p>\u003cp>נקט דמסור לרבים הוי גדר נפרד ושלם אכל עת ועת לחודיה, ויתכן באופ\"א דהוי גדר אחד ברשות, והיינו, דמאחר שאין כניסה לרבים בלילה כבר חשיב אינו מסור לרבים כלל, ונפק\"מ אי שייכא בזה רוב, וכן שיהיו שעות או ימים שאין חשובים להיות פתיחתם או נעילתם גדר בשם הרשות כמסורה לרבים.\u003c/p>"}, {"id": "1122", "n": 109, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-325 | סוג: הערת שוליים | מקור: שמעתתא דרשות הרבים ומבטלי מחיצתא, שמעתתא עותק 2 (הערת שוליים 2)\u003c/p>\u003cp>נושא ההערה: משמעות לשון \"סגי\" בהגדרת מסירות המקום לרבים; נכתבה על שיטת הרשב\"א בדלת נעולה.\u003c/p>\u003cp>נכתבה במקור כהערת שוליים על: א] הא דמהני דלת ננעלת ברה\"ר הוא משום דאין רה\"ר אלא המסור לרבים כל שעה, כלומר וכיון שבלילה אינו מסור שוב לא הוי רה\"ר כל היממה . וסגי בדלת אחת .\u003c/p>\u003cp>נוסח ההערה:\u003c/p>\u003cp>לשון \"סגי\" משמע שיש לכל צד בנפרד להיות מגדיר הרשות כמסורה לרבים, אבל הפשטות היא דאין חשוב מסור לרבים אלא בהיעדר כל הגבלה דכניסה ויציאה, ובדלת אחת כבר חשיב הרשות אין מסורה לרבים.\u003c/p>"}, {"id": "555", "n": 110, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0981 | שימוש הרבים כתנאי – להפריד בין מספר המשתמשים לבין סוג השימוש | חומרה: גבוהה בפסקאות אלו נבנית הגדרה מוקדמת של „שימוש הרבים”, שאינה מסתכמת בריבוי האנשים המשתמשים בפועל. יש להבחין בין שלושה רכיבים: מספר המשתמשים, אופי הפעולה (הילוך לעומת תשמיש), והיות המקום מיועד או נמסר לשימוש ציבורי. הסוגיות בעירובין ו ע״א וכב ע״ב אינן מנסחות את שלושתם כמושג אחד. אם „שימוש הרבים” הוא תנאי עצמאי, יש לקבוע מהו המבחן הניתן לזיהוי לפני השימוש בפועל, ומהו מקורו.\u003c/p>"}, {"id": "1123", "n": 111, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-326 | סוג: הערת שוליים | מקור: שמעתתא דרשות הרבים ומבטלי מחיצתא, שמעתתא עותק 2 (הערת שוליים 3)\u003c/p>\u003cp>נושא ההערה: שני גדרי שימוש רבים במקום והגדרת רה\"ר; נכתבה על הדיון בפלטיא.\u003c/p>\u003cp>נכתבה במקור כהערת שוליים על: ג] בפלטיא לא מהני דלתות נעולות לאפוקה מתורת רה\"ר, וביאר בית אפרים דאזיל לשיטתו שטעם תועלת נעילת הדלת הוא כי לא מסור לרבים כל שעה, וממילא זה ניחא ברה\"ר שכל ענינה שהיא 'דרך הרבים' לעבור ולילך מעיר לעיר \u003c/p>\u003cp>נוסח ההערה:\u003c/p>\u003cp>לכאורה צ\"ל דאין כוונתו (דהבי\"א) דאיתא לשני גדרי שימוש דרבים במקום, וכל חד חשוב להגדיר מקום המיועד לו כרה\"ר, דא\"כ יהא שם רה\"ר (היינו, יעוד ומוכנות מקומה) משני פנים וזה רחוק, ואפ\"ל דעיקר שם רשות הרבים הוא בהיות מקום מסור לרבים, ושייכא בכמה אנפי לפום צורך הרבים, וסרטיא ומבואות המפולשין מדרך שימושם הוה נעילתם דלתות מניעתם משא\"כ וכו'.\u003c/p>"}, {"id": "556", "n": 112, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0982 | „ס׳ ריבוא” – לציין את מקור רש״י ואת גבולות שיטתו | חומרה: גבוהה המקור המדויק הוא רש״י עירובין ו ע״ב, ד״ה „ירושלים”: „ויש בה דריסת ששים ריבוא ורחב שש עשרה אמה”; וכן בד״ה „אבולי דמחוזא” הוא מזכיר עיר שבה היו ששים ריבוא. אין להציג תנאי זה כנתון מפורש בגמרא בכל סוגיית הגדרת רשות הרבים. הרמב״ן בעירובין נט ע״א מביא את שיטת רש״י ומקשה: „לא ידענו מנין לו לרש״י כן שלא הוזכר בתלמוד בשום מקום”, ומציין שמצא כך בהלכות גדולות. לכן יש לייחס את תנאי שישים הריבוא לשיטת רש״י ולמסורת המובאת בבה״ג, ולא כתנאי מוסכם לכל הראשונים; יש לציין גם את השיטות החולקות. לשון רש״י „דריסת ששים ריבוא” אינה מכריעה לבדה אם נדרשת תנועה של מספר זה בכל רחוב ורחוב, או שמדובר בעיר שיש בה דריסת רבים בהיקף זה. יש להגדיר את מדד השימוש על פי המקור והפסיקה שעליהם המחבר מסתמך, ולא להציגו כמבחן מוסכם.\u003c/p>"}, {"id": "557", "n": 113, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0983 | היקף תקנת יהושע – להגדיר את קבוצת הדרכים שעליה היא חלה | חומרה: גבוהה לשון הגמרא כוללת „דרכים וסרטיא”, ולצדה את שבילי בית גילגול. יש לברר אם מדובר בכל סוגי המרחבים הציבוריים או דווקא בדרכים ובנתיבי מעבר. אין להרחיב ממנה אוטומטית להגדרת חצרות, רחבות, שווקים או כל קרקע שמשמשת רבים. הבחנה זו חשובה במיוחד משום שהמודל בפרק מבקש לתלות את מעמד הקרקע בסוג השימוש הציבורי.\u003c/p>"}, {"id": "558", "n": 114, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0984 | „יהושע אוהב ישראל היה” – להבחין בין תיקון דרכים לבין חקיקת גדר רשות | חומרה: גבוהה בעירובין כב ע״ב נאמר: „עמד ותיקן להם דרכים וסרטיא; כל היכא דניחא תשמישתא מסרה לרבים, וכל היכא דלא ניחא תשמישתא מסרה ליחיד”. הסוגיה מתארת תיקון ומסירה של דרכים בארץ ישראל. היא אינה אומרת במפורש שיהושע קבע הגדרה כללית של „שימוש הרבים” לכל דיני רשות הרבים. יש להציג את ההרחבה שאתה מציע כחידוש פרשני, ולברר אם „מסרה ליחיד” פירושו הקצאה קניינית, ייעוד שימושי, או תיאור של מעמד הדרך.\u003c/p>"}, {"id": "559", "n": 115, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0985 | „סוג השימוש” לעומת מספר המשתמשים – להגדיר מבחן הלכתי | חומרה: גבוהה ההבחנה בין שימוש רבים ככמות משתמשים לבין שימוש רבים כסוג שימוש היא חידוש מרכזי במודל. כדי שתהיה ניתנת לבדיקה, יש להגדיר מהו „סוג” שימוש: הילוך רציף, מעבר ציבורי, תשמיש המשרת את הדרך, או שימוש המיועד לרבים. יש גם להראות נפקא מינה: האם דרך שבה עוברים מעט אנשים אך היא פתוחה ומיועדת לרבים תיחשב רשות הרבים? ומה דין דרך פרטית שבה עוברים רבים בפועל? בלי דוגמאות נגדיות, המושג עלול להחליף את עצמו לפי הצורך.\u003c/p>"}, {"id": "560", "n": 116, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0986 | מודל השלבים – להציג את הסדר כניתוח המחבר ולא כמבנה מפורש בש״ס | חומרה: גבוהה החלוקה לשלבים — קרקע כמקום להנחת חפץ, נפרדות רשות היחיד, שימוש הילוך ברשות הרבים, ושימושים נוספים — היא מסגרת מסכמת של המחבר. יש להקפיד שלא להציג אותה כחלוקה מפורשת של הגמרא. מומלץ להצמיד לכל שלב את המקור שממנו נלקח הנתון, ולהוסיף ציון ברור כאשר המעבר בין המקורות הוא היסק שלך. כך הקורא יוכל להבחין בין מקור, פרשנות, ומבנה עיוני חדש.\u003c/p>"}, {"id": "561", "n": 117, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0987 | חילוק ארץ ישראל וחו״ל – להציג את מחלוקת הראשונים בין מישור המדבר למסירת הדרך | חומרה: קריטית לבירור בעירובין כב ע״ב אין להציג הסבר אחד מוסכם לחריג של מעלות ומורדות בארץ ישראל. רש״י מפרש „שאינן כדגלי מדבר” בכך שארץ המדבר הייתה חלקה והענן השווה אותה; לשיטתו החיוב בתל המתלקט נאמר בשאר ארצות, ואילו מעלות ומורדות שבארץ ישראל אינן רשות הרבים. תוספות כותבים שמעלות ומורדות נאמרו דווקא בארץ ישראל, ואילו בחוצה לארץ חייבים עליהן לשיטת רבי יהודה; לשיטת חכמים אין בקיעת רבים מבטלת מחיצה. הם גם מבחינים בין שבילי בית גילגול שאינם נוחים כלל לבין מבוי וחצר הנוחים לשימוש וראויים להימסר לרבים, העשויים להיחשב רשות הרבים לרבי יהודה אף שהם של יחיד. הריטב״א דוחה את הסבר המישור של רש״י: אם כל רשות הרבים נלמדת מדגלי מדבר משום שהמדבר היה מישור, היה צריך להחיל זאת גם בבבל ובשאר ארצות. הוא מפרש שהמעלות והמורדות לא נמסרו לרבים בידי יהושע מפני שלא היו נוחות לשימוש, שלא כדרכי המדבר שהיו מסורות לרבים. הרשב״א דן ביישוב קרוב על יסוד קושיית הראב״ד משבת ק ע״א: תל המתלקט עשרה מתוך ארבעה עשוי להיחשב רשות היחיד כאשר אין רבים בוקעים בו; בקיעת רבים עשויה להפוך אותו לרשות הרבים בחוצה לארץ, ואילו בארץ ישראל יהושע לא מסר את המעלות והמורדות לרבים אלא ליחידים. עם זאת הרשב״א משאיר קושי מפורש: אם בקיעת רבים משווה את המקום לדגלי מדבר, מדוע גשרים מפולשים ומקורים, שאינם דומים לדגלי מדבר, אינם נעשים רשות הרבים אף שרבים בוקעים בהם. אין להציג את יישוב הרשב״א כמסקנה חלקה. מכאן שיש בסיס ברור בריטב״א, ובמהלך מסויג גם ברשב״א, לכך שמסירת הדרך לרבים היא נתון בהגדרת רשות הרבים בארץ ישראל; אין מכאן הוכחה שהסמכות נובעת דווקא מחלוקת הנחלות או שהיא יוצרת כלל כללי של חלוקת סוגי קרקע. יש להפריד את החידוש הזה מן המקורות עצמם.\u003c/p>"}, {"id": "1124", "n": 118, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-327 | סוג: כותרות חסרות | מקור: גרסאות עדכניות של החיבורים\u003c/p>\u003cp>כותרות תמצית חסרות לקטע זה (2 כותרות, מנוסחות בסגנון כותרות המשנה שבקובץ):\u003c/p>\u003cp>1. גדר תיקון יהושע ע\"פ הנ\"ל וביחס למעלות ומורדות\u003c/p>\u003cp>2. הקדם בירור במשמעות שימוש הרבים כגדר בקרקע מקום\u003c/p>"}, {"id": "1125", "n": 119, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-328 | סוג: הערת שוליים | מקור: שמעתתא דרשות הרבים ומבטלי מחיצתא, שמעתתא עותק 1 (הערת שוליים 1)\u003c/p>\u003cp>נושא ההערה: הגדרת מבוי וביני עמודי כרשות הרבים; נכתבה על הדיון ברה\"ר המתקצרת ובביני עמודי.\u003c/p>\u003cp>נכתבה במקור כהערת שוליים על: אכן התשובה היא מיניה וביה, דהרי יש לשאול למה נחלק דין הזה לשני אופנים ומה בכלל החילוק ביניהם, הרי שניהם היינו הך, שיש רה\"ר רחבה ט\"ז אמה ובאמצעיתה יש מקום קצר. אלא ע\"כ שיש רבותא באופן אחד על רעהו, דבאמ\u003c/p>\u003cp>נוסח ההערה:\u003c/p>\u003cp>ר\"ל דאין מבוי ממיני רה\"ר. אמנם בברייתא דרשויות (שבת ו.) איתא ואיזו היא רה''ר סרטיא ופלטיא גדולה ומבואות המפולשין זו היא רה''ר גמורה. ואלא שי\"ל דלישנא דמבואות לאו דווקא (היינו, דעשויים לחצירות ובתים), אבל לכאורה זה אינו דבסיפא דברייתא איתא חצרות של רבים ומבואות שאינן מפולשין עירבו מותרין לא עירבו אסורים (וע' רש\"י שם. ואולי יש לדחוק).\u003c/p>"}, {"id": "1126", "n": 120, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-329 | סוג: הערת שוליים | מקור: שמעתתא דרשות הרבים ומבטלי מחיצתא, שמעתתא עותק 1 (הערת שוליים 2)\u003c/p>\u003cp>נושא ההערה: חילוק בין גיפופי המבוי לביני עמודי בגדרי רה\"ר המתקצרת; נכתבה על הדיון בשני האופנים של רה\"ר המתקצרת.\u003c/p>\u003cp>נכתבה במקור כהערת שוליים על: אכן התשובה היא מיניה וביה, דהרי יש לשאול למה נחלק דין הזה לשני אופנים ומה בכלל החילוק ביניהם, הרי שניהם היינו הך, שיש רה\"ר רחבה ט\"ז אמה ובאמצעיתה יש מקום קצר. אלא ע\"כ שיש רבותא באופן אחד על רעהו, דבאמ\u003c/p>\u003cp>נוסח ההערה:\u003c/p>\u003cp>ויותר היה נראה לחלק דתוס' דהכא איירי דאיכא גיפופי (דכיון שקודם המבוי הוי ט\"ז ובמבוי הוי י\"ג ושליש, או דהוה גיפופי מצד ב\"א וב' שילישים, או דהוו חציים מצד זה וחציים מצד זה), והיינו, דמלבד מה שיש לחלק מקום המבוי משאר רה\"ר מחמת קוצר רחבו, גם חלוק מקום המבוי ע\"י גיפופי, משא\"כ בביני עמודי דאף שיש בחוסר ניחותא הנעשה ע\"י הפסקם לחילוק רוחב ט\"ז לשני חלקים, אין בהם כדי לחלק מקומם משאר רה\"ר. (ואיך שיהיה מהא דלא חשו תוס' לזה ודימו מבוי דהכא לביני עמודי דהתם, יש לדחות אוקימתא דאתרומ\"מ דבין הפסים, דאיכא לרוחב ט\"ז בהצטרף דרך הרבים המתרחבת חוץ לבין הפסים. וע\"ע רש\"י (כ. ד\"ה מפסקתן)). וכן יש לפרש תרי אנפי דהשו\"ע, היינו, דבסע\"ח איירי שמתקצר בלא גיפופי כזה ובסע\"ט איירי שמתקצר ע\"י גיפופי כזה .\u003c/p>"}, {"id": "1127", "n": 121, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-330 | סוג: הערת שוליים | מקור: שמעתתא דרשות הרבים ומבטלי מחיצתא, שמעתתא עותק 5 (הערת שוליים 12)\u003c/p>\u003cp>נושא ההערה: דיון מקיף בדברי תוס', הרשב\"א והריטב\"א במבוי המתקצר ובמבואות המפולשין; נכתבה על הדיון ברה\"ר המתקצרת.\u003c/p>\u003cp>נכתבה במקור כהערת שוליים על: וכן שיטת רוב הראשונים, בר מן הריטב\"א דף ו' שכתב גבי מבוי י\"ג ההולך לאורך רה\"ר שאינו רה\"ר גמורה ואפי' הכי איכא ארומ\"מ והאחרונים דנים בכוונתו .\u003c/p>\u003cp>נוסח ההערה:\u003c/p>\u003cp>ומדיקדוק לשון הראשונים נראה כך: בתוס' כתבו וז\"ל שרשות הרבים אחת משני צידי המבוי רוחב ט''ז אמות ואורך רה''ר מהלכין דרך מבוי דהשתא אפי' במבוי דלא הוי רוחב ט''ז אמות הוי רה''ר גמורה כיון דבשני צידי המבוי הוי רוחב ט''ז אמה. ע\"כ. והנה מהא דנחתו בתוס' לומר דאף דבמקום המבוי ליתא לרוחב דרה\"ר מאחר דאורך רה\"ר מהלכין דרך מבוי הוי רה\"ר גמורה, יש לשמוע כך, דאמנם דינא דרה\"ר דליהוי דרך הרבים ברוחב ט\"ז אמה והכא הרי בתוך המבוי ליתא לרוחב הנ\"ל, אך יש לחלק גדר דין דאורך רה\"ר מדין רוחבה, דאמנם דלא תחשב דרך הראויה לרבים אלא בט\"ז, אין רוחב ט\"ז דין ותנאי דרה\"ר בפני עצמו, אלא עיקר דין רה\"ר הוא מה שהיא דרך הילוך לרבים וזה באורכה, היינו, דהיא מפולשת ומסגי בה רבים להדיא, הן אמנם דדרך שאינה ברוחב ט\"ז לא תהא מכילה שימוש הרבים, אבל אין דין רוחבה אלא לקיום שימוש הרבים באורכה, והכא מאחר דביחס לאורך רה\"ר הרי רשות הרבים שבשני עברי המבוי אחת היא, ויש בגדר הילוך הרבים דאורך רה\"ר להחשיב המבוי כחלק מאורכה אף שאין בו רוחב הראוי לדרך הרבים אילו היתה כל הדרך ברוחב זה.וברשב\"א כתב וז\"ל ולפיכך פירשו בתוס' דהכא ברשות הרבים שאינו רחב יתר מעשר היא שנויה, ואפילו הם רשות הרבים גמורה, כסרטיא או פלטיא מכאן ומכאן ואורך המבוי לארכן שהרבים נכנסין בו מכאן ויוצאין בו בזו ביושר אלא שצריכין להתעקם קצת, ובכי הא אף על פי שבאמצע מתקצר וחוזר לפחות משש עשרה אין בכך כלום ורשות הרבים גמורה היא כאלו יש בו שש עשרה אמה. וכי אוקימנא לה במסקנא במבואות המפולשין וכו' התם בשאורך המבוי לרוחב רשות הרבים שהנכנסין מן הרשות למבוי צריכין להתעקם ולהכנס ואינן נכנסין בו ביושר ולפיכך נראה המבוי כרשות אחרת ואינו מן רשות הרבים. ע\"כ. והנה בדקדוק דברי הרשב\"א יש לשמוע חילוק ותוספת אדברי תוס', דבתוס' הנ\"ל משמע שאין למצוא גדר רה\"ר קודם שנאמר דאורך רה\"ר שמשני עבריה דהוו ודאי רה\"ר גמורה מהלכין בה, אבל מדברי הרשב\"א הנ\"ל משמע דאף אי לאו דאמרן דליכא לחסרון שיעור רוחב שבאמצע מתקצר, הרי זו רה\"ר ואי נימא דלא חשיבא כן אין זה רק מחמת שאין לה תנאי דרוחב ט\"ז, וע\"כ נחית הרשב\"א למיסבר גדר כל הדרך עם המבוי כאחת, והיינו, דהיות המבוי חלק מדרך רה\"ר הוא ברור, ובפירוש התוס' רק נתחדש שלא בעי לתנאי דרוחב ט\"ז ביחס למקום שהוא חלק מדרך רה\"ר. ובאמת לפום שיטתו בעבודה\"ק דפלטיא היינו רחבה שאורכה ורוחבה ט\"ז אמה, אכן יש לשמוע שאין לומר חשיבות באורך רה\"ר ארוחבה.ובריטב\"א כתב וז\"ל לכך פרי׳ ז״ל דהשתא לא ברשות הרבים גמורה הוה שמעי׳ לה להא ברייתא אלא במבוי מפולש שאינו רחב אלא עשר, אלא דבקעי ביה רבי׳ מכל צד לרשות הרבים גמורות ור׳ יהודה נמי לא מיירי כלל ברחב י״ו אמה, וא״ת א״כ מאי איכא בין מאי דסבירא לן השת׳ כהאי ברייתא למאי דאיקימנא בסמוך במבואות המפולשים ברשות הרבים, יש לומר דהשתא ס״ד כי היה המבוי בין שתי רשויות הרבים כזה דכי האי גוונא בקעי ביה רבים יותר להדיא וכרשות הרבים גמור׳ היא לענין זה אלא שאינו ברשות הרבים שמתקצ׳ באמצעיתו, ובמסקנא אוקימנא כגון זה, דכיון דצריכין להתעסק [להתעקם] אח״כ אין משתמשין שם להדיא ולא בקעי ביה כולי האי. ע\"כ. ופירוש לפירושו שהיה המבוי בין שתי רשויות הרבים כזה דכי האי גוונא בקעי ביה רבים יותר להדיא – פ' מאילו היה המבוי מפולש לרוחבה - וכרשות הרבים גמור׳ היא לענין זה, - פ' שבאופן זה שווה המבוי לרה\"ר לגבי בקיעת הרבים בו, - שאינו אלא כרשות הרבים שמתקצר באמצעיתו – פ' דבכהאי גוונא ודאי חשוב רה\"ר גם מקום הקצר. והנשמע מדבריו דהא פשיטא דבסתם רה\"ר לא בעינן שיהא רוחב ט\"ז בכל מקומותיה, וחשובים גם מקומות הפחותים מכן כרשות הרבים גמורה, אלא דהכא מאחר שאין להמשכיות מקום רה\"ר במבוי מחמת שמתמעט בגידודי, היה לומר דלא נימא דחשיב כשאר מקומות קצרים שברה\"ר, והיינו, שנתחדש בתוס' דלגבי הא דחשיב מקום המבוי כבקעי בה רבים לא שנא האי מבוי מהך מקומות. ויש בזה יתור אאמור בדברי התוס' והרשב\"א במה דפשיטא ליה להריטב\"א דמקומות הקצרים שברה\"ר חשובים כרה\"ר גמורה, ויש בדב' צימצום מהאמור בתוס' והרשב\"א דלא נחית לדמות האי מבוי כרה\"ר אלא בצירף מה דבקעי בה רבים.\u003c/p>"}, {"id": "562", "n": 122, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0988 | דין התורה לעומת תקנת יהושע – להפריד מקור הלכתי וסיווג שימושי | חומרה: קריטית לבירור הפסקה מקשה כיצד תקנת יהושע יכולה להוסיף תנאי להגדרת רשות הרבים מדאורייתא, כאשר מקור ההגדרה נלמד מדגלי מדבר. זו קושיה יסודית, אך יש להבחין בין קביעת מעמד הדרך (מסירה לרבים או ליחיד) לבין יצירת דין תורה חדש. הסוגיה בעירובין כב ע״ב יכולה להתפרש כנתון על מעמד הדרך, ולא בהכרח כתקנה המשנה את גדרי מלאכת הוצאה. יש לנסח במדויק מה יהושע קובע ומה התורה מגדירה, ולבאר כיצד הראשון משפיע על יישום השני.\u003c/p>"}, {"id": "563", "n": 123, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0989 | „הרבים מגדירים משמעות שימוש הקרקע” – להבחין בין ייעוד, הכנה ושימוש בפועל | חומרה: גבוהה המעבר מן השימוש בפועל של הרבים אל „משמעות שימוש הקרקע” מחייב הבחנה בין שלושה מצבים: קרקע שהרבים משתמשים בה בפועל, קרקע שהוכנה או יועדה לשימושם, וקרקע שראויה לשימושם אך טרם נעשה בה שימוש. הסוגיה בעירובין כב ע״ב עוסקת בדרכים שמסר יהושע לרבים או ליחיד, אך אינה מגדירה במפורש את שלושת המצבים. כדאי לקבוע איזה מהם יוצר את שם רשות הרבים, ומהו המקור לכל אחד מהם.\u003c/p>"}, {"id": "564", "n": 124, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0990 | שימוש קרקע – להבחין בין הקרקע עצמה לבין פוטנציאל השימוש | חומרה: גבוהה הטענה שהרבים אינם מגדירים את הקרקע עצמה אלא את „משמעות שימוש הקרקע” מחדדת את המודל, אך נדרשת הגדרה למונח „אפשרות שימוש”. האם מדובר בתכונה פיזית של הקרקע, בייעוד ציבורי, בזכות מעבר, או בציפייה לשימוש בפועל? יש להראות כיצד ההבחנה פועלת במקרים של דרך שאינה נוחה, חצר פרטית שעוברים בה רבים, וקרקע ציבורית שאינה משמשת בפועל. כך ניתן למנוע מעבר לא מוסבר בין תכונה פיזית, מצב משפטי ומשמעות שימושית.\u003c/p>"}, {"id": "565", "n": 125, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0991 | סמכות יהושע – להבחין בין הקצאת נחלה, תיקון דרך ומסירת שימוש | חומרה: גבוהה בעירובין כב ע״ב לשון הגמרא היא: „יהושע אוהב ישראל היה, עמד ותיקן להם דרכים וסרטיא; כל היכא דניחא תשמישתא מסרה לרבים, כל היכא דלא ניחא תשמישתא מסרה ליחיד”. הגמרא מייחסת ליהושע במפורש את תיקון הדרכים ואת מסירתן לרבים או ליחיד לפי נוחות השימוש. בנפרד, יהושע יג, ז מצווה את יהושע: „ועתה חלק את הארץ הזאת בנחלה לתשעת השבטים וחצי השבט המנשה”; זהו מקור לסמכות חלוקת הנחלות. אולם אין בנוסח הגמרא עצמו אמירה שמסירת הדרכים נעשתה מכוח סמכות חלוקת הנחלות, או שהחלוקה יצרה כלל חדש בהגדרת רשות הרבים מן התורה. יתר על כן, תוספות (עירובין כב ע״ב, ד״ה „יהושע אוהב ישראל היה”) כותבים שמבוי מפולש לבורות וחצר שהרבים נכנסים בה מצד זה ויוצאים מצד אחר עשויים להיחשב רשות הרבים לרבי יהודה אף שהם „של יחיד”, כאשר נוח תשמישם והם ראויים להימסר לרבים. מכאן שאין לזהות בלי ראיה את „מסרה לרבים” עם העברת בעלות בקרקע; ייתכן שהכוונה להקצאת הדרך למעבר או לשימוש ציבורי. יש אפוא להפריד בין שלושה רבדים: חלוקת הנחלות (יהושע יג, ז), תיקון הדרכים ומסירתן לשימוש (עירובין כב ע״ב), והחידוש העיוני שלפיו סמכות החלוקה כוללת גם קביעת סוג קרקע וייעודה הציבורי. שני הרבדים הראשונים מעוגנים במקורות, אך הקישור ביניהם והפיכתו לעיקרון משפטי כללי הם היקש של המחבר, הטעון הנמקה והגדרה: האם מדובר בבעלות, בזכות מעבר/שימוש, או בסיווג הלכתי של המקום.\u003c/p>"}, {"id": "566", "n": 126, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0992 | סיכום תנאי רה״ר – להפריד בין שיעורי חז״ל לבין מודל המחבר | חומרה: גבוהה בסיכום מצורפים יחד תנאי קרקע, נפרדות, הילוך לרבים, שימוש בפועל, נוחות השימוש וההבדל בין ארץ ישראל לחוץ לארץ. יש לסמן מהו תנאי מפורש במקורות (כגון רוחב רשות הרבים, שיעורי גובה/רוחב, והילוך רבים), מהו דיון בראשונים (כגון שישים ריבוא), ומהו חידוש ההמשגה שבפרק. מומלץ להציג טבלה של „תנאי – מקור – תחולה – האם מוסכם”, כדי שהסיכום לא ייראה כאוסף תנאים מוסכמים באותה דרגת תוקף.\u003c/p>"}, {"id": "1128", "n": 127, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-331 | סוג: כותרות חסרות | מקור: גרסאות עדכניות של החיבורים\u003c/p>\u003cp>כותרות תמצית חסרות לקטע זה (12 כותרות, מנוסחות בסגנון כותרות המשנה שבקובץ):\u003c/p>\u003cp>1. הצריך ביאור ברש\"י בדגלי מדבר - קושי אמאי יוחד חסרון מישור למדבר לבדו\u003c/p>\u003cp>2. הצריך ביאור לפי\"ז בדברי רש\"י בדגלי מדבר\u003c/p>\u003cp>3. הנפעל במקום ע\"י דאתי רבים וחילוק ספק דרחבא\u003c/p>\u003cp>4. גדר הילוך ותשמיש הנמצא בסוגיא דרקק\u003c/p>\u003cp>5. הקדם ביאור גדר תשמיש והילוך הנשמע מסגיא דרקק\u003c/p>\u003cp>6. בגדרי שימוש דרה\"ר ודרה\"י\u003c/p>\u003cp>7. הצ\"ב בחילוק דיני רה\"ר מרה\"י לפמשנ\"ת בגדר תשמיש\u003c/p>\u003cp>8. הצריך ביאור לפי\"ז בדברי רש\"י בדגלי מדבר - קושי מדוע יוחד חסרון מישור למדבר ולא לכל הארצות\u003c/p>\u003cp>9. גדר הילוך ותשמיש הנמצא בסוגיא דרקק - שיעורי הרקק תלויים בחיבורו לרשות שלפניו ואחריו\u003c/p>\u003cp>10. ביאור חילוק גדר הנ\"ל - הילוך ותשמיש שני סוגי שימוש חלוקים ביחס להגדרת המקום כרה\"ר\u003c/p>\u003cp>11. הנפעל במקום ע\"י דאתי רבים וחילוק ספק דרחבא - בקיעה ושימוש כשני חלקים בפעולת אתי רבים\u003c/p>\u003cp>12. (339) - סיכום מהות רשות הרבים – דריסת רגל הרבים המגדירה את הקרקע (מקור - רשויות - 7 - 653)\u003c/p>"}, {"id": "1129", "n": 128, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-332 | סוג: הערת שוליים | מקור: שמעתתא דרשות הרבים ומבטלי מחיצתא, שמעתתא עותק 1 (הערת שוליים 4)\u003c/p>\u003cp>נושא ההערה: דיוק בדברי רש\"י בהגדרת פלטיא וסרטיא ובדימוי דגלי מדבר; נכתבה על שיטת רש\"י בפלטיא.\u003c/p>\u003cp>נכתבה במקור כהערת שוליים על: ב] לגבי פלטיא אם דלת נעולה לא הוי מחיצה לא תועיל גם גבי פלטיא, ושתים יש לדון שיסבור רש\"י כהרשב\"א שמה שהם מועילות זהו רק ברה\"ר כיון שזה סותר לכך שהוא דרך פתוח לרבים כל שעה אבל בפלטיא שמהותה אינה 'דרך פ\u003c/p>\u003cp>נוסח ההערה:\u003c/p>\u003cp>הנה אחר דכתב רש\"י בטעמא הדימוי לדגלי מדבר, לכאורה אין לחלק בין סרטיא לפלטיא ומבואות המפולשין, דכולהו כדגלי מדבר בעינן (ע' רש\"י ריש מסכתין), גם לא נתבאר השוואת פירושם בפלטיא (וע' רש\"י שבת (ו.) דנקט במבואות המפולשין דהן מפולשין לפלטיא משני ראשיהן, ואי ס\"ל בפלטיא כפירושא דהרשב\"א, הול\"ל מפולשין לסרטיא, וכן דא\"כ עיקר רה\"ר חסר מן הברייתא, דבכ\"מ נקט רש\"י סתם רה\"ר דהיא דרך בתוך העיר המפולשת לסרטיא (היינו, דרך שמעיר לעיר) משני ראשיה, אי לאו דנימא דהיינו פלטיא (או שנכללו בזה). וגם תמוה הוא לומר דס\"ל לרש\"י (או לשא\"ר) כהרשב\"א, ואעפ\"כ לא הזכיר בשו\"מ שיעור זה (האמור ברשב\"א) דט\"ז על ט\"ז, וכן י\"ל בדעת תוס' שחילקו במבואות המפולשין בין הוה לרוחב רה\"ר לבין הוה לאורכה, וברייתא דחנניא איירי ברוחב, ולק' איתא אר\"י א\"ר מח' בסרטיא וכו' ופלטיא מכאן ופלטיא מכאן, ואי כפירושא דהרשב\"א בפלטיא מה שייך לומר בזה חילוק בין רוחב לאורך (וזה יקשה ביותר מדברי הרשב\"א הכא דנקט בפירוש לחלק בין מפולש לרוחב או אורך פלטיא).\u003c/p>"}, {"id": "1130", "n": 129, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-333 | סוג: הערת שוליים | מקור: שמעתתא דרשות הרבים ומבטלי מחיצתא, שמעתתא עותק 2 (הערת שוליים 4)\u003c/p>\u003cp>נושא ההערה: שיעור פלטיא ט\"ז על ט\"ז וחסרון רה\"ר מקורה; נכתבה על הצ\"ע באולם גדול סגור.\u003c/p>\u003cp>נכתבה במקור כהערת שוליים על: [וצ\"ע עד כמה נאמר דחשיב רה\"ר אטו אולם גדול סגור שיש בו שוק גדול ייחשב רה\"ר, ואולי יש לחלק עכ\"פ בין אם מקורה או לא, דזה ודאי אחד מתנאי רה\"ר שלא תהיה מקורה ומסתמא גם פלטיא צריכה תנאי זה, דומיא דדגלי מדב\u003c/p>\u003cp>נוסח ההערה:\u003c/p>\u003cp>הנה איתא ברשב\"א דשיעורו ט\"ז על ט\"ז אמה. וכן דפשטות הדברים דחסרון דרה\"ר מקורה אינו בשם רה\"ר דידה אלא בחיוב מעשה הוצאה בה. ויש להאריך בזה (והיינו, דאם אכן באופן דאית בהאי אולם מקום שאינו מקורה, אפילו הוי מיעוט המקום, יתחייב המוציא לשם).\u003c/p>"}, {"id": "1131", "n": 130, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-334 | סוג: הערת שוליים | מקור: שמעתתא דרשות הרבים ומבטלי מחיצתא, שמעתתא עותק 5 (הערת שוליים 9)\u003c/p>\u003cp>נושא ההערה: מקור שיעור רוחב ט\"ז ממקומות המקורים ודגלי מדבר; נכתבה על הדיון במקורות השיעור.\u003c/p>\u003cp>נכתבה במקור כהערת שוליים על: והנה תוס' הקשו דנחלק בין י\"ג לט\"ז ומאי מקשה הגמ' מירושלים על שני בתים, הלא אף אם שני בתים הוי רה\"ר המתקצרת אבל הרוחב הוא י\"ג ולא ט\"ז. והיינו כוונתם שזה גופא שחידשנו שזה רה\"ר גמורה מהיכא תיתי, דילמא לא\u003c/p>\u003cp>נוסח ההערה:\u003c/p>\u003cp>כדברי תוס' יש לשמוע מהיות מקומות המקורים (דאמר' דלא דמו לדגלי מדבר) ברוחב ט\"ז דעגלות דמיניה ילפי שיעור רוחב זה, וכמדומני שכן היה להוכיח מסוגיא דרקק (בהו\"א דרחבה ד\"א), ויש לדחות.\u003c/p>"}, {"id": "567", "n": 131, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0993 | מישור המדבר – להבחין בין לשון רש״י לבין מסקנת המחבר | חומרה: גבוהה כאן אתה מקשה על רש״י המפרש שמעלות ומורדות אינן כדגלי מדבר משום שהמדבר היה מישור. יש להביא את לשון רש״י המדויקת בעירובין כב ע״ב ולבדוק אם הוא מתאר את פני השטח או רק מסביר את העדר הדמיון לדגלי מדבר. כמו כן, יש להבחין בין מישוריות כמאפיין של דרך לבין תנאי כללי ברשות הרבים. אם המסקנה היא שכל מקום שאינו מישור אינו רשות הרבים, היא רחבה בהרבה מן הסוגיה ודורשת מקור עצמאי.\u003c/p>"}, {"id": "568", "n": 132, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0994 | רקק מים – אין להסיק ממנו ישירות דין אתי רבים במבוי מוקף | חומרה: גבוהה הפסקה משווה בין רקק מים לבין בקיעת רבים במקום מוקף. אולם בשבת ק ע״ב הרקק נידון כחלק מרשות הרבים לצורך זריקה של ארבע אמות, ואילו בעירובין כב ע״ב תל המתלקט נידון במסגרת „אתי רבים ומבטלי מחיצתא”. אלה מסלולי דיון שונים. יש להציג מהו הדמיון המדויק שאתה מבקש ללמוד: הצטרפות לקרקע הדרך, הילוך רבים, או ביטול נפרדות. ללא הגדרה זו ההיקש עלול לטשטש בין שני דינים.\u003c/p>"}, {"id": "569", "n": 133, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0995 | שיעורי הרקק – להפריד בין עומק, שיעור הזריקה ומידות הרקק | חומרה: גבוהה משנת שבת יא,ד קובעת שרקק מים שעומקו פחות מעשרה טפחים ורשות הרבים מהלכת בו נידון לעניין זריקה של ארבע אמות. בגמרא שבת ק ע״ב מופיעים שני הסברים נוספים לחזרות שבמשנה: אביי דן ברקק שאין בו ארבע אמות לעומת רקק שיש בו ארבע אמות, שאותו הרבים עשויים להקיף; רב אשי דן ברקק שיש בו ארבעה טפחים לעומת רקק שאין בו ארבעה, שאותו הרבים עשויים לפסוע מעליו. אין לערבב בין ארבע אמות של מעשה הזריקה שבמשנה לבין ארבע האמות הנזכרות בהסבר אביי כמידה של הרקק, ובוודאי לא בין אלה לבין ארבעת הטפחים שבהסבר רב אשי. אלה שיעורים נפרדים ובעלי תפקידים שונים: עומק הרקק, מידת הרקק המשפיעה על דרך המעבר, ושיעור ארבע אמות של העברת החפץ. יש להציג את דברי אביי ורב אשי כשני מהלכי הסבר נפרדים, ולא כמערכת שיעורים אחת או כמדד כללי יחיד לשימוש הרבים. המקור להבחנה בין הילוך לתשמיש על ידי הדחק מצוי גם בשבת ח ע״ב, שם הגמרא דנה באותו דין רקק ומסיקה: „הילוך על ידי הדחק שמיה הילוך, תשמיש על ידי הדחק לא שמיה תשמיש”.\u003c/p>"}, {"id": "570", "n": 134, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0996 | הילוך ותשמיש – להפריד בין עמוד המשמש את הרבים לבין קרקע הדרך | חומרה: גבוהה בשבת ח ע״א נידון עמוד ברשות הרבים, גבוה תשעה טפחים, שרבים מכתפין עליו; הגמרא קובעת שהזריקה עליו עשויה להיחשב זריקה ברשות הרבים אף שאין בו ארבעה על ארבעה. זהו מקור חשוב להבחנה בין הילוך לבין תשמיש, אך אין בו בהכרח ראיה שהשימוש „מבטל דין קרקע נפרד” בכל מקום. יש לפרט מהו ההיקש שאתה מבקש ללמוד מן העמוד, ומה ההבדל בינו לבין חור ברשות הרבים או מקום המוקף במחיצות.\u003c/p>"}, {"id": "571", "n": 135, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0997 | שלבי אתי רבים – לא לייחס את החלוקה לשלבים לגמרא | חומרה: קריטית לבירור החלוקה לבקיעת רבים, ביטול המחיצה, ואז שיוך המקום לרשות הרבים היא מסגרת הסברית שלך. בסוגיות עירובין כ ע״א וכב ע״ב נידונות בקיעת רבים, מחיצות ותנאי רשות הרבים, אך אין בהן ניסוח מפורש של שלושה שלבים כאלה. כדאי להגדיר מהו האירוע ההלכתי בכל שלב, האם כל שלב הכרחי, ואיזו סוגיה מוכיחה אותו. במיוחד יש לברר אם „ביטול שם רשות היחיד” ו„הפיכת המקום לחלק מרשות הרבים” הם שתי תוצאות נפרדות או שני ניסוחים של אותו דין.\u003c/p>"}, {"id": "1132", "n": 136, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-335 | סוג: כותרות חסרות | מקור: גרסאות עדכניות של החיבורים\u003c/p>\u003cp>כותרות תמצית חסרות לקטע זה (8 כותרות, מנוסחות בסגנון כותרות המשנה שבקובץ):\u003c/p>\u003cp>1. חילוק קרקע דרה\"י מקרקע דרה\"ר - ברה\"י התשמיש בחפץ וברה\"ר התשמיש באדם ככיתוף\u003c/p>\u003cp>2. הנשמע מדין שיעור ד\"ט דאף גדר מקום חפץ הנ\"ל הוא במשמעות שימוש דאדם\u003c/p>\u003cp>3. עיקר גדרי רשויות הם ביחס להוצאת חפץ\u003c/p>\u003cp>4. דין ד\"ט הוא ביחס לשימוש אדם\u003c/p>\u003cp>5. עיקר גדרי רשויות הן במשמעותם כמקום חפץ\u003c/p>\u003cp>6. גדרים חלוקים במקום ד\"ט בהשתלשלות משמעות הנ\"ל\u003c/p>\u003cp>7. חילוקי דין קרקע דרה\"י מדרה\"ר - ברה\"י התשמיש ביחס לחפץ וברה\"ר ביחס לשימוש אדם דכיתוף\u003c/p>\u003cp>8. ד' טפחים כמידת שימוש ולא כמידת מקום\u003c/p>"}, {"id": "572", "n": 137, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0998 | ראוי לשימוש – להבחין בין הנחת חפץ לבין שימוש האדם | חומרה: גבוהה ההבחנה בין קרקע רשות היחיד הראויה להנחת חפץ לבין קרקע רשות הרבים הראויה להילוך או לתשמיש אדם היא הצעה מושגית משמעותית. יש להצמיד לכל רכיב את המקור: דין ארבעה על ארבעה ברשות היחיד, דין עמוד שרבים מכתפין עליו, ודין הילוך על ידי הדחק. הביטוי „ראויה לראויה” טעון מראה מקום מדויק והסבר אם הוא לשון ראשונים או ניסוח שלך. אין להציג את כל הקריטריונים כרצף אחד אם הם נלמדים מסוגיות שונות.\u003c/p>"}, {"id": "573", "n": 138, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-0999 | קרקע כמקום מנוחת חפץ – לברר את היחס לשיעור ארבעה על ארבעה | חומרה: גבוהה הטענה שעצם מושג הקרקע נדרש מפני שהחפץ צריך מקום מנוחה, ואילו שיעור ארבעה על ארבעה נוגע לשימוש אדם, היא הבחנה מחודשת. עם זאת, בהלכה שיעור ארבעה על ארבעה הוא חלק מהגדרת רשות היחיד במקרים רבים, ולכן אין להציגו כתוספת מושגית בלבד בלי מקור. יש להפריד בין השאלה מה נחשב קרקע לעומת אוויר, מהו מקום חשוב, ומהו שיעור המגדיר רשות. אלה שלוש שאלות קרובות אך לא זהות.\u003c/p>"}, {"id": "574", "n": 139, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-1000 | שיעור ארבעה – להבחין בין רוחב ארבעה לבין שטח ארבעה על ארבעה | חומרה: גבוהה בפסקה יש מעבר בין „ד׳ טפחים” לבין „ד׳ על ד׳ טפחים”. יש להקפיד שלא להשתמש בשניהם כאילו הם אותו שיעור: רוחב ארבעה הוא מידה ליניארית, ואילו ארבעה על ארבעה הוא ממד דו־ממדי של מקום. אם כוונתך לטעון ששיעור המקום נקבע לפי שימוש אדם, יש להראות כיצד השימוש מחייב גם רוחב וגם שטח, ולא רק אחת מן המידות.\u003c/p>"}, {"id": "1133", "n": 140, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-336 | סוג: כותרות חסרות | מקור: גרסאות עדכניות של החיבורים\u003c/p>\u003cp>כותרות תמצית חסרות לקטע זה (8 כותרות, מנוסחות בסגנון כותרות המשנה שבקובץ):\u003c/p>\u003cp>1. גדר שיעור ד\"ט ביחס לשטח (ד\"ט על ד\"ט)\u003c/p>\u003cp>2. ביאור חילוק רוחב ד\"ט משטח דע\"ד\u003c/p>\u003cp>3. שיתוף הגדר דרה\"ר ורה\"י לגבי הוצאה\u003c/p>\u003cp>4. חילוק משמעות שיעור ד\"ט ביחס לשיעור שטח\u003c/p>\u003cp>5. ביאור חילוק הנ\"ל כנובע מגדרי רוחב ושטח\u003c/p>\u003cp>6. בירור גדר מקום חפץ בחיוב היותו משותף לרה\"ר ורה\"י\u003c/p>\u003cp>7. הכרח גדר רה\"ר ביחס למקום חפץ בשלילת אחדות הרשות\u003c/p>\u003cp>8. שיתוף הגדר דרה\"ר ורה\"י לגבי הוצאה - שני גדרים במקום חפץ ומשמעות שיש בהיותו במקום\u003c/p>"}, {"id": "1134", "n": 141, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-337 | סוג: הערת שוליים | מקור: שמעתתא דרשות הרבים ומבטלי מחיצתא, שמעתתא עותק 5 (הערת שוליים 6)\u003c/p>\u003cp>נושא ההערה: גדר תנאי ט\"ז אמה כגדר חיובי ולא שלילי; נכתבה על הדיון בשיעור ט\"ז.\u003c/p>\u003cp>נכתבה במקור כהערת שוליים על: בתוד\"ה וכי תימא. וצ\"ל לפי זה כו'. י\"ל שהפשט בתוס' הוא כך, שבהלכות לחי וקורה מצינו שעד י\"ג ושליש מהני ויותר מזה לא, והיינו כי עד י\"ג ושליש לא הוי פירצה ויותר מזה הוי פירצה, והיינו שזה חסרון בהמחיצות , \u003c/p>\u003cp>נוסח ההערה:\u003c/p>\u003cp>הנה פשטות תנאי דט\"ז אמה לא הוי גדר שלילי להצר רוחב רה\"ר ע\"י גבול הנעשה ע\"י מחיצות, אלא הוי גדר חיובי במקום הראוי להיות בו הילוך הרבים באופן שיש לומר בו שהוא מוכן לרבים, וא\"כ אין למצוא בשיעור ט\"ז חסרון ביחס לרה\"י או ביחס למחיצות דעבידי לה.\u003c/p>"}, {"id": "575", "n": 142, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-1001 | לבוד והגדרת הקרקע – להבחין בין דין מחיצות לדין שיעור מקום | חומרה: גבוהה ההסבר שאין לבוד כאשר מבקשים להגדיר את הקרקע עצמה, מפני שהאוויר מוגדר ביחס לקרקע, הוא חידוש מושגי שדורש הבחנה מדויקת. דין לבוד משמש בכמה הקשרים — השלמת מחיצה, צירוף חלקים, ומדידות שונות — ואין להסיק שאין לו תחולה בכל שאלת קרקע או מקום. כדאי להציג את המקרה המסוים שבו אתה שולל לבוד, לציין את מקור הדין המקביל, ולהבהיר מדוע אין להקיש ממנו.\u003c/p>"}, {"id": "576", "n": 143, "a": "עורך – ביקורת עיונית, המשך", "d": "2026-11-05", "h": "\u003cp>E-1002 | מקום ארבעה על ארבעה – לא להסתפק בשטח מצטבר בלי רוחב ואורך | חומרה: גבוהה בסיום המהלך יש לדייק ש„ארבעה על ארבעה” הוא שיעור בעל שני ממדים, ולא די לומר שהשטח הכולל שווה לשישה־עשר טפחים מרובעים. מלבן צר וארוך עשוי להיות בעל שטח מצטבר זהה אך לא לעמוד בשיעור רוחב ארבעה. אם החידוש שלך הוא שהשטח נחשב אחד מכוח שימוש אפשרי, יש להבהיר האם הוא משנה את דרישת הממדים או רק מסביר מדוע חלקים מצטרפים. אלה מסקנות שונות.\u003c/p>"}, {"id": "1135", "n": 144, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-338 | סוג: כותרות חסרות | מקור: גרסאות עדכניות של החיבורים\u003c/p>\u003cp>כותרות תמצית חסרות לקטע זה (5 כותרות, מנוסחות בסגנון כותרות המשנה שבקובץ):\u003c/p>\u003cp>1. משמעות מקום חפץ והנחתו ביחס לשימוש אדם\u003c/p>\u003cp>2. משמעות מקום חפץ כגדר בקרקע רה\"י\u003c/p>\u003cp>3. משמעות מקום חפץ כגדר בקרקע רה\"י - אילו לא היה שימוש ברה\"י גם מקום חפץ לא היה נוגע לרשות\u003c/p>\u003cp>4. גדר קרקע ואוויר ביחס לרשות - שתי משמעויות מקום בתפיסה ובחלל ומקום הינוח מול מקום הילוך\u003c/p>\u003cp>5. גדר שימוש רה\"ר בהילוך ותשמיש - שני פני שימוש הרבים והגדרת קרקע ע\"י דריסה ולא ע\"י תפיסה\u003c/p>"}, {"id": "577", "n": 145, "a": "OpenAI – ביקורת עריכה", "d": "2026-11-08", "h": "\u003cp>S-20261108-006 | חומרה: קריטית | קטגוריה: מקורות ומידות — פסיעה, ארבע אמות ושש־עשרה אמה. רש״י בעירובין מב ע״א, ד״ה „פסיעות בינוניות”, מפרש: „דרך הילוכו של אדם אמה”. אם „פסיעה אחת” כאן היא פסיעה בינונית רגילה, הקביעה שאורכה ד׳ טפחים אינה תואמת מקור זה; נוסף על כך, פסיעה היא מדד אורך ולא רוחב מסלול ההליכה. יש להפריד בין שלושה שיעורים: (א) אורך פסיעה בינונית — אמה, לפי רש״י; (ב) ארבע אמות להעברת חפץ ברשות הרבים — „כל ארבע אמות ברשות הרבים גמרא גמירי לה” (שבת צו ע״ב; רמב״ם הלכות שבת יב, ט–י); בנפרד, הרמב״ם (שם יב, טו) מתיר טלטול בתוך ריבוע של ארבע על ארבע אמות ומנמקו במידת אורך אדם כשיפשוט ידיו ורגליו, לא כרוחב מסלול הליכה; (ג) רוחב דרך רשות הרבים — שש־עשרה אמה, הנידון בשבת צט ע״א על יסוד מבנה העגלות והמרווחים במשכן (ורמב״ם הלכות שבת יד, א). אין במקורות אלה גזירה מפורשת של רוחב הילוך היחיד מארבע אמות, של פסיעה מארבעה טפחים, או של רוחב רבים מארבעה מסלולי יחיד. אם זהו מודל גאומטרי מחודש שלך, יש להציג את הקישור כחידוש הטעון הוכחה, ולהבחין בין אורך, רוחב, שטח תפיסה ושיעור העברת חפץ.\u003c/p>"}, {"id": "1136", "n": 146, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-339 | סוג: כותרות חסרות | מקור: גרסאות עדכניות של החיבורים\u003c/p>\u003cp>כותרות תמצית חסרות לקטע זה (2 כותרות, מנוסחות בסגנון כותרות המשנה שבקובץ):\u003c/p>\u003cp>1. גדר שימוש הנ\"ל ביחס למקומות שאינם רה\"ר\u003c/p>\u003cp>2. גדר שימוש הרבים דבקיעה לפי הנ\"ל ובספיקא דתל\u003c/p>"}, {"id": "578", "n": 147, "a": "OpenAI – ביקורת עריכה", "d": "2026-11-08", "h": "\u003cp>S-20261108-007 | חומרה: גבוהה | קטגוריה: מקורות והגדרה — עמוד תשעה, כיתוף ושימוש ציבורי שאינו הילוך. סוגיית שבת ח ע״א אכן מלמדת שעמוד תשעה טפחים שרבים מכתפין עליו עשוי להיחשב רשות הרבים; רש״י מפרש: „וכיון דצריך לרבים רשות הרבים הוא בין רחב בין קצר”. זהו מקור לשימוש ציבורי ממשי שאינו הילוך, אך הגמרא מציגה את הכיתוף כשימוש נפרד מן המדרס וההילוך, ולא אומרת שהוא עצמו „חלק מן ההילוך”. באותה סוגיה רבא דוחה את ההשוואה לגומא: „תשמיש על ידי הדחק לא שמיה תשמיש”; כלומר, הצורך הציבורי והשימוש הממשי בעמוד הם נקודת ההבחנה. אפשר להציע שכיתוף הוא שימוש ציבורי נלווה למרחב הדרך, אך יש להציגו כקטגוריה עצמאית של שימוש רבים, ולא כהילוך ממש. ההבחנה חשובה במיוחד משום שהמהלך כאן מבקש להסביר כיצד שימוש שאינו הילוך מצטרף להגדרת קרקע הרשות.\u003c/p>"}, {"id": "579", "n": 148, "a": "OpenAI – ביקורת עריכה", "d": "2026-11-09", "h": "\u003cp>S-20261109-172 | חומרה: גבוהה | קטגוריה: רציפות ההקדמה והשתלבותה במבנה. פסקה זו בגוף הספר חוזרת ומפתחת את גדר שימוש הרבים ביחס למקום שהוצג כבר בהקדמה ב־P00879. ההצגה בהקדמה מכוונת ונועדה להעשיר את המסגרת הכללית; אין לראות בחזרה בגוף הספר טעם לקיצור, להסרה או להפניה במקום ההצגה המוקדמת. יש למקד את בדיקת העריכה באופן שבו פסקת ההקדמה נטמעת במקומה: האם היא המשך ישיר לדיון שבסביבת P00877–P00881, האם המעבר מן ההגדרה הכללית אל תפקידה של ההליכה מובן, והאם לשונה תואמת את המשלב ואת רצף המושגים של ההקדמה. במקבץ תשעת הזוגות P00863/P02906, P00877/P02921, P00879/P02923, P00881/P02925, P00885/P02929, P00896/P02875, P00898/P02877, P00900/P02879 ו־P00910/P02933 יש לנהוג באותו עיקרון: לשמר את ההצגה המוקדמת, ולבדוק רק את מקומה, הקישור אל פסקאותיה הסמוכות, ההתאמה לנוסח ההקדמה והיותה המשך רציף ולא קטע מובחן. ההופעות המאוחרות נשארות כפיתוחים ובירורים בהקשרם בגוף הספר.\u003c/p>"}, {"id": "1137", "n": 149, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-340 | סוג: קטע חסר | מקור: 04_רשויות/רשויות - סוגיות - עותק 3.txt\u003c/p>\u003cp>מיקום השילוב המוצע: לאחר הפסקה שלפני הערה זו (\"וא\"כ מצאנו דעיקר גדר רה\"ר הוא במה שהרבים משתמשים בו, ועיקר שימוש הרבים הוא הילוך, היינו, דריסת הרגל, דהוא שימו...\").\u003c/p>\u003cp>הקטע משתלב כאן כהמשך ישיר לדברים שלפניו; אין צורך בקטע קישור.\u003c/p>\u003cp>נוסח הקטע:\u003c/p>\u003cp>בירור בשם בקיעה ומשמעותו\u003c/p>\u003cp>גדר הנבקע ע\"י חיבור שימושים שבשני עבריו\u003c/p>"}, {"id": "1138", "n": 150, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-341 | סוג: כותרות חסרות | מקור: גרסאות עדכניות של החיבורים\u003c/p>\u003cp>כותרות תמצית חסרות לקטע זה (11 כותרות, מנוסחות בסגנון כותרות המשנה שבקובץ):\u003c/p>\u003cp>1. בירור מושג בקיעה ומשמעותו ברה\"ר - שייכות הילוך לשני גבולותיו וגדר קפנדריא ברש\"י\u003c/p>\u003cp>2. הנבקע ע\"י חיבור שני השימושים - צורת שימוש דבקיעה מגדירה את ההילוך כאחד ברשות\u003c/p>\u003cp>3. גדר הנבקע ע\"י חיבור שימושים שבשני עבריו\u003c/p>\u003cp>4. תלות זה בהבדל רה\"ר מרה\"י בגדר כלל מקומם\u003c/p>\u003cp>5. גדר שימוש הרבים הנשמע מסוגיית רקק\u003c/p>\u003cp>6. דימוי גדר הנ\"ל לסברא דגמ' גבי רקק\u003c/p>\u003cp>7. בירור בשם בקיעה ומשמעותו - קושי מה מחבר שני שימושים משני צידי מקום שאין דורסים בו\u003c/p>\u003cp>8. גדר הנבקע ע\"י חיבור שימושים שבשני עבריו - צורת השימוש של בקיעה מגדירה את ההילוך כאחד\u003c/p>\u003cp>9. גדר בקיעה כקפנדריא - חילוף העיקוף מגדיר את השימוש כשייך במקום ולא כחלופת עיקוף בלבד\u003c/p>\u003cp>10. גדר שימוש הרבים הנשמע מסוגיית רקק - שימוש שהוא חלופת עיקוף אינו חשוב שימוש במקום עצמו\u003c/p>\u003cp>11. תלות זה בהבדל רה\"ר מרה\"י בגדר כלל מקומם - רה\"ר אינה מוגדרת כמכלול אלא כל חלק בנפרד\u003c/p>"}, {"id": "1139", "n": 151, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-342 | סוג: הערת שוליים | מקור: שמעתתא דרשות הרבים ומבטלי מחיצתא, שמעתתא עותק 2 (הערת שוליים 5)\u003c/p>\u003cp>נושא ההערה: שני הגדרים שבצד א' - דרך סלולה והליכה במקום שאינו רשות לרבים; נכתבה על החקירה אם בקיעת הרבים שיעור היא או דין מחיצות.\u003c/p>\u003cp>נכתבה במקור כהערת שוליים על: וחקרו בזה האם זהו שיעור בבקיעת הרבים או דין במחיצות הרה\"ר, כלומר צד א' הוא שרק רבים שהולכים בדרכם הסלולה הם אלה שבוקעים ומבטלים המחיצות אבל רבים שהולכים במקום שאינו רשות לרבים אינם מבטלים , וצד ב' הוא\u003c/p>\u003cp>נוסח ההערה:\u003c/p>\u003cp>יש לדקדק ששני גדרים שכתב בצד א' לא הוו בגדר המתהפך, היינו, גדר \"רבים שהולכים בדרכם הסלולה\" דדמיא לסברא דגמ' בבין העמודים דמסגיא להדיא, וגדר \"הולכים במקום שאינו רשות לרבים\" דמיא לסברא דמעלות ומורדות דא\"י דלא מסרה י-הושוע לרבים. ועכ\"פ הרי דגדרים הללו שייכו לגדרי רה\"ר עצמה כאמור. ויל\"צ כאן לדברי הריטב\"א (כב.) דכתב כצד א' והוסיף תנאי דבקיעתם תדירה, וע' שבת (ז.) גבי קרן זווית הסמוכה וכו' זימנין דדחקי וכו', וגבי בין העמודים זימנין דדרסי וכו', וב\"ב (ז:, יב.).\u003c/p>"}, {"id": "1140", "n": 152, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-343 | סוג: הערת שוליים | מקור: שמעתתא דרשות הרבים ומבטלי מחיצתא, שמעתתא עותק 1 (הערת שוליים 5)\u003c/p>\u003cp>נושא ההערה: מקור הגדר של דריסת רבים וביטול מחיצות בדברי רש\"י; נכתבה על הדיון אם יש ארומ\"מ שלא ברה\"ר.\u003c/p>\u003cp>נכתבה במקור כהערת שוליים על: ג] האם יש ראיה בדעת רש\"י אם יש ארומ\"מ שלא ברה\"ר או לא?\u003c/p>\u003cp>נוסח ההערה:\u003c/p>\u003cp>ע' רש\"י (כ. ד\"ה מפסקתן) שכתב וז\"ל מפסקתן. שאין שם דרך אלא בין הפסין יסלקנה לצדדין דאתי דריסת רבים ומבטלי מחיצות. ע\"כ.\u003c/p>"}, {"id": "1141", "n": 153, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-344 | סוג: הערת שוליים | מקור: שמעתתא דרשות הרבים ומבטלי מחיצתא, שמעתתא עותק 2 (הערת שוליים 6)\u003c/p>\u003cp>נושא ההערה: תליית דין בקיעה בגדר המקום; נכתבה על החקירה בגדר בקיעת הרבים.\u003c/p>\u003cp>נכתבה במקור כהערת שוליים על: וחקרו בזה האם זהו שיעור בבקיעת הרבים או דין במחיצות הרה\"ר, כלומר צד א' הוא שרק רבים שהולכים בדרכם הסלולה הם אלה שבוקעים ומבטלים המחיצות אבל רבים שהולכים במקום שאינו רשות לרבים אינם מבטלים , וצד ב' הוא\u003c/p>\u003cp>נוסח ההערה:\u003c/p>\u003cp>הנה זה צ\"ב דמאחר דאנו דנים באי בקיעה משווה להאי מקום דין רה\"ר, מה שייך לומר דהוא תליא בגדר המקום בלא בקיעה.\u003c/p>"}, {"id": "1142", "n": 154, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-345 | סוג: הערת שוליים | מקור: שמעתתא דרשות הרבים ומבטלי מחיצתא, שמעתתא עותק 2 (הערת שוליים 9)\u003c/p>\u003cp>נושא ההערה: הערת המחבר על שלשון הריטב\"א שלא הבינו; נכתבה על הדיון בביטול המחיצות עצמן.\u003c/p>\u003cp>נכתבה במקור כהערת שוליים על: הנה פשטות לשון הגמ' משמע שמבטלים את המחיצה עצמה, וכן נראה מלשון הריטב\"א ריש דף כ\"ב, וכן מבואר להדיא בבעל המאור, וברמב\"ן במלחמות תלוי מה הפשט בדבריו, דבפשוטו גם הוא מודה ליסוד הזה, רק שסבר שבעומד מרובה\u003c/p>\u003cp>נוסח ההערה:\u003c/p>\u003cp>לא זכיתי להבין כוונת דבריו\u003c/p>"}, {"id": "1143", "n": 155, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-346 | סוג: כותרות חסרות | מקור: גרסאות עדכניות של החיבורים\u003c/p>\u003cp>כותרות תמצית חסרות לקטע זה (16 כותרות, מנוסחות בסגנון כותרות המשנה שבקובץ):\u003c/p>\u003cp>1. ביאור כאן הודיעוך כוחן דמחיצות - משמעות חיובית למחיצות להגדיר קרקע ולא מניעה בלבד\u003c/p>\u003cp>2. ביאור כאן הודיעוך כוחן של מחיצות להנ\"ל\u003c/p>\u003cp>3. ביאור מה דאין למצוא כוחן של מחיצות בשתי מחיצות דר\"י\u003c/p>\u003cp>4. המוכרח והנמנע בביאור גדר מחיצת רה\"י לפמשנ\"ת\u003c/p>\u003cp>5. ביאור גדר אתי רבים לפי הנ\"ל\u003c/p>\u003cp>6. חשיבות שתי מחיצות מעלייתא לפי הנ\"ל\u003c/p>\u003cp>7. בדעת חכ' דפליגי אר\"י לפי הנ\"ל\u003c/p>\u003cp>8. מחיצות כל צד חשובים להגדיר את הקרקע עצמה\u003c/p>\u003cp>9. מח' חכ' ור\"י בכח ד' מחיצות להגדיר קרקע\u003c/p>\u003cp>10. גדר קרקע רה\"י דמחיצות  עבידי לה\u003c/p>\u003cp>11. ביאור גדר אתי רבים לפי הנ\"ל - בקיעה מגדירה את השימוש כשלילי ולא כחיובי הבא מדריסה\u003c/p>\u003cp>12. חשיבות שתי מחיצות מעלייתא לפי הנ\"ל - מחיצות המגדירות מעבר מסויים חשובות ביחס לשימוש הבקיעה\u003c/p>\u003cp>13. בדעת חכ' דפליגי אר\"י לפי הנ\"ל - מחיצות אינן מגדירות רק את המעבר אלא גם את הקרקע עצמה\u003c/p>\u003cp>14. ביאור כאן הודיעוך כוחן של מחיצות להנ\"ל - יש למחיצות משמעות חיובית מלבד המניעה השלילית\u003c/p>\u003cp>15. ביאור מה דאין למצוא כוחן של מחיצות בשתי מחיצות דר\"י - חילוק בין מעלת שתי מחיצות למעלת ד'\u003c/p>\u003cp>16. מחיצות כל צד חשובים להגדיר את הקרקע עצמה - חילוק דיומדין הפועלים בנפרד ממחיצות מקום\u003c/p>"}, {"id": "1144", "n": 156, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-347 | סוג: הערת שוליים | מקור: שמעתתא דרשות הרבים ומבטלי מחיצתא, שמעתתא עותק 2 (הערת שוליים 10)\u003c/p>\u003cp>נושא ההערה: מקור לשון \"מפסקתן\" מלשון המשנה; נכתבה על לשון הרמב\"ן שדרך הרבים מפסקת את המחיצות.\u003c/p>\u003cp>נכתבה במקור כהערת שוליים על: אבל לשון הרמב\"ן קצת משמע גדר אחר בדבר, דכתב שדרך הרבים 'מפסקת' אותן , דמשמע שארומ\"מ לא מבטל והורס את המחיצות עצמן אלא רק מפריד ביניהם ומפסיק את הקשר והחיבור שלהם, ועפ\"ז יש לפרש דברי הרמב\"ן באופ\"א, שבא\u003c/p>\u003cp>נוסח ההערה:\u003c/p>\u003cp>היא לישנא דמתני' \"אם היתה דרך הרבים מפסקתן\".\u003c/p>"}, {"id": "1145", "n": 157, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-348 | סוג: הערת שוליים | מקור: שמעתתא דרשות הרבים ומבטלי מחיצתא, שמעתתא עותק 2 (הערת שוליים 11)\u003c/p>\u003cp>נושא ההערה: גדר חיבור מחיצה למחיצה שבלשון ההפרדה; נכתבה על לשון הרמב\"ן שדרך הרבים מפסקת.\u003c/p>\u003cp>נכתבה במקור כהערת שוליים על: אבל לשון הרמב\"ן קצת משמע גדר אחר בדבר, דכתב שדרך הרבים 'מפסקת' אותן , דמשמע שארומ\"מ לא מבטל והורס את המחיצות עצמן אלא רק מפריד ביניהם ומפסיק את הקשר והחיבור שלהם, ועפ\"ז יש לפרש דברי הרמב\"ן באופ\"א, שבא\u003c/p>\u003cp>נוסח ההערה:\u003c/p>\u003cp>לשון הפרדה כאן הוא חידוש, דמשמע דר\"ל שיש גדר חיבור דמחיצה למחיצה (או בשאר אופנים דמהני בצירוף) שאינו מחמת היותם חוצצים שטחים שהינם חלקי שטח מקום אחד, וכמדומה דיש להוכיח מכלאים דלא כן.\u003c/p>"}, {"id": "1146", "n": 158, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-349 | סוג: הערת שוליים | מקור: שמעתתא דרשות הרבים ומבטלי מחיצתא, שמעתתא עותק 2 (הערת שוליים 12)\u003c/p>\u003cp>נושא ההערה: ביאור דברי הרמב\"ן בחילוק עומד מרובה ופרוץ מרובה ודברי החזו\"א; נכתבה על לשון הרמב\"ן.\u003c/p>\u003cp>נכתבה במקור כהערת שוליים על: אבל לשון הרמב\"ן קצת משמע גדר אחר בדבר, דכתב שדרך הרבים 'מפסקת' אותן , דמשמע שארומ\"מ לא מבטל והורס את המחיצות עצמן אלא רק מפריד ביניהם ומפסיק את הקשר והחיבור שלהם, ועפ\"ז יש לפרש דברי הרמב\"ן באופ\"א, שבא\u003c/p>\u003cp>נוסח ההערה:\u003c/p>\u003cp>לכאורה כוונת דבריו דבעי הרמב\"ן לחלק דלא מהני בקיעת רבים אלא במחיצה שגדר סתימת צד שלה הוא שמיעוט מחיצה או צורתה חשוב להגדיר חלק הפרוץ כמחוץ כמוה (כמו גדר \"יורד וסותם\") דבזה חשוב בקיעת הרבים לגבור, אבל בעומ\"ר אין גדר סתימת הצד שחשוב העומד כחוצץ גם חלק הפרוץ, אלא שלהחשיב צד זה כסתום די בחלק העומד אף דאיתיה לחלק הפרוץ, ומימלא לא תועיל בקיעת הרבים בחלק הפרוץ יותר ממה שהוא כבר פרוץ, ובזה יל\"צ למכתב החזו\"א (שחור) שלא מצא רווח מקום גדר לחילוק זה (ואולי אתיא לשיטתו בגוד אסיק וכו'), והיינו, דסוף דבר לא תקבל הרוח שם אלא או דהוי מחוצה או דהוי פרוצה, וחילוקי לשונות וגדרים הנמצאים בצורת חציצת מחיצות השונות (בפירצה עד עשר משום פתח, ובעומד הרבה על הפרוץ, ובפי תקרה היורד וסותם, ובגוד אחית ונחית וכו') יתכנסו לגדר אחד דרוח זו מחוצה. ולדבריו צ\"ל דכוונת הרמב\"ן דבקיעת הרבים אינה פועלת בגדר רוח הנבקעת אי הוי סתומה או פרוצה, אלא פעולתה בגדר הנפרד שיש לכל חלק וחלק מרוחב הרוח להיות חצוץ במחיצה או וכו', וא\"כ לא יהיה גדר בקיעתם ביחס למחיצה הקיימת (וכדמשמע מלישנא דמפסקתן) אלא ביחס לחלק הפרוץ, דבקיעתם עבידא דלא יהא אפשר לו לקבל גדר חצוץ מכח מחיצה הקיימת (וכעין מה דלא מהני עומ\"ר לפירצת יותר מי')\u003c/p>"}, {"id": "1147", "n": 159, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-350 | סוג: הערת שוליים | מקור: שמעתתא דרשות הרבים ומבטלי מחיצתא, שמעתתא עותק 2 (הערת שוליים 16)\u003c/p>\u003cp>נושא ההערה: ביאור תנאי הדרך הסלולה - סלולה, תדירה ועשויה לכך; נכתבה על דברי הריטב\"א במבואות המפולשין.\u003c/p>\u003cp>נכתבה במקור כהערת שוליים על: ה] בענין ארומ\"מ במבואות המפולשין שאינם רה\"ר, בפשוטו דעת הריטב\"א שיש ארומ\"מ בכה\"ג, רק בתנאי שתהיה הדרך סלולה לרבים ועוברים שם בהדיא, וכן למד המשכנ\"י, אך הבית אפרים למד בדבריו דסובר כהרשב\"א ושא\"ר שאין כ\u003c/p>\u003cp>נוסח ההערה:\u003c/p>\u003cp>ותדירה. ולק' הוסיף הריטב\"א דעשויה לכך, ובתפיסת מיעוט (היינו, לומר דכוונתו בסלולה להדיא למשמעות אחת והוה תנאי אחד) נמצא ג' תנאים, סלולה, תדירה ועשויה לך, ולכשתמצי לומר יעלו כולם לקיום גדר שימוש הרבים במקום זה ובמשמעותו כן מחמת היותו המשך שימוש דרה\"ר גמורה שבשתי גבולות מקום הנ\"ל, היינו, דסלולה להדיא הוא גדר בשייכות גדר שימוש דעבידי הכא עם שימוש דעבידי ברה\"ר, ותדירה, הוא גדר חשיבות תשמיש הנ\"ל להגדיר המקום כמשמשו, ועשויה לכך, הוא גדר במוכנות היות המקום כמשמש לקבל תשמיש הנ\"ל. ולכשתדקדק תמצא דנקט הריטב\"א בכל ענין תנאי שהוא מעניינו.\u003c/p>"}, {"id": "1148", "n": 160, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-351 | סוג: הערת שוליים | מקור: שמעתתא דרשות הרבים ומבטלי מחיצתא, שמעתתא עותק 4 (הערת שוליים 1)\u003c/p>\u003cp>נושא ההערה: ביאור הפלוגתא בין תוס' לרמב\"ן בעומד מרובה; נכתבה על שיטת תוס' והרמב\"ן.\u003c/p>\u003cp>נכתבה במקור כהערת שוליים על: יד] בקיעת הרבים אינה מבטלת אלא כנגד מקום הפרוץ אבל בצדדים כנגד העומדין שפיר איכא מחיצות, ונ\"מ למשל לפי ר' יהודה דסגי בשתי מחיצות שגם בירושלים שפרוצה שתי וערב אבל כנגד העומדין לאו רה\"ר הוא. [וכהרמב\"ן ב\u003c/p>\u003cp>נוסח ההערה:\u003c/p>\u003cp>ובביאור הפלוגתא בין תוס' לרמב\"ן בזה יש לומר בשני אופנים, א' שחלקו בגדר עומד מרובה שתוס' סברי שדין המיעוט כסתום מכח ש'מאריך וסותם' ולכן שפיר שייך ביה ארומ\"מ, ב' דלעולם מודו ליה להרמב\"ן בגדר עומ\"ר, אבל פליגי בגדר ארומ\"מ שזהו אף באופן הזה, ולא נהירא. אמנם שוב התבוננתי דיתכן דלא פליגי כלל, כי תוס' הלא מדברים על ירושלים ושם היה צוה\"פ כמו שכתבו מקודם, ולכאו' בצוה\"פ גם הרמב\"ן מודה דאיכא ארומ\"מ (כמו שכתבתי בפנים בדעת הרמב\"ן) אפי' אם יש עומ\"ר.\u003c/p>"}, {"id": "1149", "n": 161, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-352 | סוג: הערת שוליים | מקור: שמעתתא דרשות הרבים ומבטלי מחיצתא, שמעתתא עותק 5 (הערת שוליים 11)\u003c/p>\u003cp>נושא ההערה: ארומ\"מ אינו אלא בפילוש גמור; נכתבה על ביאור דין אתי רבים.\u003c/p>\u003cp>נכתבה במקור כהערת שוליים על: אבל לפי צד א' בתוס' [כב. ד\"ה קשיא] משמע לכאו' שלדעת ר' יהודה יש חילוק בזה, שמבואר שכיון ששתי מחיצות דאורייתא ממילא אע\"ג שצריך מדרבנן לחי ברוח שלישית ורביעית אינם מתבטלים ע\"י בקיעת הרבים, וגם לא מוכח ש\u003c/p>\u003cp>נוסח ההערה:\u003c/p>\u003cp>אמנם פשטות הדברים דלא אמר' ארומ\"מ אלא בפילוש גמור (וע' רש\"י סוכה (יח: ד\"ה מודינא) דנקט בגדר בקיעת רבים לישנא דקפנדריא).\u003c/p>"}, {"id": "1150", "n": 162, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-353 | סוג: הערת שוליים | מקור: שמעתתא דרשות הרבים ומבטלי מחיצתא, שמעתתא עותק 2 (הערת שוליים 7)\u003c/p>\u003cp>נושא ההערה: דין מחיצות חשובות לדעת ר' יוחנן; נכתבה על דברי הרשב\"א בשם ג' וד' מחיצות.\u003c/p>\u003cp>נכתבה במקור כהערת שוליים על: ו] בדף נט. כ' הרשב\"א שדעת רבנן (למסקנא) שאפי' שם ג' מחיצות מהני שלא יהיה ארומ\"מ [ומה שנקטו שם ד' מחיצות כי כן האמת שם בביראות דבעינן ד'], רק צריך שיהיו מחיצות חשובות, לאפוקי לחי, אבל צוה\"פ וכ\"ש דלתות \u003c/p>\u003cp>נוסח ההערה:\u003c/p>\u003cp>לכאורה לא כתב כן אלא לדעת ר' יוחנן דסברי כר\"י בחדא וכרבנן בחדא, אבל לרבנן לא בעינן מחיצות חשובות. וכן הוא בסמוך אות ז'.\u003c/p>"}, {"id": "1151", "n": 163, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-354 | סוג: הערת שוליים | מקור: שמעתתא דרשות הרבים ומבטלי מחיצתא, שמעתתא עותק 2 (הערת שוליים 13)\u003c/p>\u003cp>נושא ההערה: חקירה בשיעור המחיצות שבפינות פסי ביראות; נכתבה על הראיה מפסי ביראות לנוסח א'.\u003c/p>\u003cp>נכתבה במקור כהערת שוליים על: ולכאו' יש להוכיח כנוסח א' מפסי ביראות דבפשוטו מבואר שבקיעת הרבים גורמת שכל השטח חוזר להיות רה\"ר ואע\"פ שיש אמה מכאן ואמה מכאן עומדין ולפחות שם ייחשב רה\"י. וידידי ר\"ז הרציג אמר ליישב בזה דנחשב רה\"ר המתר\u003c/p>\u003cp>נוסח ההערה:\u003c/p>\u003cp>לא נתבאר איזה אמות יועיל ואאיזה שטח יועילו, ואי כוונתו בכל פינה לעצמה, לא אשכחן דיהני ב' מחיצות כמין גאם, ואי כוונתו בצידי השטח כזה , לכאורה כמו דמהני בקיעת רבים \"להפסיק\" המחיצה ברוחב כן יועיל אאורך, ושוב אתינן להיות כל פינה לעצמה כזה וכנ\"ל, וזה צ\"ל אף לדעת תוס'.\u003c/p>"}, {"id": "1152", "n": 164, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-355 | סוג: הערת שוליים | מקור: שמעתתא דרשות הרבים ומבטלי מחיצתא, שמעתתא עותק 2 (הערת שוליים 15)\u003c/p>\u003cp>נושא ההערה: גדר ב' מחיצות מעלייתא ושם ד' מחיצות וחשיבותם; נכתבה על שני הצדדים בדעת רבנן.\u003c/p>\u003cp>נכתבה במקור כהערת שוליים על: והנה בדעת רבנן נתבאר שיש שני צדדים בראשונים, או שהם חולקים לגמרי או שרק בשם ד' מחיצות לית להו ארומ\"מ, והנה אם חולקים לגמרי הפי' הוא דס\"ל \"כוחן של מחיצות\" שאינן מתבטלות כלל ע\"י בקיעת רבים, אבל אם רק בש\u003c/p>\u003cp>נוסח ההערה:\u003c/p>\u003cp>הנה לכאורה אי נימא דלא כתירוץ א' בתוס' דכוונת הגמ' בב' מחיצות מעלייתא לדעת ר\"י בב' מחיצות דאורייתא, הרי דגדר ב' מחיצת מעלייתא, וכן גדר שם ד' מחיצות, אינם בחשיבות גדר מחיצה עצמה (ולכאורה כן מוכח מגמ' סוכה (ז:) דאתיוהו לתרוויהו ולכ\"ע והו\"א דמהנו אף לגבי סוכה. ותירוץ א' בתוס' צ\"ע), והוא לכאורה מוכרח מהא דיש לב' מחיצות מעלייתא דצדדים להיות מונעים בקיעת רבים בצד אחר, וחשיבות זו יש למצוא בשני פנים או בחשיבות מקור הגורם החוצץ, או בחשיבות צורת המחיצות (וגם זה יש למצוא בשני פנים או בחשיבות גדר מחיצה הכולל כל המחיצות יחד, או בחשיבות גדר המקום כנמחץ ע\"י מוחץ כזה), אבל איך שיהיה אין זה חזי לאיצטרופי לגדר בטלי מחיצתא דהנוסח הראשון. ובעיקר גדר חשיבות הנ\"ל יל\"צ דמאחר דלא מצינו לחשיבות זו (הן דב' מציחות מעלייתא והן דשם ד' מחיצות) במק\"א אלא גבי דין מיגו דהוי דופן, דכל משמעותו הוא דיהני מחיצות פסולות לזה מיגו וכו', יש להכריע שהוא חשיבות גדר המקום כנמחץ (או נמחצות המקום). וקשה להאריך.\u003c/p>"}, {"id": "1153", "n": 165, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-356 | סוג: קטע חסר | מקור: 04_רשויות/רשויות.pdf\u003c/p>\u003cp>מיקום השילוב המוצע: לאחר הפסקה שלפני הערה זו (\"וא\"כ זה פשר מה דס\"ל לר\"י דאי איכא שתי מחיצות מעלייתא חשיבי שלא יחשב אתי רבים, והיינו, שודאי אין משמעות במה ששנ...\").\u003c/p>\u003cp>הקטע משתלב כאן כהמשך ישיר לדברים שלפניו; אין צורך בקטע קישור.\u003c/p>\u003cp>נוסח הקטע:\u003c/p>\u003cp>גדר ד' מחיצות וסתימה\u003c/p>\u003cp>מחלוקת חכמים ורבי יהודה\u003c/p>\u003cp>ביאור אתי רבים ומחלוקת\u003c/p>\u003cp>חילוק מחיצות רה\"י דשבת מסוכה -רשויות -סוגיות\u003c/p>"}, {"id": "1154", "n": 166, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-357 | סוג: קטע חסר | מקור: 04_רשויות/רשויות - עותק 2.docx / 04_רשויות/רשויות.pdf\u003c/p>\u003cp>מיקום השילוב המוצע: לאחר הפסקה שלפני הערה זו (\"ולפי זה יבואר מה שאמרו כאן הודיעוך כוחן של מחיצות, כלומר, שאין מחיצות רה\"י רק במשמעות שלילית דמניעת רגל רבים, ...\").\u003c/p>\u003cp>הקטע משתלב כאן כהמשך ישיר לדברים שלפניו; אין צורך בקטע קישור.\u003c/p>\u003cp>נוסח הקטע:\u003c/p>\u003cp>ביאור מה דאין למצוא כוחן של מחיצות בשתי מחיצות דר\"י\u003c/p>"}, {"id": "1155", "n": 167, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-358 | סוג: הערת שוליים | מקור: שמעתתא דרשות הרבים ומבטלי מחיצתא, שמעתתא עותק 4 (הערת שוליים 2)\u003c/p>\u003cp>נושא ההערה: חידוש הבעל המאור שגם העומדין מתבטלים ודברי החזו\"א; נכתבה על דברי הרמב\"ן והבעה\"מ.\u003c/p>\u003cp>נכתבה במקור כהערת שוליים על: ג] ואפי' בעומד מרובה. ואולי חלק על הרמב\"ן ביסוד דין העומ\"ר וסבר שגם בזה צריך להאריך ולסתום ולכן שייך לבטלו ע\"י בקיעת רבים.\u003c/p>\u003cp>נוסח ההערה:\u003c/p>\u003cp>הנה בעיקר החידוש של הבעה\"מ שגם העומדין מתבטלים ע\"י הרבים בזה מסכים עמו הרמב\"ן, ונפק\"מ בפרוץ מרובה, דרק בעומ\"ר פליג עליה משום שאין שם פירצה ואינם מבטלים כלום.ודבר זה עצמו צ\"ב טובא אמאי לא נדון כל עומד בנפרד והנה לנו רשות היחיד בין כל שני עומדין בפני עצמן, בלי להתייחס כלל לפירצה שבהמשך, ואפי' בפרוץ מרובה.ולפי החזו\"א [ק\"ז ג'] שצריך שלא יהיה ארכן פחות מרוחב הרשות שביניהם י\"ל דעכ\"פ בציור הזה לא הוי רה\"י, ובאמת בפסי ביראות כן הוא, דהוא מרובע, ובזה בכל אופן אין אורך המחיצות מכסה כל הרוחב, אבל הרמב\"ן ובעה\"מ דיברו בסתמא בכל גווני. וצ\"ע.\u003c/p>"}, {"id": "1156", "n": 168, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-359 | סוג: קטע חסר | מקור: 04_רשויות/רשויות - סוגיות - עותק 3.txt\u003c/p>\u003cp>מיקום השילוב המוצע: לאחר הפסקה שלפני הערה זו (\"ואמנם כדאמרן עצם הגדרת המקום דדיומדין לא חשיב כנגד שימוש הרבים, דשימוש הוא בקרקע, ודיומדין הם במקום. אך ד' מחי...\").\u003c/p>\u003cp>הקטע משתלב כאן כהמשך ישיר לדברים שלפניו; אין צורך בקטע קישור.\u003c/p>\u003cp>נוסח הקטע:\u003c/p>\u003cp>המוכרח והנמנע בביאור גדר מחיצת רה\"י לפמשנ\"ת\u003c/p>\u003cp>ביאור דיני מחיצה לפי הנ\"ל\u003c/p>\u003cp>משמעות מחיצת צד למרחק מקום הנחצץ בכלאים ובשבת\u003c/p>"}, {"id": "1157", "n": 169, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-360 | סוג: כותרות חסרות | מקור: גרסאות עדכניות של החיבורים\u003c/p>\u003cp>כותרות תמצית חסרות לקטע זה (7 כותרות, מנוסחות בסגנון כותרות המשנה שבקובץ):\u003c/p>\u003cp>1. שלילת ראיה מהיתר לחי וקורה רק במבוי שארכו יתר על רחבו\u003c/p>\u003cp>2. משמעות מחיצת צד למרחק מקום הנחצץ בכלאים ובשבת\u003c/p>\u003cp>3. גדר מחיצת צד ביחס למקום ויושר מחיצה\u003c/p>\u003cp>4. חילוק דין אורכו יתר על רחבו בלחי וקורה מנידון הנ\"ל\u003c/p>\u003cp>5. בירור בגבול השפעת מחיצה אמקום שבעברה הנחצץ\u003c/p>\u003cp>6. שלילת רה\"ר מצד אופי הקרקע בארץ ישראל\u003c/p>\u003cp>7. מחיצת צד כקובעת גבול מקום ולא רק חציצה\u003c/p>"}, {"id": "1158", "n": 170, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-361 | סוג: הערת שוליים | מקור: שמעתתא דרשות הרבים ומבטלי מחיצתא, שמעתתא עותק 5 (הערת שוליים 5)\u003c/p>\u003cp>נושא ההערה: אם החסרון במחיצות הוא בגדר גבולות הרשות או במחיצות אותו הצד; נכתבה על הדיון בגדר החסרון במחיצות.\u003c/p>\u003cp>נכתבה במקור כהערת שוליים על: בתוד\"ה וכי תימא. וצ\"ל לפי זה כו'. י\"ל שהפשט בתוס' הוא כך, שבהלכות לחי וקורה מצינו שעד י\"ג ושליש מהני ויותר מזה לא, והיינו כי עד י\"ג ושליש לא הוי פירצה ויותר מזה הוי פירצה, והיינו שזה חסרון בהמחיצות , \u003c/p>\u003cp>נוסח ההערה:\u003c/p>\u003cp>לא נתבאר כוונתו אי הוה חסרון במחיצות דהרשות, והיינו, בגדר גבולות הרשות הניתנות להיחצץ ובגדרם הכולל, או במחיצות אותו הצד דאית ביה לפירצה (וחילוק זה נפרד ממש\"כ לק' בגדר ביטול ההיקף).\u003c/p>"}, {"id": "1159", "n": 171, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-362 | סוג: כותרות חסרות | מקור: גרסאות עדכניות של החיבורים\u003c/p>\u003cp>כותרות תמצית חסרות לקטע זה (13 כותרות, מנוסחות בסגנון כותרות המשנה שבקובץ):\u003c/p>\u003cp>1. סוגיית ארץ ישראל אינה רשות הרבים - דחיית הגמרא שאין הבדל בגודל בין א\"י לעולם\u003c/p>\u003cp>2. הנשמע מגמ' דא\"י אין עליה משום רה\"ר\u003c/p>\u003cp>3. חילוק גדר מחיצות המבטלות דין רה\"ר ממחיצות רה\"י\u003c/p>\u003cp>4. המשמע בר\"ן דגדר זה הוא ביחס לכל מחיצה\u003c/p>\u003cp>5. חילוק גדר מחיצה ברה\"י וברה\"ר בשבת ובסוכה\u003c/p>\u003cp>6. גדר הנ\"ל אינו במחציות עצמם אלא בגדרם כגבול מקום\u003c/p>\u003cp>7. ביאור כמה דיני מחיצה לפי חילוק הנ\"ל\u003c/p>\u003cp>8. הנשמע מגמ' דארץ ישראל אין עליה משום רה\"ר - דחיית הגמ' שאין הבדל בגודל בין א\"י לכל העולם\u003c/p>\u003cp>9. חילוק גדר מחיצות המבטלות דין רה\"ר ממחיצות רה\"י - אין להוכיח דין מרחק מחיצות ממחיצות ארץ\u003c/p>\u003cp>10. דעת הראשונים בשיעור דהנ\"ל - צריך שידע שהוא בתוך מחיצות כדין מחיצות ניכרות בסוכה\u003c/p>\u003cp>11. המשמע בר\"ן דגדר זה הוא ביחס לכל מחיצה - יכולת ראיה בכל מקום ברשות ולא רק היכן שרואה\u003c/p>\u003cp>12. שני גדרים בדין במחיצה - מחיצה כהגדרת קרקע להנחת חפץ ומחיצות יחד כהגדרת מקום שימוש אדם\u003c/p>\u003cp>13. מחיצות שוללות רה\"ר לעומת מחיצות יוצרות רה\"י\u003c/p>"}, {"id": "1160", "n": 172, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-363 | סוג: קטע חסר | מקור: 04_רשויות/רשויות.pdf\u003c/p>\u003cp>מיקום השילוב המוצע: לאחר הפסקה שלפני הערה זו (\"כו. במשמעות מחיצות ובגדר הנפעל ע\"י במקום...\").\u003c/p>\u003cp>הקטע משתלב כאן כהמשך ישיר לדברים שלפניו; אין צורך בקטע קישור.\u003c/p>\u003cp>נוסח הקטע:\u003c/p>\u003cp>הנשמע מגמ' דא\"י אין עליה משום רה\"ר\u003c/p>\u003cp>חילוק גדר מחיצות המבטלות דין רה\"ר ממחיצות רה\"י\u003c/p>"}, {"id": "580", "n": 173, "a": "OpenAI – ביקורת עריכה", "d": "2026-11-08", "h": "\u003cp>S-20261108-008 | חומרה: גבוהה | קטגוריה: מקורות — מחיצות טבעיות, בקיעת רבים ושיעור מרחק. בתוספות עירובין כב ע״ב, ד״ה „דילמא מעלות ומורדות קאמרת”, נידון במפורש הקושי: אם חכמים אינם אומרים אתי רבים ומבטלי מחיצה, לכאורה סולמא דצור ומחתנא דגדר היו צריכים להחשיב את ארץ ישראל לרשות היחיד, וכן בבל המוקפת בפרת ובדיגלת; ותוספות מוסיפים שאם אין שיעור לקרפף, אף אלף כורים ייחשבו מוקפים. תשובתם היא: „מחיצה שאינה עשויה בידי אדם לא חשיבא מחיצה כולי האי ואפילו רבנן מודו דאתו רבים ומבטלי מחיצה”. מכאן יש מקור מפורש להבחנה בין מחיצה טבעית למחיצה מעשה ידי אדם, ולכך שבמחיצה טבעית אף חכמים מודים לבקיעת רבים. אולם אין מכאן הוכחה שאין שיעור מרחק למחיצה מלאכותית: תוספות מיישבים את קושיית ההיקף הטבעי, ואינם קובעים שכל מחיצה מלאכותית תועיל בכל מרחק. לכן אין להסיק משתיקת הגמרא על היעדר שיעור מרחק; יש להשאיר שאלה זו פתוחה ולדון בה מול הראשונים העוסקים בנראות המחיצות.\u003c/p>"}, {"id": "581", "n": 174, "a": "OpenAI – ביקורת עריכה", "d": "2026-11-08", "h": "\u003cp>S-20261108-009 | חומרה: גבוהה | קטגוריה: דיוק בראשונים — ריטב״א, נראות מחיצות שבת וסוכה. הריטב״א בעירובין כב ע״ב מביא בשם „רבינו הרב הגדול ז״ל” את שיעור המחיצות המרוחקות: „דהיינו כל שרואה עצמו תוך המחיצות”. מיד הוא מסייג: „דאע״ג דלגבי שבת לא בעינן מחיצות הניכרות לדירתו כדאיתא בפ״ק דסוכה, אפ״ה בעינן שיראה עצמו תוך מחיצות”. אין לדייק מכאן שהריטב״א משווה את דין שבת לדין מחיצות ניכרות בסוכה; להפך, הוא מבחין ביניהם במפורש: בשבת אין צורך שהמחיצות יהיו ניכרות לדירתו באותו אופן, אך נדרש שהאדם יראה את עצמו בתוך היקפן. כמו כן, את שיעור „רואה עצמו” הריטב״א מביא בשם רבו, ולכן נכון לייחס את הניסוח לרבינו הגדול המובא בריטב״א, ולא להציגו כחידוש עצמאי של הריטב״א.\u003c/p>"}, {"id": "582", "n": 175, "a": "OpenAI – ביקורת עריכה", "d": "2026-11-08", "h": "\u003cp>S-20261108-010 | חומרה: גבוהה | קטגוריה: דיוק לשון ראשונים — הר״ן ונראות המחיצות הנצרכות מן התורה. לשון הר״ן בעירובין כב ע״ב היא: „ומשמע דמחיצות הניכרות היינו שבאי זה מקום שיעמוד באותו הקף רואה המחיצות הצריכות לו מן התורה”. יש לדייק שהר״ן תולה את הנראות „בכל מקום שיעמוד” במחיצות „הצריכות לו מן התורה”; אין בלשונו אמירה פשוטה שכל ארבע המחיצות, או כל צד וכל חלק של כל מחיצה, צריכים להיראות בכל מקרה. יש לברר לפי שיטת מניין המחיצות הנדרשת מן התורה מהן המחיצות הצריכות לאותו היקף. נוסף על כך, הר״ן מתאר תנאי של נראות לאדם העומד בתוך ההיקף; הוא אינו מנסח דין נפרד בקרקע, ואינו קובע שכל מחיצת צד מגדירה בנפרד חלק אחר של הקרקע. המעבר מן הנראות אל „גדר בקרקע בנפרד” הוא אפוא היסק מושגי של המחבר, הטעון הנמקה, ולא לשון מפורשת של הר״ן.\u003c/p>"}, {"id": "1161", "n": 176, "a": "מגיב – שילוב קטעים חסרים", "d": "2026-11-17", "h": "\u003cp>מש-364 | סוג: קטע חסר | מקור: 04_רשויות/רשויות.pdf\u003c/p>\u003cp>מיקום השילוב המוצע: לאחר הפסקה שלפני הערה זו (\"וזה ביאור הגמרא בהכשר מבוי דהו\"א דמה דבעי לב\"ש גם לחי וגם קורה זה אינו משום גדר ההכשר, אלא משום דבעי ד' מחיצות...\").\u003c/p>\u003cp>הקטע משתלב כאן כהמשך ישיר לדברים שלפניו; אין צורך בקטע קישור.\u003c/p>\u003cp>נוסח הקטע:\u003c/p>\u003cp>מקום ד' פתח נעול .והדלת שוקף בפני האסקופה הפנימית וכל האסקופה חוץ לדלת כלחוץ ואפילו תחת הקורה דכיון דנסתם המבוי בטלה לה קורה וליכא למימר יורד וסותם דכל מחיצה שאין בין חלל המחיצות ד' אינן מחיצות ולא שייכא בהו תורת גוד אחית ולהכי לא אוקמא באסקופת בית דסתם בית פתח שלו יש לו משקוף מלמעלה ונמצא עובי הפתח כולו מקורה ואפילו פתח נעול אמרינן יורד וסותם שהרי יש בחלל עביו ד' מן הדלת לסתימת פי התקרה וה''ה דמצי לאוקמא כולו מקורה אלא שאין ברחב עביו ד' אלא משום דסתם עובי החומה אינו פחות מד': ואף שכתב לעיל בכוורת שאינה רחבה גבוהה ז' ומחצה דאמרינן לבוד לגבי מחיצות אף שאין שם מקום ד' היינו ששם אין גדר המחיצה למשהו אלא לעצמה אך כאן גדר המחיצה הוא לרשות ומשום היקף ואין היקף אלא למקום ואין מקום אלא בד\"ט\u003c/p>\u003cp>אוזניים לתורה שלמה גזר .דכתיב (קהלת יב) ואיזן וחקר שעשה אזנים לתורה כלומר סייג והרחקה ככפיפה זו שנוטלין אותה באזנים ואין נוגעין בה :עירובין .אזנים להוצאת שבת שאסור להוציא מרשותו לרשות חבירו ואע''פ ששניהם רה''י: ומשמע דתרי איכא הכא דגם ע\"י עירובין אין מגיעים לגעת בכלי עצמו היינו שלא יבואו לעבור על איסור הוצאה וכן שע\"י זה אוחזין בכלי עצמו היינו שיאחזו ישראל במצוות דהכי איתא בפרש\"י בעירובין שע\"י דין עירובין מחזיקים במצוות דאיסור הוצאה בשבת שנח לאחוז בכלי שיש לו בית יד משאין לו והיינו שיש באיסור הוצאה גדר דשב ואל תעשה ואם היו נמענים כלל ממה שדומה להוצאה היה די בכך אלא שלא היה זה בגדרי המצווה ורק הרחקה אך ע\"י מצוות עירובין הרי הם אוחזין במצווה ביותר דכיון דצריכי למעיבד עירוב להוצאת חצירות הרי דהוי האי מצווה בקום ועשה ויש בזה לחזק המצווה\u003c/p>\u003cp>הנחת עירוב בעירובי תחומין .תיקון מעליא דאסמכוה רבנן תחומין אקראי ואפי' למאן דאמר תחומין דרבנן כדאמרינן בעירובין (דף נא). ילפינן מקום ממקום ומקום מניסה כו' אבל עירובי חצרות חומרא בעלמא הוא ולא מיקרי שביתה מעלייתא וספקא דבין השמשות שפיר דמי: והיינו דהכא איירי אדין דהנחת עירוב ואף דגם עירובי תחומין קימ\"ל דהוא מדרבנן עכ\"פ קנית שביתה דתחומין במקום הנחת עירוב הוא תיקון חשוב שנחשב שזה מקומו וכדילפינן וכו' אך מה דע\"י הנחת עירוב חצירות חשיב שהוא דר בבית שמונח בו עירוב אין בזה שביתה חשובה שאין בזה גדר שזה מקומו שלו אלא לגבי מה שהחצר מיוחדת לבית זה לענין צירוף בני החצר שזכותם בחצר מעורבת יחד אך עדיין חשיב מקומם בביתם שהוא מקום לינה ופיתא ואית להם רשות בית שלהם ואוסרים ומבטלין (והכי מוכח מהא דלא מועיל ביטול לחד וכתב רש\"י שהוא משום דאדעתא דהאי חולקא לא עירב ואם ע\"י עירוב נעשה שהוא גר בבית שמונח בו עירוב וע\"י הותר שאין רק בית אחד מאי נפק\"מ שלא עירב אדעת זה כיון שהוא גר רק בבית שמונח בו עירוב אין לו לאסור ואכמ\"ל) אבל אין זה אלא לגבי דין קנית מקום שע\"י הנחת עירוב אבל כיון שדין תחומין הוא דרבנן יועיל אפילו בבין השמשות דהאי סברא ליכא אלא לגבי הנחת עירוב שהיא מעשה הקניה שאין לעשותה בזמן ספק כיון שיש לה משמעות קניה אבל לגבי מה שמועילה הקניה כיון שהונח הונח וכן כתב לגבי קטן המניח את העירוב דלא מועיל בעירובי תחומין אבל מועיל בעירובי חצירות דכיון שהוא רק לעירובי רשותייהו כיון שמונח בבית ממילא\u003c/p>\u003cp>מעירבי שאין זה גדר ששינה מקום שביתתו אלא שרשות בית בחצר שלו מעורבת עם כל בני חצר אבל בעירובי תחומין צריך לשנות את מקומו מביתו למקום הנחת עירוב וזה ע\"י שקונה שם מקום שביתה וקטן אינו אלים לקנות מקום שביתה והיינו שאף שלגבי מה שנחשב מקום פיתא ולינה הרי זה כמו בעירובי חצירות אבל כיון שאין די שיהיה מונח שם העירוב אלא צריך שיקנה שביתה ע\"י הנחת עירוב אין זה מועיל בקטן ואין לזה שייכות עם מה דסבר שמואל עירוב משום קנין שזה גדר מה שעושה העירוב המונח שם ואין זה גדר הנחה עצמה דזה אף לשמואל גדר דדירה כמו שמוכח התם דכולה הכא דיירי ובית שמניחים בו את העירוב אין צריך ליתן אלא שנחלקו מה נעשה ע\"י עירוב זה שמתירם דלדעת שמואל ע\"י הנחת עירוב קונים חלק בבית ולדעת רבה ע\"י זה חשיב שהוא דר בבית ואין קטן האמור שם כקטן דהכא דקטן דהכא לא עשה רק איסוף של העירוב אבל אחר שהונח גדר הקניה הוא במה שפת שלו מונח בבית זה הרי שיש לו חלק בבית זה אבל קטן דהתם איירי שעושה אותו שליח שע\"י הנחה זו יקנה הקטן ויקנה לו ולא שע\"י דאית ליה אוכל שם קונה אבל אם אינו רק גובה לכולם אין בזה רק מעשה קוף\u003c/p>\u003cp>מושיט מט :קרקע .רשות הרבים :עגלה .רשות היחיד שגבוהה י' ורחבה ד' :דרך רשות הרבים .דאויר שבין העגלות רשות הרבים:\u003c/p>\u003cp>ולא בשבילך ואף שאם תעשה אין לחייבו כאילו היה זה מעשה שלו אבל יש לו למנוע ממנה מעשה שיש בו גדר מלאכה לאדם משום לתא דתעבוד היינו שלא יהיה יום השבת יום עבודה אלא יום שביתה ונראה שגדר זה אינו גדר מעשה היינו שנתיר ע\"י זה עוקר וזה מניח ונפק\"מ אם נעשה עקירה ע\"י בהמה אחת שלו והנחה ע\"י בהמה שניה שלו שעדין יהיה אסור וכן משמע לגבי שביתת כלים דאף דאין עושה הכלי אלא הכלת הגחלים דמוגמר ואיסור הרי נעשה גם ע\"י הגחלים עצמם ובבגד המתגמר והיה לחלק אם קודם הניח הבגד והכלי ואחר כן הניח הגחלים והגופרית שאז י\"ל דעביד הכלי מעשה דמלאכה משא\"כ אם הניח המוגמר והגפרית ואחר כן הבגד והכלי וכמו בזה הביא את העצים וכו' ומשמע שאין זה משנה והיינו שגדר שבית דכלים וכן בהמה אין זה גדר דמעשה אלא כמו בנזקי ממונו שגדר התוצאה היא האיסור והעושה אינו מתחייב על המעשה עצמו אלא במה שהוא גורם וכן כאן שגדר המלאכה היא האיסור והיינו הבגד המתגמר והכלי חשיב גורם וכמו בנזקי ממונו שגדר מה שמעשה דממונו מחייב אותו לעומת מה שאינו ממונו אינו שייך למעשה עצמו אלא רק במה שהם ברשותו שאז יש לחייבו משום שיש לו חיוב שמירה עליהם ובאי שמירה כבר נגמר המעשה המחייב אותו ואחר כן גדר המעשה דממונו הוא גדר דגרימה .ואכמ\"ל .ובזה יבואר מה שיש בזה גדר דמראית עין בעצם מה שיש על בהמתו זוג אף שפקוק בחצר ועדיין צ\"ע ע\"ש ברש\"י\u003c/p>\u003cp>גדר שביתה דבהמתו\u003c/p>\u003cp>והנה דין זה הוא דין מושיט והרי מושיט הוה אפילו ויתר מי' וליכא למאן דס\"ל קלוטה ביותר בי' דהא לא אוויר רשות הרבים דאין תופסת אווירה אלא עד י' כדאמר בפ\"ק ובהכרח דכוונתו דהעגלות עצמם חלוקות משום דאוויר שבית העגלות הוי רשות הרבים וזה קשה שהרי אין העגלות רה\"י אלא בגובהם אך תחתיהם לא ואף אי נימא דהוי רה\"ר מקורה אין הוא מוציא משם אלא היינו שכיון שמוציא דרך אוויר יש גדר בזה שהוא דרך הקרקע ואף שאין זה ענין לכלי שמוציא כדאמרן לגבי חילוק הרשויות הוי ענין דכיון שאוויר שעובר בו הכלי הוא של קרקע היינו מה שהיה אם היה נח באוויר זה הרי שיש משמעות לעגלות ביחס לקרקע שתחתיהם וכיון שכן הרי שהם חלוקים ע\"י דאיכא רשות הרבים ביניהם וחשיבי שתי רשויות חלוקות לגבי הוצאה זו (ואף שיהיו מחוברים באיזה אופן ע\"י פתח וכמו בשתי גזוזטראות דלא מצאנו שיפטר ע\"י פתח שיש בין הבתים) ואף דתחתיהם הוי רשות הרבים מקורה אין זה חסרון ברה\"ר עצמה היינו למעט ט\"ז שלה או לחלקה אלא רק לגבי מי שמטלטל תחתיה יותר מד\"א או לגבי המוציא לה\u003c/p>\u003cp>והיינו לגבי האדם שאף שיהיה גדר משוי לגבי הבהמה שאין היא רוצה בזה אין גדר מלאכה דבהמתו בה עצמה אלא במה שנחשב לגביו ואין גדר הוצאה לגביו אלא משוי היינו שאין שייכות בין גדר תכשיט לדין הוצאה שזה דין בדבר עצמו וודאי חייב בזה אם הוציא בדרך משוי אלא היינו גדר תכשיט שאין זה כלי הנעשה לצורך מעשה שהוא חוץ לאדם כמו בכל כלי שהוא עושה מעשה נפרד לעצמו שיש בתוצאתו ערך לאדם אלא הוא עצמו הערך וא\"כ בנשיאתו בדרך שהוא במשמעות זו אין זה מעשה בתכשיט אלא באדם ואין איסור הוצאה באדם (ויש לדון בזה שיאסר להוציאו חוץ לתחום בעליו אף בתוך תחום המוציאו) משא\"כ דבר שאין לומר עליו שהוא תכשיט ויהיה בו ערך עצמי מה שהוא יוצא וגדר תכשיט דכאן היינו מה שיש לאדם צורך שיהיה לבהמתו דבר זה באופן קבוע וזה גדר באדם\u003c/p>"}, {"id": "583", "n": 177, "a": "OpenAI – ביקורת עריכה", "d": "2026-11-08", "h": "\u003cp>S-20261108-011 | חומרה: גבוהה | קטגוריה: מקורות — מחלוקת לחי משום מחיצה וקורה משום היכר. יש להעמיד את המהלך מול המחלוקת המפורשת בעירובין יב ע״ב: רב יהודה ורבה סוברים „לחי משום מחיצה וקורה משום היכר”, ואילו רבא סובר „אחד זה ואחד זה משום היכר”. לכן אין להציג את ההכרח שלחי וקורה ממלאים בהכרח שני תפקידים נבדלים כמסקנה מוסכמת של הסוגיה; הוא עשוי להתאים לשיטת רב יהודה ורבה, אך טעון יישוב מול שיטת רבא, שלפיה שניהם משום היכר. נוסף על כך, המאירי בעירובין יא ע״ב מביא בשם רבנו חננאל נוסח שונה: „לא גריס לזרוק משתים מחייב אלא משתים אסור, וכן בדבית שמאי לזרוק משלש אסור”. אם המהלך נשען על ההבחנה שבין חיוב זריקה דאורייתא לבין איסור זריקה, יש לציין את נוסח הגמרא שעליו הוא מבוסס ולהתייחס לגרסת רבנו חננאל. אפשר להציע את המודל שלך, אך יש להציגו כהכרעה פרשנית בתוך מחלוקת הראשונים והאמוראים, ולא כהוכחה שאין לה חולק.\u003c/p>"}]};
